function evText(text){
  try{
    if(evValuesOn() && window.eduverseValuesText){
      var out=window.eduverseValuesText(String(text));
      if(evValuesLang()==='de' && window.eduverseGermanClean) out=window.eduverseGermanClean(out);
      if(evValuesLang()==='en' && window.eduverseEnglishClean) out=window.eduverseEnglishClean(out);
      return out;
    }
  }catch(e){}
  return text;
}

