  try{ if(!(evValuesOn && evValuesOn())) return; }catch(e){ return; }
  var l='tr'; try{ l=evValuesLang()||'tr'; }catch(e){}
  var T={
    tr:{title:'Akıllı Puzzle Laboratuvarı', choose:'Bir zeka resmi seç - 16 parçayı tamamla', today:'Bugün: ', tries:'/3 ödül hakkı', piece:'Parça: ', back:'Geri', hint:'Her parçayı doğru yere sürükle', done:'TAMAMLANDI!', win:'Puzzle tamamlandı!<br>+500 yıldız kazandın', cont:'Devam', home:'Ana sayfa', replay:'Tekrar oyna', pieces:'parça'},
    de:{title:'Smartes Puzzle-Labor', choose:'Wähle ein Bild - setze 16 Teile zusammen', today:'Heute: ', tries:'/3 Belohnungsversuche', piece:'Teil: ', back:'Zurück', hint:'Ziehe jedes Teil an die richtige Stelle', done:'GESCHAFFT!', win:'Puzzle fertig!<br>+500 Sterne gewonnen', cont:'Weiter', home:'Startseite', replay:'Nochmal', pieces:'Teile'},
