function _snPlayNote(sceneIdx){
  try{
    var A=getAC(), t=A.currentTime;
    var scale=[523,587,659,698,784,880,988,1047];
    var idx=((sceneIdx||0)%8+8)%8;
    var chord=[scale[idx], scale[(idx+2)%8], scale[(idx+4)%8]];
    chord.forEach(function(freq,i){
      var o=A.createOscillator(), g=A.createGain();
      o.type='sine';
      o.frequency.value=freq;
      g.gain.setValueAtTime(0,t+i*0.06);
      g.gain.linearRampToValueAtTime(0.12,t+i*0.06+0.04);
      g.gain.exponentialRampToValueAtTime(0.001,t+i*0.06+0.5);
      o.connect(g); g.connect(A.destination);
      o.start(t+i*0.06); o.stop(t+i*0.06+0.55);
    });
  }catch(e){}
}

