text:
function evV42SakinlikMsg(type){
  var name=''; try{name=String(playerName||'Kahraman').trim()||'Kahraman';}catch(e){name='Kahraman';}
  var l=evV42SakinlikLang();
  var m={
    breath:{tr:name+', nefes halkası açıldı. Yavaşça nefes al ve bırak.',en:name+', the breathing circle opened. Breathe in and let go.',de:name+', der Atemkreis ist offen. Atme langsam ein und lass los.',fr:name+', le cercle de respiration est ouvert. Respire et relâche.',ar:name+'، فتحت دائرة التنفس. تنفّس ببطء واترك التوتر.'},
    mirror:{tr:name+', duygu aynası parladı. Bugünkü duygunu fark ettin.',en:name+', the feeling mirror glowed. You noticed your feeling.',de:name+', der Gefühls-Spiegel leuchtet. Du hast dein Gefühl bemerkt.',fr:name+', le miroir des émotions brille. Tu as remarqué ton émotion.',ar:name+'، أضاءت مرآة الشعور. لقد لاحظت شعورك.'},
    lantern:{tr:name+', iyi dilek fenerin göğe yükseldi.',en:name+', your good-wish lantern rose into the sky.',de:name+', deine Wunschlaterne steigt in den Himmel.',fr:name+', ta lanterne de souhait monte vers le ciel.',ar:name+'، ارتفع فانوس أمنيتك الطيبة.'},
    stone:{tr:name+', teşekkür taşı parladı. Küçük şeyleri fark etmek güç verir.',en:name+', the gratitude stone glowed. Noticing small things gives strength.',de:name+', der Dankbarkeitsstein leuchtet. Kleine Dinge geben Kraft.',fr:name+', la pierre de gratitude brille. Les petites choses donnent de la force.',ar:name+'، أضاء حجر الشكر. ملاحظة الأشياء الصغيرة تمنح قوة.'},
    box:{tr:name+', bunu burada bırakabilirsin. Şimdi biraz daha hafifsin.',en:name+', you can leave it here. Now you are a little lighter.',de:name+', du kannst es hier lassen. Jetzt bist du etwas leichter.',fr:name+', tu peux le laisser ici. Tu es un peu plus léger.',ar:name+'، يمكنك تركه هنا. أنت الآن أخف قليلاً.'},
    silence:{tr:name+', sessiz dakika başladı. Oda seninle birlikte sakinleşiyor.',en:name+', the quiet minute began. The room calms down with you.',de:name+', die stille Minute beginnt. Der Raum wird mit dir ruhiger.',fr:name+', la minute calme commence. La salle s\'apaise avec toi.',ar:name+'، بدأت دقيقة الهدوء. الغرفة تهدأ معك.'}
  };
  return (m[type]&&m[type][l])||m[type].tr;
}

