      '<button id="v42-sakinlik-close" style="margin-top:18px;width:100%;padding:13px 16px;border:none;border-radius:22px;background:linear-gradient(135deg,#86e7ff,#b7ffd3);color:#06222a;font-family:Fredoka One,sans-serif;font-size:1rem;cursor:pointer;">'+evV42SakinlikLabel('continue')+'</button>'+
