function evV42TrySakinlikTap(x,y){
  try{
    if(!currentRoom || currentRoom.id!=='ibadet' || !(evValuesOn&&evValuesOn())) return false;
    var now=Date.now();
    if(now-_v42SakinlikLastTap<900) return true;
    var zones=evV42SakinlikZones();
    for(var i=0;i<zones.length;i++){
      var z=zones[i], dx=x-z.x, dy=y-z.y;
      if(Math.sqrt(dx*dx+dy*dy)<z.r){
        _v42SakinlikLastTap=now;
        evV42ShowSakinlikRitual(z.type);
        return true;
      }
    }
  }catch(e){}
  return false;
}

