  var ok={
    tr:['Süper! Bunu biliyordum! 🌟','Harika! Devam et! 🎉','Bravo! Güzel ahlak öğreniyoruz! ⭐','Evet! Doğru! 🚀'],
    en:['Great! I knew it! 🌟','Awesome! Keep going! 🎉','Bravo! We learn good character! ⭐','Yes! Correct! 🚀'],
    de:['Super! Das wusste ich! 🌟','Prima! Weiter so! 🎉','Bravo! Wir lernen guten Charakter! ⭐','Ja! Richtig! 🚀'],
    fr:['Super ! Je le savais ! 🌟','Génial ! Continue ! 🎉','Bravo ! On apprend le beau comportement ! ⭐','Oui ! Correct ! 🚀'],
    ar:['رائع! كنت أعرف ذلك! 🌟','جميل! تابع! 🎉','أحسنت! نتعلم حسن الخلق! ⭐','نعم! صحيح! 🚀']
  };
  var wrong={
    tr:['Hata yapmak da öğrenmek! 💪','Merak etme, bir sonraki! 🌈','Neredeyse! Balona bak! 👀','Öğrendik, devam! 😊'],
    en:['Mistakes help us learn! 💪','No worries, try the next one! 🌈','Almost! Look for the balloon! 👀','We learned it, keep going! 😊'],
    de:['Fehler helfen beim Lernen! 💪','Keine Sorge, die nächste Frage! 🌈','Fast! Such den Ballon! 👀','Wir haben gelernt, weiter! 😊'],
    fr:['Les erreurs nous apprennent ! 💪','Pas de souci, la prochaine ! 🌈','Presque ! Cherche le ballon ! 👀','On a appris, continuons ! 😊'],
    ar:['الأخطاء تساعدنا على التعلم! 💪','لا تقلق، جرّب التالي! 🌈','قريب! ابحث عن البالون! 👀','تعلمنا، فلنكمل! 😊']
  };
  var arr=(type==='wrong'?(wrong[l]||wrong.tr):(ok[l]||ok.tr));
  return arr[Math.floor(Math.random()*arr.length)];
}

