function evV43KMESelam(){
  var name=''; try{name=String(playerName||'Kahraman').trim()||'Kahraman';}catch(e){name='Kahraman';}
  var l=evV43KMELang();
  if(l==='en') return 'Peace be with you, '+name+'. Welcome to the Little Angels House.';
  if(l==='de') return 'Friede sei mit dir, '+name+'. Willkommen im Haus der kleinen Engel.';
  if(l==='fr') return 'Que la paix soit avec toi, '+name+'. Bienvenue dans la Maison des petits anges.';
  if(l==='ar') return 'السلام عليك يا '+name+'، أهلاً بك في بيت الملائكة الصغار.';
  return 'Selam '+name+'. Küçük Melekler Evi\'ne hoş geldin.';
}

