text:
function evV43GetKMEQuestion(){
  var l=evV43KMELang();
  if(l==='en') return [
    {q:'What is the first lesson of the Selam Gate?',opts:['Speak with peace','Mock people','Push others away','Forget kindness'],ans:0,exp:'A peaceful greeting opens hearts.',ans_txt:'Speak with peace'},
    {q:'How should we treat someone from a different belief or country?',opts:['With respect','With hate','By ignoring them','By insulting them'],ans:0,exp:'Respect and good character are for every person.',ans_txt:'With respect'},
    {q:'What happens when you share your bread?',opts:['Kindness grows','The heart gets smaller','Friendship ends','Nothing matters'],ans:0,exp:'Sharing is one of the warmest signs of mercy.',ans_txt:'Kindness grows'}
  ][Math.floor(Math.random()*3)];
  if(l==='de') return [
    {q:'Was lehrt das Selam-Tor zuerst?',opts:['Mit Frieden sprechen','Menschen verspotten','Andere wegschieben','Güte vergessen'],ans:0,exp:'Ein friedlicher Gruß öffnet Herzen.',ans_txt:'Mit Frieden sprechen'},
    {q:'Wie behandeln wir jemanden mit anderem Glauben oder Land?',opts:['Mit Respekt','Mit Hass','Gar nicht','Mit Beleidigung'],ans:0,exp:'Respekt und guter Charakter gelten für jeden Menschen.',ans_txt:'Mit Respekt'},
    {q:'Was geschieht, wenn du dein Brot teilst?',opts:['Güte wächst','Das Herz wird kleiner','Freundschaft endet','Nichts'],ans:0,exp:'Teilen ist ein schönes Zeichen der Barmherzigkeit.',ans_txt:'Güte wächst'}
  ][Math.floor(Math.random()*3)];
  if(l==='fr') return [
    {q:'Que nous apprend d\'abord la Porte du Selam ?',opts:['Parler avec paix','Se moquer','Repousser les autres','Oublier la bonté'],ans:0,exp:'Une salutation paisible ouvre les cœurs.',ans_txt:'Parler avec paix'},
    {q:'Comment traiter une personne d\'une autre croyance ou d\'un autre pays ?',opts:['Avec respect','Avec haine','En l\'ignorant','En l\'insultant'],ans:0,exp:'Le respect et le bon comportement sont pour chaque personne.',ans_txt:'Avec respect'},
    {q:'Que se passe-t-il quand tu partages ton pain ?',opts:['La bonté grandit','Le cœur diminue','L\'amitié finit','Rien'],ans:0,exp:'Partager est un beau signe de miséricorde.',ans_txt:'La bonté grandit'}
  ][Math.floor(Math.random()*3)];
  if(l==='ar') return [
    {q:'ماذا نتعلم أولاً من باب السلام؟',opts:['أن نتكلم بسلام','أن نسخر من الناس','أن نطرد الآخرين','أن ننسى الخير'],ans:0,exp:'السلام والكلمة الطيبة تفتح القلوب.',ans_txt:'أن نتكلم بسلام'},
    {q:'كيف نعامل من يختلف عنا في الدين أو البلد؟',opts:['باحترام','بكره','بتجاهل','بإهانة'],ans:0,exp:'الاحترام وحسن الخلق يكونان مع كل إنسان.',ans_txt:'باحترام'},
    {q:'ماذا يحدث عندما تشارك خبزك؟',opts:['يكبر الخير','يصغر القلب','تنتهي الصداقة','لا شيء'],ans:0,exp:'المشاركة علامة جميلة من الرحمة.',ans_txt:'يكبر الخير'}
  ][Math.floor(Math.random()*3)];
  return [
    {q:'Selam Kapısı bize ilk neyi öğretir?',opts:['Barışla konuşmayı','İnsanlarla alay etmeyi','Dışlamayı','İyiliği unutmayı'],ans:0,exp:'Selam ve güzel söz kalpleri açar.',ans_txt:'Barışla konuşmak'},
    {q:'Farklı inançtan veya ülkeden birine nasıl davranırız?',opts:['Saygıyla','Kötü davranarak','Yok sayarak','Aşağılayarak'],ans:0,exp:'Güzel ahlak her insana saygı göstermeyi öğretir.',ans_txt:'Saygıyla'},
    {q:'Ekmeğini paylaşınca ne çoğalır?',opts:['İyilik','Kibir','Yalnızlık','Öfke'],ans:0,exp:'Paylaşmak rahmetin ve dostluğun güzel bir işaretidir.',ans_txt:'İyilik'}
  ][Math.floor(Math.random()*3)];
}

