function evV47KMEEnsureNav(){
  try{
    var old=document.getElementById('v47-kme-nav');
    if(old) old.remove();
    if(!currentRoom || currentRoom.id!=='kucukmelekler' || !gameActive) return;
    var nav=document.createElement('div');
    nav.id='v47-kme-nav';
    nav.setAttribute('translate','no');
    nav.style.cssText='position:fixed;left:50%;bottom:10px;transform:translateX(-50%);z-index:120;display:flex;gap:6px;align-items:center;justify-content:center;max-width:96vw;padding:6px 7px;border-radius:22px;background:rgba(4,9,20,.64);border:1px solid rgba(255,220,130,.25);box-shadow:0 14px 50px rgba(0,0,0,.40),0 0 32px rgba(255,220,130,.12);backdrop-filter:blur(8px);';
    for(var i=1;i<=8;i++){
      var d=evV45KMEData(i), active=i===evV45GetKMELayer();
      var b=document.createElement('button');
      b.className='v47-kme-nav-btn';
      b.setAttribute('data-layer',String(i));
      b.style.cssText='width:42px;height:46px;border-radius:17px;border:1px solid '+(active?'rgba(255,230,150,.70)':'rgba(255,255,255,.16)')+';background:'+(active?'linear-gradient(145deg,rgba(255,220,130,.35),rgba(255,255,255,.12))':'rgba(255,255,255,.065)')+';color:'+(active?'#ffe8a8':'rgba(255,255,255,.72)')+';font-family:Fredoka One,system-ui,sans-serif;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1;box-shadow:'+(active?'0 0 22px rgba(255,220,130,.24)':'none')+';';
      b.innerHTML='<span style="font-size:1.05rem;line-height:1">'+d.ico+'</span><span style="font-size:.60rem;margin-top:3px;">'+i+'</span>';
      b.onclick=(function(layer){return function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} evV47SwitchKMELayer(layer); return false; };})(i);
      nav.appendChild(b);
    }
    var hub=document.createElement('button');
    hub.style.cssText='height:46px;border-radius:17px;border:1px solid rgba(255,220,130,.28);background:rgba(255,220,130,.10);color:#fff1bd;font-family:Fredoka One;font-size:.68rem;cursor:pointer;padding:0 10px;';
    hub.textContent='Kapılar';
    hub.onclick=function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} evV47BackToKMEHub(); return false; };
    nav.appendChild(hub);
    document.body.appendChild(nav);
  }catch(e){}
}

