function evV47SwitchKMELayer(layerId){
  try{
    evV45SetKMELayer(layerId);
    gameActive=false;
    currentRoom=null;
    evV47KMERemoveNav();
    setTimeout(function(){
      var room=null;
      try{ room=ROOMS.find(function(r){return r.id==='kucukmelekler';}); }catch(e){}
      if(room){
        window.__evV44KMEBypassQuestion=true;
        enterRoom(room);
        window.__evV44KMEBypassQuestion=false;
      }
    },80);
  }catch(e){}
}

