  try{
    evV47KMERemoveNav();
    gameActive=false;
    var gs=document.getElementById('gs'), hm=document.getElementById('hm');
    if(gs) gs.style.display='none';
    if(hm) hm.style.display='flex';
    currentRoom=null;
    setTimeout(function(){ evV44OpenKMEHub(); },80);
  }catch(e){ try{goHome();}catch(ex){} }
}

