function evV47DrawLayerOrb(z,active){
  var x=W*z.x,y=H*z.y,r=Math.min(W,H)*z.r;
  var pulse=1+Math.sin(Date.now()/420)*.04;
  ctx.save();
  ctx.translate(x,y);
  ctx.scale(pulse,pulse);
  var grd=ctx.createRadialGradient(0,0,0,0,0,r*2.1);
  grd.addColorStop(0,active?'rgba(255,230,150,.38)':'rgba(255,230,150,.25)');
  grd.addColorStop(.56,'rgba(255,220,130,.08)');
  grd.addColorStop(1,'transparent');
  ctx.fillStyle=grd; ctx.beginPath(); ctx.arc(0,0,r*2.1,0,Math.PI*2); ctx.fill();
  ctx.fillStyle=active?'rgba(255,245,210,.20)':'rgba(255,255,255,.13)';
  ctx.strokeStyle=active?'rgba(255,235,160,.52)':'rgba(255,220,130,.32)';
  ctx.lineWidth=active?2.2:1.5;
  ctx.beginPath(); ctx.roundRect(-r*1.05,-r*.62,r*2.1,r*1.24,17); ctx.fill(); ctx.stroke();
  ctx.font='bold '+Math.round(r*.44)+'px Fredoka One'; ctx.fillStyle='rgba(255,245,215,.98)';
  ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(z.ico,0,-r*.13);
  ctx.font='bold '+Math.round(r*.16)+'px Fredoka One'; ctx.fillStyle='rgba(255,244,218,.88)';
  ctx.fillText(z.title,0,r*.31);
  ctx.restore();
}

