function evV46KMEToast(title,msg,ico){
  try{
    var old=document.getElementById('v46-kme-toast');
    if(old) old.remove();
    var d=document.createElement('div');
    d.id='v46-kme-toast';
    d.setAttribute('translate','no');
    d.style.cssText='position:fixed;left:50%;bottom:78px;transform:translateX(-50%);z-index:99999;width:min(420px,90vw);border-radius:24px;padding:13px 15px;text-align:center;background:linear-gradient(145deg,rgba(8,14,34,.95),rgba(22,15,35,.95));border:1.5px solid rgba(255,220,130,.28);box-shadow:0 20px 70px rgba(0,0,0,.55),0 0 35px rgba(255,220,130,.12);font-family:Nunito,system-ui,sans-serif;color:white;';
    d.innerHTML='<div style="font-size:2rem;line-height:1">'+(ico||'✨')+'</div><div style="font-family:Fredoka One;font-size:1rem;color:#ffe8a8;margin-top:4px;">'+title+'</div><div style="font-weight:900;font-size:.82rem;line-height:1.45;color:rgba(255,255,255,.84);margin-top:5px;">'+msg+'</div>';
    document.body.appendChild(d);
    setTimeout(function(){ d.style.opacity='0'; d.style.transition='opacity .45s'; setTimeout(function(){if(d.parentNode)d.remove();},460);},3600);
    try{ if(typeof showOkiBubble==='function') showOkiBubble((ico||'✨')+' '+msg); }catch(e){}
  }catch(e){}
}

