function evV44BindKMESecretTitle(){
  try{
    var title=document.getElementById('v44-kme-secret-title');
    if(!title) return;
    var c=0,timer=null;
    title.onclick=function(){
      c++; clearTimeout(timer);
      timer=setTimeout(function(){c=0;},2200);
      if(c>=7){
        c=0;
        var now=!evV44KMETestMode();
        evV44SetKMETestMode(now);
        var o=document.getElementById('v44-kme-hub'); if(o)o.remove();
        setTimeout(evV44OpenKMEHub,80);
        try{ if(typeof showOkiBubble==='function') showOkiBubble(now?'🔓 Deneme modu açıldı. Katmanlar sadece sende açık.':'🔒 Deneme modu kapandı. Katmanlar tekrar kilitli.'); }catch(e){}
      }
    };
  }catch(e){}
}

