function evV44OpenKMEHub(){
  try{
    var old=document.getElementById('v44-kme-hub');
    if(old) old.remove();
    var layers=evV44KMELayers();
    var testMode=evV44KMETestMode();
    var html='';
    for(var i=0;i<layers.length;i++){
      var L=layers[i];
      html+='<button class="v44-kme-layer '+(L.open?'open':'locked')+'" data-layer="'+L.id+'" '+(L.open?'':'disabled')+' style="position:relative;display:flex;align-items:center;gap:13px;width:100%;border-radius:22px;padding:12px 13px;border:1px solid '+(L.open?'rgba(255,220,130,.45)':'rgba(255,255,255,.12)')+';background:'+(L.open?'linear-gradient(135deg,rgba(255,226,148,.20),rgba(80,140,255,.12))':'rgba(255,255,255,.055)')+';color:white;text-align:left;font-family:Nunito,system-ui,sans-serif;font-weight:900;cursor:'+(L.open?'pointer':'default')+';box-shadow:'+(L.open?'0 12px 30px rgba(255,200,80,.12)':'none')+';">'+
        '<span style="width:42px;height:42px;border-radius:16px;display:grid;place-items:center;font-size:1.45rem;background:'+(L.open?'rgba(255,220,130,.20)':'rgba(255,255,255,.08)')+';filter:drop-shadow(0 0 14px rgba(255,220,130,.25));">'+(L.open?L.ico:'🔒')+'</span>'+
        '<span style="flex:1;min-width:0;"><span style="display:block;font-family:Fredoka One,system-ui,sans-serif;font-size:.95rem;color:'+(L.open?'#ffe9a8':'rgba(255,255,255,.46)')+';">'+L.id+'. '+L.tr+'</span><span style="display:block;font-size:.72rem;line-height:1.25;color:'+(L.open?'rgba(255,255,255,.82)':'rgba(255,255,255,.36)')+';">'+L.sub+'</span></span>'+
        (L.open?'<span style="font-family:Fredoka One;font-size:.76rem;color:#fff3c4;">AÇIK</span>':'')+
      '</button>';
    }
    var ov=document.createElement('div');
    ov.id='v44-kme-hub';
    ov.setAttribute('translate','no');
    ov.style.cssText='position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;padding:18px;background:radial-gradient(circle at 50% 26%,rgba(255,220,130,.20),transparent 26%),linear-gradient(180deg,rgba(3,7,18,.92),rgba(2,3,8,.96));backdrop-filter:blur(8px);';
    ov.innerHTML=
      '<div style="width:min(760px,96vw);max-height:92vh;overflow:auto;border-radius:34px;padding:22px;background:radial-gradient(circle at 50% 0%,rgba(255,220,130,.16),transparent 34%),linear-gradient(145deg,rgba(8,14,34,.94),rgba(18,12,28,.94));border:1.5px solid rgba(255,220,130,.28);box-shadow:0 35px 110px rgba(0,0,0,.65),0 0 75px rgba(255,220,130,.13);">'+
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px;">'+
          '<button id="v44-kme-close" style="border:none;border-radius:18px;padding:9px 14px;background:rgba(255,255,255,.08);color:rgba(255,255,255,.78);font-family:Fredoka One;cursor:pointer;">Geri</button>'+
          '<div style="text-align:center;flex:1;">'+
            '<div style="font-size:2.45rem;line-height:1;filter:drop-shadow(0 0 24px rgba(255,220,130,.38));">🌙</div>'+
            '<div id="v44-kme-secret-title" title="" style="margin-top:5px;font-family:Fredoka One;font-size:1.45rem;color:#ffe8a8;cursor:pointer;">Küçük Melekler Evi</div>'+
            '<div style="margin-top:3px;font-family:Nunito,system-ui,sans-serif;font-weight:900;color:rgba(255,255,255,.78);font-size:.85rem;">Dua • Rahmet • Güzel Ahlak</div>'+
          '</div>'+
          '<div style="width:60px;"></div>'+
        '</div>'+
        '<div style="border-radius:24px;padding:14px;margin-bottom:10px;background:rgba(255,220,130,.10);border:1px solid rgba(255,220,130,.18);font-family:Nunito,system-ui,sans-serif;font-weight:900;color:#fff4ce;font-size:.82rem;line-height:1.45;text-align:center;">Burada cami sadece ibadet yeri değil; muhabbet, güzel söz, merhamet, paylaşmak ve öğrenme evidir.</div>'+
        (testMode?'<div style="margin-bottom:12px;border-radius:18px;padding:9px 12px;background:rgba(80,255,150,.12);border:1px solid rgba(80,255,150,.25);font-family:Fredoka One;color:#b8ffd2;text-align:center;font-size:.78rem;">🌙 TÜM KATMANLAR AÇIK — KÜÇÜK MELEKLER EĞİTİMİ</div>':'<div style="margin-bottom:12px;border-radius:18px;padding:8px 12px;background:rgba(255,220,130,.075);border:1px solid rgba(255,220,130,.14);font-family:Nunito;font-weight:900;color:rgba(255,244,205,.78);text-align:center;font-size:.75rem;">8 katmanın tamamı açıldı. Her kapı ayrı eğitim ve oyun alanıdır.</div>')+
        '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px;">'+html+'</div>'+
      '</div>';
    document.body.appendChild(ov);
    var close=document.getElementById('v44-kme-close');
    if(close) close.onclick=function(){var o=document.getElementById('v44-kme-hub'); if(o)o.remove();};
    evV44BindKMESecretTitle();
    Array.prototype.forEach.call(document.querySelectorAll('#v44-kme-hub .v44-kme-layer.open'),function(b){
      b.onclick=function(){
        var id=parseInt(b.getAttribute('data-layer')||'1',10);
        var o=document.getElementById('v44-kme-hub'); if(o)o.remove();
        evV44OpenKMELayerPreview(id);
      };
    });
  }catch(e){
    try{ evV44EnterKMESelam(); }catch(ex){}
  }
}

