function speakWord(tr, foreign, lang) {
  if(!window.speechSynthesis) return;
  try {
    window.speechSynthesis.cancel();
    var u1 = new SpeechSynthesisUtterance(tr);
    u1.lang = 'tr-TR'; u1.rate = 0.85; u1.pitch = 1.1;
    var u2 = new SpeechSynthesisUtterance(foreign);
    u2.lang = lang; u2.rate = 0.82; u2.pitch = 1.05;
    u1.onend = function(){ window.speechSynthesis.speak(u2); };
    u1.onerror = function(){ window.speechSynthesis.speak(u2); };
    window.speechSynthesis.speak(u1);
  } catch(e){}
}

