function trackLangWord(w,lang){
  lang=lang||((currentRoom&&currentRoom.lang)||'en');
  var k=getLangWordKey(w,lang);

  seenCount[k]=(parseInt(seenCount[k]||0,10)||0)+1;
  var count=seenCount[k];
  var learned=false;

  if(count>=2 && !learnedWords[k]){
    learnedWords[k]=1;
    learned=true;
  }

  var tk='dei_wday_'+new Date().toDateString();
  var tl=[];
  try{ tl=JSON.parse(localStorage.getItem(tk)||'[]'); }catch(e){ tl=[]; }
  if(tl.indexOf(k)<0){
    tl.push(k);
    localStorage.setItem(tk,JSON.stringify(tl));
  }

  savePlayerData();
  if(learned) showLearnedToast(w,lang);
  return {key:k,count:Math.min(count,2),learned:learned||!!learnedWords[k]};
}

