function drawParts(){
  parts=parts.filter(function(p){
    if(p.ripple){
      p.rr+=p.rrSpd; p.al-=p.dc;
      if(p.al<=0||p.rr>p.rrMax) return false;
      ctx.save(); ctx.globalAlpha=Math.max(0,p.al);
      ctx.strokeStyle=p.col; ctx.lineWidth=p.w||3;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.rr,0,Math.PI*2); ctx.stroke();
      ctx.restore(); return true;
    }
    if(p.al<=0) return false;
    p.x+=p.vx; p.y+=p.vy; if(!p.tp){p.vy+=.1;p.r+=p.vr;} p.al-=p.dc;
    ctx.save(); ctx.globalAlpha=Math.max(0,p.al);
    if(p.tp){ ctx.font='bold 18px Fredoka One'; ctx.textAlign='center'; ctx.fillStyle=p.col; ctx.fillText(evText(p.txt),p.x,p.y); }
    else { ctx.translate(p.x,p.y); ctx.rotate(p.r); ctx.fillStyle=p.col; ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h); }
    ctx.restore(); return p.al>0;
  });
}

