function evV42DrawSakinlikHouse(ts){
  var t=ts*.001;
  var floorY=H*.74;
  // Ay ışıklı sakin göl arka planı
  var bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#031021');
  bg.addColorStop(.35,'#07283a');
  bg.addColorStop(.70,'#0b3d4a');
  bg.addColorStop(1,'#021018');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

  // Yumuşak ay ve yıldız tavan
  var mx=W*.78,my=H*.16,mr=Math.min(W,H)*.075;
  var mg=ctx.createRadialGradient(mx,my,0,mx,my,mr*2.4);
  mg.addColorStop(0,'rgba(255,245,200,.92)');
  mg.addColorStop(.28,'rgba(255,235,165,.34)');
  mg.addColorStop(1,'transparent');
  ctx.fillStyle=mg; ctx.beginPath(); ctx.arc(mx,my,mr*2.4,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,245,210,.94)'; ctx.beginPath(); ctx.arc(mx,my,mr,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#031021'; ctx.beginPath(); ctx.arc(mx-mr*.30,my-mr*.05,mr*.85,0,Math.PI*2); ctx.fill();

  for(var s=0;s<86;s++){
    var sx=(s*167)%W, sy=(s*97)%(H*.56)+H*.02;
    var al=.08+.24*Math.abs(Math.sin(t*.8+s));
    ctx.fillStyle=s%5===0?'rgba(255,230,160,'+al+')':'rgba(210,245,255,'+al+')';
    ctx.beginPath(); ctx.arc(sx,sy,s%8===0?1.8:.75,0,Math.PI*2); ctx.fill();
  }

  // Sakin göl ve dalgalar
  var water=ctx.createLinearGradient(0,H*.56,0,H);
  water.addColorStop(0,'rgba(72,190,220,.22)');
  water.addColorStop(.45,'rgba(20,120,145,.34)');
  water.addColorStop(1,'rgba(2,28,38,.92)');
  ctx.fillStyle=water; ctx.fillRect(0,H*.56,W,H*.44);
  for(var w=0;w<7;w++){
    ctx.strokeStyle='rgba(180,245,255,'+(.10+w*.018)+')';
    ctx.lineWidth=1.2;
    ctx.beginPath();
    for(var x=0;x<=W;x+=8){
      var y=H*(.60+w*.045)+Math.sin(x*.018+t*(.7+w*.1)+w)*H*.006;
      x===0?ctx.moveTo(x,y):ctx.lineTo(x,y);
    }
    ctx.stroke();
  }

  // Merkez nefes halkası
  var cx=W*.50, cy=H*.43;
  var breathe=.5+.5*Math.sin(t*1.15);
  var br=Math.min(W,H)*(.095+breathe*.030);
  var rg=ctx.createRadialGradient(cx,cy,0,cx,cy,br*2.0);
  rg.addColorStop(0,'rgba(255,255,255,.36)');
  rg.addColorStop(.28,'rgba(134,231,255,.24)');
  rg.addColorStop(1,'transparent');
  ctx.fillStyle=rg; ctx.beginPath(); ctx.arc(cx,cy,br*2,0,Math.PI*2); ctx.fill();
  for(var r=0;r<4;r++){
    ctx.strokeStyle='rgba(190,245,255,'+(.34-r*.065)+')';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(cx,cy,br*(1+r*.22),0,Math.PI*2); ctx.stroke();
  }
  ctx.fillStyle='rgba(235,255,255,.94)';
  ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One';
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('🌬️',cx,cy-H*.006);
  ctx.font='bold '+Math.round(Math.min(W,H)*.016)+'px Fredoka One';
  ctx.fillStyle='rgba(225,255,255,.82)';
  ctx.fillText(evV42SakinlikLabel('breathShort'),cx,cy+H*.050);

  // Duygu aynası
  function pill(x,y,w,h,col,emoji,label){
    ctx.save();
    ctx.fillStyle='rgba(0,15,25,.42)';
    ctx.beginPath(); ctx.ellipse(x,y+h*.54,w*.55,h*.14,0,0,Math.PI*2); ctx.fill();
    var g=ctx.createLinearGradient(x-w*.5,y-h*.5,x+w*.5,y+h*.5);
    g.addColorStop(0,'rgba(255,255,255,.22)');
    g.addColorStop(.45,col);
    g.addColorStop(1,'rgba(255,255,255,.08)');
    ctx.fillStyle=g; ctx.strokeStyle='rgba(255,255,255,.22)'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.roundRect(x-w*.5,y-h*.5,w,h,18); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,.96)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(emoji,x,y-h*.06);
    ctx.font='bold '+Math.round(Math.min(W,H)*.013)+'px Fredoka One';
    ctx.fillStyle='rgba(255,255,255,.86)'; ctx.fillText(label,x,y+h*.25);
    ctx.restore();
  }
  pill(W*.20,H*.58,W*.18,H*.14,'rgba(150,205,255,.18)','🪞',evV42SakinlikLabel('mirrorShort'));
