function evV43DrawKucukMeleklerEvi(ts){
  var t=ts*.001, id=evV45GetKMELayer(), D=evV45KMEData(id);
  var W2=W,H2=H;
  function bg(a,b,c,d){
    var g=ctx.createLinearGradient(0,0,0,H2);
    g.addColorStop(0,a);g.addColorStop(.32,b);g.addColorStop(.65,c);g.addColorStop(1,d);
    ctx.fillStyle=g;ctx.fillRect(0,0,W2,H2);
  }
  function stars(n){
    for(var s=0;s<n;s++){
      var x=(s*173)%W2+Math.sin(t*.37+s)*W2*.012;
      var y=(s*97)%(H2*.62)+H2*.02;
      var al=.07+.20*Math.abs(Math.sin(t*.9+s));
      ctx.fillStyle=s%3===0?'rgba(255,230,155,'+al+')':(s%3===1?'rgba(210,235,255,'+al+')':'rgba(255,255,255,'+al+')');
      ctx.beginPath();ctx.arc(x,y,s%9===0?1.9:.8,0,Math.PI*2);ctx.fill();
    }
  }
  function title(){
    ctx.save();ctx.translate(W2*.5,H2*.088);
    ctx.fillStyle='rgba(4,9,20,.80)';ctx.strokeStyle='rgba(255,220,130,.36)';ctx.lineWidth=1.8;
    ctx.beginPath();ctx.roundRect(-W2*.38,-H2*.050,W2*.76,H2*.100,19);ctx.fill();ctx.stroke();
    ctx.fillStyle='rgba(255,239,185,.98)';ctx.font='bold '+Math.round(Math.min(W2,H2)*.026)+'px Fredoka One';
    ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(D.ico+' '+D.title,0,-H2*.014);
    ctx.fillStyle='rgba(225,240,255,.82)';ctx.font='bold '+Math.round(Math.min(W2,H2)*.014)+'px Fredoka One';ctx.fillText(D.sub,0,H2*.023);
    ctx.restore();
  }
  function mosque(yAlpha){
    ctx.save();ctx.translate(W2*.5,H2*.43);
    ctx.fillStyle='rgba(4,10,22,'+(yAlpha||.52)+')';ctx.strokeStyle='rgba(255,220,130,.22)';ctx.lineWidth=2;
    ctx.beginPath();ctx.roundRect(-W2*.24,H2*.02,W2*.48,H2*.20,18);ctx.fill();ctx.stroke();
    ctx.beginPath();ctx.arc(0,H2*.02,W2*.155,Math.PI,0);ctx.closePath();ctx.fill();ctx.stroke();
    function min(x){ctx.beginPath();ctx.roundRect(x-W2*.018,-H2*.20,W2*.036,H2*.42,12);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(x,-H2*.26);ctx.lineTo(x-W2*.025,-H2*.20);ctx.lineTo(x+W2*.025,-H2*.20);ctx.closePath();ctx.fill();ctx.stroke();}
    min(-W2*.33);min(W2*.33);ctx.restore();
  }
  function floor(){
    var f=ctx.createLinearGradient(0,H2*.65,0,H2);
    f.addColorStop(0,'rgba(214,178,102,.78)');f.addColorStop(.48,'rgba(88,60,54,.91)');f.addColorStop(1,'rgba(20,10,16,.99)');
    ctx.fillStyle=f;ctx.beginPath();ctx.moveTo(W2*.04,H2*.74);ctx.lineTo(W2*.50,H2*.55);ctx.lineTo(W2*.96,H2*.74);ctx.lineTo(W2*.84,H2);ctx.lineTo(W2*.16,H2);ctx.closePath();ctx.fill();
  }
  function layerRoad(){
    var names=evV43KMEUi('layers');
    for(var i=0;i<8;i++){
      var x=W2*(.14+i*.103), y=H2*.69+Math.sin(t*.7+i)*H2*.004, active=i+1===id;
      ctx.fillStyle=active?'rgba(255,220,130,.92)':'rgba(255,255,255,.13)';
      ctx.strokeStyle=active?'rgba(255,245,190,.72)':'rgba(255,255,255,.18)';ctx.lineWidth=active?2.4:1.3;
      ctx.beginPath();ctx.roundRect(x-W2*.040,y-H2*.030,W2*.080,H2*.060,13);ctx.fill();ctx.stroke();
      ctx.fillStyle=active?'rgba(45,23,5,.95)':'rgba(255,255,255,.62)';
      ctx.font='bold '+Math.round(Math.min(W2,H2)*.0115)+'px Fredoka One';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText((i+1===id?D.ico:'')+(names[i]||String(i+1)),x,y);
    }
  }
  function zoneBadge(z){
    var x=W2*z.x,y=H2*z.y,r=Math.min(W2,H2)*z.r;
    var grd=ctx.createRadialGradient(x,y,0,x,y,r*1.7);
    grd.addColorStop(0,'rgba(255,230,150,.30)');grd.addColorStop(1,'transparent');
    ctx.fillStyle=grd;ctx.beginPath();ctx.arc(x,y,r*1.7,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,.13)';ctx.strokeStyle='rgba(255,220,130,.33)';ctx.lineWidth=1.6;
    ctx.beginPath();ctx.roundRect(x-r*.95,y-r*.58,r*1.9,r*1.16,16);ctx.fill();ctx.stroke();
    ctx.font='bold '+Math.round(r*.45)+'px Fredoka One';ctx.fillStyle='rgba(255,245,215,.98)';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(z.ico,x,y-r*.13);
    ctx.font='bold '+Math.round(r*.17)+'px Fredoka One';ctx.fillStyle='rgba(255,244,218,.84)';ctx.fillText(z.title,x,y+r*.30);
  }

  // 1 Selam: açık avlu, üç sosyal kapı
  if(id===1){
    bg('#050711','#071b35','#0b3550','#05060b'); stars(85); mosque(.50); floor();
    ctx.save();ctx.translate(W2*.5,H2*.47);
    ctx.strokeStyle='rgba(255,220,130,.36)';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,W2*.20,Math.PI*1.05,Math.PI*1.95);ctx.stroke();
    ctx.fillStyle='rgba(255,230,150,.18)';ctx.beginPath();ctx.arc(0,0,W2*.16,0,Math.PI*2);ctx.fill();
    ctx.restore();
    evV46KMEZones().forEach(function(z){evV47DrawLayerOrb(z,true);});
  }
  // 2 Temizlik: canlı çeşme ve su akışı
  if(id===2){
    bg('#04121b','#08304a','#0f7698','#061018'); stars(60); floor();
    var cx=W2*.5, cy=H2*.45;
    ctx.fillStyle='rgba(160,230,255,.13)';ctx.beginPath();ctx.arc(cx,cy,W2*.22,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='rgba(190,240,255,.55)';ctx.lineWidth=5;ctx.beginPath();ctx.arc(cx,cy,W2*.18,Math.PI,0);ctx.stroke();
    ctx.fillStyle='rgba(255,245,210,.65)';ctx.beginPath();ctx.roundRect(cx-W2*.10,cy+H2*.06,W2*.20,H2*.10,18);ctx.fill();
    for(var d=0;d<42;d++){var x=cx+Math.sin(t*1.4+d)*W2*.12, y=H2*(.30+((t*.11+d*.045)%0.28));ctx.fillStyle='rgba(175,240,255,.80)';ctx.beginPath();ctx.ellipse(x,y,3.5,8,0,0,Math.PI*2);ctx.fill();}
    evV46KMEZones().forEach(function(z){evV47DrawLayerOrb(z,true);});
  }
  // 3 Dua Ağacı: ayrı ağaç, dua yaprakları
  if(id===3){
    bg('#08081a','#17244c','#3d326c','#070612'); stars(100); mosque(.28); floor();
