function evRoomFxV1(ts,id){
  try{
    var t=(ts||Date.now())/1000;
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    function orb(x,y,r,c,a){ctx.globalAlpha=a; ctx.fillStyle=c; ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fill();}
    function ring(x,y,r,c,a){ctx.globalAlpha=a; ctx.strokeStyle=c; ctx.lineWidth=Math.max(1, W*.0012); ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.stroke();}
    function line(x1,y1,x2,y2,c,a,w){ctx.globalAlpha=a; ctx.strokeStyle=c; ctx.lineWidth=w||2; ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();}
    var i,x,y,p;
    if(id==='cevre'){
      // nature: drifting firefly/light motes + soft water shimmer area
      for(i=0;i<18;i++){p=(Math.sin(t*.45+i*1.7)+1)/2; x=((i*97)%1000)/1000*W + Math.sin(t*.25+i)*W*.018; y=H*(.30+((i*53)%500)/1000*.48)+Math.cos(t*.33+i)*H*.012; orb(x,y,2.2+(i%3), i%2?'#b8ff9c':'#fff2a0', .15+.18*p);}
      for(i=0;i<3;i++){ring(W*(.38+i*.07),H*(.54+i*.018),W*(.035+i*.018+Math.sin(t+i)*.004),'rgba(150,240,255,.9)',.07);}
    }else if(id==='sifa'){
      // wellness: pulse on medical green light zones
      var pulse=(Math.sin(t*1.2)+1)/2;
      for(i=0;i<9;i++){x=W*(.30+(i%3)*.22); y=H*(.22+Math.floor(i/3)*.22); orb(x,y,5+pulse*5,'#9cffb6',.05+.10*pulse);}
      ring(W*.52,H*.50,W*(.055+pulse*.015),'#b6ffd0',.10);
    }else if(id==='sanat'){
      // art: tiny paint sparkle particles
      var cols=['#ff4fd8','#ffe45c','#50e4ff','#7cff70','#ff7b50'];
      for(i=0;i<24;i++){x=((i*83)%1000)/1000*W + Math.sin(t*.6+i)*W*.012; y=H*(.28+((i*47)%520)/1000*.52)+Math.cos(t*.5+i)*H*.010; orb(x,y,2+(i%4),cols[i%cols.length],.10+.10*Math.sin(t+i));}
    }else if(id==='ders'){
      // learning: hologram points around central globe/table
      var cx=W*.50, cy=H*.50;
      for(i=0;i<12;i++){var a=t*.35+i*Math.PI*2/12; orb(cx+Math.cos(a)*W*.16, cy+Math.sin(a)*H*.10,2.5,'#80d7ff',.14);}
      ring(cx,cy,W*(.07+.006*Math.sin(t)),'#8fe8ff',.09);
    }else if(id==='mutfak'){
      // futuristic kitchen: gentle steam + neon pulses
      ctx.globalCompositeOperation='source-over';
      for(i=0;i<7;i++){x=W*(.34+i*.045); y=H*(.43-.02*Math.sin(t+i)); ctx.globalAlpha=.12; ctx.strokeStyle='rgba(255,255,255,.75)'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(x,y+H*.035); ctx.bezierCurveTo(x+Math.sin(t+i)*10,y+H*.015,x-Math.cos(t+i)*12,y,x+Math.sin(t*.7+i)*8,y-H*.035); ctx.stroke();}
      ctx.globalCompositeOperation='lighter';
      ring(W*.50,H*.70,W*(.24+.006*Math.sin(t*.8)),'#d86cff',.10);
      line(W*.15,H*.87,W*.85,H*.87,'#8ae8ff',.08,3);
    }else if(id==='aile'){
      // family futuristic lounge: holographic motes + table pulse
      var pulse=(Math.sin(t*.9)+1)/2;
      ring(W*.50,H*.62,W*(.10+pulse*.018),'#7fe6ff',.12);
      ring(W*.50,H*.62,W*(.17+pulse*.014),'#d17bff',.08);
      for(i=0;i<16;i++){x=W*(.18+((i*71)%650)/1000); y=H*(.22+((i*43)%560)/1000); orb(x+Math.sin(t+i)*8,y+Math.cos(t*.8+i)*6,2.5,'#c987ff',.12);}
    }else if(id==='ada'){
      // still island: water rings, soft calm lights
      for(i=0;i<7;i++){x=W*(.18+((i*131)%700)/1000); y=H*(.43+((i*79)%420)/1000); ring(x,y,W*(.018+.006*Math.sin(t+i)),'#8af6ff',.10);}
      for(i=0;i<10;i++){orb(W*(.25+((i*97)%560)/1000),H*(.30+((i*61)%500)/1000),3,'#b46cff',.10+.07*Math.sin(t+i));}
    }else if(id==='bilgisayar'){
      // technology: subtle hologram core + data lights
      var pulse=(Math.sin(t*1.1)+1)/2;
      ring(W*.50,H*.48,W*(.09+pulse*.018),'#50f6ff',.13);
      ring(W*.50,H*.48,W*(.16+pulse*.012),'#5cffb8',.08);
      for(i=0;i<15;i++){x=W*(.12+((i*73)%760)/1000); y=H*(.22+((i*61)%560)/1000); orb(x+Math.sin(t+i)*7,y+Math.cos(t*.8+i)*6,2.3,(i%2?'#65ffe0':'#72b8ff'),.11+.05*Math.sin(t+i));}
      line(W*.18,H*.84,W*.82,H*.84,'#62fff0',.08,3);
    }else if(id==='caliskan'){
      // gym: energy rails + target pulses
      var q=(Math.sin(t*1.4)+1)/2;
      line(W*.08,H*.86,W*.92,H*.86,'#00d8ff',.12,4);
      line(W*.12,H*.12,W*.90,H*.12,'#ffb03d',.10,3);
      ring(W*.54,H*.55,W*(.08+q*.018),'#ffb13d',.12);
      ring(W*.31,H*.42,W*(.05+q*.012),'#8b5cff',.11);
    }
    ctx.restore();
  }catch(e){ try{ctx.restore();}catch(_e){} }
}

