function evKMEV6DrawImageBackground(ts){
  try{
    var layer=1;
    try{ layer=parseInt(evV45GetKMELayer()||1,10)||1; }catch(e){}
    if(layer<1||layer>8) layer=1;
    var path='assets/kme_bg/kme_'+layer+'.webp';
    var key='EV_KME_V6_BG_'+layer;
    if(!window[key]){ window[key]=new Image(); window[key].src=path; }
    var img=window[key];
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      // Keep HUD readable without changing KME logic.
      var top=ctx.createLinearGradient(0,0,0,H*.26);
      top.addColorStop(0,'rgba(0,0,0,.28)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.26);
      var bottom=ctx.createLinearGradient(0,H*.70,0,H);
      bottom.addColorStop(0,'rgba(0,0,0,0)');
      bottom.addColorStop(1,'rgba(0,0,0,.20)');
      ctx.fillStyle=bottom; ctx.fillRect(0,H*.70,W,H*.30);
      // Subtle living light particles, background only.
      var t=(ts||Date.now())/1000;
      ctx.save(); ctx.globalCompositeOperation='lighter';
      for(var i=0;i<18;i++){
        var x=W*(.08+((i*67)%840)/1000)+Math.sin(t*.35+i)*W*.010;
        var y=H*(.15+((i*41)%650)/1000)+Math.cos(t*.45+i)*H*.008;
        var a=.07+.08*Math.abs(Math.sin(t+i));
        ctx.fillStyle=(i%3===0)?'rgba(255,224,130,'+a+')':((i%3===1)?'rgba(160,230,255,'+a+')':'rgba(210,150,255,'+a+')');
        ctx.beginPath(); ctx.arc(x,y,2+(i%3),0,Math.PI*2); ctx.fill();
      }
      ctx.restore();
      return;
    }
  }catch(e){}
  try{ evV43DrawKucukMeleklerEvi(ts); }catch(e2){}
}

