function drawRoomDeco(ts,id){
  // Stars for dark rooms
  // ─── İBADET ODASI - Selimiye tarzı cami içi + Esmaül Hüsna ───
  if(id==='ibadet' && evValuesOn && evValuesOn()){
    var bgPath='assets/room_bg/sakinlik1.webp';
    if(!window.EV_SAKINLIK1_BG){
      window.EV_SAKINLIK1_BG=new Image();
      window.EV_SAKINLIK1_BG.src=bgPath;
    }
    var img=window.EV_SAKINLIK1_BG;
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.24);
      top.addColorStop(0,'rgba(0,0,0,.20)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top;
      ctx.fillRect(0,0,W,H*.25);
      var calm=ctx.createRadialGradient(W*.50,H*.62,H*.04,W*.50,H*.62,W*.40);
      calm.addColorStop(0,'rgba(255,238,210,.07)');
      calm.addColorStop(1,'rgba(255,238,210,0)');
      ctx.fillStyle=calm;
      ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#d9c5aa'); g.addColorStop(.55,'#c8a985'); g.addColorStop(1,'#8e6c4c');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
          if(id==='ders'){
    evRoomFxV1(ts,'ders'); // EV_DERS_FX_ISOLATION_V2
}else{
    evRoomFxV1(ts,'cevre');
    evRoomFxV1(ts,'sifa');
    evRoomFxV1(ts,'ders');
    evRoomFxV1(ts,'ada');
    evRoomFxV1(ts,'caliskan');
    evRoomFxV1(ts,'mutfak');
    evRoomFxV1(ts,'sanat');
}
      return;
  }
  if(id==='kucukmelekler'){ evKMEV6DrawImageBackground(ts); return; }


  // KALAN3 approved futuristic backgrounds: music, world/discovery, reward.
  // Only background changes; existing room systems, language, balls, HUD, music and rewards stay intact.
  if(id==='muzik'||id==='atlas'||id==='odulodasi'){
    var map={muzik:'muzik1',atlas:'atlas1',odulodasi:'odul1'};
    var key=map[id]||'muzik1';
    var bgPath='assets/room_bg/'+key+'.webp';
    var cacheKey='EV_KALAN3_'+key.toUpperCase();
    if(!window[cacheKey]){ window[cacheKey]=new Image(); window[cacheKey].src=bgPath; }
    var img=window[cacheKey];
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.25);
      top.addColorStop(0,'rgba(0,0,0,.24)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.26);
      var glow=ctx.createRadialGradient(W*.50,H*.53,H*.02,W*.50,H*.53,W*.42);
      if(id==='muzik'){
        glow.addColorStop(0,'rgba(185,80,255,.08)'); glow.addColorStop(.55,'rgba(70,180,255,.04)');
      }else if(id==='atlas'){
        glow.addColorStop(0,'rgba(80,210,255,.08)'); glow.addColorStop(.55,'rgba(40,120,255,.04)');
      }else{
        glow.addColorStop(0,'rgba(255,205,70,.08)'); glow.addColorStop(.55,'rgba(100,180,255,.035)');
      }
      glow.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      if(id==='muzik'){ g.addColorStop(0,'#050018'); g.addColorStop(.55,'#180044'); g.addColorStop(1,'#020009'); }
      else if(id==='atlas'){ g.addColorStop(0,'#031126'); g.addColorStop(.55,'#07396b'); g.addColorStop(1,'#010713'); }
      else { g.addColorStop(0,'#180b00'); g.addColorStop(.55,'#533500'); g.addColorStop(1,'#060200'); }
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    try{ if(typeof evRoomFxV1==='function') evRoomFxV1(ts,id); }catch(e){}
    return;
  }


  // TEKNOLOJI1 approved futuristic technology laboratory background.
  // Only background changes; existing robot/code/balloon systems stay intact.
  if(id==='bilgisayar'){
    var bgPath='assets/room_bg/teknoloji1.webp';
    if(!window.EV_TEKNOLOJI1_BG){ window.EV_TEKNOLOJI1_BG=new Image(); window.EV_TEKNOLOJI1_BG.src=bgPath; }
    var img=window.EV_TEKNOLOJI1_BG;
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.25);
      top.addColorStop(0,'rgba(0,0,0,.20)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.26);
      var glow=ctx.createRadialGradient(W*.50,H*.50,H*.02,W*.50,H*.50,W*.45);
      glow.addColorStop(0,'rgba(60,255,220,.07)');
      glow.addColorStop(.45,'rgba(70,180,255,.045)');
      glow.addColorStop(1,'rgba(70,180,255,0)');
      ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#03121f'); g.addColorStop(.55,'#062a3a'); g.addColorStop(1,'#020611');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    try{ if(typeof evRoomFxV1==='function') evRoomFxV1(ts,'bilgisayar'); }catch(e){}
    return;
  }

  // DILLER1 language room approved backgrounds
  // Four language rooms: only background changes; existing language/game systems stay intact.
  if(id==='english'||id==='deutsch'||id==='francais'||id==='arapca'){
    var langMap={english:'english1',deutsch:'deutsch1',francais:'francais1',arapca:'arapca1'};
    var key=langMap[id]||'english1';
    var bgPath='assets/room_bg/'+key+'.webp';
    var cacheKey='EV_LANGROOM_'+key.toUpperCase();
    if(!window[cacheKey]){ window[cacheKey]=new Image(); window[cacheKey].src=bgPath; }
    var img=window[cacheKey];
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.24);
      top.addColorStop(0,'rgba(0,0,0,.25)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.25);
      var glow=ctx.createRadialGradient(W*.50,H*.50,H*.03,W*.50,H*.50,W*.42);
      glow.addColorStop(0,'rgba(95,210,255,.08)');
      glow.addColorStop(1,'rgba(95,210,255,0)');
      ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#06142d'); g.addColorStop(.55,'#102d5a'); g.addColorStop(1,'#050711');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    return;
  }


  // IBADET1 approved futuristic Islamic background.
  // Only background changes; existing ibadet mode remains. Esmaül Hüsna rain continues here.
  if(id==='ibadet' && !(evValuesOn&&evValuesOn())){
    var bgPath='assets/room_bg/ibadet1.webp';
    if(!window.EV_IBADET1_BG){ window.EV_IBADET1_BG=new Image(); window.EV_IBADET1_BG.src=bgPath; }
    var img=window.EV_IBADET1_BG;
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.25);
      top.addColorStop(0,'rgba(0,0,0,.22)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.25);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#11070a'); g.addColorStop(.55,'#1c1208'); g.addColorStop(1,'#070304');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    // Esmaül Hüsna rain — room signature effect kept for İbadet mode.
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    var ESMA=['الرَّحْمٰن','الرَّحِيم','الْمَلِك','الْقُدُّوس','السَّلَام','الْمُؤْمِن','الْمُهَيْمِن','الْعَزِيز','الْجَبَّار','الْمُتَكَبِّر','الْخَالِق','الْبَارِئ','الْمُصَوِّر','الْغَفَّار','الْقَهَّار','الْوَهَّاب','الرَّزَّاق','الْفَتَّاح','الْعَلِيم','الْقَابِض','الْبَاسِط','السَّمِيع','الْبَصِير','الْحَكَم'];
    for(var es=0;es<28;es++){
      var esx=W*((es*37)%100)/100 + Math.sin(ts*.0007+es)*W*.018;
      var esy=((es*H*.073 + ts*.020 + es*31)%(H*.92))+H*.02;
      var a=.16+Math.sin(ts*.0012+es)*.08;
      ctx.fillStyle='rgba(255,210,80,'+a+')';
      ctx.font='bold '+Math.round(H*(.022+(es%3)*.004))+'px serif';
      ctx.textAlign='center';
      ctx.shadowColor='rgba(255,190,40,.55)';
      ctx.shadowBlur=12;
      ctx.fillText(ESMA[es%ESMA.length],esx,esy);
      ctx.shadowBlur=0;
      ctx.globalAlpha=.20;
      ctx.fillStyle='rgba(255,220,120,.28)';
      ctx.fillRect(esx-1,esy-H*.055,2,H*.040);
      ctx.globalAlpha=1;
    }
    ctx.restore();
