    stageGlow.addColorStop(.72,'rgba(160,120,255,.06)');
    stageGlow.addColorStop(1,'transparent');
    ctx.fillStyle=stageGlow; ctx.fillRect(0,0,W,H);

    // Tavandan hareketli ışık huzmeleri
    for(var beam=0;beam<5;beam++){
      var bx=W*(.18+beam*.16)+Math.sin(t*.35+beam)*W*.018;
      var topW=W*.026;
      var botW=W*(.10+beam*.010);
      var alpha=.055+.045*Math.abs(Math.sin(t*.75+beam));
      var grad=ctx.createLinearGradient(bx,0,W*.50,floorY);
      grad.addColorStop(0,'rgba(255,230,150,'+alpha+')');
      grad.addColorStop(1,'rgba(255,230,150,0)');
      ctx.fillStyle=grad;
      ctx.beginPath();
      ctx.moveTo(bx-topW,0);
      ctx.lineTo(bx+topW,0);
      ctx.lineTo(W*.50+botW*(beam-2)*.18,floorY);
      ctx.lineTo(W*.50-botW*(beam-2)*.18,floorY);
      ctx.closePath();
      ctx.fill();
    }

    // Uzak duvar yıldızları
    for(var st=0;st<80;st++){
      var sx=(st*173)%W;
      var sy=(st*91)%(H*.52)+H*.04;
      var al=.07+.20*Math.abs(Math.sin(t*.9+st));
      ctx.fillStyle=st%5===0?'rgba(255,220,120,'+al+')':'rgba(230,225,255,'+al+')';
      ctx.beginPath(); ctx.arc(sx,sy,st%9===0?1.9:.75,0,Math.PI*2); ctx.fill();
    }

    // Arka başarı kemeri
    var archX=W*.50, archY=H*.42, archW=W*.72, archH=H*.50;
    ctx.strokeStyle='rgba(255,215,120,.20)';
    ctx.lineWidth=Math.max(4,W*.010);
    ctx.beginPath();
    ctx.arc(archX,archY,archW*.36,Math.PI*1.05,Math.PI*1.95);
    ctx.stroke();
    ctx.strokeStyle='rgba(180,145,255,.18)';
    ctx.lineWidth=Math.max(2,W*.006);
    ctx.beginPath();
    ctx.arc(archX,archY+H*.02,archW*.30,Math.PI*1.08,Math.PI*1.92);
    ctx.stroke();

    // 2.5D salon zemini
    var floor=ctx.createLinearGradient(0,floorY-H*.08,0,H);
    floor.addColorStop(0,'rgba(112,70,36,.82)');
    floor.addColorStop(.50,'rgba(65,39,34,.93)');
    floor.addColorStop(1,'rgba(18,10,14,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
    ctx.lineTo(W*.50,H*.56);
    ctx.lineTo(W*.96,floorY);
    ctx.lineTo(W*.82,H);
    ctx.lineTo(W*.18,H);
    ctx.closePath(); ctx.fill();

    // Zemin parlayan başarı yolu
    var path=ctx.createLinearGradient(W*.5,H*.56,W*.5,H);
    path.addColorStop(0,'rgba(255,225,120,.36)');
    path.addColorStop(.50,'rgba(180,105,58,.42)');
    path.addColorStop(1,'rgba(80,45,35,.64)');
    ctx.fillStyle=path;
    ctx.beginPath();
    ctx.moveTo(W*.47,H*.56);
    ctx.lineTo(W*.53,H*.56);
    ctx.lineTo(W*.69,H);
    ctx.lineTo(W*.31,H);
    ctx.closePath(); ctx.fill();

    // Zemin yıldız basamakları
    function drawStar(cx,cy,r,fill,rot){
      ctx.save();
      ctx.translate(cx,cy);
      ctx.rotate(rot||0);
      ctx.fillStyle=fill;
      ctx.beginPath();
      for(var i=0;i<10;i++){
        var a=-Math.PI/2+i*Math.PI/5;
        var rr=i%2===0?r:r*.44;
        var x=Math.cos(a)*rr, y=Math.sin(a)*rr;
        if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
      }
      ctx.closePath(); ctx.fill();
      ctx.restore();
    }
    for(var step=0;step<8;step++){
      var k=step/7;
      var x=W*.50+Math.sin(k*5+t*.25)*W*.035;
      var y=H*(.62+k*.33);
      drawStar(x,y,Math.min(W,H)*(.012+k*.006),'rgba(255,220,110,'+(.22+k*.10)+')',t*.4+step);
    }

    // Orta ödül sandığı
    var chestX=W*.50, chestY=H*.63, chestW=W*.30, chestH=H*.16;
    ctx.fillStyle='rgba(0,0,0,.30)';
    ctx.beginPath(); ctx.ellipse(chestX,chestY+chestH*.60,chestW*.62,chestH*.22,0,0,Math.PI*2); ctx.fill();

    // Sandık gövdesi
    var chestBody=ctx.createLinearGradient(chestX-chestW*.5,chestY,chestX+chestW*.5,chestY+chestH);
    chestBody.addColorStop(0,'#7a421c');
    chestBody.addColorStop(.45,'#c47b2d');
    chestBody.addColorStop(1,'#4a2414');
    ctx.fillStyle=chestBody;
    ctx.beginPath(); ctx.roundRect(chestX-chestW*.5,chestY,chestW,chestH*.60,12); ctx.fill();

    // Sandık kapağı hafif açık ve nefes alır gibi parlıyor
    var lidLift=Math.sin(t*1.4)*H*.004;
    var lid=ctx.createLinearGradient(chestX-chestW*.5,chestY-chestH*.18+lidLift,chestX+chestW*.5,chestY+chestH*.12+lidLift);
    lid.addColorStop(0,'#9e5722');
    lid.addColorStop(.45,'#efaa45');
    lid.addColorStop(1,'#5b2b16');
    ctx.fillStyle=lid;
    ctx.beginPath();
    ctx.moveTo(chestX-chestW*.50,chestY+H*.005+lidLift);
    ctx.quadraticCurveTo(chestX,chestY-chestH*.34+lidLift,chestX+chestW*.50,chestY+H*.005+lidLift);
    ctx.lineTo(chestX+chestW*.50,chestY+chestH*.18+lidLift);
    ctx.quadraticCurveTo(chestX,chestY-chestH*.10+lidLift,chestX-chestW*.50,chestY+chestH*.18+lidLift);
    ctx.closePath(); ctx.fill();

    // Metal şeritler
    ctx.strokeStyle='rgba(255,225,130,.72)';
    ctx.lineWidth=4;
    ctx.beginPath(); ctx.moveTo(chestX-chestW*.32,chestY-chestH*.03+lidLift); ctx.lineTo(chestX-chestW*.32,chestY+chestH*.55); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(chestX+chestW*.32,chestY-chestH*.03+lidLift); ctx.lineTo(chestX+chestW*.32,chestY+chestH*.55); ctx.stroke();
    ctx.strokeStyle='rgba(255,225,130,.55)';
    ctx.lineWidth=3;
    ctx.beginPath(); ctx.moveTo(chestX-chestW*.48,chestY+chestH*.30); ctx.lineTo(chestX+chestW*.48,chestY+chestH*.30); ctx.stroke();

    // Kilit
    ctx.fillStyle='rgba(255,215,90,.88)';
    ctx.beginPath(); ctx.roundRect(chestX-W*.024,chestY+chestH*.22,W*.048,H*.040,6); ctx.fill();
    ctx.fillStyle='rgba(80,45,20,.72)';
    ctx.beginPath(); ctx.arc(chestX,chestY+chestH*.240,3,0,Math.PI*2); ctx.fill();

    // Sandıktan çıkan ışık
    var chestGlow=ctx.createRadialGradient(chestX,chestY-H*.02,0,chestX,chestY-H*.02,H*.30);
    chestGlow.addColorStop(0,'rgba(255,230,120,.34)');
    chestGlow.addColorStop(.35,'rgba(255,180,80,.18)');
    chestGlow.addColorStop(1,'transparent');
    ctx.fillStyle=chestGlow; ctx.fillRect(chestX-W*.35,chestY-H*.34,W*.70,H*.60);

    // Sandık üstünden çıkan yıldız parçacıkları
    for(var sp=0;sp<26;sp++){
      var px=chestX+Math.sin(t*.9+sp*1.7)*W*(.025+(sp%5)*.012);
      var py=chestY-H*(.02+(sp%8)*.033)-((t*.025+sp*.009)%0.18)*H;
      var al=.10+.24*Math.abs(Math.sin(t*1.7+sp));
      drawStar(px,py,Math.min(W,H)*(.006+(sp%3)*.002),'rgba(255,220,105,'+al+')',t+sp);
    }

    // Sol ve sağ kupa heykelleri
    function trophy(x,y,s,phase){
      ctx.save();
      ctx.translate(x,y);
      var shine=Math.sin(t*2.0+phase);
      ctx.fillStyle='rgba(0,0,0,.20)';
      ctx.beginPath(); ctx.ellipse(0,s*.80,s*.80,s*.18,0,0,Math.PI*2); ctx.fill();

      var g=ctx.createLinearGradient(-s,-s,s,s);
      g.addColorStop(0,'#9f6b1e');
      g.addColorStop(.35,'#ffe08a');
      g.addColorStop(.62,'#d49a2e');
      g.addColorStop(1,'#7a4a18');
      ctx.fillStyle=g;

      // kupa gövde
      ctx.beginPath();
      ctx.moveTo(-s*.42,-s*.38);
      ctx.lineTo(s*.42,-s*.38);
      ctx.quadraticCurveTo(s*.34,s*.18,0,s*.34);
      ctx.quadraticCurveTo(-s*.34,s*.18,-s*.42,-s*.38);
      ctx.fill();

      // kulplar
      ctx.strokeStyle='#d9a437';
      ctx.lineWidth=s*.12;
      ctx.beginPath(); ctx.arc(-s*.46,-s*.16,s*.28,Math.PI*.45,Math.PI*1.55); ctx.stroke();
      ctx.beginPath(); ctx.arc(s*.46,-s*.16,s*.28,-Math.PI*.55,Math.PI*.55); ctx.stroke();

      // ayak
      ctx.fillStyle='#b87924';
      ctx.fillRect(-s*.14,s*.30,s*.28,s*.25);
      ctx.fillRect(-s*.42,s*.55,s*.84,s*.18);

      // üstten geçen ışık
      ctx.globalAlpha=.25+.12*Math.max(0,shine);
      ctx.fillStyle='white';
      ctx.beginPath();
      ctx.ellipse(-s*.12,-s*.18,s*.12,s*.35,-.45,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
    trophy(W*.22,H*.62,Math.min(W,H)*.070,1);
    trophy(W*.78,H*.62,Math.min(W,H)*.070,3);

    // Hareketli rozetler
    var badges=[
      [.20,.38,'1'],[.33,.30,'★'],[.67,.30,'✓'],[.80,.39,'+']
    ];
    badges.forEach(function(b,i){
      var x=W*b[0]+Math.sin(t*.9+i)*W*.010;
      var y=H*b[1]+Math.cos(t*.75+i)*H*.010;
      var r=Math.min(W,H)*.034;
      var rot=t*.35+i;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(rot*.25);
      ctx.fillStyle='rgba(255,210,90,.78)';
      ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='rgba(255,245,190,.50)';
      ctx.lineWidth=2;
      ctx.beginPath(); ctx.arc(0,0,r*.78,0,Math.PI*2); ctx.stroke();
      ctx.fillStyle='rgba(70,38,20,.82)';
      ctx.font='bold '+Math.round(r*.86)+'px Fredoka One';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(b[2],0,1);
      ctx.restore();
    });

    // Dönen büyük yıldız halkası
    for(var rs=0;rs<10;rs++){
      var a=t*.55+rs*Math.PI*2/10;
      var rx=W*.50+Math.cos(a)*W*.32;
      var ry=H*.42+Math.sin(a)*H*.13;
      var scale=.70+.30*(Math.sin(a)+1)/2;
      drawStar(rx,ry,Math.min(W,H)*.020*scale,'rgba(255,220,120,'+(.18+.22*scale)+')',a+t);
    }

    // Konfeti parçacıkları
    var confCols=['rgba(255,115,115,.45)','rgba(255,220,100,.45)','rgba(120,220,255,.40)','rgba(180,140,255,.42)'];
    for(var cf=0;cf<42;cf++){
      var x2=W*((cf*0.061)%1);
      var y2=H*((cf*0.037+t*.025)%0.72)+H*.06;
      ctx.save();
      ctx.translate(x2+Math.sin(t+cf)*W*.010,y2);
      ctx.rotate(t+cf);
      ctx.fillStyle=confCols[cf%confCols.length];
      ctx.fillRect(-2,-5,4,10);
      ctx.restore();
    }

    // Başlık levhası
    ctx.save();
    ctx.translate(W*.50,H*.095);
    ctx.fillStyle='rgba(18,10,28,.72)';
    ctx.strokeStyle='rgba(255,220,120,.36)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.22,-H*.033,W*.44,H*.066,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,235,170,.95)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var label=(evValuesOn()&&evValuesLang()==='en')?'REWARD ROOM':(evValuesOn()&&evValuesLang()==='de')?'BELOHNUNGSRAUM':(evValuesOn()&&evValuesLang()==='fr')?'SALLE DES RECOMPENSES':(evValuesOn()&&evValuesLang()==='ar')?'غرفة المكافأة':'ÖDÜL ODASI';
    ctx.fillText(label,0,0);
    ctx.restore();

    // Alt kısa mesaj
    ctx.save();
    ctx.fillStyle='rgba(255,235,190,.80)';
    ctx.font=Math.round(Math.min(W,H)*.021)+'px Fredoka One';
    ctx.textAlign='center';
    var sub=(evValuesOn()&&evValuesLang()==='en')?'Every effort leaves a light.':(evValuesOn()&&evValuesLang()==='de')?'Jede Mühe hinterlässt Licht.':(evValuesOn()&&evValuesLang()==='fr')?'Chaque effort laisse une lumière.':(evValuesOn()&&evValuesLang()==='ar')?'كل جهد يترك نوراً':'Her emek bir ışık bırakır.';
    ctx.fillText(sub,W*.5,H*.93);
    ctx.restore();

    return;
  }


  // ─── HAYVANAT / SAFARI ODASI ───
  if(id==='hayvanat'){
    // SAFARI1: yazısız fütüristik bio-dome safari gözlem odası.
    // Kod/sistem korunur; sadece oda arka planı değişir.
    var bgPath='assets/room_bg/safari1.webp';
    if(!window.EV_SAFARI1_BG){
      window.EV_SAFARI1_BG=new Image();
      window.EV_SAFARI1_BG.src=bgPath;
    }
    var img=window.EV_SAFARI1_BG;
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.26);
      top.addColorStop(0,'rgba(0,0,0,.25)');
