      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.27);
      var center=ctx.createRadialGradient(W*.50,H*.62,H*.03,W*.50,H*.62,W*.52);
      center.addColorStop(0,'rgba(120,255,160,.06)');
      center.addColorStop(1,'rgba(120,255,160,0)');
      ctx.fillStyle=center; ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#082617'); g.addColorStop(.55,'#1a5c2a'); g.addColorStop(1,'#06130b');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    try{ if(typeof evRoomFxV1==='function') evRoomFxV1(ts,'hayvanat'); }catch(e){}
    return;
  }

  
    // ─── MÜZİK ODASI ───
  if(id==='muzik'){
    // EXPERIMENT V33: CANLI MÜZİK STÜDYOSU
    // Kritik kural: Piyanoya düşen nota / mevcut piyano sesi korunur.
    // Bu blok sadece sahne görselini büyütür. Ses motoru ve nota tıklama sistemi değiştirilmez.
    var t=ts*.001;
    var stageY=H*.74;

    // Derin konser salonu arka planı
    var bg=ctx.createRadialGradient(W*.50,H*.42,H*.04,W*.50,H*.50,H*.82);
    bg.addColorStop(0,'#3c0b78');
    bg.addColorStop(.32,'#180035');
    bg.addColorStop(.70,'#070016');
    bg.addColorStop(1,'#020006');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    // Sahne ışık perdeleri
    function beam(x,ang,col,alpha){
      ctx.save();
      ctx.globalAlpha=alpha;
      ctx.translate(x,0);
      ctx.rotate(ang);
      var g=ctx.createLinearGradient(0,0,0,H*.82);
      g.addColorStop(0,col);
      g.addColorStop(1,'transparent');
      ctx.fillStyle=g;
      ctx.beginPath();
      ctx.moveTo(-W*.035,0);
      ctx.lineTo(W*.035,0);
      ctx.lineTo(W*.20,H*.82);
      ctx.lineTo(-W*.20,H*.82);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    beam(W*.18,-.17,'rgba(80,200,255,.42)',.42+.08*Math.sin(t));
    beam(W*.36,-.06,'rgba(255,80,220,.34)',.38+.08*Math.cos(t*.8));
    beam(W*.64,.06,'rgba(255,215,100,.36)',.40+.08*Math.sin(t*.7));
    beam(W*.82,.17,'rgba(135,90,255,.38)',.38+.08*Math.cos(t));

    // Yıldızlı sahne perdesi
    for(var s=0;s<140;s++){
      var sx=(s*197+19)%W;
      var sy=(s*113+7)%(H*.70);
      var tw=.45+.55*Math.sin(t*(1.1+(s%5)*.02)+s);
      ctx.fillStyle=s%4===0?'rgba(255,225,150,'+(.18+tw*.45)+')':(s%4===1?'rgba(140,220,255,'+(.16+tw*.38)+')':'rgba(255,255,255,'+(.12+tw*.32)+')');
      ctx.beginPath(); ctx.arc(sx,sy,s%17===0?1.8:.7,0,Math.PI*2); ctx.fill();
    }

    // Sahne zemini
    var floor=ctx.createLinearGradient(0,stageY-H*.05,0,H);
    floor.addColorStop(0,'rgba(85,40,125,.80)');
    floor.addColorStop(.50,'rgba(43,18,75,.96)');
    floor.addColorStop(1,'rgba(10,3,25,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.05,stageY);
    ctx.lineTo(W*.95,stageY);
    ctx.lineTo(W*.82,H);
    ctx.lineTo(W*.18,H);
    ctx.closePath();
    ctx.fill();

    // Zemin perspektif çizgileri
    ctx.strokeStyle='rgba(255,220,150,.12)';
    ctx.lineWidth=1.2;
    for(var g=0;g<9;g++){
      var gx=W*(.12+g*.095);
      ctx.beginPath(); ctx.moveTo(gx,H); ctx.lineTo(W*.50,stageY); ctx.stroke();
    }
    for(var gy=0;gy<5;gy++){
      var yy=stageY+gy*H*.045;
      ctx.beginPath(); ctx.moveTo(W*.10,yy); ctx.lineTo(W*.90,yy); ctx.stroke();
    }

    // Büyük konser piyanosu - asıl kalp
    var pX=W*.50, pY=H*.68, pW=W*.50, pH=H*.16;
    ctx.save();
    ctx.translate(pX,pY);
    // gölge
    ctx.fillStyle='rgba(0,0,0,.34)';
    ctx.beginPath(); ctx.ellipse(0,pH*.70,pW*.56,pH*.20,0,0,Math.PI*2); ctx.fill();

    // piano gövde
    var body=ctx.createLinearGradient(-pW*.48,-pH*.52,pW*.48,pH*.55);
    body.addColorStop(0,'#050508');
    body.addColorStop(.34,'#19142d');
    body.addColorStop(.72,'#050508');
    body.addColorStop(1,'#2b2250');
    ctx.fillStyle=body;
    ctx.strokeStyle='rgba(255,235,170,.34)';
    ctx.lineWidth=2;
    ctx.beginPath();
    ctx.roundRect(-pW*.48,-pH*.46,pW*.96,pH*.78,26);
    ctx.fill(); ctx.stroke();

    // Kapak
    ctx.fillStyle='rgba(25,18,45,.92)';
    ctx.beginPath();
    ctx.moveTo(-pW*.44,-pH*.43);
    ctx.quadraticCurveTo(-pW*.10,-pH*.90,pW*.42,-pH*.42);
    ctx.quadraticCurveTo(pW*.18,-pH*.22,-pW*.44,-pH*.20);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle='rgba(255,230,150,.24)'; ctx.stroke();

    // Tuş takımı
    var keyY=pH*.05, keyW=pW*.060, keyH=pH*.23;
    ctx.fillStyle='rgba(250,250,250,.96)';
    ctx.beginPath(); ctx.roundRect(-pW*.36,keyY,pW*.72,keyH,8); ctx.fill();
    for(var k=0;k<12;k++){
      var x=-pW*.34+k*(pW*.68/12);
      ctx.strokeStyle='rgba(25,25,30,.22)';
      ctx.beginPath(); ctx.moveTo(x,keyY); ctx.lineTo(x,keyY+keyH); ctx.stroke();
      if(k%2===1 || k===6 || k===9){
        ctx.fillStyle='rgba(12,12,18,.92)';
        ctx.beginPath(); ctx.roundRect(x-keyW*.24,keyY,keyW*.48,keyH*.58,4); ctx.fill();
      }
    }

    // Nota vurduğunda görsel ışık/pulse
    var pulse=window._v33MusicPulse;
    if(pulse && Date.now()-pulse.t<900){
      var age=(Date.now()-pulse.t)/900;
      var rr=Math.min(W,H)*(.04+age*.16);
      ctx.save();
      ctx.globalAlpha=1-age;
      ctx.strokeStyle='rgba(255,230,120,.85)';
      ctx.lineWidth=3;
      ctx.beginPath(); ctx.ellipse(0,keyY+keyH*.45,rr,rr*.34,0,0,Math.PI*2); ctx.stroke();
      ctx.fillStyle='rgba(255,230,120,.85)';
      ctx.font='bold '+Math.round(Math.min(W,H)*(.026+age*.018))+'px serif';
      ctx.fillText(pulse.note||'♪',0,-pH*.78-age*H*.045);
      ctx.restore();
    }

    // Piyano ayakları
    ctx.fillStyle='rgba(5,5,9,.95)';
    ctx.fillRect(-pW*.35,pH*.29,pW*.040,pH*.48);
    ctx.fillRect(pW*.30,pH*.29,pW*.040,pH*.48);
    ctx.restore();

    // Üstten düşen dekoratif notalar - gerçek ses mevcut oyun notalarında kalır
    var noteChars=['♪','♫','♩','♬','𝄞','♭','♯'];
    ctx.textAlign='center'; ctx.textBaseline='middle';
    for(var n=0;n<42;n++){
      var nx=(n*97+Math.sin(t*.6+n)*38)%W;
      var ny=((n*53+t*(28+(n%5)*7))%(H*.74));
      var ns=Math.round(Math.min(W,H)*(.024+(n%4)*.007));
