    ctx.fillStyle=rg;
    ctx.strokeStyle='rgba(230,250,255,.55)';
    ctx.beginPath(); ctx.roundRect(-W*.042,-H*.052,W*.084,H*.092,13); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(0,20,50,.86)';
    ctx.beginPath(); ctx.arc(-W*.015,-H*.020,3.3,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(W*.015,-H*.020,3.3,0,Math.PI*2); ctx.fill();
