    ctx.beginPath(); ctx.arc(aiX,aiY,aiR,0,Math.PI*2); ctx.stroke();

    // AI çekirdeği etrafında dönen mini semboller
    var syms=['{','}','0','1','<','>'];
    ctx.font='bold '+Math.round(Math.min(W,H)*.018)+'px monospace';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    for(var si=0;si<syms.length;si++){
      var a=t*.95+si*Math.PI*2/syms.length;
      var rx=aiX+Math.cos(a)*aiR*1.75;
      var ry=aiY+Math.sin(a)*aiR*.78;
      ctx.fillStyle=si%2?'rgba(110,255,170,.82)':'rgba(120,225,255,.78)';
      ctx.fillText(syms[si],rx,ry);
    }

    // 2.5D teknoloji zemini
    var floor=ctx.createLinearGradient(0,floorY-H*.07,0,H);
    floor.addColorStop(0,'rgba(18,70,55,.78)');
    floor.addColorStop(.48,'rgba(12,42,38,.92)');
    floor.addColorStop(1,'rgba(2,8,10,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
    ctx.lineTo(W*.50,H*.56);
    ctx.lineTo(W*.96,floorY);
    ctx.lineTo(W*.82,H);
    ctx.lineTo(W*.18,H);
    ctx.closePath(); ctx.fill();

    // Devre ızgarası
    ctx.strokeStyle='rgba(80,255,165,.13)';
    ctx.lineWidth=1;
    for(var gx=0;gx<9;gx++){
      var xx=W*(.10+gx*.10);
      ctx.beginPath(); ctx.moveTo(xx,H); ctx.lineTo(W*.50,H*.56); ctx.stroke();
    }
    for(var gy=0;gy<7;gy++){
      var yy=floorY+gy*H*.038;
      ctx.beginPath(); ctx.moveTo(W*.08,yy); ctx.lineTo(W*.92,yy); ctx.stroke();
    }

    // Devre ışıkları hareket ediyor
    for(var p=0;p<18;p++){
      var k=(t*.18+p*.071)%1;
      var sx=W*.18+(p%6)*W*.12;
      var sy=H*.86;
      var ex=W*.50;
      var ey=H*.58;
      var px=sx+(ex-sx)*k;
      var py=sy+(ey-sy)*k;
      ctx.fillStyle='rgba(110,255,170,.55)';
      ctx.beginPath(); ctx.arc(px,py,2.2+(p%3)*.4,0,Math.PI*2); ctx.fill();
    }

    // Klavye / kod masası
    var deskX=W*.50, deskY=H*.69, deskW=W*.46, deskH=H*.095;
    ctx.fillStyle='rgba(0,0,0,.30)';
    ctx.beginPath(); ctx.ellipse(deskX,deskY+deskH*.64,deskW*.58,deskH*.23,0,0,Math.PI*2); ctx.fill();

    var desk=ctx.createLinearGradient(deskX-deskW*.5,deskY-deskH*.5,deskX+deskW*.5,deskY+deskH*.5);
    desk.addColorStop(0,'#102d32');
    desk.addColorStop(.50,'#2b6870');
    desk.addColorStop(1,'#07191d');
    ctx.fillStyle=desk;
    ctx.beginPath(); ctx.roundRect(deskX-deskW*.5,deskY-deskH*.5,deskW,deskH,16); ctx.fill();

    // Klavye tuşları
    for(var ky=0;ky<3;ky++){
      for(var kx=0;kx<10;kx++){
        var xk=deskX-deskW*.38+kx*deskW*.080;
        var yk=deskY-deskH*.20+ky*deskH*.22;
        var al=.16+.12*Math.abs(Math.sin(t*2+kx+ky));
        ctx.fillStyle='rgba(170,255,210,'+al+')';
        ctx.beginPath(); ctx.roundRect(xk,yk,deskW*.045,deskH*.09,3); ctx.fill();
      }
    }

    // Sol robot yardımcı
    var robotX=W*.23, robotY=H*.70;
    ctx.save();
    ctx.translate(robotX,robotY+Math.sin(t*1.5)*H*.006);
    ctx.fillStyle='rgba(0,0,0,.22)';
    ctx.beginPath(); ctx.ellipse(0,H*.062,W*.075,H*.018,0,0,Math.PI*2); ctx.fill();

    var rb=ctx.createLinearGradient(-W*.045,-H*.065,W*.045,H*.060);
    rb.addColorStop(0,'#6ee7b7');
    rb.addColorStop(.50,'#d9fff1');
    rb.addColorStop(1,'#218a63');
    ctx.fillStyle=rb;
    ctx.beginPath(); ctx.roundRect(-W*.045,-H*.030,W*.090,H*.085,12); ctx.fill();

    ctx.fillStyle='rgba(210,255,240,.94)';
    ctx.beginPath(); ctx.roundRect(-W*.040,-H*.095,W*.080,H*.052,10); ctx.fill();

    // Robot gözleri
    var blink=(Math.sin(t*2.4)>0.94);
    ctx.fillStyle='rgba(3,35,28,.94)';
    if(blink){
      ctx.fillRect(-W*.023,-H*.073,W*.016,2);
      ctx.fillRect(W*.008,-H*.073,W*.016,2);
    }else{
      ctx.beginPath(); ctx.arc(-W*.014,-H*.073,3.2,0,Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(W*.018,-H*.073,3.2,0,Math.PI*2); ctx.fill();
    }

    // Robot anten
    ctx.strokeStyle='rgba(120,255,180,.80)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(0,-H*.095); ctx.lineTo(0,-H*.126); ctx.stroke();
    ctx.fillStyle='rgba(255,235,120,.90)';
    ctx.beginPath(); ctx.arc(0,-H*.134,4+Math.sin(t*4)*1.2,0,Math.PI*2); ctx.fill();

    // Robot kolu veri küpüne uzanıyor
    ctx.strokeStyle='rgba(215,255,240,.86)';
    ctx.lineWidth=5;
    ctx.lineCap='round';
    ctx.beginPath(); ctx.moveTo(W*.043,-H*.006); ctx.lineTo(W*.085,-H*.040+Math.sin(t*2)*H*.007); ctx.stroke();
    ctx.fillStyle='rgba(120,255,180,.88)';
    ctx.beginPath(); ctx.arc(W*.090,-H*.040+Math.sin(t*2)*H*.007,4,0,Math.PI*2); ctx.fill();
    ctx.restore();

    // Uçan veri küpleri
    function cube(x,y,s,phase){
      ctx.save();
      ctx.translate(x,y+Math.sin(t*1.1+phase)*H*.012);
      ctx.rotate(Math.sin(t*.6+phase)*.10);
      var a=s*.55;
      ctx.fillStyle='rgba(80,255,170,.20)';
      ctx.strokeStyle='rgba(130,255,190,.55)';
      ctx.lineWidth=2;
      ctx.beginPath(); ctx.rect(-a,-a,a*2,a*2); ctx.fill(); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-a,-a); ctx.lineTo(-a*.35,-a*1.35); ctx.lineTo(a*1.65,-a*1.35); ctx.lineTo(a,-a); ctx.stroke();
      ctx.moveTo(a,-a); ctx.lineTo(a*1.65,-a*1.35); ctx.lineTo(a*1.65,a*.65); ctx.lineTo(a,a); ctx.stroke();
      ctx.fillStyle='rgba(210,255,235,.72)';
      ctx.font='bold '+Math.round(s*.62)+'px monospace';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(phase%2?'1':'0',0,0);
      ctx.restore();
    }
    cube(W*.18,H*.39,Math.min(W,H)*.040,1);
    cube(W*.82,H*.41,Math.min(W,H)*.040,2);
    cube(W*.30,H*.26,Math.min(W,H)*.032,3);
    cube(W*.70,H*.25,Math.min(W,H)*.032,4);

    // Veri bağlantı çizgileri
    ctx.lineWidth=1.5;
    var points=[[W*.18,H*.39],[W*.82,H*.41],[W*.30,H*.26],[W*.70,H*.25],[aiX,aiY],[robotX,robotY-H*.04]];
    for(var li=0;li<points.length;li++){
      var p1=points[li], p2=points[(li+2)%points.length];
      var al=.08+.10*Math.abs(Math.sin(t+li));
      ctx.strokeStyle='rgba(110,255,170,'+al+')';
      ctx.beginPath(); ctx.moveTo(p1[0],p1[1]); ctx.lineTo(p2[0],p2[1]); ctx.stroke();
    }

    // Küçük terminal pencereleri
    function terminal(x,y,w,h,title,phase){
      ctx.save();
      ctx.translate(x,y+Math.cos(t*.8+phase)*H*.006);
      ctx.fillStyle='rgba(2,15,14,.62)';
      ctx.strokeStyle='rgba(90,255,165,.28)';
      ctx.lineWidth=1.5;
      ctx.beginPath(); ctx.roundRect(-w*.5,-h*.5,w,h,10); ctx.fill(); ctx.stroke();
      ctx.fillStyle='rgba(100,255,170,.70)';
      ctx.font='bold '+Math.round(h*.18)+'px monospace';
      ctx.textAlign='left'; ctx.textBaseline='middle';
      ctx.fillText('> '+title,-w*.40,-h*.15);
      ctx.fillStyle='rgba(150,235,255,.55)';
      ctx.fillText('run()',-w*.32,h*.14);
      ctx.restore();
    }
    terminal(W*.20,H*.53,W*.17,H*.075,'idea',1);
    terminal(W*.80,H*.54,W*.17,H*.075,'learn',2);

    // Kod parçacıkları
    for(var pa=0;pa<34;pa++){
      var px=W*(.08+(pa*0.047)%0.84)+Math.sin(t*.9+pa)*W*.014;
      var py=H*(.22+(pa%9)*.060)+Math.cos(t*.7+pa)*H*.010;
      var al=.07+.18*Math.abs(Math.sin(t*1.4+pa));
      ctx.fillStyle=pa%3===0?'rgba(90,255,160,'+al+')':(pa%3===1?'rgba(120,225,255,'+al+')':'rgba(255,230,120,'+al+')');
      ctx.beginPath(); ctx.arc(px,py,1.4+(pa%3)*.35,0,Math.PI*2); ctx.fill();
    }

    // Başlık levhası
    ctx.save();
    ctx.translate(W*.50,H*.095);
    ctx.fillStyle='rgba(2,18,14,.76)';
    ctx.strokeStyle='rgba(95,255,165,.38)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.28,-H*.033,W*.56,H*.066,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(190,255,215,.96)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.028)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var label=(evValuesOn()&&evValuesLang()==='en')?'CODE MATRIX LAB':(evValuesOn()&&evValuesLang()==='de')?'CODE-MATRIX-LABOR':(evValuesOn()&&evValuesLang()==='fr')?'LABO CODE MATRIX':(evValuesOn()&&evValuesLang()==='ar')?'مختبر كود ماتريكس':'KOD MATRIX LABORATUVARI';
    ctx.fillText(label,0,0);
    ctx.restore();

    // Alt kısa mesaj
    ctx.save();
    ctx.fillStyle='rgba(210,255,225,.82)';
    ctx.font=Math.round(Math.min(W,H)*.021)+'px Fredoka One';
    ctx.textAlign='center';
    var sub=(evValuesOn()&&evValuesLang()==='en')?'Think, try, code.':(evValuesOn()&&evValuesLang()==='de')?'Denk, probier, code.':(evValuesOn()&&evValuesLang()==='fr')?'Pense, essaie, code.':(evValuesOn()&&evValuesLang()==='ar')?'فكّر، جرّب، وبرمج':'Düşün, dene, kodla.';
    ctx.fillText(sub,W*.5,H*.93);
    ctx.restore();

    return;
  }

