    // Orta sözlük / hologram kelime küresi
    var bookX=W*.50, bookY=H*.66, bookW=W*.38, bookH=H*.12;
    ctx.fillStyle='rgba(0,0,0,.24)';
    ctx.beginPath(); ctx.ellipse(bookX,bookY+bookH*.54,bookW*.58,bookH*.18,0,0,Math.PI*2); ctx.fill();

    ctx.fillStyle='rgba(245,250,255,.95)';
    ctx.beginPath(); ctx.roundRect(bookX-bookW*.50,bookY-bookH*.35,bookW,bookH*.70,18); ctx.fill();
    ctx.fillStyle='rgba(50,110,210,.78)';
