    ctx.beginPath();
    ctx.arc(archX,archY,archW*.36,Math.PI*1.05,Math.PI*1.95);
    ctx.stroke();
    ctx.strokeStyle='rgba(180,145,255,.18)';
    ctx.lineWidth=Math.max(2,W*.006);
    ctx.beginPath();
    ctx.arc(archX,archY+H*.02,archW*.30,Math.PI*1.08,Math.PI*1.92);
    ctx.stroke();

    // 2.5D salon zemini
    var floor=ctx.createLinearGradient(0,floorY-H*.08,0,H);
    floor.addColorStop(0,'rgba(112,70,36,.82)');
    floor.addColorStop(.50,'rgba(65,39,34,.93)');
    floor.addColorStop(1,'rgba(18,10,14,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
    ctx.lineTo(W*.50,H*.56);
    ctx.lineTo(W*.96,floorY);
