    // Zemin yıldız basamakları
    function drawStar(cx,cy,r,fill,rot){
      ctx.save();
      ctx.translate(cx,cy);
      ctx.rotate(rot||0);
      ctx.fillStyle=fill;
      ctx.beginPath();
      for(var i=0;i<10;i++){
