    // Sandık gövdesi
    var chestBody=ctx.createLinearGradient(chestX-chestW*.5,chestY,chestX+chestW*.5,chestY+chestH);
    chestBody.addColorStop(0,'#7a421c');
    chestBody.addColorStop(.45,'#c47b2d');
    chestBody.addColorStop(1,'#4a2414');
    ctx.fillStyle=chestBody;
    ctx.beginPath(); ctx.roundRect(chestX-chestW*.5,chestY,chestW,chestH*.60,12); ctx.fill();

    // Sandık kapağı hafif açık ve nefes alır gibi parlıyor
    var lidLift=Math.sin(t*1.4)*H*.004;
    var lid=ctx.createLinearGradient(chestX-chestW*.5,chestY-chestH*.18+lidLift,chestX+chestW*.5,chestY+chestH*.12+lidLift);
    lid.addColorStop(0,'#9e5722');
    lid.addColorStop(.45,'#efaa45');
