      g.addColorStop(1,col+'00');
      ctx.strokeStyle=g;
      ctx.lineWidth=w;
      ctx.lineCap='round';
      ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
      ctx.save();
      ctx.globalAlpha=.20;
      ctx.lineWidth=w+glow;
