if(id==='nefes'){
    // EXPERIMENT V24: NEFES ODASI - 2.5D SAKİN NEFES BAHÇESİ
    // Sadece Nefes Odasının sahnesi değişti.
    // Hareket eden nesneler: nefes halkası, baloncuklar, ışık dalgaları, su yansıması, yavaş parçacıklar.
    // Oyun motoru, puan, objeler, tıklama, çıkış, PDF ve layout değiştirilmedi.
    var t=ts*.001;
    var floorY=H*.76;

    // Sakin mavi/mor nefes arka planı
    var bg=ctx.createLinearGradient(0,0,0,H);
    bg.addColorStop(0,'#06111f');
    bg.addColorStop(.28,'#102846');
    bg.addColorStop(.58,'#314f7d');
    bg.addColorStop(1,'#06121d');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    // Ortadan yumuşak huzur ışığı
    var calmGlow=ctx.createRadialGradient(W*.50,H*.42,H*.02,W*.50,H*.46,H*.75);
    calmGlow.addColorStop(0,'rgba(190,245,255,.26)');
    calmGlow.addColorStop(.35,'rgba(160,150,255,.12)');
    calmGlow.addColorStop(.70,'rgba(120,220,210,.06)');
    calmGlow.addColorStop(1,'transparent');
    ctx.fillStyle=calmGlow; ctx.fillRect(0,0,W,H);

    // İnce akan arka plan dalga çizgileri
    for(var wave=0;wave<9;wave++){
      var y=H*(.16+wave*.065)+Math.sin(t*.35+wave)*H*.009;
      ctx.strokeStyle=wave%2===0?'rgba(175,240,255,.10)':'rgba(210,190,255,.08)';
      ctx.lineWidth=2;
      ctx.beginPath();
      for(var x=0;x<=W;x+=W/36){
        var yy=y+Math.sin(x*.012+t*.8+wave)*H*.010;
        if(x===0) ctx.moveTo(x,yy); else ctx.lineTo(x,yy);
      }
      ctx.stroke();
    }

    // Uzak sakin dağ/su çizgisi
    ctx.fillStyle='rgba(8,24,42,.52)';
    ctx.beginPath();
    ctx.moveTo(0,H*.58);
    ctx.bezierCurveTo(W*.22,H*.50,W*.34,H*.60,W*.50,H*.53);
    ctx.bezierCurveTo(W*.66,H*.46,W*.82,H*.60,W,H*.52);
    ctx.lineTo(W,H*.68);
    ctx.lineTo(0,H*.68);
    ctx.closePath();
    ctx.fill();

    // 2.5D su/zemin yansıması
    var floor=ctx.createLinearGradient(0,floorY-H*.08,0,H);
    floor.addColorStop(0,'rgba(83,145,170,.72)');
    floor.addColorStop(.48,'rgba(36,78,104,.90)');
    floor.addColorStop(1,'rgba(6,18,30,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
    ctx.lineTo(W*.50,H*.56);
    ctx.lineTo(W*.96,floorY);
    ctx.lineTo(W*.82,H);
    ctx.lineTo(W*.18,H);
    ctx.closePath(); ctx.fill();

    // Su gibi yansıma çizgileri
    for(var rr=0;rr<13;rr++){
      var yy=H*(.70+rr*.022);
      var ww=W*(.08+rr*.018);
      ctx.strokeStyle='rgba(210,250,255,'+(.08+rr*.006)+')';
      ctx.lineWidth=1.2;
      ctx.beginPath();
      ctx.moveTo(W*.50-ww+Math.sin(t+rr)*W*.010,yy);
      ctx.quadraticCurveTo(W*.50,yy+Math.sin(t*1.3+rr)*H*.006,W*.50+ww,yy);
      ctx.stroke();
    }

    // Nefes platformu
    var padX=W*.50, padY=H*.68;
    ctx.fillStyle='rgba(0,0,0,.22)';
    ctx.beginPath(); ctx.ellipse(padX,padY+H*.075,W*.25,H*.040,0,0,Math.PI*2); ctx.fill();

    var pad=ctx.createRadialGradient(padX,padY,H*.01,padX,padY,W*.25);
    pad.addColorStop(0,'rgba(190,245,255,.30)');
    pad.addColorStop(.46,'rgba(95,145,185,.34)');
    pad.addColorStop(1,'rgba(32,65,90,.42)');
    ctx.fillStyle=pad;
    ctx.beginPath(); ctx.ellipse(padX,padY,W*.22,H*.060,0,0,Math.PI*2); ctx.fill();

    ctx.strokeStyle='rgba(225,255,255,.28)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.ellipse(padX,padY,W*.22,H*.060,0,0,Math.PI*2); ctx.stroke();

    // Ana nefes halkası: büyür/küçülür
    var breath=(Math.sin(t*.78)+1)/2;
    var ringR=Math.min(W,H)*(.115+breath*.070);
    var ringAlpha=.28+breath*.20;

    // Dış nefes dalgaları
    for(var rg=0;rg<4;rg++){
      var k=(breath+rg*.25)%1;
      var r2=Math.min(W,H)*(.105+k*.155);
      var a2=.20*(1-k);
      ctx.strokeStyle='rgba(190,245,255,'+a2+')';
      ctx.lineWidth=2+rg;
      ctx.beginPath(); ctx.arc(W*.50,H*.42,r2,0,Math.PI*2); ctx.stroke();
    }

    // Ana halka
    var ringGrad=ctx.createRadialGradient(W*.50,H*.42,ringR*.20,W*.50,H*.42,ringR);
    ringGrad.addColorStop(0,'rgba(255,255,255,.08)');
    ringGrad.addColorStop(.70,'rgba(170,235,255,.10)');
    ringGrad.addColorStop(1,'rgba(190,245,255,.02)');
    ctx.fillStyle=ringGrad;
    ctx.beginPath(); ctx.arc(W*.50,H*.42,ringR,0,Math.PI*2); ctx.fill();

    ctx.strokeStyle='rgba(205,250,255,'+ringAlpha+')';
    ctx.lineWidth=4;
    ctx.beginPath(); ctx.arc(W*.50,H*.42,ringR,0,Math.PI*2); ctx.stroke();

    ctx.strokeStyle='rgba(190,170,255,'+(.20+breath*.16)+')';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(W*.50,H*.42,ringR*.72,0,Math.PI*2); ctx.stroke();

    // İç ışık noktası
    var inner=ctx.createRadialGradient(W*.50,H*.42,0,W*.50,H*.42,ringR*.44);
    inner.addColorStop(0,'rgba(255,255,255,.58)');
    inner.addColorStop(.28,'rgba(170,240,255,.26)');
    inner.addColorStop(1,'transparent');
    ctx.fillStyle=inner;
    ctx.fillRect(W*.50-ringR*.6,H*.42-ringR*.6,ringR*1.2,ringR*1.2);

    // Nefes metni: halka büyürken nefes al, küçülürken nefes ver
    var inhale=Math.cos(t*.78)<0;
