    if(evValuesOn()&&evValuesLang()==='en') breathText=inhale?'BREATHE IN':'BREATHE OUT';
    else if(evValuesOn()&&evValuesLang()==='de') breathText=inhale?'EINATMEN':'AUSATMEN';
    else if(evValuesOn()&&evValuesLang()==='fr') breathText=inhale?'INSPIRE':'EXPIRE';
