    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(breathText,W*.50,H*.42);

    // Alt küçük ritim noktaları
    for(var dot=0;dot<6;dot++){
      var a=Math.PI*2*dot/6+t*.25;
      var dx=W*.50+Math.cos(a)*ringR*1.22;
      var dy=H*.42+Math.sin(a)*ringR*.72;
