      ctx.beginPath(); ctx.arc(bx,by,br,0,Math.PI*2); ctx.stroke();
      ctx.fillStyle='rgba(210,250,255,'+(al*.22)+')';
      ctx.beginPath(); ctx.arc(bx-br*.25,by-br*.25,br*.35,0,Math.PI*2); ctx.fill();
    }

    // Sol ve sağ yumuşak nefes fenerleri
    function calmLantern(x,y,s,phase){
      ctx.save();
      ctx.translate(x,y+Math.sin(t*.9+phase)*H*.006);
      ctx.fillStyle='rgba(0,0,0,.18)';
      ctx.beginPath(); ctx.ellipse(0,s*.90,s*.80,s*.16,0,0,Math.PI*2); ctx.fill();

      var lg=ctx.createRadialGradient(0,0,0,0,0,s);
      lg.addColorStop(0,'rgba(255,245,200,.42)');
      lg.addColorStop(.45,'rgba(150,230,255,.22)');
      lg.addColorStop(1,'rgba(150,230,255,.02)');
      ctx.fillStyle=lg;
      ctx.beginPath(); ctx.arc(0,0,s,0,Math.PI*2); ctx.fill();

      ctx.strokeStyle='rgba(225,255,255,.28)';
      ctx.lineWidth=2;
      ctx.beginPath(); ctx.arc(0,0,s*.62,0,Math.PI*2); ctx.stroke();

      ctx.fillStyle='rgba(255,245,190,.70)';
      ctx.beginPath(); ctx.arc(0,0,s*.16+Math.sin(t*2+phase)*s*.025,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }
    calmLantern(W*.22,H*.62,Math.min(W,H)*.060,1);
    calmLantern(W*.78,H*.62,Math.min(W,H)*.060,3);

    // Yavaş akan ışık parçacıkları
    for(var p=0;p<36;p++){
      var px=W*(.08+(p*0.049)%0.84)+Math.sin(t*.55+p)*W*.018;
      var py=H*(.20+(p%10)*.057)+Math.cos(t*.45+p)*H*.012;
      var al=.07+.17*Math.abs(Math.sin(t*.9+p));
      ctx.fillStyle=p%3===0?'rgba(190,245,255,'+al+')':(p%3===1?'rgba(210,190,255,'+al+')':'rgba(255,235,170,'+al+')');
      ctx.beginPath(); ctx.arc(px,py,1.3+(p%3)*.35,0,Math.PI*2); ctx.fill();
    }

    // Küçük sakinlik taşları
    var stoneY=H*.74;
    for(var s=0;s<5;s++){
      var x=W*(.38+s*.06);
      var y=stoneY-H*(s*.012);
      ctx.fillStyle=['rgba(110,135,145,.72)','rgba(150,160,165,.68)','rgba(95,120,132,.70)','rgba(170,175,170,.64)','rgba(125,145,150,.70)'][s];
