    ctx.beginPath(); ctx.roundRect(-W*.22,-H*.033,W*.44,H*.066,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(230,255,255,.96)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var label=(evValuesOn()&&evValuesLang()==='en')?'BREATH ROOM':(evValuesOn()&&evValuesLang()==='de')?'ATEMRAUM':(evValuesOn()&&evValuesLang()==='fr')?'SALLE DU SOUFFLE':(evValuesOn()&&evValuesLang()==='ar')?'غرفة التنفس':'NEFES ODASI';
    ctx.fillText(label,0,0);
