    ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.ellipse(orbX,orbY,orbR,orbR*.45,Math.sin(t*.45)*.25,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.ellipse(orbX,orbY,orbR*.45,orbR,Math.cos(t*.45)*.25,0,Math.PI*2); ctx.stroke();

    // Küre etrafında dönen gerçek harfler
    for(var si=0;si<12;si++){
      var a=t*.65+si*Math.PI*2/12;
      var rx=orbX+Math.cos(a)*orbR*1.42;
      var ry=orbY+Math.sin(a)*orbR*.66;
      var scale=.75+.25*(Math.sin(a)+1)/2;
      ctx.fillStyle=si%2?'rgba(255,225,135,.86)':'rgba(200,220,255,.80)';
      ctx.font='bold '+Math.round(Math.min(W,H)*.030*scale)+'px serif';
      ctx.fillText(letters[(si*2)%letters.length],rx,ry);
    }

    // Merkez harf
    ctx.fillStyle='rgba(255,240,180,.94)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.080)+'px serif';
    ctx.fillText('أ',orbX,orbY+H*.004);

    // Öğrenme ilerleme levhası
    var learned=0; try{ learned=getArabicLearnedCount(); }catch(e){}
    ctx.save();
    ctx.translate(W*.50,H*.20);
    ctx.fillStyle='rgba(8,13,28,.70)';
    ctx.strokeStyle='rgba(255,220,130,.32)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.22,-H*.032,W*.44,H*.064,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,235,170,.96)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.022)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('الحروف المتعلّمة  '+learned+'/28',0,0);
    ctx.restore();

    // Sol/sağ küçük kelime köprüleri
    function miniCard(x,y,txt,phase){
      ctx.save();
      ctx.translate(x,y+Math.sin(t*.9+phase)*H*.007);
      ctx.fillStyle='rgba(255,255,255,.12)';
      ctx.strokeStyle='rgba(255,220,130,.24)';
      ctx.lineWidth=1.5;
      ctx.beginPath(); ctx.roundRect(-W*.075,-H*.027,W*.15,H*.054,12); ctx.fill(); ctx.stroke();
      ctx.fillStyle='rgba(245,235,205,.86)';
      ctx.font='bold '+Math.round(Math.min(W,H)*.018)+'px serif';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(txt,0,0);
      ctx.restore();
    }
    miniCard(W*.21,H*.47,'ألف',1);
    miniCard(W*.79,H*.47,'باء',2);
    miniCard(W*.28,H*.32,'جيم',3);
    miniCard(W*.72,H*.32,'سين',4);

    // Harften harfe giden ışık noktaları
    var nodes=[[W*.21,H*.47],[W*.28,H*.32],[W*.50,H*.40],[W*.72,H*.32],[W*.79,H*.47],[bookX,bookY]];
    ctx.lineWidth=1.5;
    for(var ni=0;ni<nodes.length-1;ni++){
      var p1=nodes[ni], p2=nodes[ni+1];
      ctx.strokeStyle='rgba(255,215,130,.10)';
      ctx.beginPath(); ctx.moveTo(p1[0],p1[1]); ctx.lineTo(p2[0],p2[1]); ctx.stroke();
      var k=(t*.18+ni*.19)%1;
      var px=p1[0]+(p2[0]-p1[0])*k;
      var py=p1[1]+(p2[1]-p1[1])*k;
      ctx.fillStyle='rgba(255,235,150,.65)';
      ctx.beginPath(); ctx.arc(px,py,2.5,0,Math.PI*2); ctx.fill();
    }

    // Yumuşak yıldız/harf parçacıkları
    for(var p=0;p<34;p++){
      var px=W*(.08+(p*0.049)%0.84)+Math.sin(t*.7+p)*W*.014;
      var py=H*(.26+(p%9)*.060)+Math.cos(t*.55+p)*H*.010;
      var al=.07+.18*Math.abs(Math.sin(t*1.1+p));
      ctx.fillStyle=p%3===0?'rgba(255,215,120,'+al+')':(p%3===1?'rgba(180,210,255,'+al+')':'rgba(255,245,210,'+al+')');
      ctx.beginPath(); ctx.arc(px,py,1.4+(p%3)*.35,0,Math.PI*2); ctx.fill();
    }

    // Başlık levhası
    ctx.save();
    ctx.translate(W*.50,H*.095);
    ctx.fillStyle='rgba(8,12,28,.74)';
    ctx.strokeStyle='rgba(255,220,130,.36)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.28,-H*.033,W*.56,H*.066,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,235,170,.96)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.028)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var label=(evValuesOn()&&evValuesLang()==='en')?'ARABIC LETTER GATE':(evValuesOn()&&evValuesLang()==='de')?'ARABISCHE BUCHSTABEN':(evValuesOn()&&evValuesLang()==='fr')?'PORTE DES LETTRES ARABES':(evValuesOn()&&evValuesLang()==='ar')?'بوابة الحروف العربية':'ARAPÇA HARF KAPISI';
    ctx.fillText(label,0,0);
    ctx.restore();

    // Alt kısa mesaj
    ctx.save();
    ctx.fillStyle='rgba(245,235,205,.82)';
    ctx.font=Math.round(Math.min(W,H)*.021)+'px Fredoka One';
    ctx.textAlign='center';
    var sub=(evValuesOn()&&evValuesLang()==='en')?'Every letter opens a new world.':(evValuesOn()&&evValuesLang()==='de')?'Jeder Buchstabe öffnet eine neue Welt.':(evValuesOn()&&evValuesLang()==='fr')?'Chaque lettre ouvre un nouveau monde.':(evValuesOn()&&evValuesLang()==='ar')?'كل حرف يفتح عالماً جديداً':'Her harf yeni bir kapı açar.';
    ctx.fillText(sub,W*.5,H*.93);
    ctx.restore();

    return;
  }

if(id==='uzay'||id==='gozlemci'){
    [[W*.2,H*.18,32,'#4466CC',true],[W*.75,H*.35,22,'#CC4422',false],[W*.55,H*.12,16,'#22AA66',false]].forEach(function(p){
      var pg=ctx.createRadialGradient(p[0]-p[2]*.3,p[1]-p[2]*.3,2,p[0],p[1],p[2]);
      pg.addColorStop(0,'rgba(255,255,255,.35)'); pg.addColorStop(.3,p[3]+'cc'); pg.addColorStop(1,p[3]+'66');
      ctx.fillStyle=pg; ctx.beginPath(); ctx.arc(p[0],p[1],p[2],0,Math.PI*2); ctx.fill();
      if(p[4]){ctx.strokeStyle='rgba(200,160,80,.45)'; ctx.lineWidth=5; ctx.beginPath(); ctx.ellipse(p[0],p[1],p[2]*2.2,p[2]*.35,-.25,0,Math.PI*2); ctx.stroke();}
    });
    // Meteor
    var mt=(ts*.0006)%1;
    var mx2=W*(1-mt),my2=H*.05,mx3=mx2-W*.15,my3=my2+H*.06;
    var mg2=ctx.createLinearGradient(mx2,my2,mx3,my3); mg2.addColorStop(0,'rgba(255,255,200,.8)'); mg2.addColorStop(1,'transparent');
    ctx.strokeStyle=mg2; ctx.lineWidth=2.5; ctx.beginPath(); ctx.moveTo(mx2,my2); ctx.lineTo(mx3,my3); ctx.stroke();
    ctx.fillStyle='rgba(255,255,200,.9)'; ctx.beginPath(); ctx.arc(mx2,my2,2.5,0,Math.PI*2); ctx.fill();
  }

if(id==='dunya'){
    // Koyu mavi okyanus arka planı (zaten bg'den geliyor)
    // Dünya haritası - continental shapes (basit poligonlar)
    ctx.save();
    ctx.globalAlpha = 0.18;
    var mapY = H * 0.5;
    var mapScale = Math.min(W, H) * 0.008;
    var drift = Math.sin(ts * 0.0003) * 8; // hafif yüzme efekti

    // Kıtalar - basit ama tanınabilir şekiller
    var continents = [
      // Kuzey Amerika
      { pts: [[.08,.28],[.22,.25],[.28,.35],[.24,.50],[.15,.52],[.07,.42]], col:'#2d8a4a' },
      // Güney Amerika
      { pts: [[.20,.52],[.28,.50],[.32,.65],[.26,.80],[.18,.78],[.15,.58]], col:'#2d8a4a' },
      // Avrupa
      { pts: [[.40,.22],[.52,.20],[.55,.32],[.48,.36],[.40,.34]], col:'#3a9a55' },
      // Afrika
      { pts: [[.44,.36],[.56,.34],[.60,.55],[.56,.72],[.46,.74],[.40,.58],[.40,.42]], col:'#2d8a4a' },
      // Asya
      { pts: [[.55,.18],[.82,.20],[.88,.38],[.78,.50],[.62,.48],[.55,.36]], col:'#3a9a55' },
      // Avustralya
      { pts: [[.74,.60],[.86,.58],[.90,.68],[.84,.74],[.74,.72]], col:'#2d8a4a' },
    ];

    continents.forEach(function(cont){
      ctx.fillStyle = cont.col;
      ctx.beginPath();
      cont.pts.forEach(function(p, i){
        var px = p[0]*W + drift;
        var py = p[1]*H;
        i===0 ? ctx.moveTo(px,py) : ctx.lineTo(px,py);
      });
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(100,220,100,.3)';
      ctx.lineWidth = 1;
      ctx.stroke();
    });

    ctx.restore();

    // Enlem/Boylam çizgileri
    ctx.save();
    ctx.globalAlpha = 0.07;
    ctx.strokeStyle = '#88CCFF';
    ctx.lineWidth = 1;
    // Yatay (enlem)
    for(var lat=0; lat<5; lat++){
      ctx.beginPath();
      ctx.moveTo(0, H*(0.2 + lat*0.15));
      ctx.lineTo(W, H*(0.2 + lat*0.15));
      ctx.stroke();
    }
    // Dikey (boylam)
    for(var lon=0; lon<8; lon++){
      ctx.beginPath();
      ctx.moveTo(W*(0.05 + lon*0.13), 0);
      ctx.lineTo(W*(0.05 + lon*0.13), H);
      ctx.stroke();
    }
    ctx.restore();

    // Dönen bayrak emojileri arka planda
    var flagEmojis = ['🇹🇷','🇩🇪','🇫🇷','🇬🇧','🇺🇸','🇯🇵','🇧🇷','🇮🇳','🇨🇳','🇮🇹'];
    ctx.save();
    ctx.globalAlpha = 0.12;
    ctx.font = '28px serif';
    ctx.textAlign = 'center';
    flagEmojis.forEach(function(f, i){
      var fx = (W * 0.1) + (i % 5) * (W * 0.2);
      var fy = i < 5 ? H * 0.2 : H * 0.75;
      var wobble = Math.sin(ts * 0.001 + i * 1.2) * 5;
      ctx.fillText(f, fx, fy + wobble);
    });
    ctx.restore();

    // "DÜNYA TURU" yazısı - soluk
    ctx.save();
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold ' + Math.floor(W*0.12) + 'px Fredoka One, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(evValuesOn()&&evValuesLang()==='en'?'WORLD TOUR':(evValuesOn()&&evValuesLang()==='fr'?'TOUR DU MONDE':(evValuesOn()&&evValuesLang()==='de'?'WELTREISE':'DUNYA TURU')), W/2, H*0.92);
    ctx.restore();
  }

if(id==='francais'){
    // EXPERIMENT V28: FRANÇAIS WORD LAB - 2.5D FRANSIZCA KELİME LABORATUVARI
    // İngilizce/Almanca ile aynı 2 tıklama mantığı. Rapor: Fransızca kelimeler X/246.
    var t=ts*.001;
    var floorY=H*.76;

    var bg=ctx.createLinearGradient(0,0,0,H);
    bg.addColorStop(0,'#07101f');
    bg.addColorStop(.30,'#16224a');
    bg.addColorStop(.62,'#244a8f');
    bg.addColorStop(1,'#101020');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    var glow=ctx.createRadialGradient(W*.50,H*.42,H*.02,W*.50,H*.48,H*.72);
    glow.addColorStop(0,'rgba(255,230,170,.26)');
    glow.addColorStop(.34,'rgba(105,165,255,.14)');
    glow.addColorStop(.70,'rgba(255,255,255,.05)');
    glow.addColorStop(1,'transparent');
    ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);

    // Zarif Paris / dil atmosferi
    ctx.strokeStyle='rgba(255,225,145,.24)';
    ctx.lineWidth=3;
    var ex=W*.18, ey=H*.50, eh=H*.24;
    ctx.beginPath(); ctx.moveTo(ex,ey); ctx.lineTo(ex-W*.045,ey+eh); ctx.lineTo(ex+W*.045,ey+eh); ctx.closePath(); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ex-W*.030,ey+eh*.42); ctx.lineTo(ex+W*.030,ey+eh*.42); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ex-W*.060,ey+eh*.72); ctx.lineTo(ex+W*.060,ey+eh*.72); ctx.stroke();

    // Uçan Fransızca kelime kartları
    var words=['BONJOUR','MERCI','ÉCOLE','AMI','LIVRE','EAU','FAMILLE','COULEUR','ESPOIR','PAIX','APPRENDRE','PARTAGER'];
    ctx.textAlign='center'; ctx.textBaseline='middle';
    words.forEach(function(wd,i){
      var x=W*(.14+(i%4)*.24)+Math.sin(t*.55+i)*W*.018;
      var y=H*(.18+Math.floor(i/4)*.15)+Math.cos(t*.65+i)*H*.010;
      var bw=W*(.13+(i%3)*.015), bh=H*.050;
      ctx.save(); ctx.translate(x,y); ctx.rotate(Math.sin(t*.45+i)*.035);
      ctx.fillStyle='rgba(255,255,255,.13)';
      ctx.strokeStyle=i%3===0?'rgba(255,225,145,.32)':(i%3===1?'rgba(120,170,255,.28)':'rgba(255,255,255,.20)');
      ctx.lineWidth=1.5;
      ctx.beginPath(); ctx.roundRect(-bw*.5,-bh*.5,bw,bh,12); ctx.fill(); ctx.stroke();
      ctx.fillStyle=i%2?'rgba(255,235,170,.88)':'rgba(225,240,255,.86)';
      ctx.font='bold '+Math.round(Math.min(W,H)*.018)+'px Fredoka One';
      ctx.fillText(wd,0,0);
      ctx.restore();
    });

    // 2.5D zemin
    var floor=ctx.createLinearGradient(0,floorY-H*.07,0,H);
    floor.addColorStop(0,'rgba(70,92,150,.74)');
    floor.addColorStop(.50,'rgba(34,48,96,.92)');
    floor.addColorStop(1,'rgba(8,10,28,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY); ctx.lineTo(W*.50,H*.56); ctx.lineTo(W*.96,floorY); ctx.lineTo(W*.82,H); ctx.lineTo(W*.18,H); ctx.closePath(); ctx.fill();

    ctx.strokeStyle='rgba(255,225,145,.11)';
    for(var g=0;g<8;g++){
      ctx.beginPath(); ctx.moveTo(W*(.12+g*.11),H); ctx.lineTo(W*.50,H*.56); ctx.stroke();
    }

    // Fransızca kafe-masa / kitap
    var tableX=W*.50, tableY=H*.66, tableW=W*.42, tableH=H*.11;
    ctx.fillStyle='rgba(0,0,0,.24)';
    ctx.beginPath(); ctx.ellipse(tableX,tableY+tableH*.56,tableW*.58,tableH*.20,0,0,Math.PI*2); ctx.fill();

    var tg=ctx.createLinearGradient(tableX-tableW*.5,tableY-tableH*.5,tableX+tableW*.5,tableY+tableH*.5);
    tg.addColorStop(0,'#1b2f66'); tg.addColorStop(.45,'#4c70c8'); tg.addColorStop(1,'#0f1a40');
    ctx.fillStyle=tg; ctx.beginPath(); ctx.roundRect(tableX-tableW*.5,tableY-tableH*.5,tableW,tableH,16); ctx.fill();
    ctx.strokeStyle='rgba(255,230,150,.28)'; ctx.lineWidth=2; ctx.beginPath(); ctx.roundRect(tableX-tableW*.5,tableY-tableH*.5,tableW,tableH,16); ctx.stroke();

    // kitap ve fincan
    ctx.font=Math.round(H*.040)+'px serif';
    ctx.fillText('📖',tableX-W*.060,tableY-H*.012);
    ctx.fillText('☕',tableX+W*.060,tableY-H*.012);

    // Ortada kelime küresi
    var orbX=W*.50, orbY=H*.42+Math.sin(t)*H*.006, orbR=Math.min(W,H)*.092;
    var orb=ctx.createRadialGradient(orbX-orbR*.3,orbY-orbR*.3,0,orbX,orbY,orbR);
    orb.addColorStop(0,'rgba(255,255,255,.86)');
    orb.addColorStop(.28,'rgba(255,225,150,.38)');
    orb.addColorStop(.62,'rgba(95,145,255,.20)');
    orb.addColorStop(1,'rgba(255,255,255,.03)');
    ctx.fillStyle=orb; ctx.beginPath(); ctx.arc(orbX,orbY,orbR,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(255,230,160,.42)'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(orbX,orbY,orbR,0,Math.PI*2); ctx.stroke();

    var chars=['É','À','Ç','È','Ù','Â','Ê','Î','Ô','Û'];
    ctx.font='bold '+Math.round(Math.min(W,H)*.024)+'px Fredoka One';
    for(var a=0;a<chars.length;a++){
      var ang=t*.85+a*Math.PI*2/chars.length;
      var x2=orbX+Math.cos(ang)*orbR*1.45;
      var y2=orbY+Math.sin(ang)*orbR*.67;
      ctx.fillStyle=a%2?'rgba(255,230,130,.86)':'rgba(220,235,255,.82)';
      ctx.fillText(chars[a],x2,y2);
    }
    ctx.fillStyle='rgba(255,245,190,.95)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.038)+'px Fredoka One';
    ctx.fillText('MOT',orbX,orbY);

    // Sol mikrofon / ses
    var micX=W*.24, micY=H*.66;
    ctx.fillStyle='rgba(0,0,0,.22)'; ctx.beginPath(); ctx.ellipse(micX,micY+H*.070,W*.075,H*.018,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(90,135,255,.88)'; ctx.beginPath(); ctx.roundRect(micX-W*.026,micY-H*.065,W*.052,H*.085,16); ctx.fill();
    ctx.strokeStyle='rgba(255,245,190,.80)'; ctx.lineWidth=3; ctx.beginPath(); ctx.arc(micX,micY-H*.010,W*.045,0,Math.PI); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(micX,micY+H*.030); ctx.lineTo(micX,micY+H*.072); ctx.stroke();

    // Sağ küçük Fransızca rehber robotu
    var robX=W*.78, robY=H*.66+Math.sin(t*1.4)*H*.006;
    ctx.fillStyle='rgba(0,0,0,.22)'; ctx.beginPath(); ctx.ellipse(robX,robY+H*.070,W*.070,H*.018,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(235,240,255,.94)'; ctx.beginPath(); ctx.roundRect(robX-W*.045,robY-H*.080,W*.090,H*.120,14); ctx.fill();
    ctx.fillStyle='rgba(40,70,170,.92)'; ctx.beginPath(); ctx.arc(robX-W*.015,robY-H*.035,3.5,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(robX+W*.018,robY-H*.035,3.5,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(205,60,80,.88)'; ctx.font='bold '+Math.round(H*.030)+'px Fredoka One'; ctx.fillText('FR',robX,robY+H*.018);

    // Işık parçacıkları
    for(var p=0;p<34;p++){
      var px=W*(.08+(p*0.049)%0.84)+Math.sin(t*.7+p)*W*.014;
      var py=H*(.25+(p%9)*.060)+Math.cos(t*.55+p)*H*.010;
      var al=.07+.16*Math.abs(Math.sin(t*1.1+p));
      ctx.fillStyle=p%3===0?'rgba(255,225,145,'+al+')':(p%3===1?'rgba(170,205,255,'+al+')':'rgba(255,255,255,'+al+')');
      ctx.beginPath(); ctx.arc(px,py,1.4+(p%3)*.35,0,Math.PI*2); ctx.fill();
    }

    // Öğrenilen sayaç
    var learned=0,total=0; try{ learned=getLangLearnedCount('fr'); total=(VOCAB&&VOCAB.length)||0; }catch(e){}
    ctx.save();
    ctx.translate(W*.50,H*.095);
    ctx.fillStyle='rgba(8,18,42,.76)'; ctx.strokeStyle='rgba(255,225,145,.36)'; ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.27,-H*.034,W*.54,H*.068,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,240,190,.96)'; ctx.font='bold '+Math.round(Math.min(W,H)*.027)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('FRANÇAIS WORD LAB',0,-H*.006);
    ctx.font='bold '+Math.round(Math.min(W,H)*.017)+'px Fredoka One';
    ctx.fillStyle='rgba(225,240,255,.92)'; ctx.fillText('APPRIS '+learned+'/'+total,0,H*.020);
    ctx.restore();

    ctx.fillStyle='rgba(235,245,255,.84)';
    ctx.font=Math.round(Math.min(W,H)*.021)+'px Fredoka One';
    ctx.textAlign='center';
    ctx.fillText('Écoute, répète, apprends en deux clics.',W*.5,H*.93);
    return;
  }

if(id==='okyanus'){
    // OKYANUS1: yazısız futuristik su altı gözlem istasyonu.
    // Kod/sistem korunur; sadece oda arka planı değişir.
    var bgPath='assets/room_bg/okyanus1.webp';
    if(!window.EV_OKYANUS1_BG){
      window.EV_OKYANUS1_BG=new Image();
      window.EV_OKYANUS1_BG.src=bgPath;
    }
    var img=window.EV_OKYANUS1_BG;
    if(img && img.complete && img.naturalWidth>0){
      var iw=img.naturalWidth, ih=img.naturalHeight;
      var scale=Math.max(W/iw,H/ih);
      var dw=iw*scale, dh=ih*scale;
      var dx=(W-dw)/2, dy=(H-dh)/2;
      ctx.drawImage(img,dx,dy,dw,dh);
      var top=ctx.createLinearGradient(0,0,0,H*.25);
      top.addColorStop(0,'rgba(0,0,0,.26)');
      top.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=top; ctx.fillRect(0,0,W,H*.26);
      var center=ctx.createRadialGradient(W*.50,H*.58,H*.04,W*.50,H*.58,W*.50);
      center.addColorStop(0,'rgba(80,200,255,.08)');
      center.addColorStop(1,'rgba(80,200,255,0)');
      ctx.fillStyle=center; ctx.fillRect(0,0,W,H);
    }else{
      var g=ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#04243d'); g.addColorStop(.55,'#075f91'); g.addColorStop(1,'#02111e');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    }
    try{ if(typeof evRoomFxV1==='function') evRoomFxV1(ts,'okyanus'); }catch(e){}
    return;
