function drawController(cx,cy,s,phase){
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(Math.sin(t*.8+phase)*.025);
      ctx.fillStyle='rgba(0,0,0,.28)';
      ctx.beginPath(); ctx.ellipse(0,s*.80,s*1.50,s*.28,0,0,Math.PI*2); ctx.fill();
      var cg=ctx.createLinearGradient(-s*1.25,-s*.50,s*1.25,s*.55);
      cg.addColorStop(0,'rgba(255,255,255,.18)');
      cg.addColorStop(.28,'rgba(80,120,255,.85)');
      cg.addColorStop(.65,'rgba(55,35,140,.92)');
      cg.addColorStop(1,'rgba(10,8,35,.98)');
      ctx.fillStyle=cg;
      ctx.strokeStyle='rgba(210,235,255,.35)';
      ctx.lineWidth=2;
      ctx.beginPath();
      ctx.roundRect(-s*1.35,-s*.48,s*2.70,s*.96,s*.25);
      ctx.fill(); ctx.stroke();

      // D-pad
      ctx.fillStyle='rgba(5,8,24,.88)';
      ctx.fillRect(-s*.95,-s*.12,s*.42,s*.10);
      ctx.fillRect(-s*.79,-s*.28,s*.10,s*.42);

      // analoglar
      ['left','right'].forEach(function(side,i){
        var x=i?-s*.15:s*.38;
        ctx.fillStyle='rgba(10,15,45,.95)';
        ctx.beginPath(); ctx.arc(x,s*.12,s*.20,0,Math.PI*2); ctx.fill();
        ctx.fillStyle='rgba(110,220,255,.75)';
        ctx.beginPath(); ctx.arc(x+Math.sin(t*1.4+phase+i)*s*.025,s*.12+Math.cos(t*1.4+phase+i)*s*.025,s*.10,0,Math.PI*2); ctx.fill();
      });

      // action buttons
      var bcols=['#ff4d6d','#ffd166','#42d9c8','#72a7ff'];
      for(var b=0;b<4;b++){
        var ax=s*(.74+Math.cos(b*Math.PI/2)*.18);
        var ay=s*(-.03+Math.sin(b*Math.PI/2)*.18);
        ctx.fillStyle=bcols[b];
        ctx.shadowColor=bcols[b];
        ctx.shadowBlur=10+8*Math.abs(Math.sin(t*2+b+phase));
        ctx.beginPath(); ctx.arc(ax,ay,s*.095,0,Math.PI*2); ctx.fill();
        ctx.shadowBlur=0;
      }

      // center display
      ctx.fillStyle='rgba(0,0,0,.46)';
      ctx.beginPath(); ctx.roundRect(-s*.23,-s*.25,s*.46,s*.22,s*.06); ctx.fill();
      ctx.fillStyle='rgba(160,255,230,.88)';
      ctx.font='bold '+Math.round(s*.18)+'px Fredoka One';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('GO',0,-s*.135);
      ctx.restore();
    }

