function laserLine(x1,y1,x2,y2,col,w,glow){
      var g=ctx.createLinearGradient(x1,y1,x2,y2);
      g.addColorStop(0,col+'00');
      g.addColorStop(.18,col+'aa');
      g.addColorStop(.52,col+'ff');
      g.addColorStop(.84,col+'aa');
      g.addColorStop(1,col+'00');
      ctx.strokeStyle=g;
      ctx.lineWidth=w;
      ctx.lineCap='round';
      ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
      ctx.save();
      ctx.globalAlpha=.20;
      ctx.lineWidth=w+glow;
