function answerRoomSoru(idx, btn) {
  if (_soruState.answered) return;
  _soruState.answered = true;
  var q = _soruState.q;
  var allBtns = document.querySelectorAll('.sq2-opt');
  var fb = document.getElementById('sq2-feedback');

  // Soru istatistiği kaydet
  var _sqKey='ev_soru_stats';
  try{
    var _sqStats=JSON.parse(localStorage.getItem(_sqKey)||'{}');
    var _rid=_soruState.room?_soruState.room.id:'genel';
    if(!_sqStats[_rid]) _sqStats[_rid]={total:0,correct:0};
    _sqStats[_rid].total++;
    if(idx===q.ans) _sqStats[_rid].correct++;
    localStorage.setItem(_sqKey,JSON.stringify(_sqStats));
  }catch(e){}

  if (idx === q.ans) {
    btn.style.background = 'rgba(68,255,136,.25)';
    btn.style.borderColor = '#44FF88';
    btn.style.color = '#44FF88';
    var roomFeedbackLang = (_soruState.room&&_soruState.room.id==='kucukmelekler') ? evV43KMELang() : (evValuesOn() ? (evValuesLang() || 'tr') : 'tr');
    var roomOkText = roomFeedbackLang==='ar' ? evAr('roomOk') : (roomFeedbackLang==='tr' ? 'OK! Harika! +15 Yildiz' : (roomFeedbackLang==='en' ? 'OK! Great! +15 Stars' : (roomFeedbackLang==='fr' ? 'OK ! Super ! +15 Etoiles' : 'OK! Grossartig! +15 Sterne'))); if(_soruState.room&&_soruState.room.id==='kucukmelekler') roomOkText=evV43KMEUi('ok');
    fb.innerHTML = '<span style="color:#44FF88">' + evGermanOk(roomOkText) + '</span><br><span style="font-size:.72rem;color:rgba(255,255,255,.5)">' + q.exp + '</span>';
    addScore(15, window.W/2, 100, '#44FF88');
    _soruState.answerBalloonPending = false;
    // Karakter tepkisi — doğru
    setTimeout(function(){
      setCharState('jump', 2000);
      var correctBubbles = (evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en') ? ['Great! I knew it! 🌟','Awesome! Keep going! 🎉','Bravo! You are brilliant! ⭐','Yes! Correct! 🚀'] : (evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='fr') ? ['Super ! Je le savais ! 🌟','Genial ! Continue ! 🎉','Bravo ! Tu es brillant ! ⭐','Oui ! Correct ! 🚀'] : ['Süper! Bunu biliyordum! 🌟','Harika! Devam et! 🎉','Bravo! Sen dahisin! ⭐','Yeeees! Doğru! 🚀']; if(_soruState.room&&_soruState.room.id==='kucukmelekler') correctBubbles=[evV43KMEOki('ok')];
      showOkiBubble(correctBubbles[Math.floor(Math.random()*correctBubbles.length)]);
      for(var _si=0;_si<5;_si++) setTimeout(_spawnSpark, _si*120);
    }, 150);
  } else {
    btn.style.background = 'rgba(255,80,80,.2)';
    btn.style.borderColor = '#FF5555';
    btn.style.color = '#FF5555';
    allBtns[q.ans].style.background = 'rgba(68,255,136,.1)';
    allBtns[q.ans].style.borderColor = 'rgba(68,255,136,.5)';
    var roomFeedbackLang = (_soruState.room&&_soruState.room.id==='kucukmelekler') ? evV43KMELang() : (evValuesOn() ? (evValuesLang() || 'tr') : 'tr');
    var roomHintText = roomFeedbackLang==='ar' ? evAr('roomHint') : (roomFeedbackLang==='tr' ? 'Ipucu: Balona bak!' : (roomFeedbackLang==='en' ? 'Hint: Check the balloon!' : (roomFeedbackLang==='fr' ? 'Indice : regarde dans le ballon !' : 'Hinweis: Schau im Ballon nach!'))); if(_soruState.room&&_soruState.room.id==='kucukmelekler') roomHintText=evV43KMEUi('hint');
    fb.innerHTML = '<span style="color:rgba(255,220,80,.8)">' + evGermanOk(roomHintText) + ' -> <b>' + q.ans_txt + '</b></span>';
    _soruState.answerBalloonPending = true;
    // Karakter tepkisi — yanlış
    setTimeout(function(){
      setCharState('sad', 2500);
      var wrongBubbles = (evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en') ? ['Mistakes help us learn! 💪','No worries, try the next one! 🌈','Almost! Look for the answer balloon! 👀','We learned it, keep going! 😊'] : (evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='fr') ? ['Les erreurs nous apprennent ! 💪','Pas de soucis, essaie le suivant ! 🌈','Presque ! Cherche le ballon-reponse ! 👀','On a appris, continuons ! 😊'] : ['Eh, hata yapmak da öğrenmek! 💪','Merak etme, bir sonraki! 🌈','Neredeyse! Balondan bak! 👀','Öğrendik, devam! 😊']; if(_soruState.room&&_soruState.room.id==='kucukmelekler') wrongBubbles=[evV43KMEOki('wrong')];
      showOkiBubble(wrongBubbles[Math.floor(Math.random()*wrongBubbles.length)]);
    }, 150);  // Balonda göster!
  }
  document.getElementById('sq2-next').style.display = 'block';
  document.querySelector('.sq2-skip').style.display = 'none';
}

