function drawObj(o,ts){
  if(!o.alive&&!(o.popped&&o.popR<1)) return;
  var sway=Math.sin(o.swayOff+ts*o.swayS)*o.swayA;
  var ox=o.x+sway,oy=o.y;
  o.hx=ox; o.hy=oy; o.spin=(o.spin||0)+.03;
  if(o.popped){
    ctx.save(); ctx.globalAlpha=Math.max(0,1-o.popR);
    ctx.strokeStyle=o.col; ctx.lineWidth=Math.max(0,4*(1-o.popR));
    ctx.beginPath(); ctx.arc(ox,oy,o.popR*o.r*2.8,0,Math.PI*2); ctx.stroke();
    ctx.restore(); return;
  }
  var rr=o.r*(1+Math.sin(ts*.002+o.phase)*.025);
  ctx.save(); ctx.translate(ox,oy);
  var sh=o.shape||'balloon';
  if(o.isSpec){
    var gw=ctx.createRadialGradient(0,0,0,0,0,rr*2.2);
    gw.addColorStop(0,o.col+'66'); gw.addColorStop(1,'transparent');
    ctx.fillStyle=gw; ctx.beginPath(); ctx.arc(0,0,rr*2.2,0,Math.PI*2); ctx.fill();
