    ctx.strokeStyle=o.col+'44'; ctx.lineWidth=1.5; ctx.beginPath(); ctx.moveTo(0,-rr*.85); ctx.lineTo(0,rr*.85); ctx.stroke();
    ctx.font=rr*.55+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
