    var cbg=ctx.createLinearGradient(-rr*.65,-rr*.1,rr*.65,rr*.75);
    cbg.addColorStop(0,'rgba(150,100,20,.9)'); cbg.addColorStop(.3,o.col+'ff'); cbg.addColorStop(.7,'rgba(100,65,10,.9)'); cbg.addColorStop(1,'rgba(70,40,5,.95)');
    ctx.fillStyle=cbg; ctx.beginPath(); ctx.roundRect(-rr*.65,-rr*.05,rr*1.3,rr*.8,4); ctx.fill();
    // Chest bands (metal straps)
    ctx.fillStyle='rgba(80,60,20,.6)'; ctx.fillRect(-rr*.65,rr*.1,rr*1.3,rr*.12); ctx.fillRect(-rr*.2,-rr*.06,rr*.4,rr*.86);
    // Metal corners
    ctx.fillStyle='rgba(200,160,40,.5)';
    [[-rr*.58,-rr*.02],[rr*.46,-rr*.02],[-rr*.58,rr*.56],[rr*.46,rr*.56]].forEach(function(c){ctx.beginPath();ctx.roundRect(c[0],c[1],rr*.2,rr*.2,2);ctx.fill();});
    // Lock
    var lkc=openPct>0?'rgba(80,200,80,.7)':'rgba(200,160,40,.7)';
    ctx.fillStyle=lkc; ctx.beginPath(); ctx.roundRect(-rr*.16,rr*.18,rr*.32,rr*.25,3); ctx.fill();
    ctx.strokeStyle=lkc; ctx.lineWidth=3; ctx.lineCap='round';
    ctx.beginPath(); ctx.arc(0,rr*.18,rr*.1,Math.PI,0); ctx.stroke();
    // LID - opens with taps
    var lidAngle = -openPct*Math.PI*.75;
    ctx.save(); ctx.translate(0,-rr*.05);
    ctx.rotate(lidAngle);
    var lidg=ctx.createLinearGradient(-rr*.65,-rr*.42,rr*.65,-rr*.05);
    lidg.addColorStop(0,'rgba(180,120,25,.9)'); lidg.addColorStop(.4,o.col+'ee'); lidg.addColorStop(1,'rgba(120,75,12,.9)');
    ctx.fillStyle=lidg; ctx.beginPath(); ctx.roundRect(-rr*.65,-rr*.42,rr*1.3,rr*.38,4); ctx.fill();
    // Lid arch
    var la2=ctx.createLinearGradient(-rr*.55,-rr*.72,rr*.55,-rr*.42);
    la2.addColorStop(0,'rgba(160,105,20,.85)'); la2.addColorStop(.5,o.col+'dd'); la2.addColorStop(1,'rgba(120,75,12,.85)');
    ctx.fillStyle=la2; ctx.beginPath(); ctx.ellipse(0,-rr*.42,rr*.6,rr*.2,0,Math.PI,0); ctx.fill();
    ctx.fillStyle='rgba(80,60,20,.55)'; ctx.fillRect(-rr*.55,-rr*.44,rr*1.1,rr*.1);
    ctx.restore();
    // Gold pouring out when open
    if(openPct>0.5){
      for(var gp2=0;gp2<8;gp2++){
        var gpa=Math.PI*(-.2+gp2*.18), gpd=rr*(.2+gp2*.1)*openPct;
        var gpx=Math.cos(gpa)*gpd, gpy=-rr*.1-Math.sin(gpa)*gpd-Math.abs(Math.sin(ts*.01+gp2))*rr*.15;
        ctx.fillStyle='rgba(255,220,50,'+(0.5+Math.sin(ts*.01+gp2)*.2)*openPct+')';
        ctx.beginPath(); ctx.ellipse(gpx,gpy,rr*.1,rr*.06,0,0,Math.PI*2); ctx.fill();
      }
    }
    // Tap count indicators (dots)
    for(var td=0;td<3;td++){
      ctx.fillStyle=td<tapN?'rgba(255,220,50,.9)':'rgba(255,255,255,.2)';
      ctx.beginPath(); ctx.arc(-rr*.2+td*rr*.2,rr*.92,rr*.08,0,Math.PI*2); ctx.fill();
    }
    // Emoji
    ctx.font=rr*.45+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(openPct>=1?'💰':o.emoji,0,rr*.35);
    ctx.restore();
    ctx.strokeStyle='rgba(100,100,100,.15)'; ctx.lineWidth=1.4;
    ctx.beginPath(); ctx.moveTo(0,rr*.97); ctx.quadraticCurveTo(4,rr+14,2,rr+28); ctx.stroke();
  } else if(sh==='puzzle'){
    ctx.save(); ctx.rotate(o.spin*.5);
    var pc=['#FF6B6B','#4ECDC4','#FFE66D','#A8E6CF','#FF8B94'];
    for(var pi=0;pi<4;pi++){
      var px3=(pi%2-.5)*rr*.6, py3=(Math.floor(pi/2)-.5)*rr*.6;
      ctx.fillStyle=pc[pi%pc.length]+'cc';
      ctx.beginPath(); ctx.roundRect(px3-rr*.28,py3-rr*.28,rr*.55,rr*.55,4); ctx.fill();
      // Tab
      ctx.beginPath(); ctx.arc(px3+(pi%2===0?rr*.27:-rr*.27),py3,rr*.1,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='rgba(255,255,255,.3)'; ctx.lineWidth=1.5; ctx.beginPath(); ctx.roundRect(px3-rr*.28,py3-rr*.28,rr*.55,rr*.55,4); ctx.stroke();
    }
    ctx.restore();
    ctx.strokeStyle='rgba(100,100,100,.18)'; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(0,rr*.7); ctx.quadraticCurveTo(4,rr+14,2,rr+28); ctx.stroke();
  } else if(sh==='letter'){
    var g=ctx.createRadialGradient(-rr*.25,-rr*.28,rr*.04,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.75)'); g.addColorStop(.2,o.col+'ee'); g.addColorStop(.8,o.col); g.addColorStop(1,o.col+'99');
    ctx.fillStyle=g; ctx.beginPath(); ctx.ellipse(0,-rr*.06,rr*.88,rr,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(0,255,100,.95)'; ctx.font='bold '+Math.round(rr*.75)+'px monospace'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.letter||'01',0,0);
    ctx.strokeStyle='rgba(0,255,100,.3)'; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(0,rr); ctx.quadraticCurveTo(5,rr+20,3,rr+36); ctx.stroke();
  } else {
    // default balloon
    var g=ctx.createRadialGradient(-rr*.25,-rr*.28,rr*.04,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.75)'); g.addColorStop(.2,o.col+'ee'); g.addColorStop(.8,o.col); g.addColorStop(1,o.col+'99');
    ctx.fillStyle=g; ctx.beginPath(); ctx.ellipse(0,-rr*.06,rr*.88,rr,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(255,255,255,.42)'; ctx.beginPath(); ctx.ellipse(-rr*.22,-rr*.3,rr*.26,rr*.16,-.4,0,Math.PI*2); ctx.fill();
    if(o.word){
      // Emoji üstte
      ctx.font=Math.round(rr*.38)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(o.word.ico,0,-rr*.48);
      // Türkçe (küçük, gri)
      ctx.fillStyle='rgba(40,40,40,.75)'; ctx.font=Math.max(8,Math.min(13,rr*.35))+'px Nunito';
      ctx.fillText(evText(o.word.tr),0,-rr*.12);
      // İngilizce veya Almanca (büyük, siyah)
      var trs3=(currentRoom&&currentRoom.lang)?getForeignWord(o.word,currentRoom.lang):o.word.en;
      ctx.fillStyle='rgba(10,10,10,.95)'; ctx.font='bold '+Math.max(10,Math.min(20,rr*.52))+'px Fredoka One';
      ctx.fillText(evText(trs3),0,rr*.22);
    } else if(currentRoom && currentRoom.id==='dunya' && !o.isSpec){
      // Dünya odası: her balonun üzerinde farklı ülke bayrağı
      var _flagIdx = (o._countryIdx !== undefined) ? o._countryIdx : Math.floor(Math.random()*DUNYA_COUNTRIES.length);
      if(o._countryIdx === undefined) o._countryIdx = _flagIdx;
      var _fc = DUNYA_COUNTRIES[_flagIdx % DUNYA_COUNTRIES.length];
      ctx.font=Math.round(rr*1.1)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(_fc.flag, 0, 0);
    } else {
      ctx.font=rr*(o.isSpec?.72:.68)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.isSpec?'✨':o.emoji,0,0);
    }
    ctx.strokeStyle='rgba(100,100,100,.22)'; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(0,rr); ctx.quadraticCurveTo(4,rr+18,2,rr+34); ctx.stroke();
  }
  ctx.restore();
}

