if(sh==='mission_balloon'){
    evV48S35DrawMissionBalloon(o,rr,ts);
  } else if(sh==='star'){
    ctx.rotate(o.spin);
    ctx.fillStyle=o.col+'cc'; ctx.beginPath();
    for(var i=0;i<10;i++){var a=i/10*Math.PI*2-Math.PI/2,r2=i%2===0?rr:rr*.45;i===0?ctx.moveTo(Math.cos(a)*r2,Math.sin(a)*r2):ctx.lineTo(Math.cos(a)*r2,Math.sin(a)*r2);}
    ctx.closePath(); ctx.fill();
    ctx.font=rr*.65+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='answer_balloon'){
    // Özel cevap balonu — çocuk buraya dokununca cevabı öğrenir
    var ag=ctx.createRadialGradient(-rr*.3,-rr*.35,rr*.08,0,0,rr);
    ag.addColorStop(0,'rgba(255,255,180,.85)');
    ag.addColorStop(.4,'rgba(255,215,0,.75)');
    ag.addColorStop(1,'rgba(200,150,0,.6)');
    ctx.fillStyle=ag;
    ctx.beginPath(); ctx.ellipse(0,-rr*.1,rr*.9,rr,0,0,Math.PI*2); ctx.fill();
    // Parlak kenar
    ctx.strokeStyle='rgba(255,240,100,.6)'; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.ellipse(0,-rr*.1,rr*.9,rr,0,0,Math.PI*2); ctx.stroke();
    // Ip
    ctx.strokeStyle='rgba(200,150,0,.5)'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.moveTo(0,rr*.92);
    ctx.quadraticCurveTo(rr*.18,rr*1.3,rr*.06,rr*1.65); ctx.stroke();
    // Soru işareti + metin
    ctx.font='bold '+Math.round(rr*.55)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillStyle='rgba(80,40,0,.9)'; ctx.fillText('❓',0,-rr*.1);
    // Alt yazı
    ctx.font='bold '+Math.round(rr*.22)+'px Fredoka One,sans-serif';
    ctx.fillStyle='rgba(100,60,0,.8)';
    ctx.fillText(evText('Cevap!'),0,rr*.62);
    // Parlayan halka
    var glowA=0.15+Math.sin(Date.now()*.003)*.08;
    var glw=ctx.createRadialGradient(0,0,rr*.8,0,0,rr*1.4);
    glw.addColorStop(0,'rgba(255,220,50,'+glowA+')');
    glw.addColorStop(1,'rgba(255,220,50,0)');
    ctx.fillStyle=glw; ctx.beginPath(); ctx.arc(0,0,rr*1.4,0,Math.PI*2); ctx.fill();
  } else if(sh==='ball'){
    var g=ctx.createRadialGradient(-rr*.3,-rr*.3,rr*.05,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.8)'); g.addColorStop(.3,o.col+'ee'); g.addColorStop(1,o.col+'aa');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle=o.col+'66'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(0,0,rr*.65,-.6,Math.PI+.6); ctx.stroke();
    ctx.font=rr*.68+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
    ctx.strokeStyle='rgba(0,0,0,.15)'; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(0,rr); ctx.quadraticCurveTo(5,rr+18,3,rr+32); ctx.stroke();
  } else if(sh==='heart'){
    ctx.rotate(Math.sin(ts*.003+o.phase)*.08);
    ctx.fillStyle=o.col+'cc'; ctx.beginPath(); ctx.moveTo(0,rr*.3);
    ctx.bezierCurveTo(0,-rr*.5,-rr*1.1,-rr*.5,-rr,0); ctx.bezierCurveTo(-rr,rr*.55,0,rr*.9,0,rr*.3);
    ctx.bezierCurveTo(0,rr*.9,rr,rr*.55,rr,0); ctx.bezierCurveTo(rr*1.1,-rr*.5,0,-rr*.5,0,rr*.3); ctx.fill();
    ctx.font=rr*.55+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,rr*.05,-rr*.05);
  } else if(sh==='butterfly'){
    var wf=Math.sin(ts*.012+o.phase)*.4;
    ctx.fillStyle=o.col+'cc';
    ctx.beginPath(); ctx.ellipse(-rr*.7,-rr*.3,rr*.7*(1+wf*.3),rr*.45,.3+wf,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(rr*.7,-rr*.3,rr*.7*(1+wf*.3),rr*.45,-.3-wf,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=o.col+'88';
    ctx.beginPath(); ctx.ellipse(-rr*.5,rr*.2,rr*.45,rr*.3,.5,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(rr*.5,rr*.2,rr*.45,rr*.3,-.5,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(30,20,10,.5)'; ctx.beginPath(); ctx.ellipse(0,0,3,rr*.6,0,0,Math.PI*2); ctx.fill();
    ctx.font=rr*.5+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='leaf'){
    ctx.rotate(o.spin*.5+Math.sin(ts*.002+o.phase)*.1);
