    ctx.strokeStyle=o.col+'44'; ctx.lineWidth=1.5; ctx.beginPath(); ctx.moveTo(0,-rr*.85); ctx.lineTo(0,rr*.85); ctx.stroke();
    ctx.font=rr*.55+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='fish'){
    ctx.rotate(Math.sin(ts*.002+o.phase)*.06);
    ctx.fillStyle=o.col+'cc'; ctx.beginPath(); ctx.ellipse(0,0,rr,rr*.55,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=o.col+'88'; ctx.beginPath(); ctx.moveTo(rr*.7,0); ctx.lineTo(rr*1.25,-rr*.35); ctx.lineTo(rr*1.25,rr*.35); ctx.closePath(); ctx.fill();
    ctx.fillStyle='rgba(0,0,0,.6)'; ctx.beginPath(); ctx.arc(-rr*.6,0,rr*.1,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='white'; ctx.beginPath(); ctx.arc(-rr*.57,-rr*.04,rr*.04,0,Math.PI*2); ctx.fill();
    if(o.emoji){ctx.font=Math.round(rr*.7)+'px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.globalAlpha=.85;ctx.fillText(o.emoji,0,0);ctx.globalAlpha=1;}
  } else if(sh==='flower'){
    ctx.rotate(o.spin*.3);
    for(var p=0;p<6;p++){var a=p/6*Math.PI*2; ctx.fillStyle=o.col+'bb'; ctx.beginPath(); ctx.ellipse(Math.cos(a)*rr*.55,Math.sin(a)*rr*.55,rr*.42,rr*.26,a,0,Math.PI*2); ctx.fill();}
    ctx.fillStyle='#FFD700'; ctx.beginPath(); ctx.arc(0,0,rr*.32,0,Math.PI*2); ctx.fill();
    ctx.font=rr*.32+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='snowflake'){
    ctx.rotate(o.spin*.5); ctx.strokeStyle=o.col; ctx.lineWidth=2.5; ctx.lineCap='round';
    for(var a=0;a<6;a++){var ang=a/6*Math.PI*2;
      ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(ang)*rr,Math.sin(ang)*rr); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(Math.cos(ang)*rr*.5,Math.sin(ang)*rr*.5); ctx.lineTo(Math.cos(ang+.5)*rr*.65,Math.sin(ang+.5)*rr*.65); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(Math.cos(ang)*rr*.5,Math.sin(ang)*rr*.5); ctx.lineTo(Math.cos(ang-.5)*rr*.65,Math.sin(ang-.5)*rr*.65); ctx.stroke();}
    ctx.font=rr*.5+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='clock'){
    var g=ctx.createRadialGradient(-rr*.2,-rr*.2,2,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.6)'); g.addColorStop(.4,o.col+'dd'); g.addColorStop(1,o.col+'88');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,.4)'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2); ctx.stroke();
    for(var h=0;h<12;h++){var a=h/12*Math.PI*2-Math.PI/2; ctx.strokeStyle='rgba(255,255,255,.5)'; ctx.lineWidth=h%3===0?2:1; ctx.beginPath(); ctx.moveTo(Math.cos(a)*rr*.72,Math.sin(a)*rr*.72); ctx.lineTo(Math.cos(a)*rr*.9,Math.sin(a)*rr*.9); ctx.stroke();}
    var sec=ts*.001,min=ts*.00016;
    ctx.strokeStyle='rgba(255,255,255,.85)'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(min-Math.PI/2)*rr*.55,Math.sin(min-Math.PI/2)*rr*.55); ctx.stroke();
    ctx.strokeStyle='rgba(255,200,100,.9)'; ctx.lineWidth=1.5; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(sec-Math.PI/2)*rr*.7,Math.sin(sec-Math.PI/2)*rr*.7); ctx.stroke();
    ctx.fillStyle='white'; ctx.beginPath(); ctx.arc(0,0,rr*.12,0,Math.PI*2); ctx.fill();
  } else if(sh==='planet'){
    var g=ctx.createRadialGradient(-rr*.3,-rr*.3,rr*.04,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.4)'); g.addColorStop(.3,o.col+'cc'); g.addColorStop(1,o.col+'66');
