    ctx.font=rr*.6+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='fruit'){
    var g=ctx.createRadialGradient(-rr*.25,-rr*.25,rr*.05,0,0,rr);
    g.addColorStop(0,'rgba(255,255,255,.7)'); g.addColorStop(.3,o.col+'ee'); g.addColorStop(1,o.col+'99');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='#5C9E3A'; ctx.lineWidth=2.5; ctx.beginPath(); ctx.moveTo(0,-rr); ctx.quadraticCurveTo(rr*.2,-rr*1.2,rr*.1,-rr*1.35); ctx.stroke();
    ctx.font=rr*.68+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='palette'){
    ctx.rotate(o.spin*.3); ctx.fillStyle=o.col+'cc'; ctx.beginPath(); ctx.ellipse(0,0,rr,rr*.85,0,0,Math.PI*2); ctx.fill();
    ['#FF5555','#5599FF','#FFDD44','#55CC55','#FF88CC'].forEach(function(c,i){var a=i/5*Math.PI*1.8-Math.PI*.3; ctx.fillStyle=c+'cc'; ctx.beginPath(); ctx.arc(Math.cos(a)*rr*.6,Math.sin(a)*rr*.6,rr*.2,0,Math.PI*2); ctx.fill();});
    ctx.font=rr*.5+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('🎨',0,0);
  } else if(sh==='trophy'){
    ctx.fillStyle=o.col+'cc'; ctx.beginPath(); ctx.moveTo(-rr*.6,-rr*.4); ctx.quadraticCurveTo(-rr*.8,rr*.2,-rr*.5,rr*.5); ctx.lineTo(rr*.5,rr*.5); ctx.quadraticCurveTo(rr*.8,rr*.2,rr*.6,-rr*.4); ctx.closePath(); ctx.fill();
    ctx.fillRect(-rr*.5,rr*.5,rr,rr*.2); ctx.fillRect(-rr*.35,rr*.68,rr*.7,rr*.18);
    ctx.font=rr*.5+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('🏆',0,-rr*.05);
  } else if(sh==='magic'){
    ctx.rotate(o.spin*2);
    for(var i=0;i<6;i++){var a=i/6*Math.PI*2; ctx.fillStyle=o.col+(i%2===0?'cc':'44'); ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0,rr,a,a+Math.PI/6); ctx.closePath(); ctx.fill();}
    ctx.fillStyle='rgba(0,0,0,.4)'; ctx.beginPath(); ctx.arc(0,0,rr*.42,0,Math.PI*2); ctx.fill();
    ctx.font=rr*.6+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='gear'){
    ctx.rotate(o.spin*3); ctx.strokeStyle=o.col; ctx.lineWidth=3; ctx.beginPath();
    for(var i=0;i<16;i++){var a=i/8*Math.PI,rg=i%2===0?rr:rr*.72;i===0?ctx.moveTo(Math.cos(a)*rg,Math.sin(a)*rg):ctx.lineTo(Math.cos(a)*rg,Math.sin(a)*rg);}
    ctx.closePath(); ctx.stroke(); ctx.beginPath(); ctx.arc(0,0,rr*.4,0,Math.PI*2); ctx.stroke();
    ctx.font=rr*.5+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(o.emoji,0,0);
  } else if(sh==='wave'){
    for(var i=0;i<3;i++){ctx.beginPath(); var yw=-rr*.2+i*rr*.3; ctx.moveTo(-rr,yw); for(var wx=-rr;wx<=rr;wx+=5){ctx.lineTo(wx,yw+Math.sin((wx+ts*0.05+i*1.2)*.15)*rr*.25);} ctx.lineTo(rr,rr*1.2); ctx.lineTo(-rr,rr*1.2); ctx.closePath(); ctx.fillStyle=o.col+(i===0?'aa':i===1?'77':'44'); ctx.fill();}
