function addScore(pts,x,y,col){
  pts=parseInt(pts)||0;
  roomScore+=pts; totalScore+=pts;
  if(currentRoom&&currentRoom.id==='gizli'){
    secretScore+=pts; savePlayerData();
    checkSecretPhase();
  }
  savePlayerData();
  var el=document.getElementById('gsn');
  if(!el) return;
  el.textContent=roomScore; el.classList.remove('bump'); void el.offsetWidth; el.classList.add('bump');
  document.getElementById('hsc').textContent=totalScore;
  scoreFloat(x,y,pts,col);
  document.getElementById('gp').style.width=Math.min(100,(roomScore/250)*100)+'%';
  updateLvl();
  okiReactToScore(pts);
  var a=ACH_LIST[nextAch];
  if(a&&totalScore>=a.at){ nextAch++; showAch(a); }
}

