function tryPop(px,py){
  getAC();
  var now=Date.now();
  for(var i=objs.length-1;i>=0;i--){
    var o=objs[i];
    if(o.popped||!o.alive) continue;
    var dx=px-o.hx, dy=py-o.hy;
    if(Math.sqrt(dx*dx+dy*dy)<o.hr+18){
      // ── CHEST: triple tap with ripple ──
      if(o.shape==='chest'){
        if(!o.tapCount) o.tapCount=0;
        if(!o.lastTap)  o.lastTap=0;
        var gap=now-o.lastTap;
        o.lastTap=now;
        if(gap<1400) o.tapCount++;
        else o.tapCount=1;
        o.phase+=1.5; // wobble
        playPop();
        // Ripple wave out from chest
        for(var rw=0;rw<3;rw++){
          parts.push({x:o.hx,y:o.hy,vx:0,vy:0,al:0.8,dc:.025+rw*.008,
            col:['rgba(255,215,50,.5)','rgba(255,140,20,.4)','rgba(255,80,0,.3)'][rw],
            tp:false, ripple:true, rr:0, rrMax:o.hr*(2.5+rw*.8), rrSpd:o.hr*.18, w:4-rw});
        }
        // ── TEK DOKUNUŞ: BIG EXPLOSION ──
        o.tapCount=1; o.popped=true; o.popR=0; o.alive=false;
        playSpec();
        // Massive burst in multiple waves
        for(var bw=0;bw<4;bw++){
          burst(o.hx,o.hy,'#FFD700',true);
          burst(o.hx,o.hy,'#FF8C00',bw%2===0);
        }
        // Gold coins flying out
        var coinCols=['#FFD700','#FFC200','#FFAA00','#FF8C00','#FFE066'];
        for(var gc3=0;gc3<30;gc3++){
          var ga=Math.random()*Math.PI*2, gs=4+Math.random()*10;
          parts.push({x:o.hx,y:o.hy,vx:Math.cos(ga)*gs,vy:Math.sin(ga)*gs-5,
            w:10+Math.random()*8,h:6+Math.random()*5,r:Math.random()*Math.PI,vr:(Math.random()-.5)*.3,
            al:1,dc:.012,col:coinCols[Math.floor(Math.random()*coinCols.length)]});
        }
        // Gems flying out
        ['#FF4444','#4488FF','#44FF88','#FF44FF','#44FFFF'].forEach(function(gc4){
          var ga2=Math.random()*Math.PI*2, gs2=3+Math.random()*8;
          parts.push({x:o.hx,y:o.hy,vx:Math.cos(ga2)*gs2,vy:Math.sin(ga2)*gs2-4,
            w:8,h:8,r:Math.random()*Math.PI,vr:.2,al:1,dc:.014,col:gc4});
        });
        // Score (no message needed for hazine)
        var prizes=[5000,8000,10000,15000,20000,25000];
        var prize=prizes[Math.floor(Math.random()*prizes.length)];
        var hzd=JSON.parse(localStorage.getItem(_hzKey())||'{}');
        if(hzd.done){ showHazineDone(); return true; }
        hzd.total=(hzd.total||0)+prize;
        // Add score with big floating number
        addScore(prize,o.hx,o.hy,'#FFD700');
        parts.push({x:o.hx,y:o.hy-o.hr,vx:0,vy:-2,w:0,h:0,al:1.5,dc:.015,tp:true,txt:'+'+prize+'⭐',col:'rgba(255,215,50,1)'});
        // Check if daily done (no hard limit)
        hzd.count=(hzd.count||0)+1;
        if(hzd.count>=5) hzd.done=true;
        localStorage.setItem(_hzKey(),JSON.stringify(hzd));
        if(hzd.done) setTimeout(showHazineDone,2500);
        return true;
      }
      // ── KUMANDA: renk değişimi + özel ses ──
      if(currentRoom&&currentRoom.id==='kumanda'&&o.shape==='remote'){
        if(!window._kumandaIntroShown){
          window._kumandaIntroShown=true;
          setTimeout(function(){showOkiBubble('🎮 Kumandaları patlat! Ses dalgalarını ve ışığı keşfet! ⚡');},600);
        }
        // 5+ farklı patlama sesi
        var kumSounds=[
          function(){try{var ac=getAC();var o2=ac.createOscillator(),g=ac.createGain();o2.type='sawtooth';o2.frequency.setValueAtTime(80,ac.currentTime);o2.frequency.exponentialRampToValueAtTime(30,ac.currentTime+.4);g.gain.setValueAtTime(.5,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.4);o2.connect(g);g.connect(ac.destination);o2.start();o2.stop(ac.currentTime+.4);}catch(e){}},  // BOOM
          function(){try{var ac=getAC();[440,880,660].forEach(function(f,i){var o3=ac.createOscillator(),g2=ac.createGain();o3.frequency.value=f;o3.type='square';g2.gain.setValueAtTime(.2,ac.currentTime+i*.05);g2.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.05+.15);o3.connect(g2);g2.connect(ac.destination);o3.start(ac.currentTime+i*.05);o3.stop(ac.currentTime+i*.05+.15);});}catch(e){}},  // ZAP
