        showMsg(o.hx,o.hy,{e:'💡',t:'Cevap: '+o.answerText+' — '+o.answerExp,p:0},o.col);
        return true;
      }
      var msgs=(currentRoom&&currentRoom.id==='kucukmelekler'&&typeof evV45KMEMessages==='function')?evV45KMEMessages():(MSGS[currentRoom.id]||MSGS.ibadet);
      var msg=getNextMsg(currentRoom.id,msgs);
      showMsg(o.hx,o.hy,msg,o.col);
      if(currentRoom.id==='arapca'&&o.letter){
        speakArabic(o.letter);
        trackArabicLetter(o.letter);
      }
      addScore(o.isSpec?msg.p*3:msg.p,o.hx,o.hy,o.col);
      return true;
    }
  }
  return false;
}

