          var freqs=[261,294,329,349,392,440,494,523,587,659,698,784];
          osc.frequency.value=freqs[Math.floor(Math.random()*freqs.length)];
          osc.type=['sine','triangle'][Math.floor(Math.random()*2)];
          gn2.gain.setValueAtTime(.3,ac2.currentTime);
          gn2.gain.exponentialRampToValueAtTime(.001,ac2.currentTime+.8);
          osc.connect(gn2); gn2.connect(ac2.destination);
          osc.start(); osc.stop(ac2.currentTime+.8);
          window._v33MusicPulse={x:o.hx||o.x,y:o.hy||o.y,t:Date.now(),note:o.e||o.ico||'♪'};
        }catch(ex){}
      }
      // ── V48S35 özel görev balonu ──
      if(o.shape==='mission_balloon'){ return evV48S35MissionPop(o); }
      // ── NORMAL POP ──
      o.popped=true; o.popR=0; o.alive=false;
      evV48S35NormalPop();
      // Dünya odası: ülke bilgisi göster
      if(gameActive && currentRoom && currentRoom.id==='dunya'){
        var _cidx = (o._countryIdx !== undefined) ? o._countryIdx : _dunyaCountryIdx++;
        var _c = DUNYA_COUNTRIES[_cidx % DUNYA_COUNTRIES.length];
        var _cn = _getCountryName(_c);
        showMsg(o.hx, o.hy-20, _c.flag+' '+_cn, '#FFD700');
        var _ct = document.createElement('div');
        _ct.className = '_gf';
        _ct.style.cssText = 'position:fixed;bottom:100px;left:50%;transform:translateX(-50%);z-index:9998;background:linear-gradient(135deg,#003366,#0055AA);border:1px solid rgba(100,200,255,.4);border-radius:20px;padding:10px 18px;font-family:Fredoka One;font-size:.85rem;color:#fff;box-shadow:0 4px 20px rgba(0,100,200,.4);pointer-events:none;max-width:85vw;text-align:center;';
