      // Kumanda odasında özel ses + renk flash
      if(currentRoom&&currentRoom.id==='kumanda'){
        var kumSounds=[
          function(){tone(200,.12,.4,'sawtooth');setTimeout(function(){tone(400,.1,.3,'square');},80);},
          function(){tone(800,.08,.2,'sine');setTimeout(function(){tone(1200,.06,.2,'sine');},60);setTimeout(function(){tone(600,.08,.3,'sine');},150);},
          function(){[150,300,600,900].forEach(function(f,i){setTimeout(function(){tone(f,.06,.25,'sawtooth');},i*50);});},
          function(){tone(1000,.06,.15,'square');setTimeout(function(){tone(500,.08,.2,'square');},100);setTimeout(function(){tone(250,.1,.3,'sawtooth');},200);},
          function(){[440,554,659,880].forEach(function(f,i){setTimeout(function(){tone(f,.05,.2,'sine');},i*40);});},
          function(){tone(100,.15,.5,'sawtooth');setTimeout(function(){tone(200,.1,.3,'sawtooth');},100);},
        ];
        kumSounds[Math.floor(Math.random()*kumSounds.length)]();
        // Screen color flash
