        showLangMsg(o.hx,o.hy,o.word,trs,flag,langCol,lang,prog);
        // Oki reads the card
        setTimeout(function(){
          var cardMsgs = [
            (o.word.tr||o.word)+' demek! Harika! 📖',
            'Ooh! Bu kelimeyi ezberle! 🧠',
            'Bir daha dene! '+( trs||'')+' 🔤',
            'Aferin! Yeni kelime ogrendik! ⭐',
            'Bak bak! Ne guzel bir kelime! 📚',
          ];
          showOkiBubble(cardMsgs[Math.floor(Math.random()*cardMsgs.length)]);
        }, 1500);
        // Ses: önce chime, sonra kelimeyi oku
        try{ tone(660,.06,.3,'sine'); setTimeout(function(){tone(880,.05,.2,'sine');},120); }catch(ex){}
        if(window.speechSynthesis){
          var utt=new SpeechSynthesisUtterance(trs);
          utt.lang=slang; utt.rate=0.82; utt.pitch=1.1; utt.volume=0.95;
          window.speechSynthesis.cancel();
          setTimeout(function(){window.speechSynthesis.speak(utt);},350);
        }
        return true;
      }
      // Cevap balonu: cevabı göster
      if(o.shape==='answer_balloon'){
