function gameLoop(ts){
  requestAnimationFrame(gameLoop);
  if(!gameActive) return;
  var dt=Math.min((ts-lastTS)/16.67,3); lastTS=ts;
  ctx.fillStyle='#000510'; ctx.fillRect(0,0,W,H);
  drawBg(ts);
  if(currentRoom&&currentRoom.id==='gizli'){ drawSecretExtras(ts); evV41DrawSecretKey(ts); }
  if(currentRoom&&currentRoom.id==='nefes') drawNefesOverlay(ts);
  // V48S35 Doğa görev balonu denemesi
  if(evV48S35ShouldSpawn()){ evV48S35SpawnMissionBalloon(); }
  // Cevap balonunu oyun başında spawn et
  if(gameActive && _soruState.answerBalloonPending && !_soruState.answerBalloonSpawned && objs.length>=0){
    spawnAnswerBalloon();
  }
  var roomObjCap=(currentRoom&&currentRoom.id==='ders')?5:14; // EV_DERS_EFFECT_DENSITY_V1
  if(ts-lastSpawn>1200&&objs.filter(function(o){return o.alive&&!o.popped;}).length<roomObjCap){
    spawnObj(); lastSpawn=ts;
  }
  objs.forEach(function(o){
    if(o.popped){ o.popR=Math.min(1,o.popR+.06*dt); return; }
    if(!o.alive) return;
    o.y-=o.speed*dt;
    if(o.y<-120){ o.alive=false; return; }
    drawObj(o,ts);
  });
  objs.forEach(function(o){ if(o.popped&&o.popR<1) drawObj(o,ts); });
  objs=objs.filter(function(o){ return o.alive||(o.popped&&o.popR<1); });
  drawParts();
  // Draw Oki on game canvas
}

