function getStreak(){
  var last=typeof _eduGetScoped==='function'?_eduGetScoped('dei_last',''):localStorage.getItem('dei_last');
  var sc=parseInt((typeof _eduGetScoped==='function'?_eduGetScoped('dei_streak','0'):localStorage.getItem('dei_streak'))||'0');
  if(!last) return 0;
  var yest=new Date(); yest.setDate(yest.getDate()-1);
  return (last===getTodayStr()||last===yest.toDateString())?sc:0;
}

