function updateStreak(){
  var today=getTodayStr(),last=typeof _eduGetScoped==='function'?_eduGetScoped('dei_last',''):localStorage.getItem('dei_last');
  if(last===today) return;
  var sc=parseInt((typeof _eduGetScoped==='function'?_eduGetScoped('dei_streak','0'):localStorage.getItem('dei_streak'))||'0');
  var yest=new Date(); yest.setDate(yest.getDate()-1);
  sc=(!last||last===yest.toDateString())?sc+1:1;
  if(typeof _eduSetScoped==='function'){ _eduSetScoped('dei_streak',sc); _eduSetScoped('dei_last',today); }
  else{ localStorage.setItem('dei_streak',sc); localStorage.setItem('dei_last',today); }
}

