    var qov=document.getElementById('qr-ov');
    if(qov){ qov.setAttribute('dir','rtl'); qov.setAttribute('lang','ar'); }
    if(rap) rap.textContent='\uD83D\uDCCA \u062A\u0642\u0631\u064A\u0631';
    if(qr) qr.textContent='\uD83D\uDCCA \u0645\u0634\u0627\u0631\u0643\u0629';
    if(rt) rt.textContent='\uD83D\uDCCA \u062A\u0642\u0631\u064A\u0631';
    if(qt) qt.textContent='\u062A\u0642\u0631\u064A\u0631 \u0627\u0644\u0648\u0627\u0644\u062F\u064A\u0646';
    if(qs) qs.textContent='\u0645\u0644\u062E\u0635 \u064A\u0648\u0645\u064A \u0644\u0644\u062A\u0639\u0644\u0645';
    if(qu && (!qu.textContent || qu.textContent.indexOf('http')<0)) qu.textContent='\u064A\u062A\u0645 \u062A\u062D\u0636\u064A\u0631 \u0627\u0644\u062A\u0642\u0631\u064A\u0631...';
    if(qh) qh.textContent='\u0627\u0645\u0633\u062D \u0631\u0645\u0632 QR \u0628\u0627\u0644\u0647\u0627\u062A\u0641';
    var dl=document.querySelector('#qr-ov button[onclick="downloadPDF()"]');
    if(dl) dl.textContent='\u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u062A\u0642\u0631\u064A\u0631';
    var mail=document.querySelector('#qr-ov button[onclick="sendMailReport()"]');
    if(mail) mail.textContent='\u0625\u0631\u0633\u0627\u0644 \u0628\u0627\u0644\u0628\u0631\u064A\u062F';
    var closes=document.querySelectorAll('#qr-ov button[onclick*="qr-ov"]');
    closes.forEach(function(b){
      if(b.getAttribute('data-qr-close-icon')==='1'){ b.textContent='×'; b.setAttribute('aria-label','\u0625\u063A\u0644\u0627\u0642'); b.setAttribute('title','\u0625\u063A\u0644\u0627\u0642'); }
      else { b.textContent='\u0625\u063A\u0644\u0627\u0642'; }
    });
  }
}

