function buildGrid(){
  var grid=document.getElementById('rgrid');
  grid.innerHTML='';
  updateStreak();
  var streak=getStreak();
  var sm=document.getElementById('streak-msg');
  if(streak>=5){
    var sr=ROOMS.find(function(r){return r.id==='gizli';}); if(sr) sr.unlock=0;
    sm.textContent=evText('Gizli Oda Acik! 5 gun tamamlandi!'); sm.style.display='block';
  } else if(streak>0){
    sm.textContent=(evValuesOn()&&evValuesLang()==='fr')?(streak+'/5 jour - Salle mystere dans '+(5-streak)+' jours !'):(evValuesOn()&&evValuesLang()==='ar')?(streak+'/5 يوم - الغرفة الغامضة بعد '+(5-streak)+' أيام!'):(evValuesOn()&&evValuesLang()==='tr')?(streak+'/5 gün - Gizli Oda için '+(5-streak)+' gün kaldı!'):(streak+'/5 '+evText('gun')+' - '+evText('Gizli Oda icin')+' '+(5-streak)+' '+evText('gun kaldi')+'!'); sm.style.display='block';
  } else { sm.style.display='none'; }
  ROOMS.forEach(function(room){
    var _v43KmeClosed=(room.id==='kucukmelekler' && !(evV43KMEEnabled&&evV43KMEEnabled()));
    var _vOn2=!!(evValuesOn&&evValuesOn())||localStorage.getItem('eduverse_values_mode')==='1';
    var locked=_v43KmeClosed?true:(room.id==='sinema'?false:(room.id==='gizli'?!(streak>=5 || room.unlock===0):(_vOn2?false:(totalScore<room.unlock))));
    var best=roomBests[room.id]||0;
    var btn=document.createElement('button');
    btn.className='rb'+(locked&&room.id!=='sinema'?' locked':'');
    var arGrid = evArabicActive&&evArabicActive();
    var bestLabel = arGrid ? '\u0627\u0644\u0623\u0641\u0636\u0644' : evText('En iyi');
    var watchLabel = arGrid ? '\u0645\u0634\u0627\u0647\u062F\u0629' : evText('Izle');
    btn.innerHTML='<div class="rb-ico">'+evRoomDisplayIcon(room)+'</div><div class="rb-name">'+evRoomDisplayName(room)+'</div><div class="rb-info">'+(_v43KmeClosed?'🔒 Ebeveyn açar':(locked&&room.id!=='sinema'?'\uD83D\uDD12 '+room.unlock+'\u2B50':best&&room.id!=='sinema'?best+'\u2B50 '+bestLabel:'\u25B6 '+watchLabel+'!'))+'</div>';
/* EV_ROOM_CARD_TEXTCONTENT_GUARD_V1
   innerHTML parser/translation race sonrasinda oda kartinin
   ikon, isim ve bilgi satirini Unicode textContent ile sabitle.
*/
var _rbIcoNode=btn.querySelector('.rb-ico');
var _rbNameNode=btn.querySelector('.rb-name');
var _rbInfoNode=btn.querySelector('.rb-info');

if(_rbIcoNode){
_rbIcoNode.textContent=evRoomDisplayIcon(room);
}

if(_rbNameNode){
_rbNameNode.textContent=evRoomDisplayName(room);
}

if(_rbInfoNode){

var _rbInfoText=
_v43KmeClosed
?'\uD83D\uDD12 Ebeveyn a\u00E7ar'
:(locked&&room.id!=='sinema'
?'\uD83D\uDD12 '+room.unlock+'\u2B50'
:(best&&room.id!=='sinema'
?best+'\u2B50 '+bestLabel
:'\u25B6 '+watchLabel+'!'));

_rbInfoNode.textContent=_rbInfoText;
}
    if(room.id==='kucukmelekler'){ btn.style.background='radial-gradient(circle at 20% 0%,rgba(255,232,166,.28),transparent 34%),linear-gradient(145deg,rgba(255,210,120,.22),rgba(110,155,255,.10),rgba(255,255,255,.055))'; btn.style.border='1.5px solid rgba(255,232,166,.35)'; btn.style.boxShadow='0 12px 38px rgba(0,0,0,.25),0 0 28px rgba(255,220,140,.18)'; if(_v43KmeClosed){btn.classList.add('locked'); btn.style.opacity='.92'; btn.style.filter='saturate(1.05)';} }
    if(room.id==='kucukmelekler' && _v43KmeClosed){ btn.onclick=function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} evV43AskEnableKME(); return false; }; btn.addEventListener('touchend',function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} evV43AskEnableKME(); return false; },{passive:false}); }
    else if(room.id==='kucukmelekler') btn.onclick=function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} evV44OpenKMEHub(); return false; };
    else if(!locked||room.id==='sinema') btn.onclick=function(){enterRoom(room);};
    grid.appendChild(btn);
  });
}

