function enterRoom(room){
  if(room&&room.id==='kucukmelekler'&&window.__evV44KMEBypassQuestion){ _showRoomHook(room,function(){ _doEnterRoom(room); }); return; }
  if(room.special==='sinema'){openSinema();return;}
  if(room.special==='hikaye'){openHikaye();return;}
  if(room.special==='refleks'){
    // Refleks odasında soru balonu istemiyoruz
    _soruState.answerBalloonPending=false;
    _soruState.active=false;
    openRefleks();return;
  }
  if(room.special==='puzzle'||room.special==='boyama'){
    // Puzzle/boyama için soru korunur. Boyama için soru sonrası liquid oda giriş penceresi de gösterilir.
    showRoomSoru(room, function(){
      _soruState.answerBalloonPending=false; // Bu odalarda balon yok
      if(room.special==='puzzle'){openPuzzle();return;}
      if(room.special==='boyama'){
        _showRoomHook(room, function(){ openBoyama(); });
        return;
      }
    });
    return;
  }
  showRoomSoru(room, function(){
    _showRoomHook(room, function(){ _doEnterRoom(room); });
  });
}

