function _showRoomHook(room, cb){
  var ov=document.getElementById('room-hook-ov');
  var card=document.getElementById('room-hook-card');
  var ico=document.getElementById('room-hook-ico');
  var name=document.getElementById('room-hook-name');
  var sub=document.getElementById('room-hook-sub');
  var bar=document.getElementById('room-hook-bar');
  if(!ov||!card){cb();return;}
  if(ico){
    ico.textContent=(typeof evRoomDisplayIcon==='function'?evRoomDisplayIcon(room):((room&&room.icon)||'✨'));
    ico.style.display='block';
    ico.setAttribute('aria-hidden','true');
  }
  if(name) name.textContent=(typeof evRoomDisplayName==='function'?evRoomDisplayName(room):evText(room.name));
  if(sub){
    var _hl='tr'; try{ _hl=(evJarLang&&evJarLang())||'tr'; }catch(e){}
    var _readyMap={tr:'Hazır mısın?',de:'Bereit?',en:'Ready?',fr:'Prêt ?',ar:'هل أنت مستعد؟'};
    sub.textContent=_readyMap[_hl]||'Hazır mısın?';
    sub.setAttribute('translate','no');
  }
  bar.style.transition='none';
  bar.style.width='0%';
  ov.style.display='flex';
  ov.style.pointerEvents='auto';
  // Bg fade in
  setTimeout(function(){ ov.style.background='rgba(8,12,24,.18)'; },10);
  // Card pop in
  setTimeout(function(){
    card.style.transform='scale(1)';
    card.style.opacity='1';
    // Bar dolu
    setTimeout(function(){ bar.style.transition='width 2s linear'; bar.style.width='100%'; },50);
  },80);
  // Kapan
  setTimeout(function(){
    card.style.transform='scale(1.1)';
    card.style.opacity='0';
    ov.style.background='rgba(0,0,0,0)';
    setTimeout(function(){
      ov.style.display='none';
      ov.style.pointerEvents='none';
      ov.style.opacity='0';
      if(bar){ bar.style.transition='none'; bar.style.width='0%'; }
      card.style.transform='scale(0)';
      card.style.opacity='0';
      cb();
    },350);
  },2400);
}

