function _doEnterRoom(room){
  if(room&&room.id==='bilgitoplari'&&window.openBilgiToplariArena){ window.openBilgiToplariArena(); return; }
  // Müzik player her odada görünür
  setTimeout(function(){
    var m=document.getElementById('ada-muzik');
    if(m) m.style.display='flex';
  },400);
  // puzzle/boyama enterRoom başında yakalandı
  if(room.special==='hazine'){
    var hzd=JSON.parse(localStorage.getItem(_hzKey())||'{}');
    if(hzd.done){ showHazineDone(); return; }
    currentRoom=room; roomScore=0; objs=[]; parts=[]; lastSpawn=0;
    initCanvas();
    document.getElementById('gs').style.display='block';
    document.getElementById('hm').style.display='none';
    document.getElementById('gri').textContent=evRoomDisplayIcon(room);
    document.getElementById('grn').textContent=evRoomDisplayName(room);
    document.getElementById('gsn').textContent='0';
    document.getElementById('gp').style.width='0%';
    W=window.innerWidth; H=window.innerHeight;
    gameActive=true;
    return;
  }
  currentRoom=room; roomScore=0; objs=[]; parts=[]; lastSpawn=0;
  if(room&&room.id==='kucukmelekler'){ evV46KMEWelcome(); setTimeout(evV47KMEEnsureNav,350); }
  initCanvas();
  document.getElementById('gs').style.display='block';
  document.getElementById('hm').style.display='none';
  document.getElementById('gri').textContent=evRoomDisplayIcon(room);
  document.getElementById('grn').textContent=evRoomDisplayName(room);
  if(room&&room.id==='kucukmelekler'){ var _gb=document.getElementById('gbk'); if(_gb){_gb.textContent=evV43KMEBackText(); _gb.setAttribute('translate','no');} }
  document.getElementById('gsn').textContent='0';
  document.getElementById('gp').style.width='0%';
  W=window.innerWidth; H=window.innerHeight;
  // Ders mesajı kaldırıldı
  gameActive=true;
  evV48S35MissionReset(room);
  if(typeof okiEnterRoom==='function') okiEnterRoom(room.id);
  try{ if(typeof evPrayerContextStart==='function') evPrayerContextStart('roomEnter'); }catch(_prStartErr){}
  setTimeout(function(){
    if(room.id==='dua'&&_selectedChar==='kiz') versePray&&versePray();
    else charSurprise&&charSurprise();
  }, 800);
  if(typeof okiStartGameSupport==='function') okiStartGameSupport();
  if(typeof okiStartAutoPop==='function') okiStartAutoPop();
  _coinRainCount=0; startCoinRain();

  if(room.lang) window.speechSynthesis&&window.speechSynthesis.getVoices();
  // Tema butonunu göster ve sıfırla
  var _rtb = document.getElementById('_room-theme-btn');
  if(_rtb){ _rtb.style.display='flex'; }
  _resetRoomTheme();
}

