function evV48S35PlayerSlug(){
  var n='';
  try{ n=String(playerName||localStorage.getItem('eduverse_player_name')||localStorage.getItem('playerName')||'Kahraman'); }catch(e){ n='Kahraman'; }
  n=(n||'Kahraman').trim().toLowerCase();
  try{ n=n.normalize('NFD').replace(/[\u0300-\u036f]/g,''); }catch(e){}
  n=n.replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ş/g,'s').replace(/ö/g,'o').replace(/ç/g,'c');
  n=n.replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
  return n||'kahraman';
}

