function evV48S35ButterflyReward(count){
  var hud=document.getElementById('ev-v48s35-hud'); if(!hud) return;
  count=count||3;
  for(var i=0;i<count;i++){
    var im=document.createElement('img'); im.className='ev-v48s35-mission'; var set=evV48S35Assets(); im.src=evV48S35Asset(set.butterflies[i%set.butterflies.length]);
    im.style.cssText='position:fixed;width:54px;height:54px;object-fit:contain;z-index:136;left:'+(hud.getBoundingClientRect().left+30+i*38)+'px;top:'+(hud.getBoundingClientRect().top-22)+'px;pointer-events:none;filter:drop-shadow(0 6px 10px rgba(0,60,90,.25));animation:evV48S35Fly '+(2.3+i*.35)+'s ease-in-out forwards;';
    evV48S35Mount(im); setTimeout((function(x){return function(){ if(x.parentNode) x.remove(); };})(im),3100);
  }
}

