function _applyRoomTheme(idx){
  _roomThemeIdx = idx % ROOM_THEMES.length;
  var th = ROOM_THEMES[_roomThemeIdx];
  var gc = document.getElementById('gc');
  if(gc) gc.style.filter = th.filter;
  var gs = document.getElementById('gs');
  if(gs && th.gsBg){
    gs.style.background = 'linear-gradient(180deg, ' + th.gsBg + ', transparent 60%)';
  } else if(gs){
    gs.style.background = '';
  }
  // Buton güncelle
  var btn = document.getElementById('_room-theme-btn');
  if(btn) btn.textContent = th.emoji;
  // Mini toast
  var t = document.createElement('div');
  t.className = '_gf';
  t.style.cssText = 'position:fixed;top:52px;left:50%;transform:translateX(-50%);z-index:9998;' +
    'background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.15);border-radius:20px;' +
    'padding:5px 14px;font-family:Fredoka One;font-size:.75rem;color:rgba(255,255,255,.9);' +
    'pointer-events:none;white-space:nowrap;backdrop-filter:blur(4px);';
  t.textContent = th.emoji + ' ' + evThemeName(th.id,th.name);
  evGameLayer().appendChild(t);
  setTimeout(function(){ t.style.opacity='0'; t.style.transition='opacity .5s'; setTimeout(function(){ if(t.parentNode) t.remove(); }, 500); }, 1500);
}

