function _showDuaLangPicker(){
  var existing = document.getElementById('_dua-lang-picker');
  if(existing){ existing.remove(); return; }
  var picker = document.createElement('div');
  picker.id = '_dua-lang-picker';
  picker.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:999999;background:linear-gradient(135deg,#1a0040,#2a0060);border:1.5px solid rgba(180,100,255,.4);border-radius:24px;padding:20px;min-width:280px;box-shadow:0 20px 60px rgba(0,0,0,.7);';
  var wrap = document.createElement('div');
  wrap.innerHTML = '<div style="font-family:Fredoka One;font-size:1.1rem;color:#E8C8FF;text-align:center;margin-bottom:14px;">🌍 Dua Dilini Seç</div>';
  picker.appendChild(wrap);
  var grid = document.createElement('div');
  grid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:8px;';
  Object.keys(DUA_LANG_DATA).forEach(function(code){
    var lang = DUA_LANG_DATA[code];
    var active = _duaLang === code;
    var btn = document.createElement('button');
    btn.style.cssText = 'background:'+(active?'rgba(150,50,255,.5)':'rgba(80,20,160,.3)')+';border:1.5px solid '+(active?'rgba(220,140,255,.8)':'rgba(180,100,255,.2)')+';border-radius:14px;padding:10px;cursor:pointer;font-family:Nunito;font-size:.9rem;color:#fff;';
    btn.textContent = lang.flag + ' ' + lang.name;
    (function(c){ btn.onclick = function(){ _setDuaLang(c); }; })(code);
    grid.appendChild(btn);
  });
  picker.appendChild(grid);
  var closeBtn = document.createElement('button');
  closeBtn.style.cssText = 'margin-top:12px;width:100%;background:transparent;border:1px solid rgba(255,255,255,.15);border-radius:20px;padding:8px;color:rgba(255,255,255,.4);font-family:Nunito;font-size:.82rem;cursor:pointer;';
  closeBtn.textContent = '✕ Kapat';
  closeBtn.onclick = function(){ picker.remove(); };
  picker.appendChild(closeBtn);
  document.body.appendChild(picker);
}

