function _applyValuesMode(){
  var btn = document.getElementById('values-toggle-btn');
  var title = document.getElementById('hm-title');
  
  if(_valuesMode){
    // Düğme aktif görünümü
    if(btn){
      btn.style.background = 'rgba(50,200,100,.25)';
      btn.style.borderColor = 'rgba(100,255,150,.5)';
      btn.style.color = '#88FF88';
    }
    // Başlık değişimi
    if(title) title.textContent = VALUES_TITLE.values;
    // Odaları dönüştür
    ROOMS.forEach(function(r){
      if(VALUES_ROOMS[r.id]){
        r._origName = r._origName || r.name;
        r._origIco  = r._origIco  || r.ico;
        r.name = VALUES_ROOMS[r.id].name;
        r.ico  = VALUES_ROOMS[r.id].ico;
      }
    });
  } else {
    // Düğme pasif görünümü
    if(btn){
      btn.style.background = 'rgba(255,255,255,.08)';
      btn.style.borderColor = 'rgba(255,255,255,.15)';
      btn.style.color = 'rgba(255,255,255,.3)';
    }
    // Başlık eski haline dön
    if(title) title.textContent = (typeof evDiscoveryPlanetTitle==='function' && window.playerName) ? evDiscoveryPlanetTitle(window.playerName) : VALUES_TITLE.islam;
    // Odaları geri al
    ROOMS.forEach(function(r){
      if(r._origName){ r.name = r._origName; delete r._origName; }
      if(r._origIco) { r.ico  = r._origIco;  delete r._origIco;  }
    });
  }
  
  // Grid'i yenile
  if(typeof buildGrid === 'function') buildGrid();
}

