function _eduTap(){
  _eduTapCount++;
  clearTimeout(_eduTapTimer);
  if(_eduTapCount >= 7){
    _eduTapCount = 0;
    // Gizli odanın kilidini geçici olarak aç
    var sr = ROOMS.find(function(r){ return r.id === 'gizli'; });
    if(sr){
      var origUnlock = sr.unlock;
      sr.unlock = 0;
      buildGrid();
      // 1 saniyelik görsel ipucu
      var logo = document.getElementById('edu-logo-tap');
      if(logo){
        logo.style.textShadow = '0 0 16px #FFD700, 0 0 32px #FFD700';
        logo.style.transition = 'text-shadow .3s';
        setTimeout(function(){
          logo.style.textShadow = '';
        }, 1500);
      }
      // Küçük bir uyarı toast
      var t = document.createElement('div');
      t.className = '_gf';
      t.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:9998;background:linear-gradient(135deg,#1a0060,#4a0080);border:1px solid rgba(200,100,255,.4);border-radius:20px;padding:8px 18px;font-family:Fredoka One;font-size:.8rem;color:#DDA0FF;box-shadow:0 4px 20px rgba(100,0,200,.4);white-space:nowrap;pointer-events:none;';
      t.textContent = '🔮 Gizli Oda aktif!';
      document.body.appendChild(t);
      setTimeout(function(){ t.style.opacity='0'; t.style.transition='opacity .5s'; setTimeout(function(){ if(t.parentNode) t.remove(); }, 500); }, 2000);
    }
    // Ebeveyn raporunu aç
    setTimeout(function(){ showReport(); }, 500);
    return;
  }
  // 800ms içinde tıklanmazsa sıfırla
  _eduTapTimer = setTimeout(function(){ _eduTapCount = 0; }, 800);
}

