function goHome(){
  try{ if(typeof evPrayerContextStop==='function') evPrayerContextStop('goHome'); }catch(_prStopErr){}
  evV47KMERemoveNav&&evV47KMERemoveNav();
  if(currentRoom){
    // Track rooms visited today for parent report
    var today=new Date().toDateString();
    var rv=JSON.parse(localStorage.getItem('dei_visited')||'{}');
    if(!rv[today]) rv[today]=[];
    if(rv[today].indexOf(currentRoom.id)<0) rv[today].push(currentRoom.id);
    localStorage.setItem('dei_visited',JSON.stringify(rv));
  }
  if(currentRoom&&roomScore>(roomBests[currentRoom.id]||0)){
    roomBests[currentRoom.id]=roomScore;
    savePlayerData();
  }
  gameActive=false;
  window._okBaliklar = null; // okyanus balıklarını sıfırla
  // Tema butonunu gizle ve sıfırla
  var _rtb2 = document.getElementById('_room-theme-btn');
  if(_rtb2){ _rtb2.style.display='none'; }
  _resetRoomTheme();
  stopCoinRain(); // Para yağmurunu durdur
  evV48S35MissionCleanup();
  // Ekrandaki tüm DOM balonları / float elementlerini temizle
  // Oyun sırasında eklenen TÜM geçici DOM elementlerini temizle
  document.querySelectorAll('._gf, .fm').forEach(function(el){ el.remove(); });
  var _ov=document.getElementById('hazine-done-ov'); if(_ov) _ov.style.display='none';
  var _ci=document.getElementById('coin-rain-counter'); if(_ci) _ci.remove();
  // Smooth fade out
  var gs2=document.getElementById('gs');
  if(gs2){
    gs2.style.transition='opacity .25s ease';
    gs2.style.opacity='0';
    setTimeout(function(){
      gs2.style.display='none';
      gs2.style.opacity='1';
      gs2.style.transition='';
      currentRoom=null; objs=[]; parts=[];
      // Extra safety: clear again after any delayed burst() calls fire
      setTimeout(function(){ parts=[]; objs=[]; },600);
      // Nuclear cleanup: catch any element that snuck through all guards
      setTimeout(function(){
        if(gameActive) return; // user re-entered a room, don't clean
        document.querySelectorAll('._gf, .fm').forEach(function(e){ e.remove(); });
      }, 800);
      var hm2=document.getElementById('hm');
      if(hm2){ hm2.style.opacity='0'; hm2.style.display='flex'; hm2.style.transition='opacity .25s ease'; setTimeout(function(){hm2.style.opacity='1'; setTimeout(function(){hm2.style.transition='';},260);},20); }
    },260);
  } else {
    currentRoom=null; objs=[]; parts=[];
    document.getElementById('hm').style.display='flex';
  }
  document.getElementById('hsc').textContent=totalScore;
  loadSavedChar(); updateLvl(); buildGrid(); setTimeout(initOki,100); setCharState('idle');
  updateDailyStrip(); setTimeout(okiGreet,1200); okiStartReminders(); setTimeout(initHmSpace,200);
  // Müzik player ana ekranda da her zaman görünür
  setTimeout(function(){
    var m=document.getElementById('ada-muzik');
    if(m) m.style.display='flex';
  },300);
}

