function evTrPossessiveSuffix(name){
  var n=String(name||'').toLowerCase();
  var vowels='aıoueiöü';
  var last='', lastChar='';
  for(var c=n.length-1;c>=0;c--){ if(/[a-zçğıöşü]/i.test(n.charAt(c))){ lastChar=n.charAt(c); break; } }
  for(var i=n.length-1;i>=0;i--){ if(vowels.indexOf(n.charAt(i))>=0){ last=n.charAt(i); break; } }
  var base=(last==='a' || last==='ı') ? 'ın' : ((last==='o' || last==='u') ? 'un' : ((last==='ö' || last==='ü') ? 'ün' : 'in'));
  return (vowels.indexOf(lastChar)>=0 ? 'n' : '') + base;
}

