function startHouse(){
  var nm=document.getElementById('ni').value.trim();
  playerName=nm||'Kahraman';
  // V48S44: oyuncu adını yerel cihazda kilitle; görev/robot kayıtları isme göre ayrılır.
  try{ localStorage.setItem('eduverse_player_name', playerName); localStorage.setItem('playerName', playerName); }catch(e){}
  // LOCAL_EDGE_FIX: on file:// do not touch browser permission APIs; Edge can keep the tab spinning. HTTPS deploy may ask normally.
  try{ if(typeof evPrayerContextStop==='function') evPrayerContextStop('startHouse'); }catch(e){}
  // Yeni oyuncu — hazine tamamen sıfırla
  localStorage.removeItem(_hzKey());
  // Yeni oyuncu — yemek besleme sıfırla (her kullanıcı kendi gününde besler)
  var _fedToday = new Date().toDateString();
  var _fedData = {};
  try{ _fedData = JSON.parse(localStorage.getItem(_fedKey())||'{}')||{}; }catch(e){ _fedData = {}; try{ localStorage.removeItem(_fedKey()); }catch(_rf){} }
  delete _fedData[_fedToday];
  try{ localStorage.setItem(_fedKey(), JSON.stringify(_fedData)); }catch(e){}
  var _hov=document.getElementById('hazine-done-ov');
  if(_hov) _hov.remove();
  _lastOkiMsg = '';
  _okiPopCount = 0;
  _okiGameMsgIdx = 0;

  // İsme özel kayıt yükle
  try{ _eduGetScoped('oki_char', localStorage.getItem('oki_char')||'erkek'); _eduGetScoped('oki_wardrobe', localStorage.getItem('oki_wardrobe')||'{}'); _eduGetScoped('sr_owned', localStorage.getItem('sr_owned')||'[]'); _eduGetScoped('sr_wearing', localStorage.getItem('sr_wearing')||'{}'); _eduGetScoped('sr_spent', localStorage.getItem('sr_spent')||'0'); _eduGetScoped('dei_streak', localStorage.getItem('dei_streak')||'0'); _eduGetScoped('dei_last', localStorage.getItem('dei_last')||''); }catch(e){}
  var saved={};
  try{ saved=JSON.parse(localStorage.getItem(_playerKey())||'{}')||{}; }catch(e){ saved={}; try{ localStorage.removeItem(_playerKey()); }catch(_rs){} }
  var _legacyScore=_eduScoreLegacyMax();
  totalScore    = parseInt((saved.score!==undefined?saved.score:_legacyScore)||0);
  if(!saved.score && _legacyScore>totalScore) totalScore=_legacyScore;
  secretScore   = parseInt(saved.secret||0);
  roomBests     = saved.bests||{};
  learnedWords  = saved.words||{};
  seenCount     = saved.seen||{};
  _shopRoomOwned   = saved.owned||_eduJsonGetScoped('sr_owned',[]);
  _shopRoomWearing = saved.wearing||_eduJsonGetScoped('sr_wearing',{});

  // Karakter - SAFE_ENTRY_FIX: girişte seçilen Edu/Verse değerini normalize et; otomatik load seçimi kullanıcı seçimi sayılmaz.
  try{
    var _entryChar = _normalizeOkiChar(_selectedChar||_eduGetScoped('oki_char','erkek'));
    var _savedRaw = saved.char || _eduGetScoped('oki_char','erkek') || 'erkek';
    var _savedChar = _normalizeOkiChar(_savedRaw);
    var _finalChar = _charSelectedOnEntry ? _entryChar : (_savedChar || _entryChar || 'erkek');
    _selectedChar = _finalChar;
    _eduSetScoped('oki_char', _finalChar);
    localStorage.setItem('oki_char', _finalChar);
  }catch(e){}
  try{ _eduJsonSetScoped('oki_wardrobe', saved.wardrobe||_eduJsonGetScoped('oki_wardrobe',{})); }catch(e){}

  // Streak — isime özel
  try{
    if(saved.streak!==undefined) _eduSetScoped('dei_streak', saved.streak);
    else _eduSetScoped('dei_streak', _eduGetScoped('dei_streak','0'));
    if(saved.last!==undefined) _eduSetScoped('dei_last', saved.last);
    else _eduSetScoped('dei_last', _eduGetScoped('dei_last',''));
  }catch(e){}
  _eduScoreSync(totalScore);

  localStorage.setItem('dei_lastplayer', playerName);

  updateStreak();
  nextAch=0; for(var i=0;i<ACH_LIST.length;i++) if(totalScore>=ACH_LIST[i].at) nextAch=i+1;
  document.getElementById('ns').style.display='none';
  document.getElementById('hm').style.display='flex';
  setTimeout(function(){ showStreakOverlay(); }, 1200);
  document.getElementById('hm-title').textContent=evDiscoveryPlanetTitle(playerName);
  document.getElementById('hsc').textContent=totalScore;
  updateLvl(); buildGrid();
  setTimeout(initOki,100);
  // Müzik player'ı göster
  setTimeout(function(){ var m=document.getElementById('ada-muzik'); if(m) m.style.display='flex'; },500);
  // Preload voices
  if(window.speechSynthesis) window.speechSynthesis.getVoices();
}

