function toggleFullscreen(){
  var el=document.getElementById('gs');
  var b=document.getElementById('gfs');
  var fs=document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement;
  if(!fs){
    if(el&&(el.requestFullscreen||el.webkitRequestFullscreen||el.mozRequestFullScreen||el.msRequestFullscreen)){
      (el.requestFullscreen||el.webkitRequestFullscreen||el.mozRequestFullScreen||el.msRequestFullscreen).call(el);
    }
    if(b) b.textContent='✕';
    setTimeout(evResizeGameCanvas,120);
  } else {
    if(document.exitFullscreen||document.webkitExitFullscreen||document.mozCancelFullScreen||document.msExitFullscreen){
      (document.exitFullscreen||document.webkitExitFullscreen||document.mozCancelFullScreen||document.msExitFullscreen).call(document);
    }
    if(b) b.textContent='⛶';
    setTimeout(evResizeGameCanvas,120);
  }
}

