function drawPuzzleTurkiye(ctx, W, H){
  // Map background - ocean
  var bg2=ctx.createLinearGradient(0,0,0,H);
  bg2.addColorStop(0,'#1a4a7a'); bg2.addColorStop(1,'#0d3560');
  ctx.fillStyle=bg2; ctx.fillRect(0,0,W,H);
  // Grid lines (latitude/longitude)
  ctx.strokeStyle='rgba(100,160,220,.15)'; ctx.lineWidth=1;
  for(var g=0;g<6;g++){ctx.beginPath();ctx.moveTo(g*W/5,0);ctx.lineTo(g*W/5,H);ctx.stroke();}
  for(var g2=0;g2<5;g2++){ctx.beginPath();ctx.moveTo(0,g2*H/4);ctx.lineTo(W,g2*H/4);ctx.stroke();}
  // Turkey landmass - simplified polygon
  var trk=[
    [.05,.42],[.08,.35],[.14,.3],[.2,.28],[.28,.25],[.35,.22],[.42,.2],[.5,.18],
    [.58,.16],[.65,.18],[.7,.2],[.75,.22],[.8,.18],[.85,.2],[.9,.22],[.95,.25],
    [.98,.3],[.96,.38],[.92,.42],[.88,.48],[.82,.52],[.78,.55],[.72,.58],[.65,.6],
    [.58,.62],[.5,.65],[.42,.62],[.35,.6],[.28,.55],[.22,.5],[.15,.48],[.1,.45],[.05,.42]
  ];
  var tg3=ctx.createLinearGradient(0,H*.2,0,H*.65);
  tg3.addColorStop(0,'rgba(220,60,30,.9)'); tg3.addColorStop(.5,'rgba(200,40,20,.85)'); tg3.addColorStop(1,'rgba(180,30,15,.8)');
  ctx.fillStyle=tg3;
  ctx.beginPath(); ctx.moveTo(W*trk[0][0],H*trk[0][1]);
  trk.forEach(function(p){ctx.lineTo(W*p[0],H*p[1]);}); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(255,180,150,.4)'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(W*trk[0][0],H*trk[0][1]);
  trk.forEach(function(p){ctx.lineTo(W*p[0],H*p[1]);}); ctx.closePath(); ctx.stroke();
  // Cities
  var cities=[
    {x:.38,y:.38,name:'Ankara',cap:true},
    {x:.22,y:.32,name:'Istanbul'},{x:.7,y:.35,name:'Van'},
    {x:.28,y:.5,name:'Izmir'},{x:.62,y:.42,name:'Diyarbakır'},
    {x:.5,y:.3,name:'Konya'},{x:.78,y:.38,name:'Erzurum'},
  ];
  cities.forEach(function(c){
    ctx.fillStyle=c.cap?'#FFD700':'rgba(255,255,200,.9)';
    ctx.beginPath(); ctx.arc(W*c.x,H*c.y,c.cap?6:4,0,Math.PI*2); ctx.fill();
    if(c.cap){ctx.strokeStyle='rgba(255,200,50,.8)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(W*c.x,H*c.y,9,0,Math.PI*2);ctx.stroke();}
    ctx.fillStyle=c.cap?'#FFD700':'rgba(255,255,200,.8)';
    ctx.font='bold '+Math.round(W*(c.cap?.035:.028))+'px Fredoka One'; ctx.textAlign='center';
    ctx.fillText(c.name,W*c.x,H*c.y-10);
  });
  // Flag
  ctx.fillStyle='rgba(200,40,20,.85)'; ctx.beginPath(); ctx.roundRect(W*.72,H*.68,W*.22,H*.14,3); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.9)'; ctx.font='bold 20px serif'; ctx.textAlign='center';
  ctx.fillText('☽ ★',W*.83,H*.78);
  ctx.fillStyle='rgba(255,200,50,.15)'; ctx.font='bold '+Math.round(W*.04)+'px Fredoka One'; ctx.textAlign='center';
  ctx.fillText('EduVerse',W*.5,H*.97);
}

