  ctx.strokeStyle='rgba(110,92,78,.85)'; ctx.lineWidth=W*.055; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(ex+W*.18,ey-H*.04); ctx.quadraticCurveTo(ex+W*.38,ey+H*.1,ex+W*.28,ey+H*.2); ctx.stroke();
