  // Tail
  ctx.strokeStyle='rgba(100,85,70,.6)'; ctx.lineWidth=W*.015;
  ctx.beginPath(); ctx.moveTo(ex-W*.27,ey); ctx.quadraticCurveTo(ex-W*.34,ey+H*.1,ex-W*.3,ey+H*.18); ctx.stroke();
  // Grass
  for(var g3=0;g3<15;g3++){ctx.fillStyle='rgba(80,120,30,.5)';ctx.fillRect(g3*W*.07+W*.01,H*.75,W*.02,H*.06+Math.sin(g3)*.03*H);}
