  for(var i=0;i<120;i++){ctx.fillStyle='rgba(255,245,180,'+(0.2+Math.random()*.6)+')';ctx.beginPath();ctx.arc(Math.random()*W,Math.random()*H,Math.random()*2+.3,0,Math.PI*2);ctx.fill();}
