  for(var mw=0;mw<80;mw++){var mx2=mw*W*.013,my2=H*.3+Math.sin(mw*.06)*H*.2;ctx.fillStyle='rgba(200,180,255,.04)';ctx.beginPath();ctx.arc(mx2,my2,3,0,Math.PI*2);ctx.fill();}
