  sg.addColorStop(0,'rgba(255,240,200,.9)'); sg.addColorStop(.4,'rgba(220,180,120,.8)'); sg.addColorStop(1,'rgba(180,130,80,.7)');
  ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(W*.7,H*.18,W*.1,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(200,160,80,.5)'; ctx.lineWidth=8; ctx.beginPath(); ctx.ellipse(W*.7,H*.18,W*.18,W*.035,-.3,0,Math.PI*2); ctx.stroke();
  // Earth
  var eg2=ctx.createRadialGradient(W*.22-W*.03,H*.65-H*.04,W*.01,W*.22,H*.65,W*.14);
  eg2.addColorStop(0,'rgba(100,180,255,.9)'); eg2.addColorStop(.4,'rgba(50,140,220,.8)'); eg2.addColorStop(1,'rgba(20,80,160,.7)');
  ctx.fillStyle=eg2; ctx.beginPath(); ctx.arc(W*.22,H*.65,W*.14,0,Math.PI*2); ctx.fill();
  // Continents on earth
  ctx.fillStyle='rgba(60,140,50,.65)'; ctx.beginPath(); ctx.ellipse(W*.2,H*.62,W*.06,W*.04,.3,0,Math.PI*2); ctx.fill();
