function drawPuzzleKuran(ctx, W, H){
  // Arka plan — ipek yeşil
  var bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0a2010');bg.addColorStop(1,'#0f3318');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // Altın arka ışık
  var gl=ctx.createRadialGradient(W*.5,H*.5,W*.05,W*.5,H*.5,W*.55);
  gl.addColorStop(0,'rgba(255,215,0,.18)');gl.addColorStop(1,'transparent');
  ctx.fillStyle=gl;ctx.fillRect(0,0,W,H);
  // Kitap kapağı
  var cg=ctx.createLinearGradient(W*.12,H*.08,W*.88,H*.92);
  cg.addColorStop(0,'#1a4a20');cg.addColorStop(.5,'#2d7a35');cg.addColorStop(1,'#1a4a20');
  ctx.fillStyle=cg;
  ctx.shadowColor='rgba(0,0,0,.5)';ctx.shadowBlur=20;
  ctx.beginPath();ctx.roundRect(W*.1,H*.06,W*.8,H*.88,8);ctx.fill();
  ctx.shadowBlur=0;
  // Altın kenarlık dış
  ctx.strokeStyle='#FFD700';ctx.lineWidth=3;
  ctx.beginPath();ctx.roundRect(W*.1,H*.06,W*.8,H*.88,8);ctx.stroke();
  ctx.strokeStyle='rgba(255,215,0,.4)';ctx.lineWidth=1;
  ctx.beginPath();ctx.roundRect(W*.14,H*.1,W*.72,H*.8,5);ctx.stroke();
  // İç köşe süsleri
  var corners=[[W*.17,H*.13],[W*.83,H*.13],[W*.17,H*.87],[W*.83,H*.87]];
  corners.forEach(function(c){
    ctx.fillStyle='#FFD700';ctx.beginPath();ctx.arc(c[0],c[1],W*.025,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#0f3318';ctx.beginPath();ctx.arc(c[0],c[1],W*.015,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#FFD700';ctx.beginPath();ctx.arc(c[0],c[1],W*.007,0,Math.PI*2);ctx.fill();
  });
  // Ortadaki yazı
  ctx.fillStyle='rgba(255,215,0,.95)';
  ctx.font='bold '+Math.round(H*.1)+'px serif';
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('القُرآن',W*.5,H*.38);
  ctx.font='bold '+Math.round(H*.065)+'px serif';
  ctx.fillStyle='rgba(255,215,0,.7)';
  ctx.fillText('الكَرِيمُ',W*.5,H*.52);
  // Alt Besmele
  ctx.font='bold '+Math.round(H*.04)+'px serif';
  ctx.fillStyle='rgba(255,215,0,.55)';
  ctx.fillText('بِسْمِ اللَّهِ',W*.5,H*.68);
  // Süslü şerit ortada
  ctx.strokeStyle='rgba(255,215,0,.35)';ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(W*.2,H*.45);ctx.lineTo(W*.8,H*.45);ctx.stroke();
  ctx.beginPath();ctx.moveTo(W*.2,H*.58);ctx.lineTo(W*.8,H*.58);ctx.stroke();
}

