  var sky=ctx.createLinearGradient(0,0,0,H*.65);
  sky.addColorStop(0,'#1a3a6a');sky.addColorStop(.4,'#2d6ca8');sky.addColorStop(1,'#87CEEB');
  ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.65);
  // Zemin
  var gnd=ctx.createLinearGradient(0,H*.6,0,H);
  gnd.addColorStop(0,'#3a7a20');gnd.addColorStop(.5,'#2d6018');gnd.addColorStop(1,'#1a3a08');
  ctx.fillStyle=gnd;ctx.fillRect(0,H*.6,W,H*.4);
  // Güneş
  var sun=ctx.createRadialGradient(W*.5,H*.28,W*.02,W*.5,H*.28,W*.18);
  sun.addColorStop(0,'rgba(255,240,150,1)');sun.addColorStop(.5,'rgba(255,200,50,.6)');sun.addColorStop(1,'transparent');
  ctx.fillStyle=sun;ctx.fillRect(W*.3,H*.1,W*.4,H*.4);
  ctx.fillStyle='rgba(255,230,100,.95)';ctx.beginPath();ctx.arc(W*.5,H*.28,W*.06,0,Math.PI*2);ctx.fill();
  // Ağaç gövdesi
  var trunk=ctx.createLinearGradient(W*.45,H*.5,W*.55,H*.5);
  trunk.addColorStop(0,'#5c3a1e');trunk.addColorStop(.5,'#8B5E2A');trunk.addColorStop(1,'#5c3a1e');
  ctx.fillStyle=trunk;
  ctx.beginPath();ctx.moveTo(W*.44,H*.95);ctx.lineTo(W*.42,H*.58);ctx.lineTo(W*.58,H*.58);ctx.lineTo(W*.56,H*.95);ctx.closePath();ctx.fill();
  // Kökler
  ctx.strokeStyle='#5c3a1e';ctx.lineWidth=W*.018;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(W*.44,H*.88);ctx.quadraticCurveTo(W*.3,H*.9,W*.2,H*.95);ctx.stroke();
  ctx.beginPath();ctx.moveTo(W*.56,H*.88);ctx.quadraticCurveTo(W*.7,H*.9,W*.8,H*.95);ctx.stroke();
  ctx.beginPath();ctx.moveTo(W*.5,H*.9);ctx.lineTo(W*.5,H*.98);ctx.stroke();
  // Taç — 3 katman
  [[W*.5,H*.52,W*.3],[W*.4,H*.42,W*.22],[W*.6,H*.42,W*.22],[W*.5,H*.28,W*.25]].forEach(function(l){
