    ctx.fillStyle='rgba(255,220,50,.8)';
    ctx.beginPath();ctx.arc(lx,ly,W*.012,0,Math.PI*2);ctx.fill();
  }
  // Kuşlar
  ctx.strokeStyle='rgba(30,30,60,.7)';ctx.lineWidth=1.5;ctx.lineCap='round';
  [[W*.25,H*.18],[W*.32,H*.16],[W*.72,H*.2]].forEach(function(b){
