function drawPuzzleAile(ctx, W, H){
  // Gece gökyüzü + ay
  var sky2=ctx.createLinearGradient(0,0,0,H*.55);
  sky2.addColorStop(0,'#060d1a');sky2.addColorStop(1,'#0a2040');
  ctx.fillStyle=sky2;ctx.fillRect(0,0,W,H*.55);
  // Yıldızlar
  for(var i=0;i<40;i++){ctx.fillStyle='rgba(255,245,200,'+(0.4+Math.random()*.6)+')';ctx.beginPath();ctx.arc(Math.random()*W,Math.random()*H*.5,Math.random()*1.5+.3,0,Math.PI*2);ctx.fill();}
  // Ay
  ctx.fillStyle='rgba(255,240,180,.9)';ctx.beginPath();ctx.arc(W*.8,H*.12,W*.06,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#0a1828';ctx.beginPath();ctx.arc(W*.82,H*.1,W*.055,0,Math.PI*2);ctx.fill();
  // Zemin gece
  var gnd2=ctx.createLinearGradient(0,H*.5,0,H);
  gnd2.addColorStop(0,'#1a3a10');gnd2.addColorStop(1,'#0d2008');
  ctx.fillStyle=gnd2;ctx.fillRect(0,H*.5,W,H*.5);
  // Ev gövdesi
  ctx.fillStyle='#c8902a';
  ctx.beginPath();ctx.roundRect(W*.12,H*.42,W*.76,H*.52,6);ctx.fill();
  // Duvar
  ctx.fillStyle='#f0d890';
  ctx.beginPath();ctx.roundRect(W*.15,H*.46,W*.7,H*.48,4);ctx.fill();
  // Çatı
  ctx.fillStyle='#8B3a0a';ctx.shadowColor='rgba(0,0,0,.4)';ctx.shadowBlur=8;
  ctx.beginPath();ctx.moveTo(W*.08,H*.46);ctx.lineTo(W*.5,H*.18);ctx.lineTo(W*.92,H*.46);ctx.closePath();ctx.fill();
  ctx.shadowBlur=0;
  // Pencereler
  [[W*.22,H*.54],[W*.68,H*.54]].forEach(function(pw){
    var wg=ctx.createRadialGradient(pw[0],pw[1],0,pw[0],pw[1],W*.07);
    wg.addColorStop(0,'rgba(255,240,150,.95)');wg.addColorStop(1,'rgba(255,200,50,.7)');
    ctx.fillStyle=wg;ctx.beginPath();ctx.roundRect(pw[0]-W*.07,pw[1]-H*.06,W*.14,H*.12,4);ctx.fill();
    ctx.strokeStyle='#c8902a';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(pw[0]-W*.07,pw[1]-H*.06,W*.14,H*.12,4);ctx.stroke();
    ctx.strokeStyle='rgba(180,140,50,.5)';ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(pw[0],pw[1]-H*.06);ctx.lineTo(pw[0],pw[1]+H*.06);ctx.stroke();
    ctx.beginPath();ctx.moveTo(pw[0]-W*.07,pw[1]);ctx.lineTo(pw[0]+W*.07,pw[1]);ctx.stroke();
  });
