  ctx.fillStyle=dg2;ctx.beginPath();ctx.roundRect(W*.4,H*.62,W*.2,H*.32,4);ctx.fill();
  ctx.fillStyle='rgba(255,215,0,.8)';ctx.beginPath();ctx.arc(W*.57,H*.78,W*.015,0,Math.PI*2);ctx.fill();
