    ctx.beginPath();ctx.moveTo(pw[0],pw[1]-H*.06);ctx.lineTo(pw[0],pw[1]+H*.06);ctx.stroke();
    ctx.beginPath();ctx.moveTo(pw[0]-W*.07,pw[1]);ctx.lineTo(pw[0]+W*.07,pw[1]);ctx.stroke();
  });
  // Kapı
  var dg2=ctx.createLinearGradient(W*.42,H*.6,W*.58,H*.6);
  dg2.addColorStop(0,'#5c2a08');dg2.addColorStop(.5,'#8B4010');dg2.addColorStop(1,'#5c2a08');
  ctx.fillStyle=dg2;ctx.beginPath();ctx.roundRect(W*.4,H*.62,W*.2,H*.32,4);ctx.fill();
  ctx.fillStyle='rgba(255,215,0,.8)';ctx.beginPath();ctx.arc(W*.57,H*.78,W*.015,0,Math.PI*2);ctx.fill();
  // Baca + duman
  ctx.fillStyle='#8B3a0a';ctx.fillRect(W*.65,H*.18,W*.06,H*.16);
  ctx.fillStyle='rgba(200,200,200,.3)';
  for(var d=0;d<3;d++){ctx.beginPath();ctx.arc(W*.68+d*W*.01,H*.12-d*H*.04,W*(.015+d*.01),0,Math.PI*2);ctx.fill();}
  // Aile figürleri (basit siluet)
  var figs=[[W*.3,H*.72,H*.14],[W*.5,H*.7,H*.18],[W*.65,H*.73,H*.12]];
  figs.forEach(function(f){
    ctx.fillStyle='rgba(40,20,10,.8)';
