  ctx.fillStyle=w1;ctx.beginPath();ctx.ellipse(bx-W*.15,by-H*.1,W*.22,H*.22,-.5,0,Math.PI*2);ctx.fill();
  // Sol alt kanat
  var w2=ctx.createRadialGradient(bx-W*.12,by+H*.1,0,bx-W*.12,by+H*.1,W*.16);
