  ctx.fillStyle=w3;ctx.beginPath();ctx.ellipse(bx+W*.15,by-H*.1,W*.22,H*.22,.5,0,Math.PI*2);ctx.fill();
  // Sağ alt kanat
  var w4=ctx.createRadialGradient(bx+W*.12,by+H*.1,0,bx+W*.12,by+H*.1,W*.16);
  w4.addColorStop(0,'rgba(255,150,0,1)');w4.addColorStop(.5,'rgba(200,60,0,.9)');w4.addColorStop(1,'rgba(100,20,0,.4)');
  ctx.fillStyle=w4;ctx.beginPath();ctx.ellipse(bx+W*.11,by+H*.1,W*.15,H*.16,-.3,0,Math.PI*2);ctx.fill();
  // Kanat desenleri — noktalar
  [[W*.36,H*.36],[W*.64,H*.36],[W*.38,H*.52],[W*.62,H*.52]].forEach(function(sp){
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.beginPath();ctx.arc(sp[0],sp[1],W*.04,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,.4)';ctx.beginPath();ctx.arc(sp[0],sp[1],W*.02,0,Math.PI*2);ctx.fill();
  });
