  var body=ctx.createLinearGradient(bx-W*.02,by-H*.2,bx+W*.02,by-H*.2);
  body.addColorStop(0,'#1a0a04');body.addColorStop(.5,'#3a1a08');body.addColorStop(1,'#1a0a04');
  ctx.fillStyle=body;ctx.beginPath();ctx.ellipse(bx,by,W*.022,H*.26,0,0,Math.PI*2);ctx.fill();
  // Antenler
  ctx.strokeStyle='#2a1008';ctx.lineWidth=2;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(bx,by-H*.22);ctx.quadraticCurveTo(bx-W*.08,by-H*.38,bx-W*.1,by-H*.45);ctx.stroke();
  ctx.beginPath();ctx.moveTo(bx,by-H*.22);ctx.quadraticCurveTo(bx+W*.08,by-H*.38,bx+W*.1,by-H*.45);ctx.stroke();
  ctx.fillStyle='#FFD700';ctx.beginPath();ctx.arc(bx-W*.1,by-H*.45,W*.015,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(bx+W*.1,by-H*.45,W*.015,0,Math.PI*2);ctx.fill();
}

