function drawPuzzleDeniz(ctx, W, H){
  // Su gradyanı — derin mavi
  var water=ctx.createLinearGradient(0,0,0,H);
  water.addColorStop(0,'#006994');water.addColorStop(.3,'#0047ab');water.addColorStop(.7,'#002255');water.addColorStop(1,'#001133');
  ctx.fillStyle=water;ctx.fillRect(0,0,W,H);
  // Işık huzmesi
  for(var ray=0;ray<5;ray++){
    var rx=W*(.1+ray*.2);
    var rg=ctx.createLinearGradient(rx,0,rx,H*.7);
    rg.addColorStop(0,'rgba(100,200,255,.2)');rg.addColorStop(1,'transparent');
    ctx.fillStyle=rg;ctx.beginPath();ctx.moveTo(rx-W*.04,0);ctx.lineTo(rx+W*.04,0);ctx.lineTo(rx+W*.06,H*.7);ctx.lineTo(rx-W*.06,H*.7);ctx.closePath();ctx.fill();
  }
  // Mercan kayalıklar altta
  [[W*.12,H*.88,W*.1,'#FF6B35'],[W*.3,H*.82,W*.08,'#FF4488'],[W*.5,H*.85,W*.12,'#FF8833'],[W*.7,H*.8,W*.09,'#FF3355'],[W*.88,H*.86,W*.1,'#FF6644']].forEach(function(c){
    ctx.fillStyle=c[3];
    for(var cb=0;cb<6;cb++){
      var ca=cb/6*Math.PI;
      ctx.beginPath();ctx.ellipse(c[0]+Math.cos(ca)*c[2]*.5,c[1]-Math.sin(ca)*H*.08,c[2]*.18,c[2]*.35,ca*.3,0,Math.PI*2);ctx.fill();
    }
  });
  // Balıklar
  var fish=[['#FF8844',W*.25,H*.35],['#FFD700',W*.65,H*.25],['#FF4488',W*.45,H*.55],['#44FF88',W*.15,H*.6],['#FF6644',W*.75,H*.45],['#44CCFF',W*.55,H*.38]];
  fish.forEach(function(f){
    ctx.save();ctx.translate(f[1],f[2]);
    ctx.fillStyle=f[0];ctx.beginPath();ctx.ellipse(0,0,W*.06,H*.035,0,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.moveTo(-W*.06,0);ctx.lineTo(-W*.1,-H*.03);ctx.lineTo(-W*.1,H*.03);ctx.closePath();ctx.fill();
    // Göz
    ctx.fillStyle='rgba(0,0,0,.8)';ctx.beginPath();ctx.arc(W*.03,-H*.008,W*.01,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='white';ctx.beginPath();ctx.arc(W*.032,-H*.009,W*.004,0,Math.PI*2);ctx.fill();
    // Yüzgeç
    ctx.strokeStyle=f[0];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-H*.035);ctx.quadraticCurveTo(W*.02,-H*.055,W*.01,-H*.035);ctx.stroke();
    ctx.restore();
  });
  // Kabuklar / deniz yıldızı
  [[W*.2,H*.93,'#FFD700'],[W*.5,H*.95,'#FF8844'],[W*.75,H*.92,'#FF6644']].forEach(function(s){
    ctx.fillStyle=s[2];
    for(var sp=0;sp<5;sp++){var sa=sp/5*Math.PI*2-Math.PI/2;ctx.beginPath();ctx.moveTo(s[0],s[1]);ctx.lineTo(s[0]+Math.cos(sa)*W*.04,s[1]+Math.sin(sa)*H*.03);ctx.lineTo(s[0]+Math.cos(sa+Math.PI/5)*W*.02,s[1]+Math.sin(sa+Math.PI/5)*H*.015);ctx.closePath();ctx.fill();}
  });
  // Kabarcıklar
  for(var bbl=0;bbl<15;bbl++){
    ctx.strokeStyle='rgba(100,200,255,.5)';ctx.lineWidth=1;
    ctx.beginPath();ctx.arc(Math.random()*W,(H*.2+Math.random()*H*.7),W*.008+Math.random()*W*.015,0,Math.PI*2);ctx.stroke();
  }
}

