function drawPuzzleBeyin(ctx, W, H){
  // Koyu arka plan
  var bg2=ctx.createRadialGradient(W*.5,H*.5,0,W*.5,H*.5,W*.6);
  bg2.addColorStop(0,'#0a0520');bg2.addColorStop(1,'#03010a');
  ctx.fillStyle=bg2;ctx.fillRect(0,0,W,H);
  // Beyin dış şekli — iki loblu
  var brain=ctx.createRadialGradient(W*.5,H*.48,W*.05,W*.5,H*.48,W*.4);
  brain.addColorStop(0,'rgba(220,120,180,1)');brain.addColorStop(.5,'rgba(180,80,140,.95)');brain.addColorStop(1,'rgba(120,40,100,.8)');
  ctx.fillStyle=brain;
  // Sol lob
  ctx.beginPath();ctx.ellipse(W*.36,H*.46,W*.25,H*.3,-.15,0,Math.PI*2);ctx.fill();
  // Sağ lob
  ctx.beginPath();ctx.ellipse(W*.64,H*.46,W*.25,H*.3,.15,0,Math.PI*2);ctx.fill();
  // Orta bağ
  ctx.fillStyle='rgba(200,100,160,.7)';ctx.beginPath();ctx.ellipse(W*.5,H*.48,W*.06,H*.2,0,0,Math.PI*2);ctx.fill();
