function evV35EnhancePuzzle(){
  try{
    var ov=document.getElementById('puzzle-ov'); if(!ov) return;
    ov.style.background='radial-gradient(circle at 15% 12%,rgba(90,210,255,.24),transparent 28%),radial-gradient(circle at 86% 18%,rgba(255,210,90,.18),transparent 30%),radial-gradient(circle at 52% 88%,rgba(120,90,255,.18),transparent 38%),linear-gradient(155deg,#020918,#07152c,#101f4b,#050716)';
    ov.style.overflowX='hidden';
    ov.style.backdropFilter='blur(10px)';

    if(!document.getElementById('v35-puzzle-style')){
      var st=document.createElement('style');
      st.id='v35-puzzle-style';
      st.textContent='@keyframes v35FloatPiece{0%{transform:translateY(0) rotate(0deg);opacity:.25}50%{opacity:.72}100%{transform:translateY(-34px) rotate(18deg);opacity:.20}}@keyframes v35SnapRing{0%{transform:translate(-50%,-50%) scale(.35);opacity:.95}100%{transform:translate(-50%,-50%) scale(2.4);opacity:0}}@keyframes v35BrainGlow{0%,100%{filter:drop-shadow(0 0 8px rgba(90,210,255,.25));transform:translateY(0)}50%{filter:drop-shadow(0 0 22px rgba(255,215,100,.55));transform:translateY(-4px)}}@keyframes v35Unlock{0%{transform:translate(-50%,-50%) scale(.6);opacity:0}15%{opacity:1}80%{opacity:1}100%{transform:translate(-50%,-65%) scale(1.08);opacity:0}}';
      document.head.appendChild(st);
    }

    if(!document.getElementById('v35-puzzle-bg')){
      var bg=document.createElement('div');
      bg.id='v35-puzzle-bg';
      bg.style.cssText='position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:0;';
      var icons=['🧩','💡','🧠','🔐','⚙️','✨','🔷','🔶','⭐','🤖'];
      for(var i=0;i<38;i++){
        var sp=document.createElement('span');
        sp.textContent=icons[i%icons.length];
        sp.style.cssText='position:absolute;left:'+((i*41)%100)+'%;top:'+((i*57)%100)+'%;font-size:'+(15+(i%5)*5)+'px;opacity:.42;filter:drop-shadow(0 0 12px rgba(255,255,255,.20));animation:v35FloatPiece '+(5+(i%7))+'s ease-in-out infinite alternate;animation-delay:-'+(i%6)+'s;';
        bg.appendChild(sp);
      }
      ov.insertBefore(bg,ov.firstChild);
    }

    Array.prototype.forEach.call(ov.children,function(ch){
      if(ch.id!=='v35-puzzle-bg'){ ch.style.position='relative'; ch.style.zIndex='1'; }
    });

    var head=ov.querySelector('div[style*="justify-content:space-between"]');
    if(head){
      head.style.background='rgba(255,255,255,.09)';
      head.style.border='1px solid rgba(255,255,255,.15)';
      head.style.borderRadius='0 0 24px 24px';
      head.style.backdropFilter='blur(14px)';
      head.style.boxShadow='0 10px 30px rgba(0,0,0,.24)';
    }
    var title=head?head.querySelector('div'):null;
    if(title){
      title.textContent='Akıllı Puzzle Laboratuvarı';
      title.setAttribute('translate','no');
      title.style.color='#fff0a8';
      title.style.textShadow='0 0 22px rgba(255,210,100,.65)';
    }
    var daily=document.getElementById('pz-daily');
    if(daily){
      daily.style.background='rgba(68,255,136,.10)';
      daily.style.border='1px solid rgba(68,255,136,.24)';
      daily.style.padding='6px 10px';
      daily.style.borderRadius='999px';
      daily.style.boxShadow='0 0 18px rgba(68,255,136,.10)';
    }

    if(!document.getElementById('v35-puzzle-ribbon')){
      var rib=document.createElement('div');
      rib.id='v35-puzzle-ribbon';
      rib.innerHTML='🧠 Parçayı bul • Sürükle • Zekâ kilidini aç';
      rib.style.cssText='position:relative;z-index:1;margin:4px 12px 12px;padding:9px 15px;border-radius:999px;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.14);color:rgba(255,245,220,.93);font-family:Fredoka One;font-size:.78rem;text-align:center;box-shadow:0 8px 24px rgba(0,0,0,.20);';
      if(head && head.nextSibling) ov.insertBefore(rib,head.nextSibling); else ov.appendChild(rib);
    }

    evV35StylePuzzleChrome();
  }catch(e){}
}

