function evV35StylePuzzleChrome(){
  try{
    var ov=document.getElementById('puzzle-ov'); if(!ov) return;
    var menu=document.getElementById('pz-menu');
    if(menu){
      menu.style.background='rgba(255,255,255,.055)';
      menu.style.border='1px solid rgba(255,255,255,.10)';
      menu.style.borderRadius='24px';
      menu.style.margin='0 10px 18px';
      menu.style.padding='16px';
      menu.style.boxShadow='0 18px 42px rgba(0,0,0,.22)';
      menu.style.backdropFilter='blur(10px)';
    }

    var game=document.getElementById('pz-game');
    if(game){
      game.style.background='rgba(255,255,255,.055)';
      game.style.border='1px solid rgba(255,255,255,.10)';
      game.style.borderRadius='24px';
      game.style.margin='0 10px 16px';
      game.style.padding='12px 10px 18px';
      game.style.boxShadow='0 18px 44px rgba(0,0,0,.25)';
      game.style.backdropFilter='blur(10px)';
    }

    var canvas=document.getElementById('pz-canvas');
    if(canvas){
      canvas.style.borderRadius='24px';
      canvas.style.border='3px solid rgba(255,220,120,.38)';
      canvas.style.boxShadow='0 22px 60px rgba(0,0,0,.35),0 0 35px rgba(80,200,255,.18),inset 0 0 0 7px rgba(255,255,255,.06)';
      canvas.style.background='radial-gradient(circle at 50% 35%,rgba(30,70,120,.7),rgba(2,8,20,.95))';
    }

    var win=document.getElementById('pz-win');
    if(win){
      win.style.background='rgba(8,12,35,.76)';
      win.style.border='1px solid rgba(255,220,120,.22)';
      win.style.borderRadius='28px';
      win.style.boxShadow='0 20px 70px rgba(0,0,0,.38),0 0 45px rgba(255,210,90,.18)';
      win.style.backdropFilter='blur(14px)';
    }

    var progress=document.getElementById('pz-progress');
    if(progress){
      progress.style.textShadow='0 0 12px rgba(68,255,136,.65)';
