function evV35PuzzleSnap(cx,cy,placed){
  try{
    var gc=document.getElementById('pz-canvas'); if(!gc) return;
    var rect=gc.getBoundingClientRect();
    var x=rect.left + (cx/gc.width)*rect.width;
    var y=rect.top + (cy/gc.height)*rect.height;
    var ring=document.createElement('div');
    ring.style.cssText='position:fixed;left:'+x+'px;top:'+y+'px;width:70px;height:70px;margin-left:-35px;margin-top:-35px;border-radius:50%;border:3px solid rgba(255,220,90,.85);box-shadow:0 0 30px rgba(255,220,90,.55);pointer-events:none;z-index:100000;animation:v35SnapRing .62s ease-out forwards;';
    document.body.appendChild(ring);
    setTimeout(function(){ring.remove();},700);
    if(placed%4===0){
      var msg=document.createElement('div');
      msg.textContent=placed+'/16  🔐';
      msg.style.cssText='position:fixed;left:'+x+'px;top:'+(y-42)+'px;transform:translate(-50%,-50%);padding:6px 11px;border-radius:999px;background:rgba(5,10,35,.86);border:1px solid rgba(255,220,90,.28);color:#ffe680;font-family:Fredoka One;font-size:.76rem;z-index:100000;pointer-events:none;box-shadow:0 8px 26px rgba(0,0,0,.25);animation:v35Unlock .85s ease-out forwards;';
      document.body.appendChild(msg);
      setTimeout(function(){msg.remove();},950);
    }
  }catch(e){}
}

