function showPuzzleMenu(){
  document.getElementById('pz-menu').style.display='flex';
  document.getElementById('pz-game').style.display='none';
  document.getElementById('pz-win').style.display='none';

  var l='tr'; try{ if(evValuesOn&&evValuesOn()) l=evValuesLang()||'tr'; }catch(e){}
  var T={
    tr:{today:'Bugün: ', tries:'/3 ödül hakkı', replay:'Tekrar oyna', pieces:'parça'},
    de:{today:'Heute: ', tries:'/3 Belohnungsversuche', replay:'Nochmal', pieces:'Teile'},
    en:{today:'Today: ', tries:'/3 reward tries left', replay:'Replay', pieces:'pieces'},
    fr:{today:'Aujourd\'hui : ', tries:'/3 essais récompense', replay:'Rejouer', pieces:'pièces'},
    ar:{today:'اليوم: ', tries:'/3 محاولة مكافأة', replay:'إعادة', pieces:'قطعة'}
  };
  var t=T[l]||T.tr;

  var today=new Date().toDateString();
  var pzd=JSON.parse(localStorage.getItem('puzzle_daily')||'{}');
  if(pzd.date!==today) pzd={date:today,count:0};
  var left=Math.max(0,3-(pzd.count||0));
  document.getElementById('pz-daily').textContent=t.today+left+t.tries;
  document.getElementById('pz-daily').style.color=left>0?'#44FF88':'#FFD76A';
  document.getElementById('pz-daily').setAttribute('translate','no');

  var grid=document.getElementById('pz-cats');
  grid.innerHTML='';
  var activePuzzleCats=evPuzzleCatsForCurrentMode();
  activePuzzleCats.forEach(function(cat,i){
    var done=!!pzd['done_'+cat.id];
    var btn=document.createElement('button');
    btn.className='pz-cat-btn';
    btn.style.cssText='background:rgba(255,200,50,.12);border:2px solid rgba(255,200,50,.3);border-radius:16px;padding:14px 10px;font-family:Fredoka One;color:rgba(255,240,200,.9);cursor:pointer;font-size:1rem;display:flex;flex-direction:column;align-items:center;gap:6px;transition:.2s;';
    btn.innerHTML='<span style="font-size:2rem;filter:drop-shadow(0 0 12px rgba(255,255,255,.25));animation:v35BrainGlow 3s ease-in-out infinite">'+cat.icon+'</span><span translate="no">'+evPuzzleCatName(cat)+'</span><span style="font-size:.75rem;color:'+(done?'#44FF88':'rgba(255,200,50,.75)')+'">'+(done?t.replay:(PUZZLE_COLS*PUZZLE_COLS+' '+t.pieces))+'</span>';
    evV35StylePuzzleCat(btn,i,cat,done);
    btn.onclick=function(){ startPuzzle(i); };
    grid.appendChild(btn);
  });
  evApplyPuzzleGerman();
}

