function startPuzzle(catIdx){
  var today=new Date().toDateString();
  var pzd=JSON.parse(localStorage.getItem('puzzle_daily')||'{}');
  if(pzd.date!==today) pzd={date:today,count:0};

  var activePuzzleCats=evPuzzleCatsForCurrentMode();
  var cat=activePuzzleCats[catIdx];
  if(!cat) return;
  var canReward = ((pzd.count||0) < 3) && !pzd['done_'+cat.id];
  window.__puzzlePractice = !canReward;

  if(canReward){
    pzd.count=(pzd.count||0)+1;
    pzd['done_'+cat.id]=true;
    localStorage.setItem('puzzle_daily',JSON.stringify(pzd));
  }

