function initPuzzlePieces(){
  var gc=document.getElementById('pz-canvas');
  var vw=Math.min(window.innerWidth*.95, 480);
  gc.width=vw; gc.height=vw;
  PUZZLE_CTX=gc.getContext('2d');
  PUZZLE_CTX.imageSmoothingEnabled=true;
  var ps=Math.floor(vw/PUZZLE_COLS); // piece size on board
  PUZZLE_PIECES=[];
  var cols=PUZZLE_COLS, rows=PUZZLE_COLS;
  for(var r=0;r<rows;r++){
    for(var c=0;c<cols;c++){
      var id=r*cols+c;
      // Scatter randomly but within canvas
      var sx=ps*1.2+Math.random()*(vw-ps*2.4);
      var sy=ps*1.2+Math.random()*(vw-ps*2.4);
      PUZZLE_PIECES.push({
        id:id, col:c, row:r,
        x:sx, y:sy,
        tx:c*ps, ty:r*ps, // target position
        ps:ps, placed:false,
        srcX:Math.floor(c*PUZZLE_PW/cols), srcY:Math.floor(r*PUZZLE_PW/rows),
        srcW:Math.floor(PUZZLE_PW/cols),    srcH:Math.floor(PUZZLE_PW/rows),
        shake:0
      });
    }
  }
  // Shuffle so some pieces start in wrong order visually
  for(var si=PUZZLE_PIECES.length-1;si>0;si--){
    var sj=Math.floor(Math.random()*(si+1));
    var tmp={x:PUZZLE_PIECES[si].x,y:PUZZLE_PIECES[si].y};
    PUZZLE_PIECES[si].x=PUZZLE_PIECES[sj].x; PUZZLE_PIECES[si].y=PUZZLE_PIECES[sj].y;
    PUZZLE_PIECES[sj].x=tmp.x; PUZZLE_PIECES[sj].y=tmp.y;
  }
  document.getElementById('pz-progress').textContent='0/16';
  drawPuzzleBoard();
}

