function drawPuzzleBoard(){
  if(!PUZZLE_CTX||!PUZZLE_IMG) return;
  var vw=PUZZLE_CTX.canvas.width;
  var ps=Math.floor(vw/PUZZLE_COLS);
  PUZZLE_CTX.clearRect(0,0,vw,vw);
  // Board background - V35 akıllı laboratuvar masası
  var bg=PUZZLE_CTX.createRadialGradient(vw*.50,vw*.42,vw*.04,vw*.50,vw*.50,vw*.72);
  bg.addColorStop(0,'rgba(28,72,130,.96)');
  bg.addColorStop(.42,'rgba(10,24,58,.98)');
  bg.addColorStop(1,'rgba(2,8,22,.99)');
  PUZZLE_CTX.fillStyle=bg;
  PUZZLE_CTX.fillRect(0,0,vw,vw);
  PUZZLE_CTX.save();
  PUZZLE_CTX.globalAlpha=.18;
  PUZZLE_CTX.strokeStyle='rgba(100,220,255,.38)';
  for(var hg=0;hg<7;hg++){
    PUZZLE_CTX.beginPath();
    PUZZLE_CTX.arc(vw*.5,vw*.5,vw*(.10+hg*.065),0,Math.PI*2);
    PUZZLE_CTX.stroke();
  }
  PUZZLE_CTX.restore();
  // Target grid (ghost)
  for(var r=0;r<PUZZLE_COLS;r++) for(var c=0;c<PUZZLE_COLS;c++){
    var tx2=c*ps, ty2=r*ps;
    PUZZLE_CTX.strokeStyle='rgba(120,220,255,.16)'; PUZZLE_CTX.lineWidth=1;
    PUZZLE_CTX.strokeRect(tx2+.5,ty2+.5,ps-1,ps-1);
    // Ghost image
    PUZZLE_CTX.save(); PUZZLE_CTX.globalAlpha=.085;
    var sid=r*PUZZLE_COLS+c;
    var p0=PUZZLE_PIECES[sid];
    PUZZLE_CTX.drawImage(PUZZLE_IMG,p0.srcX,p0.srcY,p0.srcW,p0.srcH,tx2,ty2,ps,ps);
    PUZZLE_CTX.restore();
  }
  // Draw placed pieces first
  PUZZLE_PIECES.forEach(function(p){
    if(!p.placed||PUZZLE_DRAG&&PUZZLE_DRAG.id===p.id) return;
    PUZZLE_CTX.save();
    PUZZLE_CTX.drawImage(PUZZLE_IMG,p.srcX,p.srcY,p.srcW,p.srcH,p.tx,p.ty,ps,ps);
    PUZZLE_CTX.shadowColor='rgba(68,255,136,.38)'; PUZZLE_CTX.shadowBlur=8; PUZZLE_CTX.strokeStyle='rgba(68,255,136,.45)'; PUZZLE_CTX.lineWidth=1.4;
    PUZZLE_CTX.strokeRect(p.tx,p.ty,ps,ps);
    PUZZLE_CTX.restore();
  });
  // Draw floating pieces
  PUZZLE_PIECES.forEach(function(p){
    if(p.placed) return;
    var isDrag=PUZZLE_DRAG&&PUZZLE_DRAG.id===p.id;
    PUZZLE_CTX.save();
    if(isDrag){ PUZZLE_CTX.shadowColor='rgba(255,200,50,.8)'; PUZZLE_CTX.shadowBlur=20; PUZZLE_CTX.globalAlpha=.95; }
    var shake=p.shake||0; if(shake>0){PUZZLE_CTX.translate(Math.sin(shake*8)*(shake*3),0); p.shake-=.05; if(p.shake<0)p.shake=0;}
    PUZZLE_CTX.drawImage(PUZZLE_IMG,p.srcX,p.srcY,p.srcW,p.srcH,p.x-ps/2,p.y-ps/2,ps,ps);
    PUZZLE_CTX.strokeStyle=isDrag?'rgba(255,230,90,.95)':'rgba(120,210,255,.40)'; PUZZLE_CTX.lineWidth=isDrag?3:1.7;
    PUZZLE_CTX.strokeRect(p.x-ps/2,p.y-ps/2,ps,ps);
    PUZZLE_CTX.restore();
  });
  // Dragging piece on top
  if(PUZZLE_DRAG){
    PUZZLE_CTX.save();
    PUZZLE_CTX.shadowColor='rgba(255,200,50,.9)'; PUZZLE_CTX.shadowBlur=25;
    PUZZLE_CTX.globalAlpha=.92;
    PUZZLE_CTX.drawImage(PUZZLE_IMG,PUZZLE_DRAG.srcX,PUZZLE_DRAG.srcY,PUZZLE_DRAG.srcW,PUZZLE_DRAG.srcH,PUZZLE_DRAG.x-ps/2,PUZZLE_DRAG.y-ps/2,ps,ps);
    PUZZLE_CTX.strokeStyle='rgba(255,220,80,.9)'; PUZZLE_CTX.lineWidth=3;
    PUZZLE_CTX.strokeRect(PUZZLE_DRAG.x-ps/2,PUZZLE_DRAG.y-ps/2,ps,ps);
    PUZZLE_CTX.restore();
  }
}

