function puzzleDown(e){
  e.preventDefault();
  var pos=getPuzzlePos(e);
  var ps=Math.floor(PUZZLE_CTX.canvas.width/PUZZLE_COLS);
  // Find piece under touch (top-most unplaced first)
  for(var i=PUZZLE_PIECES.length-1;i>=0;i--){
    var p=PUZZLE_PIECES[i];
    if(p.placed) continue;
    if(Math.abs(pos.x-p.x)<ps/2+6 && Math.abs(pos.y-p.y)<ps/2+6){
      PUZZLE_DRAG=p;
      PUZZLE_DRAG._ox=pos.x-p.x;
      PUZZLE_DRAG._oy=pos.y-p.y;
      // Move to end of array (render on top)
      PUZZLE_PIECES.splice(i,1);
      PUZZLE_PIECES.push(PUZZLE_DRAG);
      break;
    }
  }
  drawPuzzleBoard();
}

