function puzzleUp(e){
  e.preventDefault();
  if(!PUZZLE_DRAG) return;
  var ps=Math.floor(PUZZLE_CTX.canvas.width/PUZZLE_COLS);
  var snap=ps*.55; // snap distance
  var tx=PUZZLE_DRAG.tx+ps/2, ty=PUZZLE_DRAG.ty+ps/2;
  var dist=Math.sqrt(Math.pow(PUZZLE_DRAG.x-tx,2)+Math.pow(PUZZLE_DRAG.y-ty,2));
  if(dist<snap){
    // SNAP!
    PUZZLE_DRAG.x=tx; PUZZLE_DRAG.y=ty;
    PUZZLE_DRAG.placed=true;
    var placed=PUZZLE_PIECES.filter(function(p){return p.placed;}).length;
    document.getElementById('pz-progress').textContent=placed+'/16';
    // Sparkle effect
    puzzleSparkle(tx,ty);
    evV35PuzzleSnap(tx,ty,placed);
    if(placed===16){ setTimeout(puzzleWin,600); }
  } else {
    // Bounce back
    PUZZLE_DRAG.shake=1;
  }
  PUZZLE_DRAG=null;
  drawPuzzleBoard();
}

