function puzzleSparkle(cx,cy){
  var gc=document.getElementById('pz-canvas');
  if(!PUZZLE_CTX) return;
  var sparks=[];
  for(var i=0;i<12;i++){
    var a=Math.random()*Math.PI*2, s=2+Math.random()*5;
    sparks.push({x:cx,y:cy,vx:Math.cos(a)*s,vy:Math.sin(a)*s,al:1,col:['#FFD700','#FFAA00','#FFE066','#FFF5A0'][i%4]});
  }
  function animSparks(){
    drawPuzzleBoard();
    PUZZLE_CTX.save();
    sparks=sparks.filter(function(sp){
      sp.x+=sp.vx; sp.y+=sp.vy; sp.vy+=.15; sp.al-=.06;
      if(sp.al<=0) return false;
      PUZZLE_CTX.globalAlpha=sp.al;
      PUZZLE_CTX.fillStyle=sp.col;
      PUZZLE_CTX.beginPath(); PUZZLE_CTX.arc(sp.x,sp.y,3,0,Math.PI*2); PUZZLE_CTX.fill();
      return true;
    });
    PUZZLE_CTX.restore();
    if(sparks.length>0) requestAnimationFrame(animSparks);
  }
  requestAnimationFrame(animSparks);
}

