function puzzleWin(){
  // Show full image briefly then win screen
  PUZZLE_CTX.save();
  PUZZLE_CTX.globalAlpha=.95;
  var vw=PUZZLE_CTX.canvas.width;
  PUZZLE_CTX.drawImage(PUZZLE_IMG,0,0,vw,vw);
  PUZZLE_CTX.restore();
  // Confetti
  var cfpieces=[];
  for(var i=0;i<80;i++){
    cfpieces.push({x:Math.random()*vw,y:-20-Math.random()*50,vx:(Math.random()-.5)*4,vy:3+Math.random()*4,w:8+Math.random()*8,h:5+Math.random()*5,r:Math.random()*Math.PI,vr:(Math.random()-.5)*.15,col:['#FFD700','#FF6B6B','#4ECDC4','#C3A1FF','#FFE66D'][Math.floor(Math.random()*5)]});
  }
  function animWin(){
    PUZZLE_CTX.save(); PUZZLE_CTX.globalAlpha=.92; PUZZLE_CTX.drawImage(PUZZLE_IMG,0,0,vw,vw); PUZZLE_CTX.restore();
    cfpieces=cfpieces.filter(function(c){
      c.x+=c.vx; c.y+=c.vy; c.r+=c.vr; c.vy+=.08;
      if(c.y>vw+20) return false;
      PUZZLE_CTX.save(); PUZZLE_CTX.translate(c.x,c.y); PUZZLE_CTX.rotate(c.r);
      PUZZLE_CTX.fillStyle=c.col; PUZZLE_CTX.fillRect(-c.w/2,-c.h/2,c.w,c.h); PUZZLE_CTX.restore(); return true;
    });
    if(cfpieces.length>0) requestAnimationFrame(animWin);
  }
  requestAnimationFrame(animWin);
  // Show win overlay after delay
  setTimeout(function(){
    evV35PuzzleWinFX();
    document.getElementById('pz-win').style.display='flex';
    evV35StylePuzzleChrome();
    setTimeout(function(){evApplySpecialGerman();evV35StylePuzzleChrome();},80);
    if(!window.__puzzlePractice){ addScore(500,window.innerWidth/2,window.innerHeight/2,'#FFD700'); }
  },1200);
}

