function openBoyama(){
  document.getElementById('hm').style.display='none';
  document.getElementById('boyama-ov').style.display='flex';
  evV34EnhanceBoyama();
  var bw=Math.min(window.innerWidth*.95,500);
  var bc=document.getElementById('boy-canvas');
  bc.width=bw; bc.height=bw;
  boyaCtx=bc.getContext('2d');
  var cd=document.getElementById('boy-colors');
  cd.innerHTML='';
  BOY_COLORS.forEach(function(col,i){
    var btn=document.createElement('button');
    btn.setAttribute('aria-label','renk');
    btn.style.cssText='width:38px;height:38px;border-radius:50%;background:'+col+';border:3px solid rgba(255,255,255,.28);cursor:pointer;box-shadow:0 8px 22px rgba(0,0,0,.24),0 0 16px '+col+'55;transition:transform .18s, border-color .18s;';
    btn.onmouseenter=function(){btn.style.transform='translateY(-2px) scale(1.08)';};
    btn.onmouseleave=function(){btn.style.transform='';};
    btn.onclick=function(){
      boyaColor=col;
      document.querySelectorAll('#boy-colors button').forEach(function(b){b.style.borderColor='rgba(255,255,255,.28)';b.style.transform='';});
      btn.style.borderColor='rgba(255,255,255,.96)';
      btn.style.transform='scale(1.12)';
      evV34ColorFlash(col);
    };
    if(i===0){ btn.style.borderColor='rgba(255,255,255,.96)'; }
    cd.appendChild(btn);
  });
  setBoyamaTemplate(0);
  evApplySpecialGerman();
  setTimeout(function(){evApplySpecialGerman();evV34StyleBoyamaControls();},80);
  setTimeout(evV34StyleBoyamaControls,220);
}

