function evV34EnhanceBoyama(){
  try{
    var ov=document.getElementById('boyama-ov'); if(!ov) return;
    ov.style.background='radial-gradient(circle at 15% 15%,rgba(255,210,95,.26),transparent 28%),radial-gradient(circle at 84% 18%,rgba(120,220,255,.23),transparent 30%),radial-gradient(circle at 50% 92%,rgba(255,90,190,.20),transparent 36%),linear-gradient(155deg,#110018,#230032,#4a0b50,#0b061c)';
    ov.style.position='fixed';
    ov.style.overflowY='auto';
    ov.style.overflowX='hidden';

    if(!document.getElementById('v34-boyama-style')){
      var st=document.createElement('style');
      st.id='v34-boyama-style';
      st.textContent='@keyframes v34FloatPaint{0%{transform:translateY(0) rotate(0deg);opacity:.28}50%{opacity:.75}100%{transform:translateY(-38px) rotate(16deg);opacity:.22}}@keyframes v34ColorFlash{0%{transform:scale(.4);opacity:.9}100%{transform:scale(2.4);opacity:0}}@keyframes v34Spark{0%{transform:translate(-50%,-50%) scale(.4);opacity:1}100%{transform:translate(-50%,-130%) scale(1.5);opacity:0}}@keyframes v34CanvasGlow{0%{box-shadow:0 0 0 rgba(255,220,130,0)}50%{box-shadow:0 0 36px rgba(255,220,130,.55)}100%{box-shadow:0 0 0 rgba(255,220,130,0)}}';
      document.head.appendChild(st);
    }

    if(!document.getElementById('v34-boyama-bg')){
      var bg=document.createElement('div');
      bg.id='v34-boyama-bg';
      bg.style.cssText='position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:0;';
      var icons=['🎨','🖌️','💧','✨','🌈','🟡','🔵','🔴','🟣','🟢','⭐','🦋'];
      for(var i=0;i<34;i++){
        var sp=document.createElement('span');
        sp.textContent=icons[i%icons.length];
        sp.style.cssText='position:absolute;left:'+((i*37)%100)+'%;top:'+((i*53)%100)+'%;font-size:'+(16+(i%5)*5)+'px;filter:drop-shadow(0 0 12px rgba(255,255,255,.25));animation:v34FloatPaint '+(5+(i%7))+'s ease-in-out infinite alternate;animation-delay:-'+(i%6)+'s;';
        bg.appendChild(sp);
      }
      ov.insertBefore(bg,ov.firstChild);
    }

    Array.prototype.forEach.call(ov.children,function(ch){
      if(ch.id!=='v34-boyama-bg'){ ch.style.position='relative'; ch.style.zIndex='1'; }
    });

    var head=ov.querySelector('div[style*="justify-content:space-between"]');
    if(head){
      head.style.background='rgba(255,255,255,.09)';
      head.style.border='1px solid rgba(255,255,255,.14)';
      head.style.borderRadius='0 0 22px 22px';
      head.style.backdropFilter='blur(12px)';
      head.style.boxShadow='0 8px 28px rgba(0,0,0,.22)';
    }
    var title=head?head.querySelector('div'):null;
    if(title){
      title.style.color='#fff2a8';
      title.style.textShadow='0 0 18px rgba(255,210,100,.55)';
    }

    if(!document.getElementById('v34-boyama-ribbon')){
      var rib=document.createElement('div');
      rib.id='v34-boyama-ribbon';
      rib.innerHTML='🌈 Renk seç • Şablon seç • Tuvale dokun';
      rib.style.cssText='position:relative;z-index:1;margin:2px 12px 10px;padding:8px 14px;border-radius:999px;background:rgba(255,255,255,.11);border:1px solid rgba(255,255,255,.15);color:rgba(255,245,220,.92);font-family:Fredoka One;font-size:.78rem;text-align:center;box-shadow:0 8px 24px rgba(0,0,0,.20);';
      var after=head||ov.firstChild;
      if(after && after.nextSibling) ov.insertBefore(rib,after.nextSibling); else ov.appendChild(rib);
    }
  }catch(e){}
}

