function drawFriendChar(x,y,ts){
  var s=52; var bounce=Math.sin(ts*.003)*4;
  ctx.save(); ctx.translate(x,y+bounce);
  // Shadow
  ctx.fillStyle='rgba(0,0,0,.12)'; ctx.beginPath(); ctx.ellipse(0,s*.5+5,s*.32,s*.07,0,0,Math.PI*2); ctx.fill();
  // Legs
  ctx.fillStyle='#E8B400'; ctx.fillRect(-s*.15,s*.24,s*.13,s*.26); ctx.fillRect(s*.02,s*.24,s*.13,s*.26);
  ctx.fillStyle='#D4A017'; ctx.beginPath(); ctx.ellipse(-s*.08,s*.5,s*.1,s*.05,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(s*.08,s*.5,s*.1,s*.05,0,0,Math.PI*2); ctx.fill();
  // Body - blue for boy friend, pink for girl friend
  var bodyCol=isFemale()?'#6a9ae0':'#FF9EC5';
  var bodyGrad=ctx.createRadialGradient(-s*.08,-s*.04,0,0,s*.1,s*.38);
  bodyGrad.addColorStop(0,'#FFE566'); bodyGrad.addColorStop(1,'#FFD700');
  ctx.fillStyle=bodyGrad; ctx.beginPath(); ctx.ellipse(0,s*.16,s*.26,s*.3,0,0,Math.PI*2); ctx.fill();
  // Arms
  ctx.fillStyle='#FFD700'; ctx.save(); ctx.rotate(-.22); ctx.beginPath(); ctx.ellipse(-s*.3,s*.07,s*.09,s*.06,0,0,Math.PI*2); ctx.fill(); ctx.restore();
  ctx.save(); ctx.rotate(.22); ctx.beginPath(); ctx.ellipse(s*.3,s*.07,s*.09,s*.06,0,0,Math.PI*2); ctx.fill(); ctx.restore();
  // Head
  var hg=ctx.createRadialGradient(-s*.1,-s*.22,s*.04,0,-s*.2,s*.28);
  hg.addColorStop(0,'#FFF0A0'); hg.addColorStop(1,'#FFE566');
  ctx.fillStyle=hg; ctx.beginPath(); ctx.arc(0,-s*.2,s*.28,0,Math.PI*2); ctx.fill();
  // Hair/Hijab
  if(isFemale()){
    ctx.fillStyle='#A0C8F0'; ctx.beginPath(); ctx.ellipse(0,-s*.2,s*.26,s*.32,0,0,Math.PI*2); ctx.fill();
