function drawFireTrail(x,y){
  for(var i=0;i<3;i++){
    fireParts.push({x:x+(Math.random()-.5)*16,y:y,vx:(Math.random()-.5)*1.5,vy:-Math.random()*3-1.5,al:0.8,dc:0.04,r:Math.random()*8+4});
  }
  fireParts=fireParts.filter(function(p){
    p.x+=p.vx; p.y+=p.vy; p.vy+=.05; p.al-=p.dc;
    if(p.al<=0) return false;
    ctx.save(); ctx.globalAlpha=p.al;
    var fg=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r);
    fg.addColorStop(0,'rgba(255,255,200,'+p.al+')'); fg.addColorStop(.4,'rgba(255,150,0,'+p.al+')'); fg.addColorStop(1,'rgba(200,0,0,0)');
    ctx.fillStyle=fg; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill();
    ctx.restore(); return p.al>0;
  });
}

