function showOkiBubble(msg){
  var okiIconFixes={'\u011f\u0178\u0152\u0178':'\ud83c\udf1f','\u011f\u0178\u008f\u2020':'\ud83c\udfc6','\u00e2\u0161\u00a1':'\u26a1','\u011f\u0178\u0161\u20ac':'\ud83d\ude80','\u011f\u0178\u017d\u2030':'\ud83c\udf89','\u00e2\u00ad\u0090':'\u2b50','\u011f\u0178\u2019\u00aa':'\ud83d\udcaa','\u011f\u0178\u017d\u0160':'\ud83c\udf8a','\u011f\u0178\u00a5\u00b0':'\ud83e\udd70','\u00e2\u0153\u00a8':'\u2728','\u011f\u0178\u2022\u0152':'\ud83d\udd4c','\u011f\u0178\u00a4\u00b2':'\ud83e\udd32','\u011f\u0178\u201c\u0161':'\ud83d\udcda','\u011f\u0178\u2019\u00a1':'\ud83d\udca1','\u011f\u0178\u201c\u2013':'\ud83d\udcd6','\u011f\u0178\u02dc\u0160':'\ud83d\ude0a','\u011f\u0178\u00a4\u009d':'\ud83e\udd1d','\u011f\u0178\u0090\u00a3':'\ud83d\udc23','\u011f\u0178\u2019\u2013':'\ud83d\udc96','\u011f\u0178\u017d\u00ae':'\ud83c\udfae','\u011f\u0178\u2019\u00ac':'\ud83d\udcac','\u011f\u0178\u0152\u00b8':'\ud83c\udf38','\u011f\u0178\u2019\u00a5':'\ud83d\udca5','\u011f\u0178\u017d\u00af':'\ud83c\udfaf'};
  Object.keys(okiIconFixes).forEach(function(icon){ msg=String(msg==null?'':msg).split(icon).join(okiIconFixes[icon]); });
  msg=evCleanOkiText(msg);
  // Her zaman güncel isimle değiştir
  var pn = playerName || '';
  if(msg && pn) msg = msg.replace(/_NU/g, pn.toUpperCase()).replace(/_N/g, pn);
  okiCurrentMsg=msg; okiMsgVisible=true;
  // Shop bubble (when shop is open)
  var shopBubble=document.getElementById('shop-bubble');
  if(shopBubble){
    shopBubble.innerHTML=msg+'<div style="position:absolute;bottom:-8px;left:14px;width:0;height:0;border-left:8px solid transparent;border-right:8px solid transparent;border-top:8px solid white;"></div>';
    shopBubble.style.display='block';
    shopBubble.style.animation='none';
    setTimeout(function(){shopBubble.style.animation='oki-fadein .3s ease';},10);
    clearTimeout(shopBubble._timer);
    shopBubble._timer=setTimeout(function(){shopBubble.style.display='none';},5000);
  }
  // Home screen bubble
  var el=document.getElementById('oki-bubble');
  if(el){ el.textContent=msg; el.style.opacity='1'; }
  var oc=document.getElementById('oki-canvas');
  if(oc){ oc.classList.add('oki-happy'); setTimeout(function(){oc.classList.remove('oki-happy');},500); }
  okiBouncing=true;
  // Karakter zıplasın
  if(typeof setCharState==='function') setCharState('jump',700);
  // Refleks odası bubble
  var rb=document.getElementById('refleks-oki-bubble');
  if(rb){
    rb.textContent=msg;
    rb.style.display='block';
    rb.style.animation='none';
    setTimeout(function(){rb.style.animation='oki-fadein .3s ease';},10);
    // Oki resmini güncelle
    var ri=document.getElementById('refleks-oki-img');
    if(ri && typeof _selectedChar!=='undefined'){
      var _stage=typeof getCurrentStage==='function'?getCurrentStage():null;
      var _key=_selectedChar==='kiz'?(_stage&&_stage.charSet?(_stage.charSet==='erkek_agac'?'kiz_agac':'kiz_fidan'):'kiz'):(_stage&&_stage.charSet||'erkek');
      var _imgs=_CHARS[_key]||_CHARS[_selectedChar]||_CHARS.erkek;
      ri.src=_imgs['idle']||'';
    }
  }
  // Game screen bubble
  var gb=document.getElementById('oki-game-bubble');
  if(gb){ gb.textContent=msg; gb.style.display='block'; gb.style.animation='none'; setTimeout(function(){gb.style.animation='oki-fadein .3s ease';},10); }
  clearTimeout(okiMsgTimer);
  okiMsgTimer=setTimeout(function(){
    okiMsgVisible=false; okiBouncing=false;
    var el2=document.getElementById('oki-bubble');
    if(el2) el2.style.opacity='0';
    var oc2=document.getElementById('oki-canvas');
    if(oc2) oc2.classList.remove('oki-happy');
    var gb2=document.getElementById('oki-game-bubble');
    if(gb2) gb2.style.display='none';
    var rb2=document.getElementById('refleks-oki-bubble');
    if(rb2) rb2.style.display='none';
  },3000);
}

