function okiReactToScore(pts){
  if(pts>=40){
    setCharState('jump', 2200);
    var bigMsgs=['WOW! '+pts+' puan! 🌟','MUHTEŞEM! 🏆','İNANILMAZ! ⚡','SEN DAHISIN! 🚀'];
    showOkiBubble(bigMsgs[Math.floor(Math.random()*bigMsgs.length)]);
    for(var _si=0;_si<6;_si++) setTimeout(_spawnSpark,_si*100);
    _charScreenShake();
  } else if(pts>=20){
    setCharState('jump', 1500);
    var midMsgs=['Süper! 🎉','Harika! ⭐','Devam et! 💪','Bravo! 🎊'];
    showOkiBubble(midMsgs[Math.floor(Math.random()*midMsgs.length)]);
    for(var _si2=0;_si2<3;_si2++) setTimeout(_spawnSpark,_si2*150);
  } else if(pts>0){
    if(Math.random()<.35){
      setCharState('wave', 1200);
      showOkiBubble(getOkiStage().msg[Math.floor(Math.random()*3)]);
    }
  }
}

