function _evPrayerEmitOnce(prayer,timeStr,emit){
  if(!evPrayerContextAllowed()) return false;
  var now=new Date();
  var dayKey=now.getFullYear()+'-'+(now.getMonth()+1)+'-'+now.getDate();
  var eventKey=dayKey+'|'+String(prayer||'unknown');
  // Keep the temporary manual test isolated from today's real prayer event.
  if(timeStr==='TEST') eventKey+='|TEST';
  if(_evPrayerEventConsumed[eventKey]) return false;
  _evPrayerEventConsumed[eventKey]=true;
  try{ emit(); }catch(e){ delete _evPrayerEventConsumed[eventKey]; throw e; }
  return true;
}

