function speakArabic(letter){
  var data=arabicLetters[letter]||{ar:letter,say:letter};
  if(!window.speechSynthesis) return;

  try{
    window.speechSynthesis.cancel();

    // V25B/V26 SES:
    // "harfi" yok. Arapça ses varsa gerçek adı okur, Arapça ses yoksa sessiz kalmadan temiz Latin okunuşu okur.
    var voices=[];
    try{ voices=window.speechSynthesis.getVoices?window.speechSynthesis.getVoices():[]; }catch(e){ voices=[]; }

    var arVoice=null;
    for(var i=0;i<voices.length;i++){
      var v=voices[i];
      var lang=(v.lang||'').toLowerCase();
      var name=(v.name||'').toLowerCase();
      if(lang.indexOf('ar')===0 || name.indexOf('arabic')>-1 || name.indexOf('arab')>-1 || name.indexOf('arabe')>-1 || name.indexOf('arabisch')>-1){
        arVoice=v; break;
      }
    }

    function speakFallback(){
      try{
        window.speechSynthesis.cancel();
        var f=new SpeechSynthesisUtterance(data.say);
        f.lang='tr-TR';
        f.rate=.78;
        f.pitch=1.02;
        f.volume=.98;
        window.speechSynthesis.speak(f);
      }catch(e){}
    }

    if(arVoice){
      var started=false;
      var u=new SpeechSynthesisUtterance(data.ar);
      u.lang=arVoice.lang||'ar-SA';
      u.voice=arVoice;
      u.rate=.72;
      u.pitch=1.0;
      u.volume=.98;
      u.onstart=function(){ started=true; };
      u.onerror=function(){ if(!started) speakFallback(); };
      window.speechSynthesis.speak(u);
      setTimeout(function(){
        if(!started && !window.speechSynthesis.speaking){
          speakFallback();
        }
      },850);
    }else{
      speakFallback();
    }
  }catch(e){}
}

