function trackArabicLetter(letter){
  try{
    var data=arabicLetters[letter]||{ar:letter,say:letter};
    var key='AR:'+letter;

    // İki tıklama sistemi:
    // 1. tıklama: 1/2 görünür.
    // 2. tıklama: öğrenildi görünür, localStorage'a kaydolur, ebeveyn raporuna geçer.
    seenCount[key]=(parseInt(seenCount[key]||0,10)||0)+1;
    var count=seenCount[key];

    if(count>=2 && !learnedWords[key]){
      learnedWords[key]=1;

      var tk='dei_wday_'+new Date().toDateString();
      var tl=[];
      try{ tl=JSON.parse(localStorage.getItem(tk)||'[]'); }catch(e){ tl=[]; }
      if(tl.indexOf(key)<0){
        tl.push(key);
        localStorage.setItem(tk,JSON.stringify(tl));
      }

      savePlayerData();
