function getMelekSize(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var streak=0;
  // Count days fed (skip today if not yet fed - don't punish)
  for(var i=1;i<=30;i++){
    var d=new Date(); d.setDate(d.getDate()-i);
    if(fed[d.toDateString()]) streak++;
    else break;
  }
  // Also count today if fed
  if(fed[new Date().toDateString()]) streak++;
  // Size: starts at 0.45, grows per day fed, max 1.0
  return Math.min(1.0, 0.45+streak*0.06);
}

