function drawNefesOverlay(ts){
  var phaseLen=4800, t=ts%(phaseLen*4), phase=Math.floor(t/phaseLen), prog=(t%phaseLen)/phaseLen;
  var msgs=(evValuesOn()&&evValuesLang()==='en')?['Breathe in...','Hold...','Breathe out...','Rest...']:((evValuesOn()&&evValuesLang()==='de')?['Einatmen...','Halten...','Ausatmen...','Ruhen...']:((evValuesOn()&&evValuesLang()==='fr')?['Inspire...','Retiens...','Expire...','Repose-toi...']:((evValuesOn()&&evValuesLang()==='ar')?['\u0634\u0647\u064a\u0642...','\u0627\u062d\u0628\u0633...','\u0632\u0641\u064a\u0631...','\u0627\u0633\u062a\u0631\u062d...']:['Nefes Al...','Tut...','Nefes Ver...','Dinlen...'])));
  var col=['rgba(100,200,255,.7)','rgba(150,220,255,.5)','rgba(50,150,200,.7)','rgba(80,160,220,.5)'];
  var minR=W*.1, maxR=W*.2, r;
  if(phase===0) r=minR+(maxR-minR)*prog;
  else if(phase===1) r=maxR;
  else if(phase===2) r=maxR-(maxR-minR)*prog;
  else r=minR;
  var gw=ctx.createRadialGradient(W*.5,H*.4,r*.2,W*.5,H*.4,r*1.8);
  gw.addColorStop(0,col[phase]); gw.addColorStop(1,'transparent');
  ctx.fillStyle=gw; ctx.fillRect(0,0,W,H);
  for(var i=0;i<3;i++){
    ctx.strokeStyle=col[phase]; ctx.lineWidth=2-i*.5; ctx.globalAlpha=1-i*.25;
    ctx.beginPath(); ctx.arc(W*.5,H*.4,r+i*18,0,Math.PI*2); ctx.stroke(); ctx.globalAlpha=1;
  }
  ctx.fillStyle='rgba(200,240,255,.95)'; ctx.font='bold '+Math.round(W*.06)+'px Fredoka One'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText(msgs[phase],W*.5,H*.7);
  ctx.fillStyle='rgba(150,200,255,.5)'; ctx.font='bold '+Math.round(W*.03)+'px Nunito';
  ctx.fillText(evValuesOn()&&evValuesLang()==='en'?'Tap - collect points':(evValuesOn()&&evValuesLang()==='de'?'Tippen - Punkte sammeln':(evValuesOn()&&evValuesLang()==='fr'?'Touche - gagne des points':(evValuesOn()&&evValuesLang()==='ar'?'\u0627\u0644\u0645\u0633 - \u0627\u062c\u0645\u0639 \u0627\u0644\u0646\u0642\u0627\u0637':'Tikla - Puan Kazan'))),W*.5,H*.78);
}

