function drawWaterfall(ts){
  if(Math.random()<.35){
    wdrops.push({x:W*.25+Math.random()*W*.5,y:H*.05,vy:2+Math.random()*5,al:.8,r:Math.random()*7+2,col:['#4488FF','#44DDAA','#AA44FF','#FF4488','#44FFCC'][Math.floor(Math.random()*5)]});
  }
  wdrops=wdrops.filter(function(d){
    d.y+=d.vy; d.vy+=.1; d.al-=.007;
    if(d.al<=0||d.y>H) return false;
    ctx.save(); ctx.globalAlpha=d.al;
    var dg=ctx.createRadialGradient(d.x,d.y,0,d.x,d.y,d.r);
    dg.addColorStop(0,'rgba(255,255,255,.8)'); dg.addColorStop(.4,d.col+'cc'); dg.addColorStop(1,'transparent');
    ctx.fillStyle=dg; ctx.beginPath(); ctx.arc(d.x,d.y,d.r,0,Math.PI*2); ctx.fill();
    ctx.restore(); return true;
  });
}

