function drawSimpleQR(data){
  var canvas = document.getElementById('qr-canvas');
  if(!canvas){ return; }
  var ctx2 = canvas.getContext('2d');
  if(!ctx2) return;
  var size = 200;
  ctx2.fillStyle = 'white'; ctx2.fillRect(0,0,size,size);
  
  // Encode report data as URL-safe string
  var encoded = btoa(encodeURIComponent(JSON.stringify({
    n: data.name,
    s: data.totalScore,
    w: data.totalWords,
    al: data.arabicLetters||0,
    enw: data.englishWords||0,
    dew: data.germanWords||0,
    frw: data.frenchWords||0,
    tw: data.todayWords,
    st: data.streak,
    r: data.rooms,
    p: data.psych.slice(0,2),
  }))).replace(/[+/=]/g,'').substr(0,32);
  
  var reportURL = 'https://eduverse.club/rapor?d='+encoded;
  document.getElementById('qr-url-txt').textContent = reportURL.substr(0,45)+'...';
  
  // Draw QR-like pattern (simplified visual)
  var modules = 21;
  var cell = Math.floor((size-20)/modules);
  var offset = 10;
  ctx2.fillStyle = '#000';
  
  // Generate pseudo-random but deterministic pattern from data
  var seed = data.totalScore + data.totalWords*7 + data.streak*13;
  function pseudoRand(i){ return ((seed*1664525+i*1013904223)&0x7fffffff)/0x7fffffff; }
  
  for(var row=0;row<modules;row++){
    for(var col2=0;col2<modules;col2++){
      var x3=offset+col2*cell, y3=offset+row*cell;
      var filled=false;
      // Corner markers (3x3 finder patterns)
      if((row<7&&col2<7)||(row<7&&col2>modules-8)||(row>modules-8&&col2<7)){
        var mr=row%(modules-1),mc=col2%(modules-1);
        var inOuter=(mr<7&&mc<7);
        var inInner=(mr>=2&&mr<=4&&mc>=2&&mc<=4);
        filled=inOuter&&(mr===0||mr===6||mc===0||mc===6||inInner);
      } else {
        filled=pseudoRand(row*modules+col2)>.48;
      }
      if(filled){ ctx2.fillStyle='#000'; ctx2.fillRect(x3,y3,cell-1,cell-1); }
    }
  }
  
  // EduVerse logo center
  ctx2.fillStyle='white'; ctx2.fillRect(size/2-18,size/2-18,36,36);
  ctx2.fillStyle='#1a6a3a'; ctx2.font='bold 10px Fredoka One'; ctx2.textAlign='center'; ctx2.textBaseline='middle';
  ctx2.fillText('EDU',size/2,size/2-4); ctx2.fillText('VERSE',size/2,size/2+7);
}

