function duaGonder(){
  // Mistik ses
  try{
    var _ac=new(window.AudioContext||window.webkitAudioContext)();
    var _notes=[293.7,349.2,392,440,523.3,587.3,659.3,783.9,1046.5];
    _notes.forEach(function(f,i){
      var o=_ac.createOscillator(),g=_ac.createGain();
      o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,_ac.currentTime+i*.2);
      g.gain.linearRampToValueAtTime(.1,_ac.currentTime+i*.2+.1);
      g.gain.exponentialRampToValueAtTime(.001,_ac.currentTime+i*.2+1.5);
      o.connect(g); g.connect(_ac.destination);
      o.start(_ac.currentTime+i*.2); o.stop(_ac.currentTime+i*.2+2);
    });
    var pad=_ac.createOscillator(),padG=_ac.createGain();
    pad.type='triangle'; pad.frequency.value=110;
    padG.gain.setValueAtTime(0,_ac.currentTime);
    padG.gain.linearRampToValueAtTime(.06,_ac.currentTime+.5);
    padG.gain.exponentialRampToValueAtTime(.001,_ac.currentTime+12);
    pad.connect(padG); padG.connect(_ac.destination);
    pad.start(); pad.stop(_ac.currentTime+13);
  }catch(e){}

  document.getElementById('dua-send-btn').style.display='none';
  document.getElementById('dua-e2').style.display='none';

  // ADIM 1: Mühürleme ekranı
  var e3=document.getElementById('dua-e3');
  e3.style.cssText='display:flex;position:absolute;inset:0;z-index:4;flex-direction:column;align-items:center;justify-content:center;';
  var zarf=document.getElementById('dua-zarf');
  var mfx=document.getElementById('dua-muhur-fx');
  var mtxt=document.getElementById('dua-muhur-txt');
  var _L = DUA_LANG_DATA[_duaLang]||DUA_LANG_DATA.tr;
  mtxt.textContent = _L.muhurTxt || 'Mühürleniyor...';
  zarf.textContent='📜'; zarf.style.animation='none';
  mfx.style.opacity='0'; mfx.style.animation='none';
  mtxt.style.opacity='0';

  // Zarf sarsılır
  setTimeout(function(){ zarf.style.animation='duaShake .5s ease-in-out 3'; },300);
  // Mühür damgalanır
  setTimeout(function(){
    mfx.textContent='📮';
    mfx.style.opacity='1';
    mfx.style.animation='duaStampBig .45s cubic-bezier(.17,.67,.35,1.5)';
    mtxt.style.opacity='1';
    mtxt.style.animation='duaFadeUp .4s ease-out';
  },900);
  // Zarf mektuba dönüşür
  setTimeout(function(){ zarf.textContent='💌'; zarf.style.animation='duaBig .3s ease-out'; },1400);

  // ADIM 2: Uçuş başlar
  setTimeout(function(){
    e3.style.display='none';
    _duaStartFlight();
  },2000);
}

