function _duaStartFlight(){
  var e4=document.getElementById('dua-e4');
  e4.style.display='block';

  // Canvas üzerinde uçuş animasyonu
  var c=document.getElementById('dua-sky-c');
  var W4=window.innerWidth, H4=window.innerHeight;
  c.width=W4; c.height=H4;
  var ctx4=c.getContext('2d');

  var arabicLetters=(typeof evDuaValuesOn==='function'&&evDuaValuesOn())?['✦','★','✧','●','○','◇','☀','☾']:['ب','ت','ث','ج','ح','خ','د','ر','ز','س','ش','ص','ط','ع','غ','ف','ق','ك','ل','م','ن','ه','و','ي','ا','الله','الحمد','بسم','آمين','سبحان'];
  var stars4=[];
  for(var i=0;i<120;i++) stars4.push({x:Math.random()*W4,y:Math.random()*H4,r:Math.random()*2+.4,phase:Math.random()*Math.PI*2,spd:.6+Math.random()*1.5});
  var letters4=[];
  var envY4=H4*0.75, envAlpha4=1;
  var DURATION=12000;
  var startTs4=null;
  var letterTimer4=0;
  var rings4=[];

  function spawnLetter4(){
    letters4.push({
      x:Math.random()*W4, y:-20,
      txt:arabicLetters[Math.floor(Math.random()*arabicLetters.length)],
      spd:.4+Math.random()*.6,
      rot:(Math.random()-.5)*.3,
      rotSpd:(Math.random()-.5)*.01,
      alpha:0,
      size:14+Math.random()*16,
      col:Math.random()>.5?'rgba(255,220,100,':'rgba(200,150,255,'
    });
  }

  function flightFrame4(ts){
    if(!startTs4) startTs4=ts;
    var elapsed=ts-startTs4;
    var progress=Math.min(1,elapsed/DURATION);

    ctx4.clearRect(0,0,W4,H4);

    // Sky
    var sky4=ctx4.createLinearGradient(0,0,0,H4);
    sky4.addColorStop(0,'#010410'); sky4.addColorStop(.5,'#050d2e'); sky4.addColorStop(1,'#1a0a3e');
    ctx4.fillStyle=sky4; ctx4.fillRect(0,0,W4,H4);

    // Golden glow
    if(progress>.05){
      var gg=ctx4.createRadialGradient(W4/2,H4/2,0,W4/2,H4/2,W4*.6);
      gg.addColorStop(0,'rgba(255,200,50,'+(0.06*Math.min(1,elapsed/2000))+')');
      gg.addColorStop(1,'transparent');
      ctx4.fillStyle=gg; ctx4.fillRect(0,0,W4,H4);
    }

    // Stars twinkling
    var t4=ts*.001;
    stars4.forEach(function(s){
      var a=.15+.85*(.5+.5*Math.sin(s.phase+t4*s.spd));
      ctx4.beginPath(); ctx4.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx4.fillStyle='rgba(255,255,255,'+a+')'; ctx4.fill();
    });

    // Pulse rings
    rings4.push({r:0,al:.35});
    rings4=rings4.filter(function(rg){return rg.al>0;});
    rings4.forEach(function(rg){
      rg.r+=1.5; rg.al-=.005;
      ctx4.beginPath(); ctx4.arc(W4/2,H4/2,rg.r,0,Math.PI*2);
      ctx4.strokeStyle='rgba(255,210,80,'+rg.al+')'; ctx4.lineWidth=1.5; ctx4.stroke();
    });

    // Arabic letters raining down
    letterTimer4+=16;
    if(letterTimer4>350){ letterTimer4=0; spawnLetter4(); }
    letters4.forEach(function(l){
      l.y+=l.spd; l.rot+=l.rotSpd;
      if(l.y<H4*.35) l.alpha=Math.min(.75,l.alpha+.025);
      else l.alpha=Math.max(0,l.alpha-.006);
      if(l.alpha<=0) return;
      ctx4.save();
      ctx4.translate(l.x,l.y); ctx4.rotate(l.rot);
      ctx4.globalAlpha=l.alpha;
      ctx4.font='bold '+l.size+'px serif';
      ctx4.textAlign='center'; ctx4.textBaseline='middle';
      ctx4.fillStyle=l.col+l.alpha+')';
      ctx4.shadowColor=l.col+'0.4)'; ctx4.shadowBlur=6;
      ctx4.fillText(l.txt,0,0);
      ctx4.restore();
    });
    letters4=letters4.filter(function(l){return l.y<H4+30;});

    // Melek + mektup yükseliyor
    var eased=progress<.5?2*progress*progress:1-Math.pow(-2*progress+2,2)/2;
    envY4=H4*.75-(H4*.75+100)*eased;
    envAlpha4=progress>.85?Math.max(0,1-(progress-.85)/.15):1;
    var swayX4=Math.sin(ts*.0012)*18*(1-progress);

    ctx4.save();
    ctx4.translate(W4/2+swayX4, envY4);
    ctx4.scale(1-eased*.45, 1-eased*.45);
    ctx4.globalAlpha=envAlpha4;
    // Halo
    var hg=ctx4.createRadialGradient(0,0,5,0,0,55);
    hg.addColorStop(0,'rgba(255,215,80,.3)'); hg.addColorStop(1,'transparent');
    ctx4.fillStyle=hg; ctx4.fillRect(-55,-55,110,110);
    // Angel
    ctx4.font='3.2rem serif'; ctx4.textAlign='center'; ctx4.textBaseline='middle';
    ctx4.shadowColor='rgba(255,220,100,.8)'; ctx4.shadowBlur=20;
    ctx4.fillText('👼',0,-28);
    // Letter
    ctx4.font='2.2rem serif';
    ctx4.fillText('💌',0,18);
    ctx4.restore();

    if(progress>=1){
      if(_duaSkyAnim) cancelAnimationFrame(_duaSkyAnim);
      _duaSkyAnim=null;
      e4.style.display='none';
      _duaShowKabul4();
      return;
    }
    _duaSkyAnim=requestAnimationFrame(flightFrame4);
  }

  if(_duaSkyAnim) cancelAnimationFrame(_duaSkyAnim);
  _duaSkyAnim=requestAnimationFrame(flightFrame4);
}

