function _duaShowKabul4(){
  // Dile göre kabul ekranını güncelle
  var _dl = evActiveDuaLangData(_duaLang);
  var kabulEl = document.getElementById('dua-kabul-txt');
  var kabulSub = document.getElementById('dua-kabul-sub');
  var kabulNote = document.getElementById('dua-kabul-note');
  var backBtn = document.getElementById('dua-back-btn');
  if(kabulEl) kabulEl.textContent = _dl.kabul;
  if(kabulSub) kabulSub.innerHTML = _dl.kabulSub;
  if(kabulNote) kabulNote.textContent = _dl.kabulNote;
  if(backBtn) backBtn.textContent = _dl.backBtn;
  var e5=document.getElementById('dua-e5');
  e5.style.cssText='display:flex;position:absolute;inset:0;z-index:6;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;';
  var els=[
    {id:'dua-e5',delay:0}
  ];
  // Animate children
  var children=e5.children;
  for(var ci=0;ci<children.length;ci++){
    (function(el,delay){
      el.style.opacity='0';
      el.style.transform='translateY(20px)';
      setTimeout(function(){
        el.style.transition='opacity .5s ease,transform .5s ease';
        el.style.opacity='1';
        el.style.transform='translateY(0)';
      },delay);
    })(children[ci], ci*200+100);
  }
  // Star burst
  var b=document.getElementById('dua-burst');
  var icons=['⭐','🌟','💫','✨','🌙','👼'],ct=0;
  var iv=setInterval(function(){
    if(ct++>14){clearInterval(iv);return;}
    b.textContent=icons[Math.floor(Math.random()*6)]+' '+icons[Math.floor(Math.random()*6)]+' '+icons[Math.floor(Math.random()*6)];
  },200);
}

