function _duaStartSky(){
  var c=document.getElementById('dua-sky-c');
  if(!c) return;
  c.width=window.innerWidth; c.height=window.innerHeight;
  var ctx2=c.getContext('2d');
  var stars2=[];
  for(var i=0;i<140;i++) stars2.push({x:Math.random()*c.width,y:Math.random()*c.height,r:Math.random()*2+.4,phase:Math.random()*Math.PI*2,spd:.6+Math.random()*1.5});
  var g2=ctx2.createLinearGradient(0,0,0,c.height);
  g2.addColorStop(0,'#010410');g2.addColorStop(.5,'#050d2e');g2.addColorStop(1,'#1a0a3e');
  function frame2(ts){
    ctx2.fillStyle=g2; ctx2.fillRect(0,0,c.width,c.height);
    var t=ts*.001;
    stars2.forEach(function(s){
      var a=.15+.85*(.5+.5*Math.sin(s.phase+t*s.spd));
      ctx2.beginPath(); ctx2.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx2.fillStyle='rgba(255,255,255,'+a+')'; ctx2.fill();
    });
    _duaSkyAnim=requestAnimationFrame(frame2);
  }
  if(_duaSkyAnim) cancelAnimationFrame(_duaSkyAnim);
  _duaSkyAnim=requestAnimationFrame(frame2);
}

