function _applyTheme(idx, silent){
  var th=THEMES[idx];
  document.body.setAttribute('data-theme', th.id);
  var hm=document.getElementById('hm');
  if(hm){
    if(th.space){
      hm.style.background='linear-gradient(180deg,#000510 0%,#020820 40%,#050d30 70%,#0a0520 100%)';
      _stopGalaxy();
