function _startGalaxy(hm, th){
  _stopGalaxy();
  var old=document.getElementById('_galaxy_c');
  if(old) old.remove();
  var gc2=document.createElement('canvas');
  gc2.id='_galaxy_c';
  gc2.style.cssText='position:absolute;inset:0;pointer-events:none;z-index:0;';
  hm.insertBefore(gc2, hm.firstChild);
  gc2.width=window.innerWidth; gc2.height=window.innerHeight;
  var gx=gc2.getContext('2d');
  var gstars=[];
  for(var i=0;i<190;i++) gstars.push({
    x:Math.random()*gc2.width, y:Math.random()*gc2.height,
    r:Math.random()*2.2+.3,
    phase:Math.random()*Math.PI*2,
    spd:.4+Math.random()*1.4,
    gold:Math.random()>.5
  });
  var glitters=[];
  for(var j=0;j<58;j++) glitters.push({
    x:Math.random()*gc2.width, y:Math.random()*gc2.height,
    size:1.2+Math.random()*3.2,
    phase:Math.random()*Math.PI*2,
    spd:.8+Math.random()*2,
    vx:(Math.random()-.5)*.25, vy:(Math.random()-.5)*.25
  });
  var gc_=th.glitterCol||'rgba(255,215,80,';
  var sc_=th.starCol||'rgba(255,255,255,';
  var nc_=th.nebulaCol||'rgba(80,40,160,';
  var shc=th.shimmerCol||'rgba(255,220,100,.04)';
  var acc=th.acc||'#FFD700';
  function gframe(ts){
    var t=ts*.001;
    gx.clearRect(0,0,gc2.width,gc2.height);
    // Nebula
    var ng=gx.createRadialGradient(gc2.width*.5,gc2.height*.28,0,gc2.width*.5,gc2.height*.28,gc2.width*.68);
    ng.addColorStop(0,nc_+'.22)'); ng.addColorStop(.4,nc_+'.1)'); ng.addColorStop(1,'transparent');
    gx.fillStyle=ng; gx.fillRect(0,0,gc2.width,gc2.height);
    // Stars
    gstars.forEach(function(s){
      var a=.12+.88*(.5+.5*Math.sin(s.phase+t*s.spd));
      if(s.r>1.5){
        gx.save(); gx.translate(s.x,s.y); gx.rotate(t*s.spd*.25);
        gx.beginPath();
        for(var p=0;p<4;p++){
          var pa=p/4*Math.PI*2;
          gx.lineTo(Math.cos(pa)*s.r*2.6,Math.sin(pa)*s.r*2.6);
          gx.lineTo(Math.cos(pa+Math.PI/4)*s.r*.65,Math.sin(pa+Math.PI/4)*s.r*.65);
        }
        gx.closePath();
        gx.fillStyle=(s.gold?gc_:sc_)+a+')';
        if(s.gold&&a>.65){gx.shadowColor=acc;gx.shadowBlur=7;}else gx.shadowBlur=0;
        gx.fill(); gx.restore();
      } else {
        gx.beginPath(); gx.arc(s.x,s.y,s.r*(0.6+a*.4),0,Math.PI*2);
        gx.fillStyle=(s.gold?gc_:sc_)+a+')'; gx.fill();
      }
    });
    // Glitters
    glitters.forEach(function(g2){
      g2.x+=g2.vx; g2.y+=g2.vy;
      if(g2.x<0||g2.x>gc2.width) g2.vx*=-1;
      if(g2.y<0||g2.y>gc2.height) g2.vy*=-1;
      var ga=.25+.75*(.5+.5*Math.sin(g2.phase+t*g2.spd));
      var gs2=g2.size*(0.5+ga*.5);
      gx.save(); gx.translate(g2.x,g2.y); gx.rotate(t*g2.spd*.45);
      gx.beginPath();
      for(var p=0;p<4;p++){
        var pa=p/4*Math.PI*2;
        gx.lineTo(Math.cos(pa)*gs2*2.4,Math.sin(pa)*gs2*2.4);
        gx.lineTo(Math.cos(pa+Math.PI/4)*gs2*.55,Math.sin(pa+Math.PI/4)*gs2*.55);
      }
      gx.closePath(); gx.fillStyle=gc_+ga+')';
      gx.shadowColor=acc; gx.shadowBlur=7; gx.fill(); gx.restore();
    });
    // Shimmer sweep
    var sx=((t*.065)%1.4)*gc2.width-gc2.width*.2;
    var sg=gx.createLinearGradient(sx,0,sx+gc2.width*.24,gc2.height);
    sg.addColorStop(0,'transparent'); sg.addColorStop(.5,shc); sg.addColorStop(1,'transparent');
    gx.fillStyle=sg; gx.fillRect(0,0,gc2.width,gc2.height);
    _galaxyAnim=requestAnimationFrame(gframe);
  }
  _galaxyAnim=requestAnimationFrame(gframe);
}

