      +'<textarea id="dua-custom-txt" maxlength="250" placeholder="'+lang.placeholder+'" '
      +'style="width:100%;height:100px;background:rgba(80,20,160,.25);border:1.5px solid rgba(180,100,255,.35);border-radius:14px;padding:12px;color:#fff;font-family:Nunito;font-size:.9rem;resize:none;outline:none;box-sizing:border-box;"></textarea>'
      +'<button id="_dua-send-lang-btn" onclick="duaKendiGonder()" style="margin-top:8px;width:100%;background:linear-gradient(135deg,#5500BB,#AA33FF);border:none;border-radius:22px;padding:11px;color:#fff;font-family:Fredoka One;font-size:1rem;cursor:pointer;">'+lang.btn+'</button>';
