function initPrayerTimes(){
  if(!evPrayerContextAllowed()) return;
  /* V48S73: Values/login ekraninda konum veya bildirim izni isteme.
     Namaz vakti sistemi sadece Dua/Ibadet tarafinda kullanilsin. */
  try{ if(typeof evValuesOn==='function' && evValuesOn()) return; }catch(e){}
  try{ if(localStorage.getItem('eduverse_values_mode')==='1') return; }catch(e2){}
  try{
    var ns=document.getElementById('ns');
    var cs=ns?window.getComputedStyle(ns):null;
    if(cs && cs.display!=='none' && cs.visibility!=='hidden') return;
  }catch(e3){}
  if('Notification' in window && Notification.permission==='default'){
    Notification.requestPermission();
  }
  if(!navigator.geolocation){ return; }
  navigator.geolocation.getCurrentPosition(function(pos){
    _fetchPrayerTimes(pos.coords.latitude, pos.coords.longitude);
  }, function(err){
    console.warn('Location unavailable:', err.message);
  }, {timeout:3000});
}

