function evRestoreLocationPermissionFlow(reason){
  if(!evPrayerContextAllowed()) return;
  try{
    if(_evLocationPermissionAskedThisSession) return;
    _evLocationPermissionAskedThisSession = true;
    if(!navigator.geolocation){ return; }
    // Edge/local file safety: file:// pages can leave the tab spinning or permission in an odd state.
    // In local desktop tests, do not block entry with browser permission; deployed HTTPS can ask normally.
    if(String(location.protocol||'')==='file:'){
      try{ localStorage.setItem('eduverse_location_permission_status','local_file_skipped'); }catch(_lf){}
      return;
    }
    if('Notification' in window && Notification.permission==='default'){
      try{ Notification.requestPermission(); }catch(_nerr){}
    }
    navigator.geolocation.getCurrentPosition(function(pos){
      try{
        localStorage.setItem('eduverse_location_permission_status','granted');
        localStorage.setItem('eduverse_location_last_reason', String(reason||'entry'));
      }catch(_s1){}
      try{ _fetchPrayerTimes(pos.coords.latitude, pos.coords.longitude); }catch(_ferr){}
    }, function(err){
      try{
        localStorage.setItem('eduverse_location_permission_status', err && err.code===1 ? 'denied' : 'unavailable');
        localStorage.setItem('eduverse_location_last_error', err && err.message ? String(err.message) : 'unknown');
      }catch(_s2){}
      try{ console.warn('Location permission flow:', err && err.message ? err.message : err); }catch(_c){}
    }, {enableHighAccuracy:false, timeout:7000, maximumAge:21600000});
  }catch(e){ try{ console.warn('Location permission flow failed:', e); }catch(_e){} }
}

