function _fetchPrayerTimes(lat, lng){
  if(!evPrayerContextAllowed()) return;
  var now = new Date();
  var ts = Math.floor(now.getTime()/1000);
  var url = 'https://api.aladhan.com/v1/timings/'+ts+'?latitude='+lat+'&longitude='+lng+'&method=13';
  
  fetch(url)
    .then(function(r){ return r.json(); })
    .then(function(data){
      if(!evPrayerContextAllowed()) return;
      if(data.code!==200) return;
      _prayerTimes = data.data.timings;
      _schedulePrayers(_prayerTimes);
      _showNextPrayer(_prayerTimes);
    })
    .catch(function(e){ console.warn('Namaz vakitleri alınamadı'); });
}

