prayers.forEach(function(prayer){
    var timeStr = timings[prayer]; // e.g. "05:32"
    if(!timeStr) return;
    var parts = timeStr.split(':');
    var prayerDate = new Date();
    prayerDate.setHours(parseInt(parts[0]), parseInt(parts[1]), 0, 0);
    
    var diff = prayerDate - now;
    if(diff < -60000) return; // already passed (more than 1 min ago)
    if(diff < 0) diff = 0;
    
    var timer = setTimeout(function(){
      _onPrayerTime(prayer, timeStr);
    }, diff);
    _prayerTimers.push(timer);
    
    // 10 min warning
    if(diff > 600000){
      var warnTimer = setTimeout(function(){
        _showPrayerWarning(prayer, timeStr);
      }, diff - 600000);
      _prayerTimers.push(warnTimer);
    }
  });

