function _onPrayerTime(prayer, timeStr){
  if(!evPrayerContextAllowed()) return;
  return _evPrayerEmitOnce(prayer,timeStr,function(){
  var name = _prayerNames[prayer] || prayer;
  // Show banner
  var banner = document.getElementById('prayer-banner');
  var nameEl = document.getElementById('prayer-name');
  var txtEl = document.getElementById('prayer-time-txt');
  if(banner && nameEl && txtEl){
    nameEl.textContent = name;
    txtEl.textContent = timeStr + ' — Namaz vakti geldi';
    banner.style.display = 'block';
    // Auto hide after 30s
    setTimeout(function(){
      if(banner) banner.style.display='none';
    }, 30000);
  }
  // Browser notification
  if('Notification' in window && Notification.permission==='granted'){
    new Notification('🕌 '+name, {
      body: timeStr+' — Allah kabul etsin 🤲',
      icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🕌</text></svg>',
      tag: 'prayer-'+prayer
    });
  }
  // Play azan sound (simple tone sequence)
  _playAzanTone();
  });
}

