function _showNextPrayer(timings){
  if(!evPrayerContextAllowed()){ evPrayerContextStop('nextPrayerBlocked'); return; }
  var now = new Date();
  var prayers = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  var next = null;
  prayers.forEach(function(p){
    var parts = (timings[p]||'').split(':');
    var pd = new Date();
    pd.setHours(parseInt(parts[0]||0), parseInt(parts[1]||0), 0, 0);
    if(pd > now && !next) next = {name:_prayerNames[p], time:timings[p]};
  });
  if(!next) return;
  // Update home screen if visible
  var el = document.getElementById('prayer-next');
  if(el){ el.textContent = 'Sonraki namaz: '+next.name+' — '+next.time; }
}

