function _playAzanTone(){
  if(!evPrayerContextAllowed()) return;
  try{
    if(_evPrayerAzanAudioContext){
      try{ _evPrayerAzanAudioContext.close(); }catch(_previousAzanCloseErr){}
      _evPrayerAzanAudioContext=null;
    }
    var ac2=new(window.AudioContext||window.webkitAudioContext)();
    _evPrayerAzanAudioContext=ac2;
    // Simple ascending spiritual tone
    var freqs=[440,495,440,392,440,495,528];
    var time=ac2.currentTime;
    freqs.forEach(function(f,i){
      var o=ac2.createOscillator(),g=ac2.createGain();
      o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,time+i*.4);
      g.gain.linearRampToValueAtTime(.15,time+i*.4+.15);
      g.gain.exponentialRampToValueAtTime(.001,time+i*.4+.5);
      o.connect(g); g.connect(ac2.destination);
      o.start(time+i*.4); o.stop(time+i*.4+.6);
    });
    setTimeout(function(){
      if(_evPrayerAzanAudioContext===ac2){
        _evPrayerAzanAudioContext=null;
        try{ ac2.close(); }catch(_azanCloseErr){}
      }
    },3400);
  }catch(e){}
}

