function updateDailyStrip(){
  if(typeof getTodayTasks!=='function') return;
  var done=getTodayTasks();
  var total=typeof DAILY_TASKS!=='undefined'?DAILY_TASKS.length:12;
  var completed=Object.keys(done).filter(function(k){return done[k];}).length;
  var pct=Math.round((completed/total)*100);
  var txt=document.getElementById('daily-strip-text');
  var fill=document.getElementById('daily-strip-fill');
  var stripLang=evValuesOn()?evValuesLang():'tr';
