function evEnglishOkiStageName(stageName){
  var n=evAscii(stageName||'');
  if(n.indexOf('bebek')>=0) return 'Baby Oki';
  if(n.indexOf('kucuk')>=0) return 'Little Oki';
  if(n.indexOf('okul')>=0) return 'School Oki';
  if(n.indexOf('kahraman')>=0) return 'Hero Oki';
  if(n.indexOf('usta')>=0) return 'Master Oki';
  if(n.indexOf('yildiz')>=0) return 'Star Oki';
  if(n.indexOf('efsane')>=0) return 'Legend Oki';
  if(n.indexOf('melek')>=0) return 'Angel Oki';
  return 'Oki';
}

