function showTasks(){
  var ov = document.getElementById('tasks-ov');
  hideStreakOv();
  ov.style.display = 'block';
  var taskLang=evValuesOn()?evValuesLang():'tr';
  var taskTitles={tr:'Bugunun Gorevleri',de:'Heutige Aufgaben',en:'Daily Tasks',fr:'Missions du jour',ar:'مهام اليوم'};
  var tTitle=ov.querySelector('div[style*="font-size:1.6rem"]');
  if(tTitle && taskTitles[taskLang]) tTitle.textContent=taskTitles[taskLang];
  
  // Date
  var dateEl = document.getElementById('tasks-date');
  var taskLocales={tr:'tr-TR',de:'de-DE',en:'en-US',fr:'fr-FR',ar:'ar-SA'};
  if(dateEl) dateEl.textContent = new Date().toLocaleDateString(taskLocales[taskLang]||'tr-TR',{weekday:'long',day:'numeric',month:'long'});
  
  // Oki mini
  var miniCanvas = document.getElementById('tasks-oki-mini');
  if(miniCanvas && typeof drawOki === 'function'){
    okiCanvas = miniCanvas;
    okiCtx = miniCanvas.getContext('2d');
    drawOki(0);
    okiCanvas = document.getElementById('oki-canvas');
    okiCtx = okiCanvas ? okiCanvas.getContext('2d') : null;
  }
  
  // Oki name
  var stage = typeof getOkiStage==='function' ? getOkiStage() : {name:'Okişi'};
  var nameEl = document.getElementById('tasks-oki-name');
  if(nameEl) nameEl.textContent = taskLang==='en' ? evEnglishOkiStageName(stage.name) : (taskLang==='de'?'Baby Oki':(taskLang==='fr'?'Bebe Oki':(taskLang==='ar'?'أوكي الصغير':(taskLang==='tr'?'Bebek Oki':stage.name))));
  
  // XP bar
  var done = getTodayTasks();
  var taskList=!evValuesOn()?DAILY_TASKS:(taskLang==='ar'?getArabicDailyTasks():(taskLang==='en'?getEnglishDailyTasks():(taskLang==='de'?getValuesDailyTasks():(taskLang==='fr'?getFrenchDailyTasks():getTurkishValuesDailyTasks()))));
  var todayXP = taskList.reduce(function(s,t){return done[t.id]?s+t.xp:s;},0);
  var maxXP = taskList.reduce(function(s,t){return s+t.xp;},0);
  var xpEl = document.getElementById('tasks-xp-earned');
  var barEl = document.getElementById('tasks-xp-bar');
  if(xpEl) xpEl.textContent = todayXP;
  if(taskLang==='en' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='Today <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> XP earned'; xpEl=document.getElementById('tasks-xp-earned'); }
  else if(taskLang==='de' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='Heute <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> XP verdient'; xpEl=document.getElementById('tasks-xp-earned'); }
  else if(taskLang==='fr' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='Aujourd\'hui <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> XP gagnes'; xpEl=document.getElementById('tasks-xp-earned'); }
  else if(taskLang==='ar' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='تم كسب <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> XP اليوم'; xpEl=document.getElementById('tasks-xp-earned'); }
  else if(taskLang==='tr' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='Bugun <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> XP kazanildi'; xpEl=document.getElementById('tasks-xp-earned'); }
  if(taskLang==='ar' && xpEl && xpEl.parentNode){ xpEl.parentNode.innerHTML='\u062A\u0645 \u0643\u0633\u0628 <span id="tasks-xp-earned" style="color:#FFD700;font-weight:700;">'+todayXP+'</span> \u0646\u0642\u0637\u0629 \u0627\u0644\u064A\u0648\u0645'; xpEl=document.getElementById('tasks-xp-earned'); }
  if(barEl) barEl.style.width = Math.min(100,(todayXP/maxXP)*100)+'%';
  
  // Task list
  var list = document.getElementById('tasks-list');
  if(!list) return;
  list.innerHTML = '';
  
  taskList.forEach(function(task){
    var completed = !!done[task.id];
    var div = document.createElement('div');
    div.style.cssText = 'background:'+(completed?'rgba(80,200,80,.15)':'rgba(255,255,255,.06)')+
      ';border:1.5px solid '+(completed?'rgba(80,200,80,.4)':'rgba(255,255,255,.12)')+
      ';border-radius:16px;padding:14px 16px;display:flex;align-items:center;gap:12px;cursor:pointer;transition:all .2s;';
    
    div.innerHTML = 
      '<div style="font-size:2rem;flex-shrink:0;">'+task.icon+'</div>'+
      '<div style="flex:1;">'+
        '<div style="font-family:Fredoka One;font-size:.95rem;color:'+(completed?'#66DD66':'#fff')+';">'+task.name+'</div>'+
        '<div style="font-size:.72rem;color:rgba(255,255,255,.5);margin-top:2px;">'+task.desc+'</div>'+
      '</div>'+
      '<div style="text-align:center;flex-shrink:0;">'+
        '<div style="font-family:Fredoka One;font-size:1rem;color:#FFD700;">+'+task.xp+'</div>'+
        '<div style="font-size:.65rem;color:rgba(255,255,255,.4);">XP</div>'+
      '</div>'+
'<div style="font-size:1.6rem;flex-shrink:0;">'+(completed?'\u2713':'\u25CB')+'</div>';
    if(taskLang==='ar') div.innerHTML = div.innerHTML.replace('>XP<','>'+evAr('point')+'<');
    
    div.onclick = (function(t, el){
      return function(){
        var d = getTodayTasks();
        if(d[t.id]){
          // Uncheck
          delete d[t.id];
          saveTodayTasks(d);
        } else {
          // Complete task!
          d[t.id] = Date.now();
          saveTodayTasks(d);
          // Give score to game
          if(typeof addScore==='function') addScore(t.xp, 0, 0, '#FFD700');
          // Oki reaction
          _taskOkiReact(t);
        }
        showTasks(); // refresh
      };
    })(task, div);
    
    list.appendChild(div);
  });
}

