function _taskOkiReact(task){
  // Make Oki happy
  var canvas = document.getElementById('oki-canvas');
  if(canvas) canvas.classList.add('oki-happy');
  setTimeout(function(){
    if(canvas) canvas.classList.remove('oki-happy');
  }, 1500);
  
  // Play happy sound
  try{
    var ac2=new(window.AudioContext||window.webkitAudioContext)();
    var freqs = task.cat==='namaz' ? [523,659,784,1047] : [440,554,659,880];
    freqs.forEach(function(f,i){
      var o=ac2.createOscillator(),g=ac2.createGain();
      o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,ac2.currentTime+i*.12);
      g.gain.linearRampToValueAtTime(.12,ac2.currentTime+i*.12+.08);
      g.gain.exponentialRampToValueAtTime(.001,ac2.currentTime+i*.12+.4);
      o.connect(g); g.connect(ac2.destination);
      o.start(ac2.currentTime+i*.12); o.stop(ac2.currentTime+i*.12+.5);
    });
  }catch(e){}
  
  // Show mini toast
  _themeToast(task.icon+' '+task.name+' — +'+task.xp+' XP!');
}

