      name+', bist du bereit? Los gehts!',
      'Schoen dich zu sehen, '+name+'!'
    ];
    setTimeout(function(){ showOkiBubble(deGreets[Math.floor(Math.random()*deGreets.length)]); },800);
    return;
  }
  var hour = new Date().getHours();
  var timeGreet = hour<12?'Günaydın':(hour<18?'İyi günler':'İyi akşamlar');
  var greets = [
