function okiRandomReminder(){
  var done = getTodayTasks ? getTodayTasks() : {};
  var name = playerName || 'Kahraman';
  var hour = new Date().getHours();
  
  
  if(evValuesOn()) {
    var valueMsgs=[name+', lass uns etwas Neues entdecken!','Schoen, dass du da bist, '+name+'!','Heute ist ein guter Tag zum Lernen.'];
    showOkiBubble(valueMsgs[Math.floor(Math.random()*valueMsgs.length)]);
    return;
  }
// Namaz hatırlatma
  var namazMap = {5:'namaz1',12:'namaz2',15:'namaz3',18:'namaz4',20:'namaz5'};
  var namazNames = {5:'Sabah',12:'Öğle',15:'İkindi',18:'Akşam',20:'Yatsı'};
  for(var h in namazMap){
    if(Math.abs(hour-parseInt(h))<=1 && !done[namazMap[h]]){
      showOkiBubble('🕌 '+name+', '+namazNames[h]+' namazi vakti! Unutma 🤲');
      return;
    }
  }
  
  // Ders hatırlatma
  if(hour>=14&&hour<=18&&!done['ders']){
    var msgs = [
      '📚 '+name+', biraz ders çalışalım mı? Beraberce! 💡',
      name+', öğle yemeğinden sonra ders vakti! Hadi başlayalım 📖',
    ];
    showOkiBubble(msgs[Math.floor(Math.random()*msgs.length)]);
    return;
  }
  
  // Genel motivasyon
  var motivs = [
    name+', seninle olmak çok güzel 🥰',
    'Bugün '+name+' ile vakit geçirmek harikaydı! ⭐',
    name+'! Sana bir sır: sen çok özel birisin 🌟',
    'Seni seviyorum '+name+'! Hep buradayım 💕',
    name+', bugün ne hissediyorsun? Ben çok mutluyum! 😊',
    'Bil bakalım '+name+'... Sen benim en iyi arkadaşımsın! 🤝',
    name+' ile büyümek çok güzel 🐣',
    'Seni gördükçe mutlu oluyorum '+name+'! 💖',
    'Haydi '+name+'! Bir odaya gidelim, eğlenelim! 🎮',
    name+', bugün ne öğrenmek istersin? 📚',
    'Şu an ne düşünüyorsun '+name+'? Ben hep buradayım! 💬',
    'Allah seni korusun '+name+'! Sen çok kıymetlisin! 🤲',
    'Oki seni çok özlüyor '+name+'! 🥰',
    name+'! Güzelsin, iyisin, çok özelsin! 🌸',
  ];
  showOkiBubble(motivs[Math.floor(Math.random()*motivs.length)]);
}

