function okiStartGameSupport(){
  _okiGameTimer && clearInterval(_okiGameTimer);
  if(evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en'&&currentRoom&&currentRoom.id==='ders'){
    _okiRoomGameMsgs.ders=[
      'Keep learning! 📚','Read, grow, discover! 💡',
      'Every question trains your brain! 🧠','You are becoming stronger! 🌟',
      'Math is fun! ➕','Science is amazing! 🔬',
      'Learning is a superpower! ✨','Great job, clever thinker! 🏆',
      'Did you open your notebook? 📝','Stay curious! 🔍',
      'Knowledge grows step by step! 📖','Learn, teach, share! 💫',
      'You can solve the hard question! 🧩'
    ];
  }
  if(evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en'&&currentRoom&&currentRoom.id==='ders'){
    _okiGameMsgs=['Amazing, _N!','Faster, _N! You can do it!','Boom! Keep going, _N!','Legendary move, _N!','Do not stop now!','More focus, more power!','You are breaking records, _N!','Great energy!'];
  }
  _okiGameMsgIdx = 0;
  _okiGameTimer = setInterval(function(){
    if(!gameActive) return;
    var r2=Math.random();
    var msg;
    if(r2<0.55) msg=_getUniqueMsg(_okiRoomGameMsgs[currentRoom?currentRoom.id:'default']||_okiRoomGameMsgs.default);
    else msg=_getUniqueMsg(_okiGameMsgs);
    showOkiBubble(msg);
    // Rastgele animasyon — her seferinde farklı
    var anim=Math.random();
    if(anim<0.35){
      setCharState('jump',1500);
      for(var _i=0;_i<3;_i++) setTimeout(_spawnSpark,_i*120);
    } else if(anim<0.6){
      setCharState('wave',1200);
    } else if(anim<0.8){
      _charScreenShake();
    } else {
      setCharState('jump',800);
    }
  }, 5000);
}

