function okiStartAutoPop(){
  _okiAutoPopTimer && clearInterval(_okiAutoPopTimer);
  _okiAutoPopTimer = setInterval(function(){
    if(!gameActive || !objs || objs.length===0) return;
    // Find a live balloon
    var live = objs.filter(function(o){ return o.alive && !o.popped && o.hx && o.hy; });
    if(live.length===0) return;
