function _getUniqueMsg(arr){
  var attempts = 0;
  var msg;
  do {
    msg = arr[Math.floor(Math.random()*arr.length)];
    attempts++;
  } while(msg === _lastOkiMsg && attempts < 8);
  _lastOkiMsg = msg;
  // Çalışma zamanında ismi yerleştir — önce _NU (büyük), sonra _N (normal)
  var pn = playerName || '';
  if(msg && pn){
    msg = msg.replace(/_NU/g, pn.toUpperCase()).replace(/_N/g, pn);
  }
  return msg;
}

