function _drawHeartMini(ts){
  var c=document.getElementById('jar-heart');
  if(!c) return;
  var ctx=c.getContext('2d'), W=c.width, H=c.height, t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var pulse=1+Math.sin(t*2)*.05;
  var cx=W/2, cy=H/2-4, s=W*.38*pulse;
  ctx.save(); ctx.translate(cx,cy); ctx.scale(s,s);
  ctx.beginPath();
  ctx.moveTo(0,.3);
  ctx.bezierCurveTo(0,-.1,-.5,-.5,-1,-.1);
  ctx.bezierCurveTo(-1.4,.3,-1,.9,0,1.4);
  ctx.bezierCurveTo(1,.9,1.4,.3,1,-.1);
  ctx.bezierCurveTo(.5,-.5,0,-.1,0,.3);
  ctx.closePath();
  var g=ctx.createRadialGradient(-.2,-.1,.1,0,.5,1.2);
  g.addColorStop(0,'rgba(255,180,180,.9)');
  g.addColorStop(.4,'rgba(220,50,80,.85)');
  g.addColorStop(1,'rgba(150,0,40,.9)');
  ctx.fillStyle=g; ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.35)';
  ctx.beginPath(); ctx.ellipse(-.35,-.25,.18,.28,-.5,0,Math.PI*2); ctx.fill();
  ctx.restore();
  // Stars
  var stars=Math.min(5,Math.floor(getTotalStars()/200)+1);
  for(var i=0;i<stars;i++){
    var ang=t*.4+i*(Math.PI*2/Math.max(stars,1));
    ctx.font='9px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.7;
    ctx.beginPath(); ctx.arc(cx+Math.cos(ang)*W*.2,cy+Math.sin(ang)*H*.14+H*.06,2.2,0,Math.PI*2); ctx.fillStyle='rgba(255,215,80,.9)'; ctx.fill();
  }
  ctx.globalAlpha=1;
}

