  ctx.clearRect(0,0,W,H);
  var cx=W/2, cy=H/2-2, r=W*.36;
  var glow=ctx.createRadialGradient(cx,cy,r*.1,cx,cy,r*1.5);
  glow.addColorStop(0,'rgba(160,80,255,.3)'); glow.addColorStop(1,'transparent');
  ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
  var sg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,r*.05,cx,cy,r);
  sg.addColorStop(0,'rgba(255,255,255,.65)');
  sg.addColorStop(.25,'rgba(180,120,255,.8)');
  sg.addColorStop(.7,'rgba(100,40,200,.9)');
  sg.addColorStop(1,'rgba(60,0,140,.95)');
  ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();
  // Stars inside
  for(var i=0;i<8;i++){
    var a=.12+.88*(.5+.5*Math.sin(t*2+i));
    ctx.beginPath(); ctx.arc(cx+Math.cos(i*1.3+t*.3)*r*.6,cy+Math.sin(i*.9+t*.4)*r*.5,1.2,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,'+a+')'; ctx.fill();
  }
  var stage=getCoinStage();
  ctx.font=Math.round(r*.65)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.globalAlpha=.85+Math.sin(t*1.5)*.1;
  ctx.fillStyle='rgba(220,185,255,.95)'; ctx.beginPath(); ctx.moveTo(cx,cy-r*.42); ctx.lineTo(cx+r*.34,cy); ctx.lineTo(cx,cy+r*.42); ctx.lineTo(cx-r*.34,cy); ctx.closePath(); ctx.fill(); ctx.globalAlpha=1;
  ctx.fillStyle='rgba(255,255,255,.2)';
  ctx.beginPath(); ctx.ellipse(cx-r*.28,cy-r*.28,r*.16,r*.1,-.5,0,Math.PI*2); ctx.fill();
}

