function _drawGoldMini(ts){
  var c=document.getElementById('jar-gold');
  if(!c) return;
  var ctx=c.getContext('2d'), W=c.width, H=c.height, t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2;
  var jx=W*.1, jy=H*.15, jw=W*.8, jh=H*.65;
  var todayPct=Math.min(1,getTodayStars()/500);
  ctx.fillStyle='rgba(0,0,0,.15)';
  ctx.beginPath(); ctx.ellipse(cx,H*.9,jw*.38,H*.035,0,0,Math.PI*2); ctx.fill();
  ctx.save();
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,6); ctx.clip();
  ctx.fillStyle='rgba(255,250,230,.08)'; ctx.fillRect(jx,jy,jw,jh);
  var fy=jy+jh*(1-todayPct), wave=Math.sin(t*1.5)*2;
  ctx.beginPath(); ctx.moveTo(jx,fy+wave);
  for(var wx=0;wx<=jw;wx+=5)
    ctx.lineTo(jx+wx,fy+Math.sin((wx/jw)*Math.PI*4+t*2)*2+wave);
  ctx.lineTo(jx+jw,jy+jh); ctx.lineTo(jx,jy+jh); ctx.closePath();
  var lg=ctx.createLinearGradient(0,fy,0,jy+jh);
  lg.addColorStop(0,'rgba(255,200,50,.95)'); lg.addColorStop(1,'rgba(200,100,0,.85)');
  ctx.fillStyle=lg; ctx.fill();
  ctx.restore();
  ctx.strokeStyle='rgba(255,215,80,.55)'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,6); ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,.25)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.moveTo(jx+5,jy+8); ctx.lineTo(jx+5,jy+jh-8); ctx.stroke();
  var lidG=ctx.createLinearGradient(0,jy-15,0,jy);
  lidG.addColorStop(0,'#FFE070'); lidG.addColorStop(1,'#CC8800');
  ctx.fillStyle=lidG;
  ctx.beginPath(); ctx.roundRect(jx-3,jy-15,jw+6,16,4); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.2)';
  ctx.beginPath(); ctx.roundRect(jx+3,jy-12,jw-6,6,2); ctx.fill();
  ctx.fillStyle='#CC8800';
  ctx.beginPath(); ctx.ellipse(cx,jy-17,6,4,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#FFD700';
  ctx.beginPath(); ctx.ellipse(cx,jy-18,4,2.5,0,0,Math.PI*2); ctx.fill();
}

