function _drawHeartBig(c,ts){
  if(!c||document.getElementById('star-ov').style.display==='none'){
    cancelAnimationFrame(_starBigAnim); return;
  }
  var ctx=c.getContext('2d'),W=c.width,H=c.height,t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var pulse=1+Math.sin(t*1.8)*.06;
  var cx=W/2,cy=H*.48,s=W*.42*pulse;
  ctx.save(); ctx.translate(cx,cy); ctx.scale(s,s);
  ctx.beginPath();
  ctx.moveTo(0,.3); ctx.bezierCurveTo(0,-.1,-.5,-.5,-1,-.1);
  ctx.bezierCurveTo(-1.4,.3,-1,.9,0,1.4);
  ctx.bezierCurveTo(1,.9,1.4,.3,1,-.1); ctx.bezierCurveTo(.5,-.5,0,-.1,0,.3);
  ctx.closePath();
  var g=ctx.createRadialGradient(-.2,-.1,.1,0,.5,1.3);
  g.addColorStop(0,'rgba(255,200,200,.95)'); g.addColorStop(.3,'rgba(220,50,80,.9)'); g.addColorStop(1,'rgba(120,0,40,.95)');
  ctx.fillStyle=g; ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.4)';
  ctx.beginPath(); ctx.ellipse(-.35,-.25,.2,.3,-.5,0,Math.PI*2); ctx.fill();
  ctx.restore();
  // Orbiting stars
  var n=Math.min(8,Math.floor(getTotalStars()/100)+1);
  for(var i=0;i<n;i++){
    var ang=t*.5+i*(Math.PI*2/Math.max(n,1));
    ctx.font='16px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.7+Math.sin(t*2+i)*.3;
    ctx.beginPath(); ctx.arc(cx+Math.cos(ang)*W*.2,cy+Math.sin(ang)*H*.14+H*.06,2.2,0,Math.PI*2); ctx.fillStyle='rgba(255,215,80,.9)'; ctx.fill();
  }
  ctx.globalAlpha=1;
}

