function showCrystalJar(){
  var crystalOpenTarget=document.getElementById('crystal-ov');
  if(!crystalOpenTarget) return;
  crystalOpenTarget.style.display='block';
  if(evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='tr'){
    crystalOpenTarget.removeAttribute('dir');
    crystalOpenTarget.setAttribute('lang','tr');
    var crystalBoxTr=crystalOpenTarget.firstElementChild;
    if(crystalBoxTr&&crystalBoxTr.children&&crystalBoxTr.children[1]) crystalBoxTr.children[1].textContent='Mutluluk Paraları';
    if(crystalBoxTr&&crystalBoxTr.children&&crystalBoxTr.children[2]) crystalBoxTr.children[2].textContent='Oki bu paralarla büyür';
    var rewardBoxTr=document.getElementById('crystal-stage-box');
    rewardBoxTr=rewardBoxTr&&rewardBoxTr.nextElementSibling;
    if(rewardBoxTr&&rewardBoxTr.children&&rewardBoxTr.children[0]) rewardBoxTr.children[0].textContent='Ebeveyn bunu gerçek bir ödüle çevirebilir';
    if(rewardBoxTr&&rewardBoxTr.children&&rewardBoxTr.children[1]) rewardBoxTr.children[1].textContent='10 para = 1 ödül hakkı';
    var closeTr=crystalOpenTarget.querySelector('button');
    if(closeTr) closeTr.textContent='Kapat';
  }
  if(evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en'){
    var crystalOvEn=document.getElementById('crystal-ov');
