function _drawCrystalBig(c,ts){
  if(!c||document.getElementById('crystal-ov').style.display==='none'){
    cancelAnimationFrame(_crystalBigAnim); return;
  }
  var ctx=c.getContext('2d'),W=c.width,H=c.height,t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2,cy=H*.5,r=W*.42;
  var glow=ctx.createRadialGradient(cx,cy,r*.1,cx,cy,r*1.6);
  glow.addColorStop(0,'rgba(160,80,255,.35)'); glow.addColorStop(1,'transparent');
  ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
  var sg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,r*.05,cx,cy,r);
  sg.addColorStop(0,'rgba(255,255,255,.7)'); sg.addColorStop(.25,'rgba(180,120,255,.85)');
  sg.addColorStop(.7,'rgba(100,40,200,.92)'); sg.addColorStop(1,'rgba(60,0,140,.98)');
  ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();
  // Nebula
  ctx.save(); ctx.globalCompositeOperation='screen';
  [[.25,.25,'rgba(200,100,255,.25)'],[.7,.65,'rgba(100,200,255,.18)'],[.4,.7,'rgba(255,150,200,.18)']].forEach(function(n){
    var ng=ctx.createRadialGradient(cx+r*(n[0]-.5)*1.5,cy+r*(n[1]-.5)*1.5,0,cx+r*(n[0]-.5)*1.5,cy+r*(n[1]-.5)*1.5,r*.45);
    ng.addColorStop(0,n[2]); ng.addColorStop(1,'transparent');
    ctx.fillStyle=ng; ctx.fillRect(0,0,W,H);
  });
  ctx.restore();
  // Stars
  for(var i=0;i<16;i++){
    var a=.15+.85*(.5+.5*Math.sin(t*2+i));
    ctx.beginPath(); ctx.arc(cx+Math.cos(i*1.3+t*.3)*r*.65,cy+Math.sin(i*.9+t*.4)*r*.55,1.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,'+a+')'; ctx.fill();
  }
  // Floating coins
  var coins=Math.min(8,getCoins());
  for(var j=0;j<coins;j++){
    var ca=t*.4+j*(Math.PI*2/Math.max(coins,1));
    var cr=r*(j%2===0?.45:.3);
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.65; ctx.fillStyle='rgba(255,215,80,.9)'; ctx.beginPath(); ctx.arc(cx+Math.cos(ca)*cr,cy+Math.sin(ca)*cr,5,0,Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha=1;
  // Oki
  var stage=getCoinStage();
  ctx.font=Math.round(r*.75)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.globalAlpha=.9+Math.sin(t*1.5)*.1;
  ctx.fillStyle='rgba(220,185,255,.95)'; ctx.beginPath(); ctx.moveTo(cx,cy-r*.42); ctx.lineTo(cx+r*.34,cy); ctx.lineTo(cx,cy+r*.42); ctx.lineTo(cx-r*.34,cy); ctx.closePath(); ctx.fill(); ctx.globalAlpha=1;
  // Shine
  ctx.fillStyle='rgba(255,255,255,.22)';
  ctx.beginPath(); ctx.ellipse(cx-r*.28,cy-r*.28,r*.18,r*.12,-.5,0,Math.PI*2); ctx.fill();
  // Base
  ctx.fillStyle='rgba(100,50,200,.3)';
  ctx.beginPath(); ctx.ellipse(cx,cy+r+6,r*.45,r*.09,0,0,Math.PI*2); ctx.fill();
}

