function _updateCrystalOverlay(){
  var coins=getCoins(), stage=getCoinStage();
  var arJar=evArabicActive();
  var deJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='de';
  var enJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en';
  var ce=document.getElementById('crystal-count'); if(ce) ce.textContent=arJar?(coins+' '+evAr('coins')):(deJar?(coins+' Muenzen'):(enJar?(coins+' coins'):(coins+' '+evJarText('coins'))));
  var idx=OKI_COIN_STAGES.indexOf(stage), next=OKI_COIN_STAGES[idx+1];
  var arStageNames=[evAr('egg'),evAr('baby'),evAr('child'),evAr('young'),evAr('big'),evAr('angel')];
  var deStageNames=['Ei','Baby','Klein','Jung','Gross','Engel'];
  var enStageNames=['Egg','Baby','Little','Young','Big','Angel'];
  var trStageNames=['Yumurta Oki','Bebek Oki','Küçük Oki','Genç Oki','Büyük Oki','Melek Oki'];
  var trJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='tr';
  var sn=document.getElementById('crystal-stage'); if(sn) sn.textContent=arJar?(stage.emoji+' '+(arStageNames[idx]||stage.name)):(deJar?(stage.emoji+' '+(deStageNames[idx]||stage.name)):(enJar?(stage.emoji+' '+(enStageNames[idx]||stage.name)):(trJar?(stage.emoji+' '+(trStageNames[idx]||stage.name)):stage.name)));
  var pct=next?((coins-stage.min)/(next.min-stage.min))*100:100;
  var bar=document.getElementById('crystal-bar'); if(bar) bar.style.width=Math.min(100,pct)+'%';
  var nt=document.getElementById('crystal-next');
  if(nt) nt.textContent=arJar?(next?('\u0628\u0627\u0642\u064A '+(next.min-coins)+' \u0646\u0642\u0648\u062F \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 '+(arStageNames[idx+1]||next.name)):evAr('maxLevel')):(deJar?(next?((next.min-coins)+' Muenzen bis '+(deStageNames[idx+1]||next.name)):'Maximales Level!'):(enJar?(next?((next.min-coins)+' more coins to '+(enStageNames[idx+1]||next.name)):'Maximum level!'):(trJar?(next?((next.min-coins)+' para daha → '+(trStageNames[idx+1]||next.name)):'Maksimum seviye!'):(next?(next.min-coins)+' '+evJarText('moreCoins')+' -> '+next.name:evJarText('max')))));
}

