function _drawGoldBig(c,ts){
  if(!c||document.getElementById('daily-ov').style.display==='none'){
    cancelAnimationFrame(_goldBigAnim); return;
  }
  var ctx=c.getContext('2d'),W=c.width,H=c.height,t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2, jx=W*.08, jy=H*.14, jw=W*.84, jh=H*.67;
  var pct=Math.min(1,getTodayStars()/500);
  ctx.fillStyle='rgba(0,0,0,.15)';
  ctx.beginPath(); ctx.ellipse(cx,H*.92,jw*.38,H*.035,0,0,Math.PI*2); ctx.fill();
  ctx.save(); ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,8); ctx.clip();
  ctx.fillStyle='rgba(255,250,230,.06)'; ctx.fillRect(jx,jy,jw,jh);
  var fy=jy+jh*(1-pct), wave=Math.sin(t*1.5)*3;
  ctx.beginPath(); ctx.moveTo(jx,fy+wave);
  for(var wx=0;wx<=jw;wx+=6)
    ctx.lineTo(jx+wx,fy+Math.sin((wx/jw)*Math.PI*4+t*2)*3+wave);
  ctx.lineTo(jx+jw,jy+jh); ctx.lineTo(jx,jy+jh); ctx.closePath();
  var lg=ctx.createLinearGradient(0,fy,0,jy+jh);
  lg.addColorStop(0,'rgba(255,210,50,.98)'); lg.addColorStop(.5,'rgba(255,160,20,.92)'); lg.addColorStop(1,'rgba(180,80,0,.88)');
  ctx.fillStyle=lg; ctx.fill();
  // Floating emojis
  ['🪙','⭐','💫','🪙','⭐'].forEach(function(ico,i){
    var fx=jx+jw*(.15+i*.18), fy2=fy+10+Math.sin(t*1.2+i)*10+(jh-(fy-jy))*(.2+i*.08);
    if(fy2>jy+jh-6) return;
    ctx.font='13px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.75; ctx.fillText(ico,fx,fy2); ctx.globalAlpha=1;
  });
  ctx.restore();
  ctx.strokeStyle='rgba(255,215,80,.6)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,8); ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,.28)'; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(jx+6,jy+10); ctx.lineTo(jx+6,jy+jh-10); ctx.stroke();
  var lidG=ctx.createLinearGradient(0,jy-20,0,jy-2);
  lidG.addColorStop(0,'#FFE570'); lidG.addColorStop(.5,'#FFBE20'); lidG.addColorStop(1,'#BB7700');
  ctx.fillStyle=lidG; ctx.beginPath(); ctx.roundRect(jx-5,jy-20,jw+10,22,5); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.28)';
  ctx.beginPath(); ctx.roundRect(jx+4,jy-17,jw-8,8,3); ctx.fill();
  ctx.fillStyle='#AA7700';
  ctx.beginPath(); ctx.ellipse(cx,jy-23,9,5.5,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#FFD700';
  ctx.beginPath(); ctx.ellipse(cx,jy-24,6,3.5,0,0,Math.PI*2); ctx.fill();
  ctx.font=Math.round(W*.18)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('🐣',cx,jy-H*.08);
}

