function trackDailyStars(){
  var now=getTotalStars();
  if(now>_prevTotal){
    var gained=now-_prevTotal;
    saveTodayStars(getTodayStars()+gained);
    // Check coin milestone
    var oldCoins=Math.floor(_prevTotal/100);
    var newCoins=Math.floor(now/100);
    if(newCoins>oldCoins){
      _onNewCoin(newCoins);
    }
    _prevTotal=now;
  }
}

