function _onNewCoin(coins){
  // Check stage up
  var levels=[0,10,30,60,100,150];
  var stageNames=['Yumurta','Bebek','Kucuk','Genc','Buyuk','Melek'];
  var stageEmojis=['🥚','🐣','🐥','🐦','✨','👼'];
  var curStage=0;
  levels.forEach(function(l,i){ if(coins>=l) curStage=i; });
  if(curStage>_prevCoinStage){
    _prevCoinStage=curStage;
    // Level up!
    showOkiBubble('Buyudum! Artik '+stageNames[curStage]+' '+stageEmojis[curStage]+' oldum! 🎉');
    _okiDanceIfExists();
    // Auto outfit
    updateOkiByCoins();
  }
}

