function _dropCoin(x, y){
  if(!gameActive){ return; } // Oyun bitmişse coin uçurma
  var icons = ['🪙','⭐','💰','🪙','⭐','🪙'];
  var n = Math.random()<0.3 ? 3 : 2;
  for(var i=0;i<n;i++){
    (function(delay, ico){
      setTimeout(function(){
        if(!gameActive) return; // gecikme sırasında oyun bittiyse çık
        var el = document.createElement('div');
        el.textContent = ico;
        el.className = '_gf'; // game float — temizlik için
        // Başlangıç: ekranın ÜSTÜNDE rastgele X
        var startX = (x||window.innerWidth/2) + (Math.random()-0.5)*80;
        // Bitiş: ekranın ALTINDAki kavanoz bölgesine
        var jarX = window.innerWidth/2 + (Math.random()-0.5)*60;
        var jarY = window.innerHeight - 55;
        el.style.cssText =
          'position:fixed;'+
          'left:'+startX+'px;'+
          'top:-40px;'+
          'font-size:2rem;'+
          'z-index:9999;'+
          'pointer-events:none;'+
          'text-shadow:0 3px 12px rgba(0,0,0,.6);'+
          'transition:none;';
        evGameLayer().appendChild(el);

        // 1. Adım: üstten ortaya hızlıca düş (0.6sn)
        requestAnimationFrame(function(){
          requestAnimationFrame(function(){
            if(!el.parentNode) return;
            el.style.transition =
              'left 0.6s ease-in, top 0.6s cubic-bezier(.2,0,.8,1), font-size 0.6s ease';
            el.style.top = (window.innerHeight*0.4)+'px';
            el.style.left = startX+'px';
            el.style.fontSize = '2.4rem';
          });
        });

        // 2. Adım: ortadan kavanoza git (0.7sn sonra)
        setTimeout(function(){
          if(!el.parentNode) return;
          el.style.transition =
            'left 0.65s ease-in, top 0.65s cubic-bezier(.4,0,1,1), font-size 0.65s ease-in, opacity 0.65s ease-in';
          el.style.left = jarX+'px';
          el.style.top  = jarY+'px';
          el.style.fontSize = '0.5rem';
          el.style.opacity  = '0';
        }, 700);

        // Temizle + kavanoz güncelle
        setTimeout(function(){
          if(el.parentNode) el.remove();
          trackDailyStars();
        }, 1400);
      }, delay);
    })(i*200, icons[Math.floor(Math.random()*icons.length)]);
  }
}

