function _spawnFallingCoin(){
  if(!gameActive){ return; } // Oyun bitmişse para düşürme
  var icons = ['🪙','🪙','⭐','🪙','💰'];
  var ico = icons[Math.floor(Math.random()*icons.length)];
  var startX = 30 + Math.random()*(window.innerWidth-60);
  var dur = 2.5 + Math.random()*1.5; // düşme süresi

  var el = document.createElement('div');
  el.textContent = ico;
  el.className = '_gf'; // game float — temizlik için
  el.style.cssText =
    'position:fixed;left:'+startX+'px;top:-50px;'+
    'font-size:2rem;z-index:9999;pointer-events:none;'+
    'text-shadow:0 3px 10px rgba(0,0,0,.5);'+
    'transition:top '+dur+'s linear, opacity '+dur+'s ease-in;';
  evGameLayer().appendChild(el);

  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      if(!el.parentNode) return;
      el.style.top = (window.innerHeight+10)+'px';
      el.style.opacity = '0.15';
    });
  });

  // Para yere değince kavanoza gir
  setTimeout(function(){
    if(!el.parentNode) return; // element zaten temizlendiyse
    // Kavanoza uç animasyonu
    var jarX = window.innerWidth/2;
    var jarY = window.innerHeight - 55;
    el.style.transition = 'left .4s ease-in, top .4s ease-in, font-size .4s, opacity .4s';
    el.style.left = jarX+'px';
    el.style.top  = jarY+'px';
    el.style.fontSize = '0.4rem';
    el.style.opacity = '1';
    setTimeout(function(){
      el.remove();
      // Kavanoza ekle
      _coinRainCount++;
      _updateRainCounter();
      trackDailyStars();
      // Kavanoz titreşimi
      var jh = document.getElementById('jar-gold');
      if(jh){ jh.style.transform='scale(1.2)'; setTimeout(function(){jh.style.transform='scale(1)';},200); }
    }, 420);
  }, dur*1000);
}

