function _renderShop(){
  var coins = getCoins();
  var wardrobe = getWardrobe();
  var wearing = getWearing();

  // Bakiye
  var bal = document.getElementById('shop-balance');
  if(bal) bal.textContent = coins+' 🪙';

  // Üzerinde ne var
  var wearEl = document.getElementById('shop-wearing');
  if(wearEl){
    var parts = Object.values(wearing).filter(Boolean);
    wearEl.textContent = parts.length ? parts.map(function(id){
      var it=SHOP_ITEMS.find(function(i){return i.id===id;});
      return it?it.emoji:'';
    }).join(' ') : 'Henüz yok';
  }

  // Kategori butonları
  var cats=['Tümü','Başlık','Kıyafet','Aksesuar','Sırt','Kostüm'];
  var catsEl=document.getElementById('shop-cats');
  if(catsEl){
    catsEl.innerHTML='';
    cats.forEach(function(cat){
      var btn=document.createElement('button');
      btn.textContent=evShopCatLabel(cat);
      btn.style.cssText='padding:5px 14px;border-radius:20px;font-size:.75rem;cursor:pointer;backdrop-filter:blur(8px);font-family:Nunito;font-weight:700;'+
        'border:1px solid rgba(100,180,255,'+(cat===_shopCat?'.7':'.2')+');'+
        'background:'+(cat===_shopCat?'rgba(30,60,150,.6)':'rgba(10,20,60,.4)')+';'+
        'color:'+(cat===_shopCat?'#88CCFF':'rgba(150,200,255,.55)')+';'+
        'box-shadow:'+(cat===_shopCat?'0 0 12px rgba(80,150,255,.3)':'none')+';';
      btn.onclick=(function(c){return function(){ _shopCat=c; _renderShop(); };})(cat);
      catsEl.appendChild(btn);
    });
  }

  // Ürünler
  var itemsEl=document.getElementById('shop-items');
  if(!itemsEl) return;
  itemsEl.innerHTML='';

  var filtered=SHOP_ITEMS.filter(function(it){
    return _shopCat==='Tümü'||it.cat===_shopCat;
  });

  filtered.forEach(function(item){
    var owned=!!wardrobe[item.id];
    var isWearing=Object.values(wearing).indexOf(item.id)>=0;
    var canAfford=coins>=item.price;

    var div=document.createElement('div');
    div.style.cssText='background:'+(isWearing?'rgba(30,60,150,.5)':'rgba(10,20,60,.4)')+';'+
      'border:1.5px solid rgba(100,180,255,'+(isWearing?'.6':owned?'.2':'.1')+');'+
      'border-radius:16px;padding:12px;text-align:center;position:relative;'+
      'box-shadow:'+(isWearing?'0 0 16px rgba(80,150,255,.3)':'none')+';backdrop-filter:blur(4px);';
    if(isWearing) div.style.borderColor='rgba(255,215,0,.5)';

    var badge=isWearing?'<div style="position:absolute;top:6px;right:6px;font-size:.6rem;background:rgba(255,215,0,.2);color:#FFD700;border-radius:8px;padding:2px 6px;">'+evShopWearingLabel()+'</div>':
      owned?'<div style="position:absolute;top:6px;right:6px;font-size:.6rem;color:rgba(100,255,100,.7);">✅</div>':'';

    div.innerHTML=badge+
      '<div style="font-size:2.2rem;margin-bottom:4px;">'+item.emoji+'</div>'+
      '<div style="font-family:Fredoka One;font-size:.85rem;color:#E8C8FF;margin-bottom:2px;">'+evShopRoomItemText(item,'name')+'</div>'+
      '<div style="font-size:.65rem;color:rgba(255,255,255,.35);margin-bottom:8px;">'+evShopRoomItemText(item,'desc')+'</div>'+
      '<button id="shop-btn-'+item.id+'" style="width:100%;padding:6px;border-radius:10px;font-size:.78rem;cursor:pointer;'+
      'border:1px solid rgba(255,215,0,.3);font-family:Nunito;font-weight:700;'+
      'background:'+(isWearing?'rgba(255,215,0,.2)':owned?'rgba(100,255,100,.1)':canAfford?'rgba(255,215,0,.1)':'rgba(100,100,100,.1)')+';'+
      'color:'+(isWearing?'#FFD700':owned?'#66FF88':canAfford?'#FFD700':'rgba(255,255,255,.3)')+';'+
      'cursor:'+(isWearing||(!owned&&!canAfford)?'default':'pointer')+';">'+
      ((evValuesOn()&&evValuesLang()==='de')?(isWearing?'Ausziehen':owned?'Anziehen':'💰 '+item.price+' 🪙'):(isWearing?'\u00C7\u0131kar':owned?'Giy':'💰 '+item.price+' 🪙'))+'</button>';

    // Buton tıklama
    div.querySelector('button').onclick=(function(it, ow, iw){
      return function(){
        if(iw){ okiRemoveItem(it); }
        else if(ow){ okiWearItem(it); }
        else if(getCoins()>=it.price){ okiBuyItem(it); }
        else{ var name2=playerName||'canım';
        showOkiBubble(_shopMsg(SHOP_CANT_AFFORD(item))); }
      };
    })(item, owned, isWearing);

    itemsEl.appendChild(div);
  });
}

