function initNsStars(){
  var c=document.getElementById('ns-stars');
  if(!c) return;
  c.width=window.innerWidth; c.height=window.innerHeight;
  var ctx=c.getContext('2d');
  var stars=[];
  for(var i=0;i<180;i++){
    stars.push({
      x:Math.random()*c.width, y:Math.random()*c.height,
      r:.5+Math.random()*2, a:Math.random(), da:.005+Math.random()*.01,
      col:Math.random()<.3?'#FFD700':Math.random()<.5?'#88CCFF':'#ffffff'
    });
  }
  // Shooting stars
  var shoots=[];
  function addShoot(){
    shoots.push({x:Math.random()*c.width,y:0,vx:3+Math.random()*4,vy:2+Math.random()*3,life:1});
    setTimeout(addShoot,1500+Math.random()*2000);
  }
  addShoot();
  
  function draw(){
    if(!document.getElementById('ns')||document.getElementById('ns').style.display==='none') return;
    ctx.clearRect(0,0,c.width,c.height);
    // Stars
    stars.forEach(function(s){
      s.a+=s.da; if(s.a>1||s.a<0) s.da*=-1;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle=s.col; ctx.globalAlpha=s.a*.9; ctx.fill();
    });
    // Shooting stars
    shoots.forEach(function(s,i){
      ctx.beginPath(); ctx.moveTo(s.x,s.y); ctx.lineTo(s.x-s.vx*8,s.y-s.vy*8);
      ctx.strokeStyle='rgba(255,220,150,'+s.life+')'; ctx.lineWidth=1.5; ctx.stroke();
      s.x+=s.vx; s.y+=s.vy; s.life-=.02;
      if(s.life<0||s.x>c.width) shoots.splice(i,1);
    });
    ctx.globalAlpha=1;
    requestAnimationFrame(draw);
  }
  draw();
}

