function initShopStars(){
  var c=document.getElementById('shop-stars-c');
  if(!c) return;
  var ov=document.getElementById('shop-ov');
  if(ov) ov.style.background='linear-gradient(180deg,#000510 0%,#020820 30%,#050d30 60%,#0a0520 100%)';
  c.width=window.innerWidth; c.height=window.innerHeight;
  var ctx=c.getContext('2d');
  var stars=[];
  for(var i=0;i<200;i++){
    stars.push({
      x:Math.random()*c.width, y:Math.random()*c.height,
      r:.3+Math.random()*1.8, a:Math.random(),
      da:.003+Math.random()*.008,
      col:Math.random()<.25?'#FFD700':Math.random()<.4?'#88CCFF':'rgba(255,255,255,'
    });
  }
  var nebulas=[
    {x:.2,y:.3,r:120,col:'rgba(80,40,200,'},
    {x:.8,y:.6,r:100,col:'rgba(40,80,200,'},
    {x:.5,y:.8,r:80, col:'rgba(120,40,160,'},
  ];
  function draw(){
    if(!document.getElementById('shop-ov')||document.getElementById('shop-ov').style.display==='none') return;
    ctx.clearRect(0,0,c.width,c.height);
    // Nebula
    nebulas.forEach(function(n){
      var ng=ctx.createRadialGradient(n.x*c.width,n.y*c.height,0,n.x*c.width,n.y*c.height,n.r);
      ng.addColorStop(0,n.col+'.08)'); ng.addColorStop(1,'transparent');
      ctx.fillStyle=ng; ctx.fillRect(0,0,c.width,c.height);
    });
    // Stars
    stars.forEach(function(s){
      s.a+=s.da; if(s.a>1||s.a<0) s.da*=-1;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle=s.col.startsWith('rgba')?s.col:s.col+s.a+')';
      ctx.globalAlpha=s.col.startsWith('rgba')?s.a:.9;
      ctx.fill();
    });
    ctx.globalAlpha=1;
    requestAnimationFrame(draw);
  }
  draw();
}

