        y: Math.random()*c.height*0.4,
        vx: 4+Math.random()*6,
        vy: 2+Math.random()*4,
        life: 1, trail: 12+Math.random()*18
      });
      setTimeout(addShoot, 1200+Math.random()*2500);
    }
  }
  setTimeout(addShoot, 800);
  
  // Nebula blob'ları
  var nebulas = [
    {x:0.1, y:0.2, r:160, col:'rgba(80,30,180,'},
    {x:0.9, y:0.7, r:140, col:'rgba(30,60,180,'},
    {x:0.5, y:0.5, r:120, col:'rgba(100,20,150,'},
    {x:0.2, y:0.8, r:100, col:'rgba(20,80,160,'},
  ];
  
  function draw(ts){
    var hm = document.getElementById('hm');
    if(!hm || hm.style.display==='none'){
      cancelAnimationFrame(_hmSpaceAnim);
      _hmSpaceAnim=null;
      return;
    }
    ctx.clearRect(0,0,c.width,c.height);
    
    // Nebula
    nebulas.forEach(function(n){
      var g=ctx.createRadialGradient(n.x*c.width,n.y*c.height,0,n.x*c.width,n.y*c.height,n.r);
      g.addColorStop(0,n.col+'0.06)');
      g.addColorStop(1,'transparent');
      ctx.fillStyle=g; ctx.fillRect(0,0,c.width,c.height);
    });
    
