    stars.forEach(function(s){
      s.a += s.da;
      if(s.a>1||s.a<0) s.da*=-1;
      s.y -= s.speed;
      if(s.y < 0) s.y = c.height;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle = s.col;
      ctx.globalAlpha = s.a*0.9;
      ctx.fill();
    });
    
    // Kayan yıldızlar
    shoots.forEach(function(s,i){
      ctx.strokeStyle='rgba(255,220,150,'+s.life+')';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(s.x,s.y);
      ctx.lineTo(s.x-s.vx*s.trail/4, s.y-s.vy*s.trail/4);
      ctx.stroke();
      s.x+=s.vx; s.y+=s.vy; s.life-=0.025;
      if(s.life<=0) shoots.splice(i,1);
    });
    
    // EduVerse yüzen yazılar
    eduTexts.forEach(function(e){
      e.x += e.vx;
      e.y += e.vy;
      if(e.y < -40) { e.y = c.height+20; e.x = Math.random()*c.width; }
      if(e.x < -80 || e.x > c.width+80){ e.vx *= -1; }
      ctx.save();
      ctx.translate(e.x, e.y);
      ctx.rotate(e.rot);
      ctx.globalAlpha = e.alpha;
      ctx.fillStyle = e.col;
      ctx.font = 'bold '+Math.round(e.size)+'px "Fredoka One", Arial Black';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(e.text, 0, 0);
      ctx.restore();
    });
    
    ctx.globalAlpha = 1;
    _hmSpaceAnim = requestAnimationFrame(draw);
  }
  
  _hmSpaceAnim = requestAnimationFrame(draw);
}

