function setCharState(state, durationMs){
  _charState = state;
  var _stage = typeof getCurrentStage==='function' ? getCurrentStage() : null;
  var _stageSet = _stage&&_stage.charSet;
  var _key = _selectedChar==='kiz'
    ? (_stageSet ? (_stageSet==='erkek_agac'?'kiz_agac':'kiz_fidan') : 'kiz')
    : (_stageSet || 'erkek');
  var imgs = _CHARS[_key] || _CHARS[_selectedChar] || _CHARS.erkek;
  var src  = imgs[state] || imgs['idle'];
  // ana ekran
  var el = document.getElementById('char-main-img');
  if(el){ el.src = src; _applyStateAnim(el, state); }
  // oyun içi
  var gel = document.getElementById('char-game-img');
  if(gel){ gel.src = src; }
  // auto-return to idle
  if(_charStateTimer){ clearTimeout(_charStateTimer); _charStateTimer=null; }
  if(state !== 'idle' && state !== 'sleep'){
    _charStateTimer = setTimeout(function(){ setCharState('idle'); }, durationMs||2500);
  }
}

