text:
function _applyStateAnim(el, state){
  el.style.animation = 'none';
  el.style.transform = '';
  el.style.filter    = '';
  setTimeout(function(){
    if(state==='idle')  el.style.animation = 'charFloat 3s ease-in-out infinite';
    if(state==='wave')  el.style.animation = 'charWave 0.5s ease-in-out 4, charFloat 3s ease-in-out 2s infinite';
    if(state==='jump')  el.style.animation = 'charJump 0.4s ease-out 3, charFloat 3s ease-in-out 1.2s infinite';
    if(state==='eat')   el.style.animation = 'charBounce 0.5s ease-in-out 3, charFloat 3s ease-in-out 1.5s infinite';
    if(state==='sleep') el.style.animation = 'charSway 2s ease-in-out infinite';
    if(state==='sad')   el.style.animation = 'charSad 1s ease-in-out 2, charFloat 3s ease-in-out 2s infinite';
  }, 10);
}

