function _spawnSpark(){
  var wrap=document.querySelector('#char-main-img')?.parentElement;
  if(!wrap) return;
  var sp=document.createElement('div');
  var emojis=['✨','⭐','💫','🌟','✦'];
  sp.textContent=emojis[Math.floor(Math.random()*emojis.length)];
  var angle=Math.random()*Math.PI*2;
  var r=55+Math.random()*20;
  sp.style.cssText='position:absolute;font-size:'+(10+Math.random()*8)+'px;'+
    'left:calc(50% + '+Math.cos(angle)*r+'px);'+
    'top:calc(50% + '+Math.sin(angle)*r+'px);'+
    'transform:translate(-50%,-50%);pointer-events:none;z-index:10;'+
    'animation:charSpark '+(0.8+Math.random()*0.6)+'s ease forwards;';
  wrap.appendChild(sp);
  setTimeout(function(){sp.remove();},1500);
}

