function shopSwitchChar(c){
  _shopRoomChar=c;
  var imgs=_CHARS[c==='edu'?'erkek':'kiz'];
  var el=document.getElementById('shop-char-img');
  if(el) el.src=imgs.idle;
  var nm=document.getElementById('shop-char-name');
  if(nm) nm.textContent=c==='edu'?'🌱 Edu':'🌸 Verse';
  ['edu','verse'].forEach(function(t){
    var btn=document.getElementById('shop-btn-'+t);
    if(!btn) return;
    var sel=t===c;
    btn.style.background=sel?'rgba(255,255,255,.12)':'rgba(255,255,255,.04)';
    btn.style.borderColor=sel?(t==='edu'?'rgba(100,255,100,.5)':'rgba(255,100,200,.5)'):'rgba(255,255,255,.1)';
  });
  shopUpdateWearing();
  shopRenderItems();
}

