function shopStartEffect(item){
  shopStopEffect();
  _fxActive = true;
  var cfg = FX_CONFIG[item.cat] || FX_CONFIG.Doga;

  // Center icon + label + item name
  var icon = document.getElementById('shop-fx-icon');
  var lbl  = document.getElementById('shop-fx-label');
  var nm   = document.getElementById('shop-fx-name');
  if(icon){
    icon.textContent = item.emoji;
    icon.style.opacity='.2';
    setTimeout(function(){icon.style.opacity='.55';icon.style.fontSize='5rem';
      setTimeout(function(){icon.style.fontSize='4.5rem';},300);},50);
  }
  if(nm)   nm.textContent   = evShopRoomItemText(item,'name');
  var enFxLabels = {Doga:'Nature spirit!',Kahraman:'Hero spirit!',Sihirbaz:'Magic time!',Uzay:'To the galaxy!',Akvaryum:'Art and sea!',Sampion:'Champion!',Tumu:'Select an item!'};
  if(lbl)  lbl.textContent  = evShopRoomIsAr()?(SHOP_ROOM_AR_FX[item.cat]||SHOP_ROOM_AR_FX.Tumu):((evValuesOn()&&evValuesLang()==='en')?(enFxLabels[item.cat]||enFxLabels.Tumu):cfg.label);

  // Stage background
  var stage = document.getElementById('shop-effect-stage');
  if(stage){
    stage.style.background = cfg.bg;
    stage.style.borderColor = cfg.glow.replace('.5',',.4').replace('rgba','rgba');
    stage.style.boxShadow = 'inset 0 0 30px ' + cfg.glow + ', 0 0 20px ' + cfg.glow;
  }

  // Glow rengi karaktere
  var charImg = document.getElementById('shop-char-img');
  if(charImg){
    charImg.style.filter = 'drop-shadow(0 0 18px '+cfg.glow+') drop-shadow(0 4px 12px rgba(0,0,0,.3))';
    charImg.style.animation = 'shopBounce .4s ease 3, shopFloat 3s ease-in-out 1.2s infinite';
    setTimeout(function(){
      if(charImg) charImg.style.animation = 'shopFloat 3s ease-in-out infinite';
    }, 2500);
  }

  // Glow halkası rengi
  var glow = document.getElementById('shop-char-glow');
  if(glow) glow.style.background = 'radial-gradient(circle,'+cfg.glow.replace('.5','.25')+',transparent 70%)';

  // Canvas efekti başlat
  _startFxCanvas(cfg);

  // Emoji yağmuru
  _fxTimer = setInterval(function(){
    if(!_fxActive) return;
    _spawnFxEmoji(cfg.emojis);
  }, 280);
}

