function _startFxCanvas(cfg){
  var canvas = document.getElementById('shop-fx-canvas');
  if(!canvas) return;
  var stage = document.getElementById('shop-effect-stage');
  canvas.width  = stage ? stage.offsetWidth  : 180;
  canvas.height = stage ? stage.offsetHeight : 150;
  var ctx = canvas.getContext('2d');
  var particles = [];
  var W = canvas.width, H = canvas.height;

  // Parçacık sistemi
  for(var i=0;i<18;i++){
    particles.push({
      x: Math.random()*W, y: Math.random()*H,
      vx:(Math.random()-.5)*1.2, vy:-(Math.random()*1.5+.3),
      size: 2+Math.random()*4, life:1, dec:.008+Math.random()*.006,
      col: cfg.trail,
    });
  }

  // Akvaryum için balık pozisyonları
  var fishList = [];
  if(cfg.icon==='🐠'){
    for(var fi=0;fi<6;fi++) fishList.push({
      x:Math.random()*W, y:20+Math.random()*(H-40),
      vx:(Math.random()>.5?1:-1)*(0.4+Math.random()*.6),
      emoji:['🐠','🐟','🐡','🦈'][Math.floor(Math.random()*4)],
      size:12+Math.random()*10, wave:Math.random()*Math.PI*2
    });
  }
  function draw(){
    if(!_fxActive){ ctx.clearRect(0,0,W,H); return; }
    ctx.clearRect(0,0,W,H);

    // Dönen halka
    var t = Date.now()*.001;
    var cx=W/2, cy=H/2, r=Math.min(W,H)*.35;
    for(var j=0;j<8;j++){
      var ang = t*1.2 + j*(Math.PI*2/8);
      var px = cx+Math.cos(ang)*r, py = cy+Math.sin(ang)*r*.7;
      var g = ctx.createRadialGradient(px,py,0,px,py,8);
      g.addColorStop(0, cfg.trail);
      g.addColorStop(1,'transparent');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(px,py,8,0,Math.PI*2); ctx.fill();
    }

    // İkinci halka tersi
    for(var j2=0;j2<5;j2++){
      var ang2 = -t*.8 + j2*(Math.PI*2/5);
      var px2=cx+Math.cos(ang2)*r*.55, py2=cy+Math.sin(ang2)*r*.45;
      ctx.fillStyle=cfg.glow.replace('.5','.6');
      ctx.beginPath(); ctx.arc(px2,py2,5,0,Math.PI*2); ctx.fill();
    }

    // Parçacıklar
    particles.forEach(function(p){
      p.x+=p.vx; p.y+=p.vy; p.life-=p.dec;
      if(p.life<=0){ p.x=Math.random()*W; p.y=H+5; p.life=1; p.vy=-(Math.random()*1.5+.3); }
      ctx.globalAlpha = p.life * .7;
      ctx.fillStyle = p.col;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2); ctx.fill();
    });

    // Balık animasyonu (akvaryum)
    if(cfg.icon==='🐠' && fishList.length){
      var t2=Date.now()*.001;
      ctx.font='20px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      fishList.forEach(function(fish){
        fish.x += fish.vx;
        fish.y += Math.sin(t2*1.2+fish.wave)*0.4;
        if(fish.x > W+20) fish.x=-20;
        if(fish.x < -20) fish.x=W+20;
        ctx.globalAlpha=0.85;
        ctx.save();
        if(fish.vx < 0){ ctx.scale(-1,1); ctx.fillText(fish.emoji,-fish.x,fish.y); }
        else { ctx.fillText(fish.emoji,fish.x,fish.y); }
        ctx.restore();
        // Baloncuklar
        if(Math.random()<.04){
          ctx.globalAlpha=0.4; ctx.strokeStyle='#88CCFF'; ctx.lineWidth=1.2;
          ctx.beginPath(); ctx.arc(fish.x,fish.y-8,2+Math.random()*4,0,Math.PI*2); ctx.stroke();
        }
      });
    }
    ctx.globalAlpha=1;
    _fxRaf = requestAnimationFrame(draw);
  }
  draw();
}

