          ctx.globalAlpha=0.4; ctx.strokeStyle='#88CCFF'; ctx.lineWidth=1.2;
          ctx.beginPath(); ctx.arc(fish.x,fish.y-8,2+Math.random()*4,0,Math.PI*2); ctx.stroke();
        }
      });
    }
    ctx.globalAlpha=1;
    _fxRaf = requestAnimationFrame(draw);
  }

