function _spawnFxEmoji(emojis){
  var div = document.getElementById('shop-fx-emojis');
  var stage = document.getElementById('shop-effect-stage');
  if(!div||!stage) return;
  var W=stage.offsetWidth, H=stage.offsetHeight;
  var sp=document.createElement('div');
  var emoji=emojis[Math.floor(Math.random()*emojis.length)];
  var size=14+Math.random()*16;
  var startX=Math.random()*W;
  var endX=startX+(Math.random()-.5)*60;
  sp.textContent=emoji;
  sp.style.cssText='position:absolute;font-size:'+size+'px;'+
    'left:'+startX+'px;top:'+(H+10)+'px;'+
    'pointer-events:none;'+
    'transition:all 1.8s ease-out;opacity:1;';
  div.appendChild(sp);
  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      sp.style.top=(-size-10)+'px';
      sp.style.left=endX+'px';
      sp.style.opacity='0';
    });
  });
  setTimeout(function(){ if(sp.parentElement) sp.remove(); },2000);
}

