function playShopSound(cat){
  try{
    var ac = new(window.AudioContext||window.webkitAudioContext)();
    var patterns = {
      Doga:     [[523,.1],[659,.1],[784,.15],[1047,.2]],       // Do Mi Sol Do - huzurlu
      Kahraman: [[220,.05],[277,.05],[330,.05],[440,.15],[330,.05],[440,.2]], // güçlü
      Sihirbaz: [[800,.05],[1000,.05],[900,.05],[1200,.1],[600,.15]], // büyülü tınlama
      Uzay:     [[200,.1],[400,.05],[600,.05],[800,.1],[400,.15]],    // uzay synth
      Akvaryum: [[1046,.08],[1318,.08],[1568,.08],[2093,.12],[1568,.2]], // su damlaları
      Sampion:  [[523,.05],[659,.05],[784,.05],[1047,.05],[1318,.15],[1047,.1]], // zafer
      Tumu:     [[523,.1],[659,.15]],
    };
    var pattern = patterns[cat] || patterns.Tumu;
    var t = ac.currentTime;
    pattern.forEach(function(note, i){
      var o = ac.createOscillator();
      var g = ac.createGain();
      var wave = (cat==='Uzay'||cat==='Sihirbaz') ? 'sine' : (cat==='Kahraman'?'sawtooth':'triangle');
      o.type = wave;
      o.frequency.value = note[0];
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(.12, t+.02);
      g.gain.exponentialRampToValueAtTime(.001, t+note[1]+.1);
      o.connect(g); g.connect(ac.destination);
      var delay = pattern.slice(0,i).reduce(function(s,n){ return s+n[1]; },0);
      o.start(t+delay);
      o.stop(t+delay+note[1]+.15);
    });
  }catch(e){}
}

