function shopSetPose(pose, durationMs){
  var charKey = _shopRoomChar==='edu' ? 'erkek' : 'kiz';
  var imgs = _CHARS[charKey];
  var src = imgs[pose] || imgs['idle'];
  var img = document.getElementById('shop-char-img');
  if(!img) return;
  img.src = src;
  // Bounce animasyonu
  img.style.animation = 'shopBounce .4s ease, shopFloat 3s ease-in-out 1s infinite';
  // Timer ile idle'a dön
  if(_shopPoseTimer) clearTimeout(_shopPoseTimer);
  _shopPoseTimer = setTimeout(function(){
    var idleSrc = (_CHARS[charKey]||{}).idle;
    if(img && idleSrc) img.src = idleSrc;
    img.style.animation = 'shopFloat 3s ease-in-out infinite';
  }, durationMs || 2500);
}

