function shopRenderSplit(){
  var left  = document.getElementById('shop-left');
  var right = document.getElementById('shop-right');
  if(!left||!right) return;
  left.innerHTML=''; right.innerHTML='';

  var coins = (typeof getRealCoins==='function')?getRealCoins():((typeof getCoins==='function')?getCoins():0);
  var list  = _shopRoomCat==='Tumu'?SHOP_ROOM_ITEMS:SHOP_ROOM_ITEMS.filter(function(i){return i.cat===_shopRoomCat;});
  var w     = _shopRoomWearing[_shopRoomChar]||[];

  list.forEach(function(item, idx){
    var owned = _shopRoomOwned.indexOf(item.id)>=0;
    var worn  = w.indexOf(item.id)>=0;
    var canBuy= coins>=item.price;

    var card = document.createElement('div');
    card.style.cssText =
      'background:rgba(10,20,60,'+(worn?'.8':'.5')+');'+
      'border:1.5px solid rgba('+(worn?'255,215,0,.6':owned?'100,255,100,.3':'100,180,255,.12')+');'+
      'border-radius:14px;padding:8px 4px;text-align:center;cursor:pointer;transition:all .2s;'+
      'box-shadow:'+(worn?'0 0 14px rgba(255,215,0,.3)':'none')+';'+
      'position:relative;';

    var badge = worn?
      '<div style="position:absolute;top:3px;right:3px;font-size:.48rem;background:rgba(255,215,0,.2);color:#FFD700;padding:1px 4px;border-radius:5px;">✅</div>':
      owned?'<div style="position:absolute;top:3px;right:3px;font-size:.48rem;background:rgba(100,255,100,.15);color:#88FF88;padding:1px 4px;border-radius:5px;">✓</div>':'';

    var btnTxt = evShopRoomIsAr()?(worn?evShopRoomUi('takeOff'):owned?evShopRoomUi('wear'):(item.price+' '+evShopRoomUi('coins'))):((evValuesOn()&&evValuesLang()==='en')?(worn?'Take off':owned?'Wear':('Coins: '+item.price)):((evValuesOn()&&evValuesLang()==='de')?(worn?'Ausziehen':owned?'Anziehen':('🪙'+item.price)):(worn?'\u00C7\u0131kar':owned?'Giy':('🪙'+item.price))));
    var btnCol = worn?'#FFD700':owned?'#88FF88':canBuy?'#FFD700':'rgba(255,255,255,.3)';

    card.innerHTML = badge +
      '<div style="font-size:1.8rem;margin-bottom:3px;">'+item.emoji+'</div>'+
      '<div style="font-family:Fredoka One;font-size:.6rem;color:#E8C8FF;margin-bottom:4px;line-height:1.2;">'+evShopRoomItemText(item,'name')+'</div>'+ 
      '<button style="width:100%;padding:3px 2px;border-radius:8px;font-size:.6rem;font-weight:700;font-family:Nunito;cursor:pointer;'+
        'border:1px solid rgba(255,215,0,.25);background:rgba(255,215,0,.08);color:'+btnCol+';'+
        ((!owned&&!canBuy)?'opacity:.4;':'')+'">'+btnTxt+'</button>';

    card.querySelector('button').addEventListener('click', function(){ shopItemAction(item.id); });

    // Sol/Sağ dağıtım
    if(idx%2===0) left.appendChild(card);
    else right.appendChild(card);
  });

  shopUpdateWearing();
}

