function updateGrowthUI(){
  var stage = getCurrentStage();
  var progress = getStageProgress();
  var stars = getTotalStars();
  // Aşamaya göre karakter resmi güncelle
  var _gCharSet = stage.charSet;
  var _gKey = _selectedChar==='kiz'
    ? (_gCharSet ? (_gCharSet==='erkek_agac'?'kiz_agac':'kiz_fidan') : 'kiz')
    : (_gCharSet || 'erkek');
  var _gImgs = _CHARS[_gKey] || _CHARS[_selectedChar] || _CHARS.erkek;
  var _gMi = document.getElementById('char-main-img');
  var _gGi = document.getElementById('char-game-img');
  if(_gMi && _gMi.src !== (_gImgs.idle||'')) _gMi.src = _gImgs.idle||'';
  if(_gGi && _gGi.src !== (_gImgs.idle||'')) _gGi.src = _gImgs.idle||'';

  // Ana ekran karakter boyutu
  var img = document.getElementById('char-main-img');
  if(img){
    img.style.width  = Math.round(120 * stage.scale) + 'px';
    img.style.height = Math.round(140 * stage.scale) + 'px';
  }

  // Büyüme bar güncelle
  var bar = document.getElementById('growth-bar-fill');
  if(bar) bar.style.width = progress + '%';
  var barLabel = document.getElementById('growth-bar-label');
  if(barLabel){
    var next = GROWTH_STAGES.find(function(s){ return s.minStars > stars; });
    if(typeof evValuesOn==='function' && evValuesOn() && typeof evValuesLang==='function' && evValuesLang()==='ar'){
      barLabel.textContent = next ? ('بذرة أوكي: بقي '+(next.minStars - stars)+' نجمة') : 'المستوى الأقصى!';
    } else if(typeof evValuesOn==='function' && evValuesOn() && typeof evValuesLang==='function' && evValuesLang()==='en'){
      barLabel.textContent = next ? (evEnglishOkiStageName(stage)+' -> '+(next.minStars - stars)+' stars left') : 'Maximum level!';
    } else if(!(typeof evValuesOn==='function' && evValuesOn())){
      var trStageNames={tohum:'Tohum Oki',fidan:'Fidan Oki',agac:'A\u011fa\u00e7 Oki',cicek:'\u00c7i\u00e7ek Oki',yildiz:'Y\u0131ld\u0131z Oki'};
      barLabel.textContent = next ? ((trStageNames[stage.id]||'Oki')+' -> '+(next.minStars - stars)+' y\u0131ld\u0131z kald\u0131') : 'Maksimum seviye!';
    } else {
      barLabel.textContent = next ? (stage.name+' -> '+(next.minStars - stars)+' stars left') : 'Maximum level!';
    }
  }

  // Aşama emojisi
  var stageEl = document.getElementById('growth-stage-emoji');
  if(stageEl) stageEl.textContent = stage.emoji;

  // Oki name badge
  var nm = document.getElementById('oki-name');
  if(nm && nm.textContent){
    nm.style.color = stage.color;
  }
}

