function checkAndUpdateStreak(){
  var data = getStreakData();
  var today = getTodayKey();
  var yesterday = getYesterdayKey();

  if(data.lastDay === today){
    // Bugün zaten kontrol edildi
    return data;
  }

  if(data.lastDay === yesterday){
    // Dün açmış - seri devam
    data.count = (data.count||0) + 1;
  } else if(!data.lastDay){
    // İlk gün
    data.count = 1;
  } else {
    // Seri koptu
    data.broke = data.count || 0;
    data.count = 1;
  }

  data.lastDay = today;
  data.best = Math.max(data.count, data.best||0);
  saveStreakData(data);
  return data;
}

