function evV47CFixStreakDayRow(){
  try{
    var ov=document.getElementById('streak-ov');
    if(!ov) return;

    // Kart içindeki haftalık gün satırını bul.
    var cal=document.getElementById('streak-cal') || document.getElementById('streak-days');
    if(!cal) return;

    cal.setAttribute('translate','no');
    cal.style.display='flex';
    cal.style.justifyContent='center';
    cal.style.alignItems='center';
    cal.style.gap='6px';
    cal.style.flexWrap='nowrap';
    cal.style.maxWidth='100%';
    cal.style.width='100%';
    cal.style.margin='14px auto 12px';
    cal.style.overflow='visible';

    var tr=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];
    var en=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
    var de=['Mo','Di','Mi','Do','Fr','Sa','So'];
    var fr=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];
    var ar=['إث','ثل','أر','خم','جم','سب','أح'];

    var lang=(ov.getAttribute('lang')||'tr').toLowerCase();
    var days=tr;
    if(lang.indexOf('en')===0) days=en;
    else if(lang.indexOf('de')===0) days=de;
    else if(lang.indexOf('fr')===0) days=fr;
    else if(lang.indexOf('ar')===0 || ov.getAttribute('dir')==='rtl') days=ar;

    var dots=cal.children;
    for(var i=0;i<dots.length;i++){
      var d=dots[i];
      d.setAttribute('translate','no');
      d.style.width='34px';
      d.style.minWidth='34px';
      d.style.maxWidth='34px';
      d.style.height='34px';
      d.style.minHeight='34px';
      d.style.borderRadius='50%';
      d.style.display='flex';
      d.style.alignItems='center';
      d.style.justifyContent='center';
      d.style.boxSizing='border-box';
      d.style.fontFamily='Fredoka One, Nunito, system-ui, sans-serif';
      d.style.fontSize='.56rem';
      d.style.fontWeight='900';
      d.style.lineHeight='1';
      d.style.letterSpacing='-0.04em';
      d.style.whiteSpace='nowrap';
      d.style.overflow='hidden';
      d.style.textAlign='center';
      d.style.padding='0';
      d.style.margin='0';

      // Ateş olan gün ateş kalsın, yazılı günler kısa kalsın.
      var txt=(d.textContent||'').trim();
      if(txt !== '🔥'){
        d.textContent = days[i%7];
      }
    }

    // Kartı ekranda taşmayacak şekilde ortala ve üstteki ateş çemberine yer aç.
    var card = ov.querySelector('.streak-card') || ov.querySelector('[id*="streak-card"]') || ov.firstElementChild;
    if(card){
      card.style.maxWidth='min(430px,92vw)';
      card.style.width='min(430px,92vw)';
      card.style.margin='auto';
      card.style.boxSizing='border-box';
      card.style.overflow='visible';
    }

    // Çok büyük elips ateş başlığın üstünü eziyorsa biraz yukarı değil, merkeze çek.
    var orbit=document.getElementById('streak-flame-orbit');
    if(orbit){
      orbit.style.pointerEvents='none';
      orbit.style.overflow='visible';
    }
  }catch(e){}
}

