function evV47FFullScreenFireCleanup(){
  try{
    var ov=document.getElementById('streak-ov');
    if(!ov) return;

    ov.style.position='fixed';
    ov.style.inset='0';
    ov.style.overflow='hidden';
    ov.style.background='radial-gradient(circle at 50% 78%, rgba(255,185,35,.42) 0%, rgba(255,95,0,.28) 24%, rgba(85,16,0,.18) 52%, rgba(28,5,0,.96) 100%), radial-gradient(circle at 9% 58%, rgba(255,95,0,.32) 0%, rgba(255,70,0,.16) 34%, rgba(255,40,0,0) 64%), radial-gradient(circle at 91% 56%, rgba(255,95,0,.32) 0%, rgba(255,70,0,.16) 34%, rgba(255,40,0,0) 64%), linear-gradient(180deg, #210300 0%, #3b0700 42%, #821d00 76%, #f08a00 100%)';

    // Sadece arka plan canvas'ı overlay'in en arkasına alınır.
    // Öndeki kart, 5 gün yazısı, ateş çemberi, gün yuvarlakları ve metinler değiştirilmez.
    var c=document.getElementById('streak-fire-c');
    if(c){
      if(c.parentNode!==ov){
        try{ c.parentNode.removeChild(c); }catch(e){}
        ov.insertBefore(c,ov.firstChild);
      }
      c.style.position='fixed';
      c.style.inset='0';
      c.style.width='100vw';
      c.style.height='100vh';
      c.style.pointerEvents='none';
      c.style.zIndex='1';
      c.style.mixBlendMode='screen';
    }

    var bg=document.getElementById('streak-fire-premium-bg');
    if(bg && bg.parentNode!==ov){
      try{ bg.parentNode.removeChild(bg); }catch(e){}
      ov.insertBefore(bg,ov.firstChild);
    }

    Array.prototype.forEach.call(ov.children,function(el){
      if(el.id!=='streak-fire-c' && el.id!=='streak-fire-premium-bg'){
        el.style.position = el.style.position || 'relative';
        el.style.zIndex = '5';
      }
    });

    if(typeof evV47CFixStreakDayRow==='function') evV47CFixStreakDayRow();
  }catch(e){}
}

