function evV47S8ApplyStreakTexts(data,broke){
  try{
    var ov=document.getElementById('streak-ov'); if(!ov) return;
    var p=evV47S8StreakPack(data||getStreakData(),broke);
    ov.setAttribute('lang',p.lang);
    ov.setAttribute('dir',p.dir);
    ov.setAttribute('translate','no');
    evV47S8SetText('streak-title',p.title);
    evV47S8SetText('streak-best',p.best);
    evV47S8SetText('streak-msg-ov',p.msg);
    var goalLabel=document.getElementById('streak-goal-label');
    var goalTxt=document.getElementById('streak-goal-txt');
    if(goalLabel){ goalLabel.setAttribute('translate','no'); }
    if(goalTxt){ goalTxt.setAttribute('translate','no'); goalTxt.textContent=p.goal; }
    if(goalLabel && goalTxt){
      while(goalLabel.firstChild && goalLabel.firstChild!==goalTxt){ goalLabel.removeChild(goalLabel.firstChild); }
      goalLabel.insertBefore(document.createTextNode(p.goalLabel), goalTxt);
    }
    evV47S8SetText('streak-continue-btn',p.btn);
    var cal=document.getElementById('streak-cal');
    if(cal){
      cal.setAttribute('translate','no');
      Array.prototype.forEach.call(cal.children,function(d,i){
        d.setAttribute('translate','no');
        if((d.textContent||'').trim()!=='🔥') d.textContent=p.days[i%7];
      });
    }
  }catch(e){}
}

