function showStreakOverlay(){
  var data = checkAndUpdateStreak();
  var ov = document.getElementById('streak-ov');
  if(!ov) return;
  var broke = data.broke && data.broke > 1;
  var p = evV47S8StreakPack(data,broke);

  ov.setAttribute('lang',p.lang);
  ov.setAttribute('dir',p.dir);
  ov.setAttribute('translate','no');

  // Sayaç animasyonlu artış
  var countEl = document.getElementById('streak-count');
  if(countEl){
    countEl.setAttribute('translate','no');
    countEl.style.animation = 'none';
    countEl.textContent = '0';
    void countEl.offsetWidth;
    countEl.style.animation = 'streakCountPop .6s cubic-bezier(.34,1.56,.64,1)';
    var _stTarget = data.count, _stCur = 0, _stStep = Math.max(1, Math.floor(_stTarget/12));
    var _stTimer = setInterval(function(){
      _stCur = Math.min(_stCur + _stStep, _stTarget);
      countEl.textContent = _stCur;
      if(_stCur >= _stTarget){ clearInterval(_stTimer); }
    }, 60);
  }

  // Hedef çubuğu
  var _goalBar = document.getElementById('streak-goal-bar');
  if(_goalBar){
    var _goalPct = Math.min(100, Math.round((data.count/5)*100));
    _goalBar.style.width='0%';
    setTimeout(function(){ _goalBar.style.width = _goalPct + '%'; }, 400);
  }

  // Fire canvas
  _startStreakFire();

  // Emoji
  var emoji = '🔥';
  if(data.count >= 30) emoji = '🌟';
  else if(data.count >= 14) emoji = '🏆';
  else if(data.count >= 7)  emoji = '👑';
  else if(data.count >= 5)  emoji = '🔥🔥🔥';
  else if(data.count >= 3)  emoji = '🔥🔥';
  var em=document.getElementById('streak-emoji');
  if(em){ em.textContent = emoji; em.setAttribute('translate','no'); }

  // 7 günlük mini takvim
  var cal = document.getElementById('streak-cal');
  if(cal){
    cal.innerHTML = '';
    cal.setAttribute('translate','no');
    for(var i=6; i>=0; i--){
      var done = i === 0 ? true : (data.count > i);
      var dot = document.createElement('div');
      dot.setAttribute('translate','no');
      dot.style.cssText = 'width:34px;height:34px;min-width:34px;max-width:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;box-sizing:border-box;overflow:hidden;white-space:nowrap;line-height:1;letter-spacing:-.04em;padding:0;margin:0;'+
        'font-size:.7rem;font-weight:700;font-family:Fredoka One;'+
        (done ? 'background:linear-gradient(135deg,#FF6600,#FFD700);color:#fff;box-shadow:0 0 10px rgba(255,150,0,.5);' :
                'background:rgba(255,255,255,.1);color:rgba(255,255,255,.3);');
      dot.textContent = done ? '🔥' : p.days[(6-i)%7];
      cal.appendChild(dot);
    }
  }

  evV47S8ApplyStreakTexts(data,broke);
  ov.style.display = 'flex';

  // Ödül ver
  giveStreakReward(data);
}

