function _startStreakFire(){
  var ov = document.getElementById('streak-ov');
  if(!ov) return;

  var c = document.getElementById('streak-fire-c');
  if(!c){
    c = document.createElement('canvas');
    c.id = 'streak-fire-c';
  }

  var bg = document.getElementById('streak-fire-premium-bg');
  if(!bg){
    bg = document.createElement('div');
    bg.id = 'streak-fire-premium-bg';
  }
  bg.style.cssText = 'position:fixed;inset:-6%;z-index:0;pointer-events:none;'+
    'background:'+[
      'radial-gradient(circle at 50% 86%, rgba(255,214,96,.44) 0%, rgba(255,118,0,.32) 22%, rgba(141,28,0,.22) 48%, rgba(31,4,0,.98) 100%)',
      'radial-gradient(circle at 5% 62%, rgba(255,116,0,.38) 0%, rgba(255,74,0,.20) 34%, rgba(255,30,0,0) 66%)',
      'radial-gradient(circle at 95% 60%, rgba(255,116,0,.38) 0%, rgba(255,74,0,.20) 34%, rgba(255,30,0,0) 66%)',
      'linear-gradient(180deg,#240300 0%,#3a0600 38%,#7b1700 72%,#f28b00 100%)'
    ].join(',')+';filter:saturate(1.12) contrast(1.04);';

  if(bg.parentNode !== ov){
    try{ if(bg.parentNode) bg.parentNode.removeChild(bg); }catch(e){}
    ov.insertBefore(bg, ov.firstChild);
  }
  if(c.parentNode !== ov){
    try{ if(c.parentNode) c.parentNode.removeChild(c); }catch(e){}
    ov.insertBefore(c, bg.nextSibling);
  }

  var Ww = Math.max(window.innerWidth || 0, document.documentElement.clientWidth || 0, 1280);
  var Hh = Math.max(window.innerHeight || 0, document.documentElement.clientHeight || 0, 720);
  var DPR = Math.min(1.6, window.devicePixelRatio || 1);
  c.width = Math.floor(Ww * DPR);
  c.height = Math.floor(Hh * DPR);

  c.style.position = 'fixed';
  c.style.left = '0';
  c.style.top = '0';
  c.style.width = '100vw';
  c.style.height = '100vh';
  c.style.zIndex = '1';
  c.style.pointerEvents = 'none';
  c.style.opacity = '1';
  c.style.mixBlendMode = 'screen';

  ov.style.position = 'fixed';
  ov.style.inset = '0';
  ov.style.overflow = 'hidden';
  ov.style.background = 'radial-gradient(circle at 50% 78%, rgba(255,185,35,.42) 0%, rgba(255,95,0,.28) 24%, rgba(85,16,0,.18) 52%, rgba(28,5,0,.96) 100%), radial-gradient(circle at 9% 58%, rgba(255,95,0,.32) 0%, rgba(255,70,0,.16) 34%, rgba(255,40,0,0) 64%), radial-gradient(circle at 91% 56%, rgba(255,95,0,.32) 0%, rgba(255,70,0,.16) 34%, rgba(255,40,0,0) 64%), linear-gradient(180deg, #210300 0%, #3b0700 42%, #821d00 76%, #f08a00 100%)';

  try{
    Array.prototype.forEach.call(ov.children,function(el){
      if(el.id !== 'streak-fire-c' && el.id !== 'streak-fire-premium-bg'){
        el.style.position = el.style.position || 'relative';
        el.style.zIndex = '5';
      }
    });
  }catch(e){}

  var ctx = c.getContext('2d');
  ctx.setTransform(DPR,0,0,DPR,0,0);

  var embers = [];
  var curtains = [];
  var bottomFlames = [];
  var start = performance.now();
  var maxEmbers = 760;

  function seed(){
    curtains.length = 0;
    bottomFlames.length = 0;

    // Sol / sağ / orta: perde gibi değil, bütün ekranı saran farklı derinlikte alev kütleleri.
    for(var i=0;i<96;i++){
      var edge = i < 28 ? 'L' : (i < 56 ? 'R' : 'M');
      var x;
      if(edge === 'L') x = Math.random()*Ww*.28;
      else if(edge === 'R') x = Ww*(.72 + Math.random()*.28);
      else x = Math.random()*Ww;
      curtains.push({
        x:x,
        base:Hh*(.92 + Math.random()*.10),
        w:Ww*(edge==='M' ? (.045+Math.random()*.055) : (.055+Math.random()*.075)),
        h:Hh*((edge==='M'?.22:.30) + Math.random()*(edge==='M'?.34:.46)),
        phase:Math.random()*Math.PI*2,
        speed:.42+Math.random()*1.15,
        lean:(edge==='L' ? 1 : edge==='R' ? -1 : (Math.random()-.5))*Ww*(.010+Math.random()*.030),
        hue:18+Math.random()*38,
        alpha:(edge==='M'?.16:.20)+Math.random()*.22
      });
    }

    for(var f=0; f<42; f++){
      bottomFlames.push({
        x: Ww*(f/41) + (Math.random()-.5)*Ww*.035,
        w: Ww*(.028+Math.random()*.030),
        h: Hh*(.18+Math.random()*.24),
        phase: Math.random()*Math.PI*2,
        speed: .70+Math.random()*1.40,
        hue: 18+Math.random()*34
      });
    }
  }

  function spawnEmbers(n,strong){
    n = n || 18;
    for(var i=0;i<n;i++){
      var r=Math.random(), x;
      if(r<.25) x=Math.random()*Ww*.24;
      else if(r<.50) x=Ww*(.76+Math.random()*.24);
      else x=Math.random()*Ww;
      embers.push({
        x:x,
        y:Hh + Math.random()*Hh*.18,
        vx:(Math.random()-.5)*(strong?2.8:1.35),
        vy:-(1.0+Math.random()*(strong?5.4:3.2)),
        s:(strong?10:4)+Math.random()*(strong?42:22),
        life:.56+Math.random()*.62,
        decay:(strong?.0046:.0078)+Math.random()*.006,
        hue:20+Math.random()*42,
        wob:Math.random()*Math.PI*2,
        type:Math.random()<.38?'flame':'ember'
      });
    }
    if(embers.length>maxEmbers) embers.splice(0,embers.length-maxEmbers);
  }

  function flameShape(x,base,w,h,phase,t,hue,alpha,lean){
    var sway = Math.sin(t*1.5 + phase)*w*.22 + lean*Math.sin(t*.65+phase*.7);
    var tipX = x + sway;
    var tipY = base - h*(.82 + Math.abs(Math.sin(t*.9+phase))*.20);
    var leftX = x - w*(.45 + Math.sin(t+phase)*.06);
    var rightX = x + w*(.45 + Math.cos(t*.9+phase)*.06);
    var midY = base - h*.42;

    var g = ctx.createRadialGradient(x, base-h*.10, 0, tipX, tipY+h*.18, h*.86);
    g.addColorStop(0,'hsla(48,100%,72%,'+(alpha*.95)+')');
    g.addColorStop(.18,'hsla('+(hue+12)+',100%,56%,'+(alpha*.88)+')');
    g.addColorStop(.48,'hsla('+hue+',100%,42%,'+(alpha*.46)+')');
    g.addColorStop(1,'rgba(255,25,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(leftX, base);
    ctx.bezierCurveTo(leftX-w*.38, midY, tipX-w*.20, tipY+h*.25, tipX, tipY);
    ctx.bezierCurveTo(tipX+w*.26, tipY+h*.23, rightX+w*.30, midY, rightX, base);
    ctx.closePath();
    ctx.fill();
  }

  function draw(){
    var now = performance.now();
    var t = (now-start)/1000;
    ctx.setTransform(DPR,0,0,DPR,0,0);
    ctx.clearRect(0,0,Ww,Hh);

    // Tam ekran sıcak atmosfer: üst, yanlar ve alt boş kalmaz.
    ctx.globalCompositeOperation='source-over';
    var haze = ctx.createRadialGradient(Ww*.50,Hh*.58,0,Ww*.50,Hh*.58,Math.max(Ww,Hh)*.86);
    haze.addColorStop(0,'rgba(255,130,0,.08)');
    haze.addColorStop(.44,'rgba(255,76,0,.06)');
    haze.addColorStop(1,'rgba(255,42,0,.025)');
    ctx.fillStyle=haze;
    ctx.fillRect(0,0,Ww,Hh);

    var lower = ctx.createLinearGradient(0,Hh*.18,0,Hh);
    lower.addColorStop(0,'rgba(255,70,0,.012)');
    lower.addColorStop(.38,'rgba(255,72,0,.070)');
    lower.addColorStop(.70,'rgba(255,118,0,.22)');
    lower.addColorStop(1,'rgba(255,215,70,.56)');
    ctx.fillStyle=lower;
    ctx.fillRect(0,0,Ww,Hh);

    var left = ctx.createLinearGradient(0,0,Ww*.40,0);
    left.addColorStop(0,'rgba(255,105,0,.22)');
    left.addColorStop(.52,'rgba(255,65,0,.065)');
    left.addColorStop(1,'rgba(255,30,0,0)');
    ctx.fillStyle=left; ctx.fillRect(0,0,Ww,Hh);

    var right = ctx.createLinearGradient(Ww,0,Ww*.60,0);
    right.addColorStop(0,'rgba(255,105,0,.22)');
    right.addColorStop(.52,'rgba(255,65,0,.065)');
    right.addColorStop(1,'rgba(255,30,0,0)');
    ctx.fillStyle=right; ctx.fillRect(0,0,Ww,Hh);

    ctx.globalCompositeOperation='lighter';

    // Uzak, büyük alev atmosferi.
    for(var j=0;j<curtains.length;j++){
      var q=curtains[j];
      var pulse=.78+Math.abs(Math.sin(t*q.speed+q.phase))*.42;
      flameShape(q.x + Math.sin(t*.55+q.phase)*Ww*.018, q.base, q.w*pulse, q.h*pulse, q.phase, t, q.hue, q.alpha, q.lean);
    }

    // Alt çizgi boyunca yoğun ve geniş alevler.
    for(var f=0; f<bottomFlames.length; f++){
      var b=bottomFlames[f];
      var bp=.82+Math.abs(Math.sin(t*b.speed+b.phase))*.46;
      flameShape(b.x + Math.sin(t*1.1+b.phase)*18, Hh+18, b.w*bp, b.h*bp, b.phase, t, b.hue, .32, Math.sin(b.phase)*18);
    }

    // Kartın arkasını parlatan ama kartı bozmayan geniş premium aura.
    var aura = ctx.createRadialGradient(Ww*.50,Hh*.49,0,Ww*.50,Hh*.49,Math.max(Ww,Hh)*.48);
    aura.addColorStop(0,'rgba(255,160,0,.13)');
    aura.addColorStop(.42,'rgba(255,80,0,.065)');
    aura.addColorStop(1,'rgba(255,40,0,0)');
    ctx.fillStyle=aura;
    ctx.fillRect(0,0,Ww,Hh);

    spawnEmbers(18,false);
    if(Math.random()<.10) spawnEmbers(48,true);

    for(var k=embers.length-1;k>=0;k--){
      var e=embers[k];
      e.wob += .045;
      e.x += e.vx + Math.sin(e.wob)*.92;
      e.y += e.vy;
      e.life -= e.decay;
      e.s *= .992;
      if(e.life<=0 || e.s<.8 || e.y<-100){ embers.splice(k,1); continue; }

      var eg=ctx.createRadialGradient(e.x,e.y,0,e.x,e.y,e.s);
      if(e.type==='flame'){
        eg.addColorStop(0,'rgba(255,250,165,'+Math.min(.95,e.life)+')');
        eg.addColorStop(.22,'rgba(255,172,25,'+(e.life*.78)+')');
        eg.addColorStop(.58,'rgba(255,64,0,'+(e.life*.34)+')');
        eg.addColorStop(1,'rgba(255,35,0,0)');
      }else{
        eg.addColorStop(0,'hsla('+e.hue+',100%,74%,'+e.life+')');
        eg.addColorStop(.45,'hsla('+e.hue+',100%,52%,'+(e.life*.58)+')');
        eg.addColorStop(1,'hsla('+e.hue+',100%,28%,0)');
      }
      ctx.fillStyle=eg;
      ctx.beginPath();
      ctx.arc(e.x,e.y,e.s,0,Math.PI*2);
      ctx.fill();
    }

    // Hafif sıcak tarama: siyah boşluğu kırar, premium ekran hissi verir.
    ctx.globalCompositeOperation='source-over';
    var scan = ctx.createLinearGradient(0,0,0,Hh);
    scan.addColorStop(0,'rgba(255,120,0,.025)');
    scan.addColorStop(.5,'rgba(255,180,45,.018)');
    scan.addColorStop(1,'rgba(255,240,120,.035)');
    ctx.fillStyle=scan;
    ctx.fillRect(0,0,Ww,Hh);

    _streakFireRAF = requestAnimationFrame(draw);
  }

  if(_streakFireRAF) cancelAnimationFrame(_streakFireRAF);
  seed();
  spawnEmbers(180,true);
  draw();
}

