    var g = ctx.createRadialGradient(x, base-h*.10, 0, tipX, tipY+h*.18, h*.86);
    g.addColorStop(0,'hsla(48,100%,72%,'+(alpha*.95)+')');
    g.addColorStop(.18,'hsla('+(hue+12)+',100%,56%,'+(alpha*.88)+')');
    g.addColorStop(.48,'hsla('+hue+',100%,42%,'+(alpha*.46)+')');
    g.addColorStop(1,'rgba(255,25,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(leftX, base);
    ctx.bezierCurveTo(leftX-w*.38, midY, tipX-w*.20, tipY+h*.25, tipX, tipY);
    ctx.bezierCurveTo(tipX+w*.26, tipY+h*.23, rightX+w*.30, midY, rightX, base);
    ctx.closePath();
    ctx.fill();
  }

