function draw(){
    var now = performance.now();
    var t = (now-start)/1000;
    ctx.setTransform(DPR,0,0,DPR,0,0);
    ctx.clearRect(0,0,Ww,Hh);

    // Tam ekran sıcak atmosfer: üst, yanlar ve alt boş kalmaz.
    ctx.globalCompositeOperation='source-over';
    var haze = ctx.createRadialGradient(Ww*.50,Hh*.58,0,Ww*.50,Hh*.58,Math.max(Ww,Hh)*.86);
    haze.addColorStop(0,'rgba(255,130,0,.08)');
    haze.addColorStop(.44,'rgba(255,76,0,.06)');
    haze.addColorStop(1,'rgba(255,42,0,.025)');
    ctx.fillStyle=haze;
    ctx.fillRect(0,0,Ww,Hh);

    var lower = ctx.createLinearGradient(0,Hh*.18,0,Hh);
    lower.addColorStop(0,'rgba(255,70,0,.012)');
    lower.addColorStop(.38,'rgba(255,72,0,.070)');
    lower.addColorStop(.70,'rgba(255,118,0,.22)');
    lower.addColorStop(1,'rgba(255,215,70,.56)');
    ctx.fillStyle=lower;
    ctx.fillRect(0,0,Ww,Hh);

    var left = ctx.createLinearGradient(0,0,Ww*.40,0);
    left.addColorStop(0,'rgba(255,105,0,.22)');
    left.addColorStop(.52,'rgba(255,65,0,.065)');
    left.addColorStop(1,'rgba(255,30,0,0)');
    ctx.fillStyle=left; ctx.fillRect(0,0,Ww,Hh);

    var right = ctx.createLinearGradient(Ww,0,Ww*.60,0);
    right.addColorStop(0,'rgba(255,105,0,.22)');
    right.addColorStop(.52,'rgba(255,65,0,.065)');
    right.addColorStop(1,'rgba(255,30,0,0)');
    ctx.fillStyle=right; ctx.fillRect(0,0,Ww,Hh);

    ctx.globalCompositeOperation='lighter';

    // Uzak, büyük alev atmosferi.
    for(var j=0;j<curtains.length;j++){
      var q=curtains[j];
      var pulse=.78+Math.abs(Math.sin(t*q.speed+q.phase))*.42;
      flameShape(q.x + Math.sin(t*.55+q.phase)*Ww*.018, q.base, q.w*pulse, q.h*pulse, q.phase, t, q.hue, q.alpha, q.lean);
    }

    // Alt çizgi boyunca yoğun ve geniş alevler.
    for(var f=0; f<bottomFlames.length; f++){
      var b=bottomFlames[f];
      var bp=.82+Math.abs(Math.sin(t*b.speed+b.phase))*.46;
      flameShape(b.x + Math.sin(t*1.1+b.phase)*18, Hh+18, b.w*bp, b.h*bp, b.phase, t, b.hue, .32, Math.sin(b.phase)*18);
    }

    // Kartın arkasını parlatan ama kartı bozmayan geniş premium aura.
    var aura = ctx.createRadialGradient(Ww*.50,Hh*.49,0,Ww*.50,Hh*.49,Math.max(Ww,Hh)*.48);
    aura.addColorStop(0,'rgba(255,160,0,.13)');
    aura.addColorStop(.42,'rgba(255,80,0,.065)');
    aura.addColorStop(1,'rgba(255,40,0,0)');
    ctx.fillStyle=aura;
    ctx.fillRect(0,0,Ww,Hh);

    spawnEmbers(18,false);
    if(Math.random()<.10) spawnEmbers(48,true);

    for(var k=embers.length-1;k>=0;k--){
      var e=embers[k];
      e.wob += .045;
      e.x += e.vx + Math.sin(e.wob)*.92;
      e.y += e.vy;
      e.life -= e.decay;
      e.s *= .992;
      if(e.life<=0 || e.s<.8 || e.y<-100){ embers.splice(k,1); continue; }

      var eg=ctx.createRadialGradient(e.x,e.y,0,e.x,e.y,e.s);
      if(e.type==='flame'){
        eg.addColorStop(0,'rgba(255,250,165,'+Math.min(.95,e.life)+')');
        eg.addColorStop(.22,'rgba(255,172,25,'+(e.life*.78)+')');
        eg.addColorStop(.58,'rgba(255,64,0,'+(e.life*.34)+')');
        eg.addColorStop(1,'rgba(255,35,0,0)');
      }else{
        eg.addColorStop(0,'hsla('+e.hue+',100%,74%,'+e.life+')');
        eg.addColorStop(.45,'hsla('+e.hue+',100%,52%,'+(e.life*.58)+')');
        eg.addColorStop(1,'hsla('+e.hue+',100%,28%,0)');
      }
      ctx.fillStyle=eg;
      ctx.beginPath();
      ctx.arc(e.x,e.y,e.s,0,Math.PI*2);
      ctx.fill();
    }

    // Hafif sıcak tarama: siyah boşluğu kırar, premium ekran hissi verir.
    ctx.globalCompositeOperation='source-over';
    var scan = ctx.createLinearGradient(0,0,0,Hh);
    scan.addColorStop(0,'rgba(255,120,0,.025)');
    scan.addColorStop(.5,'rgba(255,180,45,.018)');
    scan.addColorStop(1,'rgba(255,240,120,.035)');
    ctx.fillStyle=scan;
    ctx.fillRect(0,0,Ww,Hh);

    _streakFireRAF = requestAnimationFrame(draw);
  }

