function renderDiary(){
  var wrap=document.getElementById('ani-entries');
  if(!wrap) return;
  wrap.innerHTML='';
  MEMORIES.forEach(function(m,i){
    var cs=CARD_STYLES[m.color]||{bg:'rgba(100,180,255,.06)',border:'rgba(100,180,255,.2)'};
    var card=document.createElement('div');
    card.className='mcard';
    card.style.background=cs.bg;
    card.style.border='1px solid '+cs.border;
    card.style.animationDelay=(i*.12)+'s';

    var img=getAniImgSafe(m.previewImg) || getAniImg('edu_tohum');
    card.innerHTML=
      '<div class="mcard-top">'+
        '<div class="mcard-emoji">'+m.stageEmoji+'</div>'+
        '<div class="mcard-info">'+
          '<div class="mcard-title" style="color:'+m.color+'">'+m.stageName+' — '+m.charName+'</div>'+
          '<div class="mcard-date">📅 '+m.date+'</div>'+
        '</div>'+
        '<img class="mcard-char" src="'+img+'" alt="'+m.charName+'">'+
      '</div>'+
      '<div class="mcard-stats">'+
        (m.stars?'<div class="stat">⭐ '+m.stars.toLocaleString('tr')+'</div>':'')+
        (m.prayer?'<div class="stat">🕌 '+m.prayer+' namaz</div>':'')+
        (m.tasks?'<div class="stat">📋 '+m.tasks+' görev</div>':'')+
        (m.streak?'<div class="stat">\uD83D\uDD25 '+m.streak+' gün</div>':'')+
      '</div>'+
      '<div class="mcard-quote" style="border-color:'+m.color+'">💬 "'+m.quote+'"</div>'+
      '<div class="mcard-tap">▶ O ANA GİT</div>';

    card.onclick=function(){openFlashback(m);};
    wrap.appendChild(card);
  });
}

