function openFlashback(m){
  var fb=document.getElementById('ani-flashback');
  fb.style.background=m.bg;
  fb.style.display='flex';
  fb.style.animation='slideInRight .45s ease';
  setTimeout(function(){fb.style.animation='';},450);

  // Film delikleri
  ['cin-top','cin-bot'].forEach(function(id){
    var el=document.getElementById(id);
    el.innerHTML='';
    for(var i=0;i<25;i++) el.innerHTML+='<div class="cin-hole"></div>';
  });

  // Tarih
  document.getElementById('fb-date-stamp').textContent=m.dateStamp;

  // Mumlar
  var cl=document.getElementById('fb-candles');
  cl.innerHTML='';
  var cc=['#FF6B6B','#FFD700','#88FF88','#88CCFF','#FF88CC'];
  for(var i=0;i<m.candles;i++){
    cl.innerHTML+=
      '<div style="display:flex;flex-direction:column;align-items:center;">'+
        '<div class="fb-flame">\uD83D\uDD25</div>'+
        '<div class="fb-candle-body" style="background:'+cc[i%cc.length]+';"></div>'+
      '</div>';
  }

  // Başlık
  var t=document.getElementById('fb-title');
  t.textContent=m.stageName.toUpperCase()+' OLDUN!';
  t.style.color=m.color;
  t.style.textShadow='0 0 20px '+m.color;
  document.getElementById('fb-sub').textContent=m.date+' — O muhteşem gün...';

  // Dönüşüm
  var ow=document.getElementById('fb-old-wrap');
  if(m.oldImg){
    ow.style.display='';
    document.getElementById('fb-old-img').src=getAniImgSafe(m.oldImg)||'';
    document.getElementById('fb-old-lbl').textContent=m.oldLbl;
  }else{
    ow.style.display='none';
  }
  var ni=document.getElementById('fb-new-img');
  ni.src=getAniImgSafe(m.newImg)||'';
  ni.style.filter='drop-shadow(0 0 18px '+m.color+')';
  var nl=document.getElementById('fb-new-lbl');
  nl.textContent=m.newLbl;
  nl.style.color=m.color;

  // Quote
  var q=document.getElementById('fb-quote');
  q.textContent='"'+m.quote+'"';
  q.style.borderColor=m.color;

  // Chips
  var ch=document.getElementById('fb-chips');
  ch.innerHTML='';
  if(m.stars) ch.innerHTML+='<div class="fb-chip">⭐ '+m.stars.toLocaleString('tr')+'</div>';
  if(m.prayer) ch.innerHTML+='<div class="fb-chip">🕌 '+m.prayer+' namaz</div>';
  if(m.tasks) ch.innerHTML+='<div class="fb-chip">📋 '+m.tasks+' görev</div>';
  if(m.streak) ch.innerHTML+='<div class="fb-chip">\uD83D\uDD25 '+m.streak+' gün seri</div>';

  // Balonlar
  var bl=document.getElementById('fb-bals');bl.innerHTML='';
  for(var i=0;i<12;i++){
    var el=document.createElement('div');el.className='fb-bal';
    el.textContent=m.balloons[Math.floor(Math.random()*m.balloons.length)];
    el.style.cssText='left:'+Math.random()*100+'%;bottom:-5%;'+
      'animation-duration:'+(4+Math.random()*5)+'s;animation-delay:'+Math.random()*3+'s;';
    bl.appendChild(el);
  }

  // Konfeti
  var cf=document.getElementById('fb-confs');cf.innerHTML='';
  for(var i=0;i<50;i++){
    var el=document.createElement('div');el.className='fb-c';
    el.style.cssText=
      'width:'+(5+Math.random()*7)+'px;height:'+(5+Math.random()*7)+'px;'+
      'left:'+Math.random()*100+'%;border-radius:'+Math.floor(Math.random()*50)+'%;'+
      'background:'+m.confColors[Math.floor(Math.random()*m.confColors.length)]+';'+
      'animation-duration:'+(2+Math.random()*3)+'s;animation-delay:'+Math.random()*2+'s;';
    cf.appendChild(el);
  }

  // Yıldız yağmuru
  var sr=document.getElementById('fb-stars-r');sr.innerHTML='';
  for(var i=0;i<18;i++){
    var el=document.createElement('div');el.className='fb-s';
    el.textContent=m.starEmoji;
    el.style.cssText='left:'+Math.random()*100+'%;font-size:'+(1+Math.random())+'rem;'+
      'animation-duration:'+(2+Math.random()*3)+'s;animation-delay:'+Math.random()*4+'s;';
    sr.appendChild(el);
  }

  // Müzik
  try{
    var ac=new(window.AudioContext||window.webkitAudioContext)();
    var notes=[[523,.08],[659,.08],[784,.08],[1047,.1],[1318,.12],[1568,.12],[1047,.08],[1318,.08],[1568,.08],[2093,.4]];
    var t2=ac.currentTime;
    notes.forEach(function(n,i){
      var o=ac.createOscillator(),g=ac.createGain();
      o.frequency.value=n[0];o.type='triangle';
      g.gain.setValueAtTime(0,t2);g.gain.linearRampToValueAtTime(.12,t2+.02);
      g.gain.exponentialRampToValueAtTime(.001,t2+n[1]+.1);
      o.connect(g);g.connect(ac.destination);
      var d=notes.slice(0,i).reduce(function(s,x){return s+x[1];},0);
      o.start(t2+d);o.stop(t2+d+n[1]+.2);
    });
  }catch(e){}
}

