function openHikaye(){
  _hikayeState.idx = Math.floor(Math.random() * HIKAYELER.length);
  _hikayeState.phase = 'hikaye';
  _hikayeState.answered = false;
  var h = HIKAYELER[_hikayeState.idx];

  // Overlay oluştur (yoksa)
  var ov = document.getElementById('hikaye-ov');
  if(!ov){
    ov = document.createElement('div');
    ov.id = 'hikaye-ov';
    ov.style.cssText = 'position:fixed;inset:0;z-index:80;display:flex;flex-direction:column;background:linear-gradient(180deg,#05030f,#0a0520,#120830);overflow-y:auto;padding:0;';
    document.body.appendChild(ov);
  }

  ov.innerHTML =
    '<div style="position:relative;min-height:100%;display:flex;flex-direction:column;">' +
    // Geri butonu
    '<div style="padding:14px 16px 0;display:flex;justify-content:space-between;align-items:center;">' +
    '<button onclick="closeHikaye()" style="background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);border-radius:20px;padding:7px 16px;font-family:Fredoka One,sans-serif;font-size:.8rem;color:white;cursor:pointer;">← Geri</button>' +
    '<div style="font-family:Fredoka One,sans-serif;font-size:.75rem;color:rgba(180,140,255,.6);letter-spacing:2px;">✦ HİKAYE ODASI ✦</div>' +
    '<div style="width:60px;"></div></div>' +
    // İçerik
    '<div style="flex:1;padding:20px 18px 100px;max-width:500px;margin:0 auto;width:100%;">' +
    // Başlık
    '<div style="text-align:center;margin-bottom:20px;">' +
    '<div style="font-size:3rem;margin-bottom:8px;">'+h.ico+'</div>' +
    '<div style="font-family:Fredoka One,sans-serif;font-size:1.15rem;color:#FFD700;margin-bottom:4px;">'+h.baslik+'</div>' +
    '<div style="font-size:.65rem;color:rgba(180,140,255,.5);letter-spacing:1px;">'+h.kaynak+'</div></div>' +
    // Hikaye metni
    '<div style="background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:18px 16px;font-size:.85rem;color:rgba(255,255,255,.85);line-height:1.8;margin-bottom:20px;white-space:pre-line;">'+h.metin+'</div>' +
    // Soru bölümü
    '<div id="hk-soru-wrap">' +
    '<div style="font-family:Fredoka One,sans-serif;font-size:.85rem;color:#88CCFF;margin-bottom:8px;">🎯 Hikayeden Bir Soru</div>' +
    '<div style="font-size:.88rem;font-weight:800;color:rgba(255,255,255,.9);margin-bottom:12px;line-height:1.4;">'+h.soru+'</div>' +
    '<div id="hk-opts" style="display:flex;flex-direction:column;gap:8px;"></div>' +
    '<div id="hk-fb" style="font-size:.76rem;min-height:24px;margin-top:10px;font-weight:700;line-height:1.4;"></div></div>' +
    // Butonlar
    '<div style="margin-top:16px;">' +
    '<button id="hk-btn" onclick="hikayeBtn()" style="background:linear-gradient(135deg,#8844FF,#AA66FF);border:none;border-radius:24px;padding:12px 32px;font-family:Fredoka One,sans-serif;font-size:.95rem;color:white;cursor:pointer;width:100%;">Soruya Geç 🎯</button>' +
    '</div></div></div>';

  // Şıkları doldur
  var optsEl = document.getElementById('hk-opts');
  h.opts.forEach(function(opt,i){
    var btn = document.createElement('button');
    btn.style.cssText = 'background:rgba(255,255,255,.07);border:1.5px solid rgba(255,255,255,.14);border-radius:12px;padding:10px 14px;font-family:Fredoka One,sans-serif;font-size:.82rem;color:rgba(255,255,255,.8);cursor:pointer;text-align:left;transition:.18s;';
    btn.textContent = opt;
    btn.onclick = function(){ answerHikaye(i, btn); };
    optsEl.appendChild(btn);
  });

  ov.style.display = 'flex';
  evV39EnhanceHikaye();
  // Oyun ekranını gizle
  document.getElementById('gs').style.display = 'none';
}

