function hikayeBtn(){
  if(_hikayeState.phase === 'bitti'){
    // Sonraki hikaye
    _hikayeState.idx = (_hikayeState.idx + 1) % HIKAYELER.length;
    _hikayeState.phase = 'hikaye';
    _hikayeState.answered = false;
    openHikaye();
  }
}

