text:
function answerHikaye(idx, btn){
  if(_hikayeState.answered) return;
  _hikayeState.answered = true;
  var h = HIKAYELER[_hikayeState.idx];
  var allBtns = document.querySelectorAll('#hk-opts button');
  var fb = document.getElementById('hk-fb');
  var hkBtn = document.getElementById('hk-btn');

  if(idx === h.ans){
    btn.style.background = 'rgba(68,255,136,.22)';
    btn.style.borderColor = '#44FF88'; btn.style.color = '#44FF88';
    fb.innerHTML = '<span style="color:#44FF88">✅ Harika! +'+h.puan+' ⭐</span><br><span style="color:rgba(255,255,255,.5);font-size:.72rem">'+h.exp+'</span>';
    addScore(h.puan, 0, 0, '#FFD700');
    var hikayeCorrect=['Aferin! Çok akıllısın! 🌟','Büyüksün! Devam et! 🚀','Harika okuma! 📖✨','Muhteşemsin! 🏆'];
    showOkiBubble(hikayeCorrect[Math.floor(Math.random()*hikayeCorrect.length)]);
    setCharState('jump', 2000);
    for(var _hsi=0;_hsi<4;_hsi++) setTimeout(_spawnSpark,_hsi*130);
  } else {
    btn.style.background = 'rgba(255,80,80,.18)';
    btn.style.borderColor = '#FF5555'; btn.style.color = '#FF5555';
    allBtns[h.ans].style.background = 'rgba(68,255,136,.1)';
    allBtns[h.ans].style.borderColor = 'rgba(68,255,136,.4)';
    allBtns[h.ans].style.color = 'rgba(68,255,136,.8)';
    fb.innerHTML = '<span style="color:rgba(255,220,80,.85)">💡 '+h.exp+'</span>';
    var hikayeWrong=['Üzülme, tekrar oku! 📖','Hata yapmak öğrenmektir! 💪','Neredeyse! 😊','Bir sonrakinde olur! 🌈'];
    showOkiBubble(hikayeWrong[Math.floor(Math.random()*hikayeWrong.length)]);
    setCharState('sad', 2000);
  }
  _hikayeState.phase = 'bitti';
  if(hkBtn){ hkBtn.textContent = 'Sonraki Hikaye →'; }
}

