text:
function evV38StyleRefleksButtons(){
  try{
    var menu=document.getElementById('refleks-menu'); if(!menu) return;
    var cols=['#00e5ff','#ff2d75','#ffd84d','#33ff99','#8b5cff','#ff7a00','#66ddff'];
    Array.prototype.forEach.call(menu.querySelectorAll('.rmb'),function(btn,i){
      var col=cols[i%cols.length];
      btn.style.position='relative';
      btn.style.overflow='hidden';
      btn.style.width='min(460px,92vw)';
      btn.style.margin='5px 0';
      btn.style.padding='12px 14px';
      btn.style.borderRadius='18px';
      btn.style.background='linear-gradient(135deg,'+col+'24,rgba(255,255,255,.075))';
      btn.style.border='1px solid '+col+'88';
      btn.style.boxShadow='0 10px 28px rgba(0,0,0,.23), inset 0 0 22px '+col+'18';
      btn.style.backdropFilter='blur(10px)';
      btn.style.transition='transform .16s, box-shadow .16s';
      var ico=btn.querySelector('.rmb-ico');
      if(ico){
        ico.style.filter='drop-shadow(0 0 12px '+col+'99)';
        ico.style.animation='v38Pulse '+(2.4+i*.12)+'s ease-in-out infinite';
      }
      var nm=btn.querySelector('.rmb-name');
      if(nm){ nm.style.color='rgba(255,250,230,.98)'; nm.style.textShadow='0 1px 8px rgba(0,0,0,.25)'; }
      var ds=btn.querySelector('.rmb-desc');
      if(ds){ ds.style.color='rgba(190,230,255,.72)'; }
      btn.onmouseenter=function(){ btn.style.transform='translateY(-2px) scale(1.015)'; btn.style.boxShadow='0 14px 34px rgba(0,0,0,.27),0 0 24px '+col+'55'; };
      btn.onmouseleave=function(){ btn.style.transform=''; btn.style.boxShadow='0 10px 28px rgba(0,0,0,.23), inset 0 0 22px '+col+'18'; };
    });
  }catch(e){}
}

