  try{
    var p=document.createElement('div');
    p.textContent=txt||'HAZIR OL!';
    p.style.cssText='position:fixed;left:50%;top:42%;transform:translate(-50%,-50%);z-index:100000;padding:14px 20px;border-radius:24px;background:rgba(2,8,28,.86);border:1px solid rgba(0,229,255,.36);color:#fff0a8;font-family:Fredoka One;font-size:1.05rem;text-align:center;box-shadow:0 20px 70px rgba(0,0,0,.45),0 0 40px rgba(0,229,255,.22);pointer-events:none;animation:v38Ready 1.2s ease-out forwards;';
