function evV38DrawRefleksBackground(){
  try{
    if(!rCtx) return;
    var t=Date.now()*0.001;
    var g=rCtx.createRadialGradient(rW*.5,rH*.38,rH*.03,rW*.5,rH*.5,rH*.95);
    g.addColorStop(0,'#123d7a');
    g.addColorStop(.38,'#071f3d');
    g.addColorStop(.74,'#020817');
    g.addColorStop(1,'#01030a');
    rCtx.fillStyle=g; rCtx.fillRect(0,0,rW,rH);

    // hız tüneli
    rCtx.save();
    rCtx.strokeStyle='rgba(0,229,255,.11)';
    rCtx.lineWidth=1;
    for(var i=0;i<13;i++){
      var x=rW*(i/12);
      rCtx.beginPath(); rCtx.moveTo(rW*.5,rH*.50); rCtx.lineTo(x,rH); rCtx.stroke();
    }
    for(var j=0;j<9;j++){
      var rr=rH*(.08+j*.055);
      rCtx.strokeStyle=j%2?'rgba(255,45,117,.10)':'rgba(0,229,255,.12)';
      rCtx.beginPath(); rCtx.ellipse(rW*.5,rH*.50,rr*1.35,rr*.42,0,0,Math.PI*2); rCtx.stroke();
    }
    rCtx.restore();

    // hareketli çizgiler
    var cols=['rgba(0,229,255,.28)','rgba(255,45,117,.22)','rgba(255,216,77,.22)','rgba(51,255,153,.20)'];
    for(var k=0;k<26;k++){
      var y=(k*53+t*80)%rH;
      var x1=(k*97)%rW;
      rCtx.strokeStyle=cols[k%cols.length];
      rCtx.lineWidth=1+(k%3);
      rCtx.beginPath();
      rCtx.moveTo(x1,y);
      rCtx.lineTo(x1+(k%2?80:-80),y+18);
      rCtx.stroke();
    }

    // yıldızlar korunur ama rengi güçlenir
    rStars.forEach(function(s,idx){
      s.t+=s.s;
      s.a=.10+Math.abs(Math.sin(s.t))*0.50;
      rCtx.globalAlpha=s.a;
      rCtx.fillStyle=idx%3===0?'#00e5ff':(idx%3===1?'#ffd84d':'#ffffff');
      rCtx.beginPath();
      rCtx.arc(s.x,s.y,s.r,0,Math.PI*2);
      rCtx.fill();
    });
    rCtx.globalAlpha=1;

    // yan refleks panelleri
    function panel(x,side){
      rCtx.save(); rCtx.translate(x,rH*.46);
      rCtx.fillStyle='rgba(255,255,255,.045)';
      rCtx.strokeStyle=side<0?'rgba(0,229,255,.24)':'rgba(255,45,117,.24)';
      rCtx.lineWidth=1.2;
      rCtx.beginPath(); rCtx.roundRect(-rW*.045,-rH*.19,rW*.09,rH*.38,16); rCtx.fill(); rCtx.stroke();
      for(var p=0;p<5;p++){
        rCtx.fillStyle=(side<0?'#00e5ff':'#ff2d75');
        rCtx.globalAlpha=.30+.45*Math.abs(Math.sin(t*2+p));
        rCtx.beginPath(); rCtx.arc(0,-rH*.12+p*rH*.06,Math.min(rW,rH)*.006,0,Math.PI*2); rCtx.fill();
      }
      rCtx.globalAlpha=1;
      rCtx.restore();
    }
    panel(rW*.05,-1); panel(rW*.95,1);
  }catch(e){}
}

