  rTemizle(); // Önceki modun tüm timer ve objelerini temizle
  rInit();
  rMod=m;rSkor=0;rSure=60;rObjs=[];rParts=[];rHayvan=null;rHayvanHiz=4.5;
  rSiraObjs=[];rSiraBeklenen=0;_rCommentCount=0;
  document.getElementById('refleks-menu').style.display='none';
  document.getElementById('refleks-hud').style.display='flex';
  document.getElementById('refleks-bitis').style.display='none';
  document.getElementById('refleks-talimat').style.display='none';
  document.getElementById('refleks-sira-wrap').style.display='none';
  document.getElementById('refleks-sira-wrap').innerHTML='';
  // Oyun modunda canvas dokunmaları aktif
  var gc2=document.getElementById('refleks-gc');
  if(gc2){gc2.style.pointerEvents='auto';}
  evV38EnhanceRefleks();
  evV38RefleksReadyFX('HAZIR OL!');
  document.getElementById('rh-skor').textContent='0';
  document.getElementById('rh-sure').textContent='60';
  document.getElementById('rh-sure').style.color='#FF6B6B';
  document.getElementById('refleks-pb').style.width='100%';
  document.getElementById('rh-mod').textContent=(evValuesOn()&&evValuesLang()==='en'?{isik:'Light',renk:'Color',hayvan:'Target',sira:'Sequence',kaybolan:'Disappearing',bomba:'Bomb',buyuk:'Biggest'}:(evValuesOn()&&evValuesLang()==='de'?{isik:'Licht',renk:'Farbe',hayvan:'Ziel',sira:'Reihenfolge',kaybolan:'Verschwindend',bomba:'Bombe',buyuk:'Groesster'}:{isik:'Light',renk:'Color',hayvan:'Target',sira:'Sequence',kaybolan:'Disappearing',bomba:'Bomb',buyuk:'Biggest'}))[m];

  if(m==='renk')rRenkBasla();
  else if(m==='hayvan')rHayvanBasla();
  else if(m==='sira')rSiraBasla();
  else if(m==='kaybolan')rKaybolanBasla();
  else if(m==='bomba')rBombaBasla();
  else if(m==='buyuk')rBuyukBasla();
  else rIsikBasla();

  rSureInt=setInterval(function(){
    rSure--;
    document.getElementById('rh-sure').textContent=rSure;
    document.getElementById('refleks-pb').style.width=(rSure/60*100)+'%';
    if(rSure<=10)document.getElementById('rh-sure').style.color='#FF3333';
    if(rSure<=0){clearInterval(rSureInt);rBitis();}
  },1000);

  rGc.ontouchstart=function(e){e.preventDefault();Array.from(e.changedTouches).forEach(function(t){rDokunma(t.clientX,t.clientY);});};
  rGc.onmousedown=function(e){rDokunma(e.clientX,e.clientY);};
  rAnimId=requestAnimationFrame(rLoop);
}

