function rDaireCiz(o){
  if(!o.alive)return;
  o.scale=Math.min(1,(o.scale||0)+.15);o.puls=(o.puls||0)+.08;
  var r=o.r*o.scale;
  rCtx.save();rCtx.translate(o.x,o.y);
  var gl=rCtx.createRadialGradient(0,0,0,0,0,r*2.5);
  gl.addColorStop(0,o.col+'33');gl.addColorStop(1,'transparent');
  rCtx.fillStyle=gl;rCtx.fillRect(-r*2.5,-r*2.5,r*5,r*5);
  var bg=rCtx.createRadialGradient(-r*.3,-r*.3,r*.08,0,0,r);
  bg.addColorStop(0,'rgba(255,255,255,.35)');bg.addColorStop(.35,o.col);bg.addColorStop(1,o.col+'99');
  rCtx.fillStyle=bg;rCtx.beginPath();rCtx.arc(0,0,r,0,Math.PI*2);rCtx.fill();
  if(o.maxLife){var ratio=o.life/o.maxLife;rCtx.strokeStyle='rgba(255,255,255,.2)';rCtx.lineWidth=3;rCtx.beginPath();rCtx.arc(0,0,r+5,-Math.PI/2,-Math.PI/2+ratio*Math.PI*2);rCtx.stroke();}
  if(o.label){rCtx.font='bold '+Math.round(r*.65)+'px Fredoka One,sans-serif';rCtx.fillStyle='rgba(255,255,255,.9)';rCtx.textAlign='center';rCtx.textBaseline='middle';rCtx.fillText(o.label,0,0);}
  if(o.emoji){rCtx.font=Math.round(r*1.2)+'px serif';rCtx.textAlign='center';rCtx.textBaseline='middle';rCtx.fillText(o.emoji,0,0);}
  rCtx.restore();
}

