function rPatlat(x,y,col,dogru,isBomba){
  var c=dogru?col:'#FF3333';
  var pcnt=isBomba?28:14;
  for(var i=0;i<pcnt;i++){
    var a=Math.random()*Math.PI*2,s=(isBomba?5:3)+Math.random()*(isBomba?10:7);
    rParts.push({x:x,y:y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,r:(isBomba?4:3)+Math.random()*(isBomba?7:5),al:1,col:isBomba?(['#FF8800','#FF4400','#FFDD00','#FF6600'][Math.floor(Math.random()*4)]):c});
  }
  try{
    var ac=new(window.AudioContext||window.webkitAudioContext)();
    if(isBomba&&dogru){
      // Bomba patlaması — derin boom + crackle
      var buf=ac.createBuffer(1,ac.sampleRate*.5,ac.sampleRate);
      var d=buf.getChannelData(0);
      for(var i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,1.5);
      var src=ac.createBufferSource(),g0=ac.createGain();
      var lf=ac.createBiquadFilter();lf.type='lowpass';lf.frequency.value=180;
      src.buffer=buf;g0.gain.value=1.2;
      src.connect(lf);lf.connect(g0);g0.connect(ac.destination);src.start();
      // Derin bas darbe
      var o0=ac.createOscillator(),g00=ac.createGain();
      o0.type='sine';o0.frequency.setValueAtTime(80,ac.currentTime);
      o0.frequency.exponentialRampToValueAtTime(30,ac.currentTime+.3);
      g00.gain.setValueAtTime(.9,ac.currentTime);g00.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.45);
      o0.connect(g00);g00.connect(ac.destination);o0.start();o0.stop(ac.currentTime+.45);
      // Crackle
      var o1=ac.createOscillator(),g01=ac.createGain();
      o1.type='sawtooth';o1.frequency.setValueAtTime(400,ac.currentTime);
      o1.frequency.exponentialRampToValueAtTime(50,ac.currentTime+.2);
      g01.gain.setValueAtTime(.3,ac.currentTime);g01.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.25);
      o1.connect(g01);g01.connect(ac.destination);o1.start();o1.stop(ac.currentTime+.25);
    } else if(dogru){
      [440,550,660].forEach(function(f,i){var o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.07,ac.currentTime+i*.04);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.04+.13);o.connect(g);g.connect(ac.destination);o.start(ac.currentTime+i*.04);o.stop(ac.currentTime+i*.04+.13);});
    } else {
      var o2=ac.createOscillator(),g2=ac.createGain();o2.type='sawtooth';o2.frequency.setValueAtTime(200,ac.currentTime);o2.frequency.exponentialRampToValueAtTime(60,ac.currentTime+.22);g2.gain.setValueAtTime(.08,ac.currentTime);g2.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.22);o2.connect(g2);g2.connect(ac.destination);o2.start();o2.stop(ac.currentTime+.22);
    }
  }catch(e){}
}

