function rEkle(pts){
  rSkor=Math.max(0,rSkor+pts);
  document.getElementById('rh-skor').textContent=rSkor;
  _rCommentCount++;
  // Her 5 hamlede bir şakacı yorum
  if(_rCommentCount%5===0){
    var positiveComments=(evValuesOn()&&evValuesLang()==='en')?['A little faster!','Nice reflex!','That was sharp!','Yes, that worked!','Keep going!']:((evValuesOn()&&evValuesLang()==='de')?['Etwas schneller!','Starke Reaktion!','Das war wach!','Ja, das passt!','Weiter so!']:['Hizlan biraz!','Guzel refleks!','Devam devam!']);
    var negativeComments=(evValuesOn()&&evValuesLang()==='en')?['Wrong one, try again!','Careful, look closely!','Almost, stay calm!','Slow down and focus!']:((evValuesOn()&&evValuesLang()==='de')?['Falsch, versuch es nochmal!','Vorsicht, genau schauen!','Fast, bleib ruhig!','Langsamer und fokussiert!']:['Yanlis! Tekrar dene!','Dikkat et!','Sakin ol!']);
    var msg = pts>0 ? positiveComments[Math.floor(Math.random()*positiveComments.length)] : negativeComments[Math.floor(Math.random()*negativeComments.length)];
    showOkiBubble(msg);
  }
}

