function rIsikBasla(){
  // Dinamik interval — sure azaldıkça hızlanır
  function spawnIsik(){
    if(!rMod||!rAktif())return;
    if(rObjs.filter(function(o){return o.type==='isik';}).length>=8)return;
    var p=rSpawnPos();
    var cols=['#FFD700','#FF6B6B','#44AAFF','#AA44FF','#44FF88','#FF8844'];
    var c=cols[Math.floor(Math.random()*cols.length)];
    var life=Math.max(30,75-(60-rSure)*1.4); // hızla azalır
    rObjs.push({type:'isik',x:p.x,y:p.y,r:22+Math.random()*18,col:c,alive:true,scale:0,puls:0,life:life,maxLife:life});
    // Bir sonraki spawn süresini dinamik hesapla
    var nextMs=Math.max(150,600-(60-rSure)*10);
    rSpawnTimers.push(setTimeout(spawnIsik,nextMs));
  }
  rSpawnTimers.push(setTimeout(spawnIsik,400));
}

