      msgs=['Hayır hayır hayır! Bu böyle olmaz! Tekrar dene! 😅','Ben de senin için endişelendim açıkçası... 😂 Tekrar!','Dur dur dur! Ellerini ısıt önce, sonra tekrar! \uD83D\uDD25'];
    }
