function evV39EnhanceCinema(){
  try{
    evV39EnsureCinemaStyle();
    var ov=document.getElementById('sn-ov'); if(!ov) return;
    ov.style.background='radial-gradient(circle at 15% 12%,rgba(255,211,107,.18),transparent 26%),radial-gradient(circle at 88% 18%,rgba(255,51,102,.20),transparent 30%),linear-gradient(180deg,#09020b,#140514,#250818,#070006)';
    ov.style.overflow='hidden';
    ov.style.position='fixed';

    if(!document.getElementById('v39-cinema-bg')){
      var bg=document.createElement('div');
      bg.id='v39-cinema-bg';
      bg.style.cssText='position:absolute;inset:0;z-index:0;pointer-events:none;overflow:hidden;';
      var icons=['🎬','🎥','📽️','🍿','⭐','✨','🎞️','🎭'];
      for(var i=0;i<34;i++){
        var sp=document.createElement('span');
        sp.textContent=icons[i%icons.length];
        sp.style.cssText='position:absolute;left:'+((i*41)%100)+'%;top:'+((i*57)%100)+'%;font-size:'+(15+(i%5)*5)+'px;opacity:.40;filter:drop-shadow(0 0 12px rgba(255,255,255,.16));animation:v39FilmFloat '+(5+(i%7))+'s ease-in-out infinite alternate;animation-delay:-'+(i%6)+'s;';
        bg.appendChild(sp);
      }
