function evV39CinemaSceneFX(i){
  try{
    evV39EnhanceCinema();
    var ov=document.getElementById('sn-ov'); if(!ov) return;
    var panel=document.getElementById('v39-director-panel');
    if(panel){
      var scene=(typeof i==='number'?i+1:1);
      panel.innerHTML='<div style="font-size:1.25rem">🎞️</div><div><b>SCENE '+scene+'/8</b><br><span>Hikâye akıyor</span></div>';
    }
    var pop=document.createElement('div');
    pop.textContent='🎬 SAHNE '+((typeof i==='number'?i:0)+1);
    pop.style.cssText='position:fixed;left:50%;top:38%;transform:translate(-50%,-50%);z-index:100000;padding:10px 16px;border-radius:20px;background:rgba(5,3,14,.82);border:1px solid rgba(255,211,107,.34);color:#ffe6a6;font-family:Fredoka One;font-size:.88rem;text-align:center;box-shadow:0 18px 55px rgba(0,0,0,.40),0 0 30px rgba(255,211,107,.20);pointer-events:none;animation:v39SceneFlash 1.0s ease-out forwards;';
    document.body.appendChild(pop);
    setTimeout(function(){pop.remove();},1100);
  }catch(e){}
}

