function _snMuz(){
  try{
    var A = getAC();
    var ns = [[392,.18],[494,.18],[587,.18],[698,.22],[587,.1],[494,.1],[587,.3]];
    var t = A.currentTime;
    ns.forEach(function(n,i){
      var o = A.createOscillator(), g = A.createGain();
      o.type = 'triangle'; o.frequency.value = n[0];
      var d = ns.slice(0,i).reduce(function(s,x){ return s+x[1]; },0);
      g.gain.setValueAtTime(0,t+d);
      g.gain.linearRampToValueAtTime(.12,t+d+.04);
      g.gain.exponentialRampToValueAtTime(.001,t+d+n[1]);
      o.connect(g); g.connect(A.destination);
      o.start(t+d); o.stop(t+d+n[1]+.1);
    });
  }catch(e){}
}

