function _snBurst(){
  var r = document.getElementById('sn-rn'); if(!r) return;
  var W = r.offsetWidth || 360;
  var H = r.offsetHeight || 640;
  var emojis = ['🍿','⭐','✨','🌟','🎬','💥','🎊','🎉','💫','🏆'];
  for(var i=0;i<30;i++){
    (function(){
      var el = document.createElement('div');
      el.textContent = emojis[Math.floor(Math.random()*emojis.length)];
      var startX = W * (0.2 + Math.random()*0.6);
      var startY = H * (0.3 + Math.random()*0.4);
      var angle = Math.random() * Math.PI * 2;
      var speed = 80 + Math.random() * 150;
      var endX = startX + Math.cos(angle) * speed;
      var endY = startY + Math.sin(angle) * speed;
      el.style.cssText = 'position:absolute;font-size:'+(1+Math.random()*0.8)+'rem;'+
        'left:'+startX+'px;top:'+startY+'px;'+
        'transition:all '+(0.4+Math.random()*0.6)+'s ease-out;'+
        'pointer-events:none;z-index:95;opacity:1;';
      r.appendChild(el);
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          el.style.left = endX + 'px';
          el.style.top = endY + 'px';
          el.style.opacity = '0';
          el.style.transform = 'scale(0.3) rotate('+(Math.random()*360)+'deg)';
        });
      });
      setTimeout(function(){ el.remove(); }, 1200);
    })();
  }
  // Ses
  try{
    var A=getAC();
    [[523,.08],[659,.06],[784,.08],[1047,.12]].forEach(function(n,i){
      var o=A.createOscillator(),g=A.createGain();
      o.type='triangle';o.frequency.value=n[0];
      g.gain.setValueAtTime(.15,A.currentTime+i*.06);
      g.gain.exponentialRampToValueAtTime(.001,A.currentTime+i*.06+n[1]);
      o.connect(g);g.connect(A.destination);
      o.start(A.currentTime+i*.06);o.stop(A.currentTime+i*.06+n[1]+.05);
    });
  }catch(e){}
}

