function cleanGermanParentReport(data){
    data=data||{};
    var today=new Date().toLocaleDateString('de-DE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
    var visited=[]; try{var rv=JSON.parse(localStorage.getItem('dei_visited')||'{}'); visited=rv[new Date().toDateString()]||data.roomsVisited||[];}catch(e){visited=data.roomsVisited||[];}
    var used=[]; (visited||[]).forEach(function(id){if(id&&used.indexOf(id)<0) used.push(id);});
    var roomHtml=used.slice(0,6).map(function(id){return '<div style="background:#fff;border:1px solid #dfe7f5;border-radius:12px;padding:12px 14px;margin-bottom:8px;"><b style="color:#173d6b;">'+esc(roomName(id))+'</b><div style="font-size:.78rem;line-height:1.55;color:#42536d;margin-top:4px;">Heute wurde spielerisch gelernt. Fragen Sie nach dem Lieblingsmoment und loben Sie Neugier, Ruhe und Ausdauer.</div></div>';}).join('');
    if(!roomHtml) roomHtml='<div style="padding:14px;border:1px dashed #ccd6e8;border-radius:12px;color:#66758d;font-size:.82rem;">Heute wurden noch keine Raumdaten gespeichert.</div>';
    var bars=(data.weekData||[]).map(function(d){var w=n(d.words);var h=Math.max(8,Math.min(54,w*8));return '<div style="flex:1;text-align:center;"><div style="height:60px;display:flex;align-items:flex-end;justify-content:center;"><div style="width:70%;height:'+h+'px;background:'+(d.isToday?'#f4b740':'#7aa7e8')+';border-radius:7px 7px 0 0;"></div></div><div style="font-size:.62rem;color:#607086;font-weight:800;margin-top:4px;">'+w+'</div></div>';}).join('');
    return '<div style="font-family:Nunito,Arial,sans-serif;background:#f6f8fc;color:#172033;margin:0;">'
      +'<div style="background:linear-gradient(135deg,#10294f,#286b7a);color:#fff;padding:22px 24px;"><div style="font-size:1.55rem;font-weight:900;color:#ffe08a;">EduVerse Werte</div><div style="font-size:.86rem;font-weight:800;opacity:.84;margin-top:4px;">Elternbericht</div><div style="display:flex;justify-content:space-between;gap:12px;margin-top:14px;font-size:.76rem;opacity:.92;"><span>'+esc(today)+'</span><span>'+esc(data.name||playerName||'EduVerse Kind')+'</span></div></div>'
      +'<div style="padding:16px 18px;"><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:14px;">'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">PUNKTE</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.totalScore)+'</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">SERIE</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.streak)+'</div></div>'
