function evV41DrawSecretKey(ts){
  try{
    if(!currentRoom || currentRoom.id!=='gizli') return;
    var t=ts*.001, p=evV41SecretKeyPos(), x=p.x, y=p.y, r=p.r;
    ctx.save();
    ctx.translate(x,y+Math.sin(t*2.1)*H*.006);
    ctx.rotate(Math.sin(t*1.3)*.08);

    // Anahtar parıltısı
    var glow=ctx.createRadialGradient(0,0,0,0,0,r*2.2);
    glow.addColorStop(0,'rgba(255,211,107,.46)');
    glow.addColorStop(.32,'rgba(255,211,107,.18)');
    glow.addColorStop(1,'transparent');
    ctx.fillStyle=glow;
    ctx.beginPath(); ctx.arc(0,0,r*2.2,0,Math.PI*2); ctx.fill();

    // Tıklanabilir enerji halkaları
    for(var i=0;i<3;i++){
      ctx.strokeStyle='rgba(255,211,107,'+(.28-i*.07)+')';
      ctx.lineWidth=2;
      ctx.beginPath();
      ctx.arc(0,0,r*(.72+i*.22+Math.sin(t*2+i)*.025),0,Math.PI*2);
      ctx.stroke();
    }

    // Anahtar gövdesi
    var kg=ctx.createLinearGradient(-r*.8,-r*.4,r*.9,r*.5);
    kg.addColorStop(0,'#fff4b8');
    kg.addColorStop(.35,'#ffd36b');
    kg.addColorStop(.72,'#ff9f2f');
    kg.addColorStop(1,'#ad5b12');
    ctx.strokeStyle=kg;
    ctx.lineCap='round';
    ctx.lineJoin='round';
    ctx.lineWidth=Math.max(7,r*.14);

    // baş halka
    ctx.beginPath();
    ctx.arc(-r*.42,-r*.02,r*.28,0,Math.PI*2);
    ctx.stroke();
    ctx.lineWidth=Math.max(5,r*.10);
    ctx.strokeStyle='rgba(80,38,8,.42)';
    ctx.beginPath();
    ctx.arc(-r*.42,-r*.02,r*.13,0,Math.PI*2);
    ctx.stroke();

    // sap
    ctx.strokeStyle=kg;
    ctx.lineWidth=Math.max(8,r*.16);
    ctx.beginPath();
    ctx.moveTo(-r*.16,0);
    ctx.lineTo(r*.68,0);
    ctx.stroke();

