        sp.style.cssText='position:absolute;left:'+((i*37)%100)+'%;top:-30px;font-size:'+(16+(i%5)*6)+'px;animation:v41Fall '+(2.4+(i%7)*.35)+'s ease-in both;animation-delay:'+(i*.035)+'s;filter:drop-shadow(0 0 12px rgba(255,255,255,.25));';
        starWrap.appendChild(sp);
      }
    }

    var close=document.getElementById('v41-secret-close');
    if(close) close.onclick=function(){ var o=document.getElementById('v41-secret-key-ov'); if(o) o.remove(); };

    // Oki balonu ve kısa sesli motivasyon
    if(typeof showOkiBubble==='function'){
      setTimeout(function(){ showOkiBubble('🔑 '+name+', gizli anahtarı buldun! Harika sabır! ✨'); },250);
    }
    try{
      if(window.speechSynthesis){
        window.speechSynthesis.cancel();
        var speechText = l==='en' ? name+', the secret room is open. You were patient and you made it.' :
                         l==='de' ? name+', der geheime Raum ist offen. Du warst geduldig und hast es geschafft.' :
                         l==='fr' ? name+', la salle secrète est ouverte. Tu as été patient et tu as réussi.' :
                         l==='ar' ? name+'، الغرفة السرية مفتوحة. لقد صبرت ونجحت.' :
                         name+', gizli oda açıldı. Beş gün sabrettin ve başardın.';
        var u=new SpeechSynthesisUtterance(speechText);
        u.lang = l==='en'?'en-US':(l==='de'?'de-DE':(l==='fr'?'fr-FR':(l==='ar'?'ar-SA':'tr-TR')));
        u.rate=.88; u.pitch=1.05; u.volume=1;
        setTimeout(function(){ window.speechSynthesis.speak(u); },450);
      }
    }catch(e){}
  }catch(e){}
}

