function s10Unit(lang,n){
    if(lang==='en') return n===1?'day':'days';
    if(lang==='de') return n===1?'Tag':'Tage';
    if(lang==='fr') return n===1?'jour':'jours';
    if(lang==='ar') return 'يوم';
    return 'gün';
  }

