function V48JG_pickIndex(key,len){
    var last=-1,idx=0,guard=0;
    try{ last=parseInt(localStorage.getItem(key)||'-1',10); }catch(e){}
    if(!len||len<1) return 0;
    idx=Math.floor(Math.random()*len);
    while(len>1 && idx===last && guard<12){ idx=Math.floor(Math.random()*len); guard++; }
    try{ localStorage.setItem(key,String(idx)); }catch(e2){}
    return idx;
  }

