function ev48kStageNumber(data){
    var n=1;
    try{ n=parseInt((data&&data.count)||getCurrentStreak()||1,10)||1; }catch(e){ n=1; }
    if(n<1) n=1;
    if(n>7) n=7;
    return n;
  }

