function ev48kFindCard(ov){
    var c=document.getElementById('streak-fire-c');
    if(c && c.nextElementSibling) return c.nextElementSibling;
    return ov.querySelector('.streak-card') || ov.querySelector('[id*="streak-card"]') || ov.firstElementChild;
