function ev48kBuildStage(ov,data){
    var lang=ev48kLang();
    var n=ev48kStageNumber(data);
    var list=ev48kStages(lang);
    var s=list[n-1] || list[0];
    var card=ev48kFindCard(ov);
    if(!card) return;
    card.classList.add('ev48k-card');
    ov.classList.add('ev48k-cinema');
    ov.classList.remove('ev48k-day7');
    if(n>=7) ov.classList.add('ev48k-day7');
    ov.setAttribute('data-ev48k-day',String(n));

    var stage=document.getElementById('ev48k-stage');
    if(!stage){
      stage=document.createElement('div');
      stage.id='ev48k-stage';
      stage.setAttribute('translate','no');
      var msg=document.getElementById('streak-msg-ov');
      if(msg && msg.parentNode){ msg.parentNode.insertBefore(stage,msg.nextSibling); }
      else{ card.appendChild(stage); }
    }

    var dots='';
    for(var i=1;i<=7;i++){
      var on=i<=n?' on':'';
      var sym=(list[i-1]&&list[i-1].s)||'•';
      dots+='<span class="ev48k-path-dot'+on+'">'+(i<=n?sym:i)+'</span>';
    }
    stage.innerHTML='<div class="ev48k-stage-line"><div class="ev48k-stage-symbol ev48k-'+s.k+'">'+s.s+'</div><div><div class="ev48k-stage-title">'+s.t+'</div><div class="ev48k-stage-msg">'+s.m+'</div></div></div><div class="ev48k-path">'+dots+'</div>';

    var canvas=document.getElementById('streak-fire-c');
    if(canvas){ canvas.style.opacity='0.82'; }
    var bg=document.getElementById('streak-fire-premium-bg');
    if(bg){ bg.style.opacity='0.88'; bg.style.filter='saturate(1.04) contrast(.98)'; }

    var cal=document.getElementById('streak-cal');
    if(cal){
      Array.prototype.forEach.call(cal.children,function(d,i){
        var done=(d.textContent||'').trim()==='🔥';
        d.style.transform='translateZ(0)';
        d.style.boxShadow=done?'0 0 14px rgba(255,190,50,.45)':'none';
      });
    }

    if(n>=7) ev48kBurst(ov);
  }

