function ev48kBurst(ov){
    var burst=document.getElementById('ev48k-burst');
    if(!burst){
      burst=document.createElement('div');
      burst.id='ev48k-burst';
      burst.className='ev48k-burst';
      ov.appendChild(burst);
    }
    if(burst.getAttribute('data-ready')==='1') return;
    burst.setAttribute('data-ready','1');
    var html='';
    for(var i=0;i<24;i++){
      var left=8+Math.random()*84;
      var top=72+Math.random()*18;
      var delay=Math.random()*1.3;
      var dur=1.25+Math.random()*1.25;
      html+='<span class="ev48k-star" style="left:'+left+'%;top:'+top+'%;animation-delay:'+delay+'s;animation-duration:'+dur+'s"></span>';
    }
    burst.innerHTML=html;
  }

