function ev48mPrepareStageClick(){
    try{
      var n=ev48mDayNumber();
      var stage=document.getElementById('ev48k-stage');
      if(!stage) return;
      if(n>=7){
        stage.classList.add('ev48m-clickable');
        stage.setAttribute('role','button');
        stage.setAttribute('tabindex','0');
        stage.setAttribute('aria-label',ev48mTxt('open'));
        stage.setAttribute('title',ev48mTxt('tap'));
        stage.onclick=function(){ ev48mOpenCelebration(); };
        stage.onkeydown=function(e){ e=e||window.event; var k=e.key||e.keyCode; if(k==='Enter'||k===' '||k===13||k===32){ if(e.preventDefault) e.preventDefault(); ev48mOpenCelebration(); } };
        var msg=stage.querySelector('.ev48k-stage-msg');
        if(msg && !stage.querySelector('.ev48m-tap-note')){
          var note=document.createElement('span');
          note.className='ev48m-tap-note';
          note.textContent=ev48mTxt('tap');
          msg.parentNode.appendChild(note);
        }
      } else {
        stage.classList.remove('ev48m-clickable');
        stage.removeAttribute('role');
        stage.removeAttribute('tabindex');
        stage.onclick=null;
        stage.onkeydown=null;
        var note2=stage.querySelector('.ev48m-tap-note');
        if(note2 && note2.parentNode) note2.parentNode.removeChild(note2);
      }
    }catch(e2){}
  }

