text:
function ev48mParticles(){
    var html='';
    for(var i=0;i<42;i++){
      var l=4+Math.random()*92;
      var t=62+Math.random()*31;
      var d=Math.random()*1.35;
      var dur=1.35+Math.random()*1.45;
      var cls=(i%3===0)?'ev48m-confetti':'ev48m-star';
      var color=(i%5===0)?'#fff1a6':(i%5===1?'#ffd35f':(i%5===2?'#ff8a3d':(i%5===3?'#f9a8d4':'#93c5fd')));
      html+='<span class="'+cls+'" style="left:'+l+'%;top:'+t+'%;background:'+color+';animation-delay:'+d+'s;animation-duration:'+dur+'s"></span>';
    }
    return html;
  }

