function ev48mBounceDays(){
    try{
      var cal=document.getElementById('streak-cal');
      if(!cal) return;
      var nodes=cal.children;
      for(var i=0;i<nodes.length;i++){
        if((nodes[i].textContent||'').indexOf('🔥')>=0){
          nodes[i].classList.remove('ev48m-day-hop');
          nodes[i].style.animationDelay=(i*.06)+'s';
          void nodes[i].offsetWidth;
          nodes[i].classList.add('ev48m-day-hop');
        }
      }
    }catch(e){}
  }

