function v48nApplyStreak(){
    try{
      v48nMakeStyle();
      var ov=document.getElementById('streak-ov');
      if(!ov) return false;
      var lang=v48nLang();
      var pack=V48N_STREAK[lang]||V48N_STREAK.tr;
      var count=v48nCount();
      var best=v48nBest();
      var left=Math.max(0,5-count);
      ov.setAttribute('lang',lang); ov.setAttribute('dir',pack.dir); v48nNoTrans(ov);
      v48nSet(document.getElementById('streak-title'),pack.title);
      v48nSet(document.getElementById('streak-best'),'🏆 '+pack.best+': '+best+' '+v48nNumUnit(pack,best));
      var msg=(count>=7)?pack.msg7:(count+' '+pack.def);
      if(count===1 && lang==='tr') msg='Hoş geldin! Seriyi başlatıyoruz! 🌱';
      if(count===1 && lang==='en') msg='Welcome! Your streak starts today! 🌱';
      if(count===1 && lang==='de') msg='Willkommen! Deine Serie beginnt heute! 🌱';
      if(count===1 && lang==='fr') msg='Bienvenue ! Ta série commence aujourd’hui ! 🌱';
      if(count===1 && lang==='ar') msg='مرحباً! تبدأ سلسلتك اليوم! 🌱';
      v48nSet(document.getElementById('streak-msg-ov'),msg);
      v48nSet(document.getElementById('streak-continue-btn'),pack.btn);
      var goalLabel=document.getElementById('streak-goal-label');
      var goalTxt=document.getElementById('streak-goal-txt');
      if(goalTxt) v48nSet(goalTxt,count>=5?('🔓 '+pack.open):(left+' '+v48nNumUnit(pack,left)+' '+pack.left));
      if(goalLabel){
        v48nNoTrans(goalLabel);
        while(goalLabel.firstChild){ goalLabel.removeChild(goalLabel.firstChild); }
        goalLabel.appendChild(document.createTextNode('🔮 '+pack.secret+': '));
        if(goalTxt) goalLabel.appendChild(goalTxt); else goalLabel.appendChild(document.createTextNode(count>=5?pack.open:(left+' '+pack.left)));
      }
      var cal=document.getElementById('streak-cal');
      if(cal){
        v48nNoTrans(cal);
        Array.prototype.forEach.call(cal.children,function(d,i){ v48nNoTrans(d); if((d.textContent||'').trim()!=='🔥') d.textContent=pack.days[i%7]; });
      }
      var day=v48nDay();
      var stage=pack.stage[day-1]||pack.stage[0];
      var stg=document.getElementById('ev48k-stage');
      if(stg){
        stg.setAttribute('lang',lang); stg.setAttribute('dir',pack.dir); v48nNoTrans(stg);
        v48nSet(stg.querySelector('.ev48k-stage-title'),stage[0]);
        v48nSet(stg.querySelector('.ev48k-stage-msg'),stage[1]);
        var note=stg.querySelector('.ev48m-tap-note');
        if(note) v48nSet(note,pack.tap);
        if(day>=7){ stg.setAttribute('aria-label',pack.tap); stg.setAttribute('title',pack.tap); }
      }
      var celeb=document.getElementById('ev48m-celebration');
      if(celeb){
        celeb.setAttribute('lang',lang); celeb.setAttribute('dir',pack.dir); v48nNoTrans(celeb);
        v48nSet(celeb.querySelector('.ev48m-cele-title'),pack.celeTitle.replace('_NU',v48nPlayer().toUpperCase()));
        var cm=celeb.querySelector('.ev48m-cele-msg');
        if(cm){ cm.innerHTML=pack.celeMsg+'<br><span style="color:#ffe78b">'+pack.celeSmall+'</span>'; v48nNoTrans(cm); }
        var b=celeb.querySelectorAll('button');
        if(b[0]) v48nSet(b[0],pack.again);
        if(b[1]) v48nSet(b[1],pack.close);
      }
      return true;
    }catch(e){ return false; }
  }

