function v48nFixTextNodes(root){
    try{
      if(!root) return;
      var lang=v48nLang();
      var maps=v48nFixMaps[lang]||[];
      if(!maps.length) return;
      var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null);
      var node, txt, i;
      while((node=walker.nextNode())){
        txt=node.nodeValue;
        if(!txt || !String(txt).trim()) continue;
        for(i=0;i<maps.length;i++){ txt=txt.replace(maps[i][0],maps[i][1]); }
        if(txt!==node.nodeValue) node.nodeValue=txt;
      }
    }catch(e){}
  }

