function v48nMakeNoise(ctx,seconds){
    var len=Math.max(1,Math.floor(ctx.sampleRate*seconds));
    var b=ctx.createBuffer(1,len,ctx.sampleRate);
    var d=b.getChannelData(0);
    var last=0,i,raw;
    for(i=0;i<len;i++){ raw=(Math.random()*2-1); last=(last*.92)+(raw*.08); d[i]=last*.55; }
    return b;
  }

