    try{
      var ov=document.getElementById('streak-ov');
      if(!ov || ov.style.display==='none') return;
      if(v48nAudio.on) return;
      var ctx=v48nCtx(); if(!ctx) return;
      if(ctx.state==='suspended' && ctx.resume) ctx.resume();
      var src=ctx.createBufferSource(); src.buffer=v48nMakeNoise(ctx,2.2); src.loop=true;
      var filt=ctx.createBiquadFilter(); filt.type='bandpass'; filt.frequency.value=620; filt.Q.value=.85;
      var gain=ctx.createGain(); gain.gain.setValueAtTime(0.0001,ctx.currentTime); gain.gain.linearRampToValueAtTime(0.020,ctx.currentTime+.55);
      src.connect(filt); filt.connect(gain); gain.connect(ctx.destination); src.start(0);
      v48nAudio.source=src; v48nAudio.filter=filt; v48nAudio.gain=gain; v48nAudio.on=true;
      v48nAudio.timer=setInterval(v48nCrackle,650);
    }catch(e){}
  }

