function v48nCrackle(){
    try{
      var ctx=v48nAudio.ctx; if(!ctx || !v48nAudio.on) return;
      var src=ctx.createBufferSource(); src.buffer=v48nMakeNoise(ctx,.12);
      var hp=ctx.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=900+(Math.random()*1200);
      var g=ctx.createGain(); var now=ctx.currentTime;
      g.gain.setValueAtTime(0.0001,now); g.gain.exponentialRampToValueAtTime(0.018+(Math.random()*.018),now+.025); g.gain.exponentialRampToValueAtTime(0.0001,now+.16);
      src.connect(hp); hp.connect(g); g.connect(ctx.destination); src.start(now); src.stop(now+.18);
    }catch(e){}
  }

