function v48nSparkleSound(){
    try{
      var ctx=v48nCtx(); if(!ctx) return;
      if(ctx.state==='suspended' && ctx.resume) ctx.resume();
      var notes=[880,1174,1568,2093];
      var i;
      for(i=0;i<notes.length;i++){
        (function(f,delay){
          var o=ctx.createOscillator(); var g=ctx.createGain(); var now=ctx.currentTime+delay;
          o.type='sine'; o.frequency.setValueAtTime(f,now);
          g.gain.setValueAtTime(0.0001,now); g.gain.exponentialRampToValueAtTime(.045,now+.025); g.gain.exponentialRampToValueAtTime(0.0001,now+.42);
          o.connect(g); g.connect(ctx.destination); o.start(now); o.stop(now+.46);
        })(notes[i],i*.055);
      }
    }catch(e){}
  }

