function v48n3EnsureStreakShield(){
    try{
      v48n3Style();
      var ov=document.getElementById('streak-ov');
      if(!ov) return;
      if(v48n3Visible(ov)){
        ov.classList.add('ev48n3-isolated');
        document.body.classList.add('ev48n3-modal-open');
        var sh=document.getElementById('ev48n3-streak-shield');
        if(!sh){ sh=document.createElement('div'); sh.id='ev48n3-streak-shield'; }
        if(sh.parentNode!==ov){
          try{ if(sh.parentNode) sh.parentNode.removeChild(sh); }catch(e){}
          ov.insertBefore(sh,ov.firstChild);
        }
        var card=ov.querySelector('.ev48k-card')||ov.querySelector('.streak-card')||ov.querySelector('[id*="streak-card"]');
        if(card){ card.style.position='relative'; card.style.zIndex='12'; }
        var bg=document.getElementById('streak-fire-premium-bg');
        if(bg){ bg.style.zIndex='1'; bg.style.opacity='.92'; bg.style.mixBlendMode='normal'; }
        var cv=document.getElementById('streak-fire-c');
        if(cv){ cv.style.zIndex='2'; cv.style.opacity='.96'; cv.style.mixBlendMode='screen'; }
      }else{
        ov.classList.remove('ev48n3-isolated');
        var sh2=document.getElementById('ev48n3-streak-shield');
        if(sh2 && sh2.parentNode) sh2.parentNode.removeChild(sh2);
        var gate=document.getElementById('v48j-gate');
        if(!v48n3Visible(gate)) document.body.classList.remove('ev48n3-modal-open');
      }
    }catch(e){}
  }

