text:
function v48oHardClean(){
    try{ v48oStyle(); }catch(e){}
    try{
      var q=document.getElementById('ov-soru2');
      if(q){ q.classList.add('v48o-force-hide'); q.classList.remove('show'); }
    }catch(e2){}
    try{ if(typeof window.evV48N3OverlayLeakFix==='function') window.evV48N3OverlayLeakFix(); }catch(e3){}
    try{ if(!v48oStreakVisible()) v48oStopFire(); }catch(e4){}
    v48oCleanupModalClass();
  }

