function v48o2Style(){
    if(document.getElementById('v48o2-room-entry-style')) return;
    var st=document.createElement('style');
    st.id='v48o2-room-entry-style';
    st.textContent=''
      +'#v48j-gate .v48j-title{overflow-wrap:anywhere!important;text-align:center!important;}'
      +'#v48j-gate .v48j-room-francais .v48j-icon{filter:drop-shadow(0 14px 22px rgba(59,130,246,.35));}'
      +'#v48j-gate .v48j-room-ibadet .v48j-icon{filter:drop-shadow(0 14px 22px rgba(96,165,250,.32));}'
      +'.rb-name{overflow-wrap:anywhere!important;line-height:1.05!important;}';
    document.head.appendChild(st);
  }

