function v48pTone(freq,dur,type,gain,delay){
    var ctx=v48pAudio(); if(!ctx) return;
    try{ var osc=ctx.createOscillator(); var g=ctx.createGain(); osc.type=type||'sine'; osc.frequency.value=freq; g.gain.setValueAtTime(0.0001,ctx.currentTime+(delay||0)); g.gain.exponentialRampToValueAtTime(gain||0.035,ctx.currentTime+(delay||0)+0.012); g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+(delay||0)+dur); osc.connect(g); g.connect(ctx.destination); osc.start(ctx.currentTime+(delay||0)); osc.stop(ctx.currentTime+(delay||0)+dur+0.02); }catch(e){}
  }

