function v48pSound(kind){
    if(kind==='click'){ v48pTone(420,0.06,'triangle',0.022,0); return; }
    if(kind==='correct'){ v48pTone(620,0.08,'sine',0.035,0); v48pTone(880,0.12,'sine',0.035,0.07); return; }
    if(kind==='wrong'){ v48pTone(170,0.16,'sawtooth',0.020,0); return; }
    if(kind==='gift'){ v48pTone(740,0.08,'sine',0.035,0); v48pTone(980,0.10,'sine',0.030,0.06); return; }
    if(kind==='theme'){ v48pTone(520,0.06,'triangle',0.025,0); v48pTone(720,0.08,'triangle',0.022,0.055); return; }
    if(kind==='win'){ v48pTone(520,0.10,'sine',0.035,0); v48pTone(660,0.10,'sine',0.035,0.08); v48pTone(820,0.12,'sine',0.040,0.16); return; }
  }

