function v48pBurst(btn,good){
    var box=document.getElementById('v48p-box'); if(!box) return;
    var r=btn?btn.getBoundingClientRect():box.getBoundingClientRect(); var br=box.getBoundingClientRect(); var cx=r.left-br.left+r.width/2, cy=r.top-br.top+r.height/2; var i,sp,ang,dist;
    for(i=0;i<(good?10:4);i++){ sp=document.createElement('span'); sp.className='v48p-spark '+(good?'good':'bad'); sp.textContent=good?'✦':'•'; ang=(Math.PI*2*i)/(good?10:4); dist=good?(28+Math.random()*24):(16+Math.random()*10); sp.style.left=cx+'px'; sp.style.top=cy+'px'; sp.style.setProperty('--x',Math.cos(ang)*dist+'px'); sp.style.setProperty('--y',Math.sin(ang)*dist+'px'); box.appendChild(sp); (function(x){ setTimeout(function(){ try{x.remove();}catch(e){} },680); })(sp); }
  }

