function v48pPick(btn){
    if(game.locked || game.won) return;
    v48pSound('click');
    game.locked=true;
    var ans=btn.getAttribute('data-answer')||'';
    if(ans===game.correct){
      btn.classList.add('ok'); game.right++;
      v48pSound('correct'); v48pBurst(btn,true);
      document.getElementById('v48p-feedback').textContent='✨ '+v48pT('right')+'!';
    }else{
      btn.classList.add('bad');
      v48pSound('wrong'); v48pBurst(btn,false);
      document.getElementById('v48p-feedback').textContent='💡 '+game.correct;
    }
    setTimeout(function(){
      game.round++;
      if(game.round>=7){ v48pFinish(); return; }
      v48pRender();
    },820);
  }

