function v48pFinish(){
    var win=document.getElementById('v48p-win');
    var name=v48pPlayer()||v48pT('emptyName');
    var bigTaken=false;
    try{ bigTaken=localStorage.getItem(v48pTodayKey())==='1'; }catch(e){}
    game.won=(game.right>=7);
    win.style.display='block';
    win.className=game.won?'v48p-celebrate':'';
    if(game.won){
      v48pSound('win');
      v48pWinRain();
      if(!bigTaken){
        v48pAward(10000);
        try{ localStorage.setItem(v48pTodayKey(),'1'); }catch(e2){}
        document.getElementById('v48p-win-title').textContent=v48pT('bravo')+' '+name+'!';
        document.getElementById('v48p-win-msg').textContent=v48pT('final')+' '+v48pT('bonus');
      }else{
        v48pAward(350);
        document.getElementById('v48p-win-title').textContent=v48pT('win');
        document.getElementById('v48p-win-msg').textContent=v48pT('daily');
      }
      v48pGifts();
    }else{
      v48pAward(150+game.right*50);
      document.getElementById('v48p-win-title').textContent=game.right+'/7';
      document.getElementById('v48p-win-msg').textContent=v48pT('lost');
      document.getElementById('v48p-gifts').innerHTML='';
    }
    document.getElementById('v48p-score').innerHTML=v48pT('score')+': <b>'+((typeof totalScore!=='undefined')?totalScore:0)+'</b>';
  }

