function v48qStyle(){
    if(document.getElementById('v48q-story-style')) return;
    var st=document.createElement('style'); st.id='v48q-story-style';
    st.textContent=
      '#v48q-story{position:fixed;inset:0;z-index:999999;display:none;align-items:center;justify-content:center;padding:10px;background:linear-gradient(135deg,rgba(10,12,32,.94),rgba(49,28,72,.92));color:#fff;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;direction:ltr}#v48q-story[dir="rtl"]{direction:rtl}'
      +'#v48q-box{width:min(1030px,98vw);max-height:96dvh;overflow:auto;border-radius:30px;background:radial-gradient(circle at 20% 8%,rgba(251,191,36,.18),transparent 28%),linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.055)),linear-gradient(145deg,#1e1b4b,#172554);border:1px solid rgba(255,255,255,.22);box-shadow:0 28px 80px rgba(0,0,0,.44);padding:15px;position:relative;isolation:isolate}'
      +'#v48q-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}#v48q-title{margin:0;font-size:clamp(20px,3vw,30px);font-weight:950;text-shadow:0 4px 18px rgba(0,0,0,.34)}#v48q-role{padding:8px 12px;border-radius:999px;background:rgba(255,255,255,.16);font-weight:850;color:#fde68a;font-size:13px}#v48q-story-title{text-align:center;margin:10px 0 7px;font-weight:950;color:#fde68a;font-size:clamp(18px,2.6vw,24px)}#v48q-sub{text-align:center;margin:0 0 10px;opacity:.9;font-weight:800}'
      +'#v48q-zones{display:grid;grid-template-columns:1fr 1.25fr 1.25fr;gap:10px;margin:10px 0}.v48q-zone{min-height:176px;border-radius:24px;padding:10px;border:2px dashed rgba(255,255,255,.28);background:rgba(255,255,255,.08);transition:.16s;position:relative}.v48q-zone:after{content:attr(data-need);position:absolute;right:12px;top:10px;font-size:11px;font-weight:950;color:#fde68a;background:rgba(0,0,0,.18);border-radius:999px;padding:4px 8px}.v48q-zone.active{border-color:#fde68a;box-shadow:0 0 0 5px rgba(250,204,21,.12)}.v48q-zone.ok{border-color:#86efac}.v48q-zone h3{margin:0 0 8px;text-align:center;font-size:16px;color:#fff}.v48q-card{border:0;width:100%;text-align:left;margin:6px 0;padding:10px 11px;border-radius:16px;background:linear-gradient(135deg,#fff7ed,#fde68a);color:#111827;font-weight:850;line-height:1.25;box-shadow:0 8px 18px rgba(0,0,0,.24);cursor:pointer}.v48q-card.selected{outline:4px solid #60a5fa;transform:scale(1.02)}.v48q-card.wrong{animation:v48qShake .34s ease both;background:linear-gradient(135deg,#fee2e2,#fb7185)}.v48q-card.correct{background:linear-gradient(135deg,#dcfce7,#86efac)}#v48q-deck-title{margin:8px 0 6px;text-align:center;font-weight:950;color:#bfdbfe}#v48q-deck{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;background:rgba(0,0,0,.16);border-radius:22px;padding:10px;min-height:82px}'
      +'#v48q-feedback{min-height:31px;text-align:center;margin:9px 0 0;font-size:clamp(17px,2.5vw,23px);font-weight:950;color:#fde68a;text-shadow:0 4px 16px rgba(0,0,0,.32)}#v48q-mini{display:none;margin:10px auto 0;max-width:800px;border-radius:24px;padding:13px;background:rgba(0,0,0,.24);border:1px solid rgba(253,230,138,.35);text-align:center}#v48q-mini h3{margin:0 0 7px;color:#fde68a}#v48q-mini p{margin:0;font-weight:850}#v48q-actions{display:flex;gap:9px;justify-content:center;flex-wrap:wrap;margin-top:12px}.v48q-action{border:0;border-radius:999px;padding:11px 18px;background:linear-gradient(90deg,#f59e0b,#fde68a);color:#111827;font-size:15px;font-weight:950;cursor:pointer}.v48q-action.secondary{background:rgba(255,255,255,.14);color:#fff}.v48q-action:active,.v48q-card:active{transform:scale(.98)}.v48q-spark{position:absolute;z-index:30;pointer-events:none;font-size:20px;animation:v48qSpark 1s ease-out forwards}'
      +'@keyframes v48qShake{20%,60%{transform:translateX(-5px)}40%,80%{transform:translateX(5px)}}@keyframes v48qSpark{0%{opacity:0;transform:translateY(30px) scale(.6)}20%{opacity:1}100%{opacity:0;transform:translateY(-80px) rotate(160deg) scale(1.2)}}'
      +'@media(max-width:720px){#v48q-box{padding:10px}#v48q-zones{grid-template-columns:1fr;gap:8px}.v48q-zone{min-height:112px}#v48q-deck{grid-template-columns:1fr}.v48q-card{font-size:13px;padding:9px}.v48q-zone h3{font-size:14px}#v48q-role{font-size:11px}}';
    document.head.appendChild(st);
  }

