function v48qCard(id,text,zone,order){
    var b=document.createElement('button'); b.type='button'; b.className='v48q-card'; b.textContent=text; b.dataset.id=id; b.dataset.zone=zone; b.dataset.order=String(order); b.draggable=true;
    b.onclick=function(){ v48qSelect(this); };
    b.ondragstart=function(ev){ try{ ev.dataTransfer.setData('text/plain',this.dataset.id); }catch(e){} };
    return b;
  }

