function v48qSelect(el){
    var old=document.querySelector('#v48q-story .v48q-card.selected');
    if(old) old.classList.remove('selected');
    if(state.selected===el.dataset.id){ state.selected=null; return; }
    state.selected=el.dataset.id; el.classList.add('selected');
    var zones=document.querySelectorAll('#v48q-story .v48q-zone'); var i;
    for(i=0;i<zones.length;i++) zones[i].classList.add('active');
  }

