function v48qPlace(card,zone){
    var z=document.querySelector('#v48q-story .v48q-zone[data-zone="'+zone+'"]');
    if(!card||!z) return;
    card.classList.remove('selected'); state.selected=null;
    var zones=document.querySelectorAll('#v48q-story .v48q-zone'); var i;
    for(i=0;i<zones.length;i++) zones[i].classList.remove('active');
    z.appendChild(card);
    v48qFeedback(v48qT('hint'));
  }

