function v48qZoneEvents(){
    var zones=document.querySelectorAll('#v48q-story .v48q-zone'); var i;
    for(i=0;i<zones.length;i++){
      zones[i].onclick=function(ev){
        if(ev.target && ev.target.className && String(ev.target.className).indexOf('v48q-card')>=0) return;
        if(state.selected) v48qPlace(v48qFindCard(state.selected),this.dataset.zone);
      };
      zones[i].ondragover=function(ev){ ev.preventDefault(); this.classList.add('active'); };
      zones[i].ondragleave=function(){ this.classList.remove('active'); };
      zones[i].ondrop=function(ev){
        ev.preventDefault(); this.classList.remove('active');
        var id=''; try{id=ev.dataTransfer.getData('text/plain');}catch(e){}
        v48qPlace(v48qFindCard(id),this.dataset.zone);
      };
    }
  }

