function v48qSpark(){
    var box=document.getElementById('v48q-box'); if(!box) return;
    var i,sp;
    for(i=0;i<18;i++){
      sp=document.createElement('span'); sp.className='v48q-spark'; sp.textContent=['✨','⭐','🎬','📖','💛'][i%5]; sp.style.left=(10+Math.random()*80)+'%'; sp.style.top=(45+Math.random()*35)+'%'; sp.style.animationDelay=(Math.random()*0.35)+'s'; box.appendChild(sp);
      setTimeout((function(x){return function(){try{x.remove();}catch(e){}};})(sp),1500);
    }
  }

