function v48qRender(){
    var ov=v48qOverlay(); var l=v48qLang(); ov.setAttribute('dir',l==='ar'?'rtl':'ltr');
    var list=v48qData(); if(state.story>=list.length) state.story=0;
    var story=list[state.story]; var cards=[],i,c;
    state.selected=null; state.done=false;
    document.getElementById('v48q-title').textContent=v48qT('title');
    document.getElementById('v48q-role').textContent=v48qT('role');
    document.getElementById('v48q-story-title').textContent='🎬 '+story.title;
    document.getElementById('v48q-sub').textContent=v48qT('sub');
    var z=document.querySelector('#v48q-story .v48q-zone[data-zone="intro"] h3'); if(z) z.textContent='1 • '+v48qT('intro');
    var zoneBox=document.querySelector('#v48q-story .v48q-zone[data-zone="intro"]'); if(zoneBox) zoneBox.setAttribute('data-need',v48qT('introSlot'));
    z=document.querySelector('#v48q-story .v48q-zone[data-zone="middle"] h3'); if(z) z.textContent='2 • '+v48qT('middle');
    zoneBox=document.querySelector('#v48q-story .v48q-zone[data-zone="middle"]'); if(zoneBox) zoneBox.setAttribute('data-need',v48qT('middleSlot'));
    z=document.querySelector('#v48q-story .v48q-zone[data-zone="end"] h3'); if(z) z.textContent='3 • '+v48qT('end');
    zoneBox=document.querySelector('#v48q-story .v48q-zone[data-zone="end"]'); if(zoneBox) zoneBox.setAttribute('data-need',v48qT('endSlot'));
    var zones=document.querySelectorAll('#v48q-story .v48q-zone');
    for(i=0;i<zones.length;i++){
      zones[i].classList.remove('ok');
      var h=zones[i].querySelector('h3'); zones[i].innerHTML=''; if(h) zones[i].appendChild(h);
    }
    document.getElementById('v48q-deck-title').textContent='🧩 '+v48qT('deck');
    var deck=document.getElementById('v48q-deck'); deck.innerHTML='';
    for(i=0;i<story.cards.length;i++){ c=story.cards[i]; cards.push({id:'c'+i,text:c[0],zone:c[1],order:i}); }
    v48qShuffle(cards);
    for(i=0;i<cards.length;i++) deck.appendChild(v48qCard(cards[i].id,cards[i].text,cards[i].zone,cards[i].order));
    document.getElementById('v48q-check').textContent=v48qT('check');
    document.getElementById('v48q-next').textContent=v48qT('next');
    document.getElementById('v48q-close').textContent=v48qT('close');
    document.getElementById('v48q-check').onclick=v48qCheck;
    document.getElementById('v48q-next').onclick=function(){ state.story=(state.story+1)%v48qData().length; v48qRender(); };
    document.getElementById('v48q-close').onclick=v48qClose;
    var mini=document.getElementById('v48q-mini'); if(mini) mini.style.display='none';
    v48qFeedback(v48qT('hint')+' '+v48qT('orderHint'));
    v48qZoneEvents();
  }

