function v48qCheck(){
    var cards=document.querySelectorAll('#v48q-story .v48q-card');
    var wrong=[],ok=0,i,card,parentZone,zone,expected,zoneCards,j;
    for(i=0;i<cards.length;i++){
      cards[i].classList.remove('wrong'); cards[i].classList.remove('correct');
    }
    var zones=['intro','middle','end'];
    for(i=0;i<zones.length;i++){
      zone=zones[i]; expected=v48qExpectedOrder(zone);
      zoneCards=document.querySelectorAll('#v48q-story .v48q-zone[data-zone="'+zone+'"] .v48q-card');
      for(j=0;j<zoneCards.length;j++){
        card=zoneCards[j];
        parentZone=card.parentNode&&card.parentNode.dataset?card.parentNode.dataset.zone:'';
        if(parentZone===card.dataset.zone && expected[j]!==undefined && Number(card.dataset.order)===expected[j]){
          ok++; card.classList.add('correct');
        }else{
          wrong.push(card);
        }
      }
      if(zoneCards.length<expected.length){
        /* empty slots are counted as missing; feedback will show progress */
      }
    }
    for(i=0;i<cards.length;i++){
      card=cards[i];
      if(!(card.classList.contains('correct')) && wrong.indexOf(card)<0) wrong.push(card);
    }
    if(ok===cards.length){
      var allZones=document.querySelectorAll('#v48q-story .v48q-zone'); for(i=0;i<allZones.length;i++) allZones[i].classList.add('ok');
      var mini=document.getElementById('v48q-mini');
      if(mini){ mini.style.display='block'; mini.querySelector('h3').textContent='🎉 '+v48qT('good'); mini.querySelector('p').textContent=v48qT('mini')+' '+v48qT('award'); }
      v48qFeedback(v48qT('good'));
      if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('success');
      v48qSpark(); v48qAward();
    }else{
      for(i=0;i<wrong.length;i++){
        wrong[i].classList.add('wrong');
        if(document.getElementById('v48q-deck')) document.getElementById('v48q-deck').appendChild(wrong[i]);
      }
      if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('soft');
      v48qFeedback(v48qT('tryagain')+' '+ok+'/'+cards.length+' • '+v48qT('orderHint'));
    }
  }

