function activateRoomMusic(roomId){
    showAdaMusic();
    hideTinyMusicButtons();
    try{
      if(roomId==='bilgitoplari') window._adaIdx=9;
      if(roomId==='hikayestudio') window._adaIdx=10;
      if(typeof window._adaMarkActive==='function') window._adaMarkActive(window._adaIdx||0);
    }catch(e){}
    setTimeout(showAdaMusic,120);
    setTimeout(showAdaMusic,520);
  }

