function v48sStyle(){
    if(document.getElementById('v48s-oki3d-style')) return;
    var st=document.createElement('style'); st.id='v48s-oki3d-style';
    st.textContent=
      '#v48s-oki3d{position:fixed;inset:0;z-index:999999;display:none;align-items:center;justify-content:center;padding:10px;background:radial-gradient(circle at 12% 10%,rgba(34,197,94,.28),transparent 22%),radial-gradient(circle at 88% 18%,rgba(56,189,248,.23),transparent 26%),linear-gradient(135deg,#07121e,#0f172a 44%,#132a1d);color:#fff;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;direction:ltr}#v48s-oki3d[dir="rtl"]{direction:rtl}'
      +'#v48s-shell{width:min(1160px,98vw);max-height:96dvh;overflow:auto;border-radius:32px;padding:14px;background:linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.055)),linear-gradient(145deg,#0b1220,#10331f);border:1px solid rgba(255,255,255,.2);box-shadow:0 28px 88px rgba(0,0,0,.46);position:relative;isolation:isolate}#v48s-shell:before{content:"";position:absolute;inset:10px;border-radius:26px;border:1px solid rgba(125,211,252,.15);pointer-events:none;background-image:linear-gradient(rgba(125,211,252,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(125,211,252,.08) 1px,transparent 1px);background-size:34px 34px;opacity:.45}'
      +'#v48s-head{position:relative;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}#v48s-title{margin:0;font-size:clamp(22px,3.4vw,34px);font-weight:1000;text-shadow:0 5px 18px rgba(0,0,0,.44)}#v48s-role{padding:8px 12px;border-radius:999px;background:rgba(14,165,233,.16);border:1px solid rgba(125,211,252,.35);font-weight:950;color:#bae6fd;font-size:13px}.v48s-chip{display:inline-flex;align-items:center;gap:5px;margin:3px;padding:7px 10px;border-radius:999px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.16);font-weight:900;font-size:12px}'
      +'#v48s-layout{position:relative;display:grid;grid-template-columns:1.35fr .78fr;gap:14px;margin-top:12px}#v48s-viewport{min-height:520px;border-radius:28px;background:radial-gradient(circle at 50% 18%,rgba(20,184,166,.22),transparent 30%),linear-gradient(180deg,rgba(125,211,252,.12),rgba(0,0,0,.2));border:1px solid rgba(255,255,255,.18);box-shadow:inset 0 0 30px rgba(14,165,233,.12);position:relative;overflow:hidden;perspective:950px}'
