function v48sCheck(){
    var m=v48sMission(); var mods=v48sPresentMods(); var miss=[],i;
    for(i=0;i<m.need.length;i++){ if(mods.indexOf(m.need[i])<0) miss.push(m.need[i]); }
    if(miss.length===0){
      var solvedKey='m'+String(v48sState.mission);
      if(!v48sState.solved[solvedKey]){ v48sState.solved[solvedKey]=true; v48sAward(); }
      v48sState.done=true; v48sRender(); v48sLog(v48sT('good')+' '+v48sT('award')+' • '+v48sT('mini')); v48sPop('🌸');
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('success'); }catch(e){}
    }else{
      for(i=0;i<miss.length;i++){}
      v48sLog(v48sT('missing')+' → '+miss.map(function(x){ return v48sModData[x].ico+' '+v48sModName(x); }).join(', '));
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('soft'); }catch(e2){}
    }
  }

