function v48s4Mission(){
  var n=v48s4State.level||1, p=v48s4Pattern(n), need=[], i;
  for(i=0;i<p.need.length;i++) need.push(p.need[i]);
  if(n>12 && n%3===0 && need.indexOf('sensor')<0) need.push('sensor');
  if(n>18 && n%4===0 && need.indexOf('battery')<0) need.push('battery');
  if(n>30 && n%5===0 && need.indexOf('wind')<0) need.push('wind');
  while(need.length>5) need.pop();
  return {level:n,world:v48s4WorldName(n),worldIndex:v48s4WorldIndex(n),title:String(p.title).replace('{world}',v48s4WorldName(n)),goal:p.goal,need:need,tier:Math.floor((n-1)/5)+1};
}

