    if(!pos) return;
    v48s4State.grid[pos]=v48s4State.selected||'seed';
    v48s4State.done=false;
    v48s4State.log=((v48s4ModData[v48s4State.selected]&&v48s4ModData[v48s4State.selected].ico)||'🔧')+' '+v48s4ModName(v48s4State.selected);
    v48s4Render();
    v48s4Pop(((v48s4ModData[v48s4State.selected]&&v48s4ModData[v48s4State.selected].ico)||'✨'));
  }

