function v48s4Check(){
    var m=v48s4Mission(), miss=v48s4PresentNeed(m), add, txt, i;
    if(miss.length===0){
      if(!v48s4State.done){ add=v48s4Award(); v48s4SaveDone(v48s4State.level); v48s4SaveLevel(v48s4State.level+1); }
      else add=0;
      v48s4State.done=true;
      txt=v48s4T('good')+' '+(add?('+'+add+' '+v48s4T('award')+'. '):'')+v48s4T('saved');
      v48s4State.log=txt;
      v48s4Render();
      v48s4Pop('🌸');
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('success'); }catch(e){}
    }else{
      txt=v48s4T('missing')+' → ';
      for(i=0;i<miss.length;i++){ txt+=(i?', ':'')+((v48s4ModData[miss[i]]&&v48s4ModData[miss[i]].ico)||'🔧')+' '+v48s4ModName(miss[i]); }
      v48s4Log(txt);
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('soft'); }catch(e2){}
    }
  }

