function v48s5BuiltMap(m){
    var map={}, done=v48s5Done(), count=v48s5TileCount(m), start=m.regionStart, end=start+9, lvl, p, pos;
    for(lvl=start;lvl<=end&&lvl<=done;lvl++){
      p=v48s5Plan(lvl);
      pos=(lvl-start)%count;
      map[String(pos)]={level:lvl,obj:p.obj};
    }
    if(v48s5State.done&&done<m.level){ p=v48s5Plan(m.level); pos=(m.level-start)%count; map[String(pos)]={level:m.level,obj:p.obj}; }
    return map;
  }

