function v48s5Run(){
    var m=v48s5Mission(), miss=v48s5Missing(m), txt='', add=0, i;
    if(miss.length){
      txt=v48s5T('missing')+' → ';
      for(i=0;i<miss.length;i++) txt+=(i?', ':'')+(v48s5ModIcon[miss[i]]||'🔧')+' '+v48s5ModName(miss[i]);
      v48s5Log(txt);
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('soft'); }catch(e){}
      return;
    }
    if(!v48s5State.done){
      add=v48s5Award();
      v48s5SaveDone(m.level);
      v48s5SaveLevel(m.level+1);
      v48s5State.done=true;
    }
    v48s5State.log=v48s5T('good')+' +'+add+' '+v48s5T('point')+'. '+v48s5T('ready')+' '+v48s5T('objectLog');
    v48s5Render();
    v48s5Pop(v48s5ObjIcon[m.obj]||'🏗️');
    try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('success'); }catch(e2){}
  }

