function v48s7NodeHtml(level, preview){
    var p=v48s7Plan(level), pos=v48s7Pos[(level-1)%v48s7Pos.length], nm=v48s7ObjName(p.obj), ico=v48s7ObjIcon[p.obj]||'✨', big=((level%5)===0||p.kind==='festival'||p.kind==='unlock'), st='', cls;
