function v48s7WorldHtml(m){
    var h='', done=m.done, i, lim, zoneDone;
    h+='<div id="v48s7-world" class="v48s7-cam'+String(v48s7State.cam||0)+'">';
    h+='<div class="v48s7-sea"></div><div class="v48s7-sun"></div><div class="v48s7-cloud c1">☁️</div><div class="v48s7-cloud c2">☁️</div>';
    for(i=0;i<6;i++){ zoneDone=done>=(i+1)*5; h+='<div class="v48s7-island z'+i+' '+(zoneDone?'open':'')+'"><em></em><b>'+v48s7Esc((i+1)*5)+'</b></div>'; }
    h+='<div class="v48s7-path p1"></div><div class="v48s7-path p2"></div><div class="v48s7-path p3"></div><div class="v48s7-path p4"></div>';
    if(done>=1) h+='<div class="v48s9-landmark v48s9-river"><i></i><b>💦</b></div>';
    if(done>=2) h+='<div class="v48s9-landmark v48s9-field"><i></i><b>🌱</b></div>';
    if(done>=3) h+='<div class="v48s9-landmark v48s9-beam"><i></i><b>☀️</b></div>';
    if(done>=4) h+='<div class="v48s9-landmark v48s9-turbine"><i></i><b>🌬️</b></div>';
    if(done>=5) h+='<div class="v48s9-landmark v48s9-bridgeBig"><i></i><b>🌉</b></div>';
    if(done>=6) h+='<div class="v48s9-landmark v48s9-robotRoad"><i></i><b>🤖</b></div>';
    if(done>=8) h+='<div class="v48s9-landmark v48s9-beeTrail"><i></i><b>🐝</b></div>';
    if(done>=10) h+='<div class="v48s9-landmark v48s9-pondBig"><i></i><b>🌊</b></div>';
    if(done>=15) h+='<div class="v48s9-landmark v48s9-forestBig"><i></i><b>🌲</b></div>';
    if(done>=20) h+='<div class="v48s9-landmark v48s9-festivalBig"><i></i><b>🎪</b></div>';
    lim=Math.min(done,30);
    for(i=1;i<=lim;i++) h+=v48s7NodeHtml(i,false);
    if(done<m.level) h+=v48s7NodeHtml(m.level,true);
    h+='<div class="v48s7-oki '+(v48s7State.mood||'idle')+'"><span>🤖</span><b>Oki</b></div>';
    h+='<div class="v48s7-drone">🚁</div><div class="v48s7-boat">⛵</div><div id="v48s7-fx"></div>';
    h+='</div>';
    return h;
  }

