function v48s12PrepChapter(n){
    v48s12State.chapter=n; v48s12State.x=1; v48s12State.y=2; v48s12State.collected={}; v48s12State.count=0; v48s12State.gateOpen=false; v48s12State.mode='play'; v48s12State.gateTry=0; v48s12State.bridgeStep=0; v48s12State.bridgeFlash=0; v48s12State.wrong=0; v48s12State.celebrate=0;
    if(n===1){ v48s12State.msg=v48s12T('ch1h'); }
    else if(n===2){ v48s12State.msg=v48s12T('ch2h'); }
    else { v48s12State.msg=v48s12T('ch3h'); }
  }

