function v48s12Move(dx,dy,noRender){
    if(v48s12State.chapter!==1 || v48s12State.done>=1) return;
    var nx=v48s12State.x+dx, ny=v48s12State.y+dy, st;
    if(!v48s12Passable(nx,ny)){ v48s12State.msg=v48s12T('bad'); v48s12State.wrong=1; if(!noRender) v48s12Render(); v48s12State.wrong=0; return; }
    v48s12State.x=nx; v48s12State.y=ny; st=v48s12StarAt(nx,ny);
    if(st){ v48s12State.collected[st.id]=1; v48s12State.count++; v48s12State.score+=120; v48s12State.celebrate=1; if(v48s12State.count>=3){ v48s12State.gateOpen=true; v48s12State.msg=v48s12T('ch1c'); }else v48s12State.msg='⭐ '+v48s12State.count+'/3'; }
    else if(v48s12State.gateOpen && nx===4 && ny===3){ v48s12Complete(1,noRender); return; }
    else v48s12State.msg=v48s12T('ch1h');
    if(!noRender) v48s12Render(); v48s12State.celebrate=0;
  }

