function v48s12Key(e){
    var k=e&&e.key?e.key:'';
    if(!document.getElementById('v48s12-oki') || document.getElementById('v48s12-oki').style.display==='none') return;
    if(k==='ArrowUp'){ e.preventDefault(); v48s12Move(0,-1); }
    else if(k==='ArrowDown'){ e.preventDefault(); v48s12Move(0,1); }
    else if(k==='ArrowLeft'){ e.preventDefault(); v48s12Move(-1,0); }
    else if(k==='ArrowRight'){ e.preventDefault(); v48s12Move(1,0); }
    else if(k==='1'){ if(v48s12State.chapter===2) v48s12Gate('red'); else if(v48s12State.chapter===3) v48s12Stone(1); }
    else if(k==='2'){ if(v48s12State.chapter===2) v48s12Gate('blue'); else if(v48s12State.chapter===3) v48s12Stone(2); }
    else if(k==='3'){ if(v48s12State.chapter===2) v48s12Gate('yellow'); else if(v48s12State.chapter===3) v48s12Stone(3); }
    else if(k==='4'){ if(v48s12State.chapter===3) v48s12Stone(4); }
  }

