function stageData(n){
    var cycle=['move','numbers','colors','letters','pattern','animals','icons','arrows','pattern','shapes'];
    var kind=cycle[(n-1)%cycle.length];
    var diff=Math.floor((n-1)/5);
    var len=Math.min(3+diff,8);
    var opts=Math.min(4+Math.floor((n-1)/6),8);
    var d={kind:kind,type:'seq',len:len,opts:opts,need:len};
    if(kind==='move'){
      d.type='move'; d.icon='⭐'; d.name={tr:'Yıldız Yolu',en:'Star Path',de:'Sternenweg',fr:'Chemin des étoiles',ar:'طريق النجوم'}; d.text={tr:'Yıldızları topla, kapıya ulaş.',en:'Collect the stars and reach the gate.',de:'Sammle Sterne und erreiche das Tor.',fr:'Ramasse les étoiles et va à la porte.',ar:'اجمع النجوم واذهب إلى الباب.'};
      d.stars=[[4,0],[3,2],[0,3],[4,3]].slice(0,Math.min(2+diff,4)); d.blocks=(diff<2)?[[1,1],[2,2]]:[[1,1],[2,0],[2,2],[3,1]]; d.gate=[4,3]; d.start=[0,2]; return d;
    }
    if(kind==='pattern'){
      d.type='pattern'; d.icon='🧩'; d.name={tr:'Desen Kutuları',en:'Pattern Boxes',de:'Musterfelder',fr:'Cases motifs',ar:'خانات النمط'}; d.text={tr:'Parlayan kutuları aklında tut.',en:'Remember the glowing boxes.',de:'Merke dir die leuchtenden Felder.',fr:'Mémorise les cases lumineuses.',ar:'تذكّر الخانات المضيئة.'}; d.cells=12; d.need=Math.min(3+diff,7); d.pattern=patFor(n,d.cells,d.need); return d;
    }
    var set=SETS[kind]||SETS.icons; d.icon=set.icon; d.name=set.label; d.text={tr:'Gösterilen sırayı aklında tut ve aynısını seç.',en:'Remember the shown order and choose the same one.',de:'Merke dir die gezeigte Reihenfolge und tippe sie nach.',fr:'Retiens l’ordre affiché puis choisis le même.',ar:'تذكّر الترتيب المعروض واختره نفسه.'}; d.items=set.items.slice(0,Math.min(opts,set.items.length)); d.seq=seqFor(n,len,d.items.length); return d;
  }

