function stageData(n){
    var season=n>100?2:1, local=((n-1)%100)+1, cycle=(season===1?SEASON1:SEASON2), kind=cycle[(local-1)%cycle.length], diff=diffFor(n), pos=(local-1)%10, len, opts, d, set, pool;
    len=Math.min(3+Math.floor(diff/2)+(pos>6?1:0),9); opts=Math.min(4+Math.floor(diff/2),9);
    d={kind:kind,type:'seq',len:len,opts:opts,need:len,season:season};
    if(kind==='move'){
      d.type='move'; d.icon='⭐'; d.name=item(season===1?'Yıldız Yolu':'Keşif Yolu','Star Path','Sternenweg','Chemin des étoiles','طريق النجوم'); d.text=item('Yıldızları topla, kapıya ulaş.','Collect the stars and reach the gate.','Sammle Sterne und erreiche das Tor.','Ramasse les étoiles et va à la porte.','اجمع النجوم واذهب إلى الباب.');
      d.stars=[[4,0],[3,2],[0,3],[4,3],[2,1],[1,0]].slice(0,Math.min(2+Math.floor(diff/2),6));
      d.blocks=(diff<2)?[[1,1],[2,2]]:(diff<5?[[1,1],[2,0],[2,2],[3,1]]:[[1,1],[2,0],[2,2],[3,1],[0,1],[4,2]]);
      d.gate=[4,3]; d.start=[0,2]; return d;
    }
    if(kind==='pattern'){
      d.type='pattern'; d.icon='🧩'; d.name=item('Parlayan Desenler','Glowing Patterns','Leuchtmuster','Motifs lumineux','أنماط مضيئة'); d.text=item('Ayrı yerlerde parlayan kutuları aklında tut.','Remember the boxes glowing in different places.','Merke dir die leuchtenden Felder.','Mémorise les cases lumineuses.','تذكّر الخانات المضيئة.'); d.cells=Math.min(12+Math.floor(diff/2),24); d.need=Math.min(3+Math.floor(diff/2)+(pos>7?1:0),9); d.pattern=patFor(n,d.cells,d.need); return d;
    }
    if(kind==='mixed'||kind==='mixed2'){
      pool=[].concat(SETS.numbers.items,SETS.colors.items.slice(0,4),SETS.animals.items.slice(0,4),SETS.school.items.slice(0,4),SETS.devices.items.slice(0,3),SETS.foods.items.slice(0,3),SETS.shapes.items.slice(0,5));
      d.icon='🧠'; d.name=item(season===1?'Karışık Hafıza':'Yeni Sezon Karışımı','Mixed Memory','Gemischtes Merken','Mémoire mixte','ذاكرة مختلطة'); d.text=item('Sayı, renk, şekil ve nesneleri karıştırmadan sırayla seç.','Choose numbers, colors, shapes and objects in order.','Wähle Zahlen, Farben, Formen und Dinge der Reihe nach.','Choisis nombres, couleurs, formes et objets dans l’ordre.','اختر الأرقام والألوان والأشكال والأشياء بالترتيب.'); d.items=pool.slice(0,Math.min(opts+4,pool.length)); d.seq=seqFor(n,len,d.items.length); return d;
    }
    set=SETS[kind]||SETS.icons; d.icon=set.icon; d.name=set.label; d.text=item('Gösterilen sırayı aklında tut ve aynısını seç.','Remember the shown order and choose the same one.','Merke dir die gezeigte Reihenfolge und tippe sie nach.','Retiens l’ordre affiché puis choisis le même.','تذكّر الترتيب المعروض واختره نفسه.'); d.items=set.items.slice(0,Math.min(opts,set.items.length)); d.seq=seqFor(n,len,d.items.length); return d;
  }

