function missionFor(n){
    var s=sectorFor(n), local=((n-1)%50)+1, wave=Math.floor((local-1)/10), r=(n-1)%12;
    var cats=seasonCats(n), cat=pick(cats,n+wave+r), pool=POOLS[cat]||POOLS.object, target=pool[(n*3+r+wave)%pool.length];
    var len=3+Math.min(6,Math.floor((local+wave)/16)+Math.min(2,s.idx));
    var base=4+Math.min(9,Math.floor(local/6))+Math.min(4,s.idx);
    var need=base+(r%3===0?1:0)-(r%5===0?1:0); if(need<4) need=4;
    if(r===0) return {type:'tap',kind:'meteor',target:'meteor',need:need,title:s.emoji+' Meteor Yağmuru',goal:s.name+': gri meteorları ışınla/parçala. Kırmızı ateş Oki’ye değerse can gider.',pool:['meteor','redMeteor','star','crystal','powerShield'],danger:true};
    if(r===1) return {type:'catch',kind:'star',target:'star',need:need,title:s.emoji+' Yıldız Kurtarma',goal:'Yıldızları kurtar, kristaller enerji verir. Kırmızı meteordan kaç.',pool:['star','crystal','redMeteor','meteor','powerMagnet'],danger:true};
    if(r===2) return {type:'value',target:target,need:need,title:'Hedef: '+itemName(target),goal:'Sadece '+itemName(target)+' hedeflerini seç. '+s.name+' görevi.',pool:pool.concat(['redMeteor','meteor','powerDouble']),danger:true};
    if(r===3) return {type:(n%2?'even':'odd'),need:need,title:(n%2?'Çift Sayı Avı':'Tek Sayı Avı'),goal:(n%2?'Sadece çift sayıları seç.':'Sadece tek sayıları seç.')+' Hız yavaş yavaş artar.',pool:POOLS.number.concat(['redMeteor','star','powerSlow']),danger:true};
    if(r===4) return {type:'shield',need:Math.max(4,need-1),title:'Kalkan Zamanı',goal:'Büyük meteor yaklaşınca Kalkan’a bas. Kalkan kapsülleri ekstra koruma verir.',pool:['bigMeteor','star','redMeteor','powerShield','powerHeart'],danger:true};
    if(r===5) { var a=pool.concat(POOLS.space).concat(POOLS.shape||[]); return {type:'value',target:target,need:need,title:'Karışık Seçim',goal:'Benzer objeler düşecek. Sadece '+itemName(target)+' seç.',pool:a.concat(['redMeteor','powerDouble']),danger:true}; }
    if(r===6) return {type:'avoid',target:target,need:need,title:'Kaç ve Yakala',goal:itemName(target)+' topla. Kırmızı meteorları Oki’den kaçır.',pool:[target,'redMeteor','meteor','star','crystal','powerMagnet'],danger:true};
    if(r===7) { var seq=makeSeq(pool.concat(POOLS.shape||[]), len, n+s.idx); return {type:'seq',seq:seq,need:seq.length,title:'Hafıza Yağmuru',goal:'Sırayı hatırla ve düşerken aynı sırayla seç: '+seq.map(itemName).join(' → '),pool:seq.concat(pool).concat(['redMeteor','powerSlow']),danger:true}; }
    if(r===8) return {type:'bonus',target:target,need:need+2,title:'Bonus Yağmur',goal:'Hedefleri seç, bonus kristalleri de al. Yanlış seçim seriyi bozar.',pool:[target,'crystal','star','redMeteor','powerHeart'].concat(pool),danger:true};
    if(r===9) return {type:'power',need:Math.max(3,Math.floor(need/2)),title:'Güç Kapsülü',goal:'Gökten inen güç kapsüllerini yakala: kalkan, mıknatıs, yavaş zaman veya mega ışın.',pool:['powerShield','powerDouble','powerMagnet','powerSlow','powerHeart','powerMega','redMeteor','meteor','star'],danger:true};
    if(r===10) { var seq2=makeSeq(POOLS.number.concat(pool), Math.min(8,len+1), n*2); return {type:'seq',seq:seq2,need:seq2.length,title:'Akıl Sırası',goal:'Sayı/obje sırasını aklında tut: '+seq2.map(itemName).join(' → '),pool:seq2.concat(pool).concat(['redMeteor','powerMega']),danger:true}; }
    return {type:'boss',target:'bigMeteor',need:3+Math.min(8,wave+s.idx),title:s.emoji+' Büyük Meteor Boss',goal:'Büyük meteoru ışınla parçala. Yıldızlar enerji verir; güç kapsülleri işi kolaylaştırır.',pool:['bigMeteor','redMeteor','star','crystal','powerShield','powerDouble','powerMega'],danger:true};
  }

