function applyPower(v){ var msg; if(v==='powerShield'){ S.shield=true; msg=tx('shieldOk'); setTimeout(function(){ S.shield=false; positionOki(); },3600); }
    else if(v==='powerDouble'){ S.double=true; msg=tx('double'); setTimeout(function(){ S.double=false; },6500); }
    else if(v==='powerMagnet'){ S.magnet=true; msg=tx('magnet'); setTimeout(function(){ S.magnet=false; },6500); }
    else if(v==='powerSlow'){ S.slow=true; msg=tx('slow'); setTimeout(function(){ S.slow=false; },6500); }
    else if(v==='powerHeart'){ S.lives++; if(S.lives>6) S.lives=6; msg=tx('heart'); }
    else if(v==='powerMega'){ S.megaReady=true; msg=tx('mega'); }
    S.score+=15; S.msg=msg||tx('power'); render(); }

