function hitWithShot(sh,it){ var m=mission(); if(!it) return; if(isPower(it.v)){ applyPower(it.v); if(m.type==='power'){ S.got++; S.combo++; } boom(it); removeItem(it); removeShot(sh); if(S.got>=S.need) complete(); else render(); return; }
    if(it.v==='star'||it.v==='crystal'){ energyUp(1); S.score+=8; boom(it); removeItem(it); removeShot(sh); render(); return; }
    if(it.v==='bigMeteor'){ it.hp--; S.score+=9; S.msg=tx('boss'); if(it.el) it.el.innerHTML=esc((EMO.bigMeteor||'💥')+' '+it.hp); if(it.hp>0){ removeShot(sh); render(); return; } }
    if(it.v==='meteor'||it.v==='redMeteor'||it.v==='bigMeteor'||isGoal(it)){ if(isGoal(it)){ S.got++; S.combo++; if(m.type==='seq') S.seqAt++; } S.score+=14+Math.min(20,S.combo); boom(it); removeItem(it); removeShot(sh); if(S.got>=S.need) complete(); else render(); return; }
    removeShot(sh); }

