function tapItem(it){ var m=mission(), arr=MOT[lang()]||MOT.tr; if(!S.active||S.paused||S.complete||!it) return; if(isPower(it.v)){ applyPower(it.v); if(m.type==='power'){ S.got++; S.combo++; } boom(it); removeItem(it); if(S.got>=S.need) complete(); else render(); return; } if(it.v==='star'||it.v==='crystal') energyUp(1); if(it.v==='redMeteor'||it.v==='bigMeteor'){ S.lives--; S.combo=0; S.msg=tx('wrong'); boom(it); removeItem(it); if(S.lives<=0) fail(); else render(); return; }
    if(isGoal(it)){ boom(it); removeItem(it); S.got++; S.combo++; S.score+=10+Math.min(20,S.combo); if(m.type==='seq'||m.type==='boss') S.seqAt++; S.msg=arr[(S.score+S.combo+S.level)%arr.length]; if(S.got>=S.need) complete(); else render(); }
    else { S.lives--; S.combo=0; S.msg=tx('wrong'); removeItem(it); if(S.lives<=0) fail(); else render(); }
  }

