function tick(){ var i,j,it,near,sh,spd; if(S.paused||S.complete) return;
    for(j=S.shots.length-1;j>=0;j--){ sh=S.shots[j]; sh.y-=sh.speed; if(sh.el) sh.el.style.top=sh.y+'%'; if(sh.y<-8){ removeShot(sh); continue; } for(i=S.items.length-1;i>=0;i--){ it=S.items[i]; if(shotHit(sh,it)){ hitWithShot(sh,it); break; } } }
    for(i=S.items.length-1;i>=0;i--){ it=S.items[i]; if(S.magnet&&(isGoal(it)||isPower(it.v)||it.v==='star'||it.v==='crystal')){ it.x+=(S.okiX-it.x)*.045; if(it.el) it.el.style.left=it.x+'%'; }
      spd=it.speed*(S.slow?.52:1); it.y+=spd; if(it.el) it.el.style.top=it.y+'%'; if(it.y>78){ near=Math.abs(it.x-S.okiX)<12; if(isPower(it.v)&&near){ applyPower(it.v); if(mission().type==='power'){ S.got++; S.combo++; } boom(it); removeItem(it); if(S.got>=S.need) complete(); else render(); }
        else if((it.v==='redMeteor'||it.v==='bigMeteor'||it.v==='meteor')&&near){ if(S.shield){ S.got+=(mission().type==='shield'?1:0); S.score+=8; S.msg=tx('shieldOk'); boom(it); removeItem(it); if(S.got>=S.need) complete(); else render(); } else { S.lives--; S.combo=0; S.msg=tx('hurt'); boom(it); removeItem(it); if(S.lives<=0) fail(); else render(); } }
        else if(isGoal(it)&&near){ S.got++; S.combo++; S.score+=12; energyUp(it.v==='star'||it.v==='crystal'?1:0); S.msg=(MOT[lang()]||MOT.tr)[S.combo%(MOT[lang()]||MOT.tr).length]; boom(it); removeItem(it); if(S.got>=S.need) complete(); else render(); }
        else { removeItem(it); } } }
  }

