function v48s50WireBoxDrag(el){
    if(!el || el.getAttribute('data-v48s50-dragwired')==='1') return;
    el.setAttribute('data-v48s50-dragwired','1');
    var drag=null;
    function pos(ev){ var p=(ev&&ev.touches&&ev.touches[0])?ev.touches[0]:ev; return {x:p&&p.clientX||0,y:p&&p.clientY||0}; }
    function isSizeButton(t){ return t && (t.id==='ev-v48s50-size-btn' || (t.closest&&t.closest('#ev-v48s50-size-btn'))); }
    function start(ev){
      if(isSizeButton(ev&&ev.target)) return;
      var p=pos(ev), r=el.getBoundingClientRect();
      drag={sx:p.x,sy:p.y,dx:p.x-r.left,dy:p.y-r.top,moved:false};
      el.classList.add('ev-v48s50-dragging');
      el.style.cursor='grabbing';
      if(ev&&ev.stopPropagation) ev.stopPropagation();
    }
    function move(ev){
      if(!drag) return;
      var p=pos(ev), size=el.getAttribute('data-v48s50-size')||'m', q;
      if(Math.abs(p.x-drag.sx)>4 || Math.abs(p.y-drag.sy)>4) drag.moved=true;
      q=v48s50Clamp(el,p.x-drag.dx,p.y-drag.dy,size);
      el.style.left=q.x+'px'; el.style.top=q.y+'px';
      el.setAttribute('data-v48s50-x',String(Math.round(q.x)));
      el.setAttribute('data-v48s50-y',String(Math.round(q.y)));
      if(ev&&ev.preventDefault) ev.preventDefault();
      if(ev&&ev.stopPropagation) ev.stopPropagation();
    }
    function end(ev){
      if(!drag) return;
      var moved=drag.moved, size=el.getAttribute('data-v48s50-size')||'m';
      var x=parseFloat(el.getAttribute('data-v48s50-x')||el.style.left||'16')||16;
      var y=parseFloat(el.getAttribute('data-v48s50-y')||el.style.top||'112')||112;
      var q=v48s50Clamp(el,x,y,size);
      v48s50SaveBox({x:q.x,y:q.y,size:size});
      v48s50ApplyBox(el,{x:q.x,y:q.y,size:size});
      el.classList.remove('ev-v48s50-dragging');
      el.style.cursor='grab';
      if(moved){
        el.setAttribute('data-v48s50-skip-click','1');
        setTimeout(function(){ try{ el.removeAttribute('data-v48s50-skip-click'); }catch(e){} },80);
        if(ev&&ev.preventDefault) ev.preventDefault();
        if(ev&&ev.stopPropagation) ev.stopPropagation();
      }
      drag=null;
    }
    el.addEventListener('pointerdown',start,{passive:false});
    document.addEventListener('pointermove',move,{passive:false});
    document.addEventListener('pointerup',end,{passive:false});
    el.addEventListener('touchstart',start,{passive:false});
    document.addEventListener('touchmove',move,{passive:false});
    document.addEventListener('touchend',end,{passive:false});
    el.addEventListener('click',function(ev){
      if(el.getAttribute('data-v48s50-skip-click')==='1'){
        if(ev&&ev.preventDefault) ev.preventDefault();
        if(ev&&ev.stopPropagation) ev.stopPropagation();
        return false;
      }
    },true);
  }

