function v48s55SafeMergeArrays(obj,target,source){
    try{
      if(!obj || !obj[target] || !obj[source]) return;
      if(!Array.isArray(obj[target]) || !Array.isArray(obj[source])) return;
      var seen={};
      var out=[];
      var i,item,key;
      for(i=0;i<obj[target].length;i++){
        item=obj[target][i];
        key=JSON.stringify(item);
        if(!seen[key]){ seen[key]=1; out.push(item); }
      }
      for(i=0;i<obj[source].length;i++){
        item=obj[source][i];
        key=JSON.stringify(item);
        if(!seen[key]){ seen[key]=1; out.push(item); }
      }
      obj[target]=out;
      try{ delete obj[source]; }catch(e1){}
    }catch(e){}
  }

