function fixGateNow(){
    var ov,scene,id,cfg,l,titleEl,msgEl,btn,room=null,rooms,i;
    try{ ov=document.getElementById('v48j-gate'); }catch(e0){}
    if(!ov || ov.style.display==='none') return;
    scene=ov.querySelector?ov.querySelector('.v48j-scene'):null;
    if(!scene) return;
    l=syncLang();
    scene.setAttribute('dir',l==='ar'?'rtl':'ltr');
    try{ rooms=window.evV48JGateRooms||{}; }catch(e1){ rooms={}; }
    id='';
    for(i=0;i<scene.classList.length;i++){
      var c=String(scene.classList[i]||'');
      if(c.indexOf('v48j-room-')===0){ id=c.replace('v48j-room-',''); break; }
    }
    cfg=rooms[id]||null;
    if(!cfg) return;
    try{
      if(typeof ROOMS!=='undefined'){
        for(i=0;i<ROOMS.length;i++){ if(ROOMS[i]&&ROOMS[i].id===id){ room=ROOMS[i]; break; } }
      }
    }catch(e2){}
    titleEl=ov.querySelector('.v48j-title'); msgEl=ov.querySelector('.v48j-msg'); btn=ov.querySelector('.v48j-enter');
    if(titleEl){ try{ titleEl.textContent=(typeof evRoomDisplayName==='function'&&room)?evRoomDisplayName(room):(titleEl.textContent||''); }catch(e3){} titleEl.setAttribute('translate','no'); }
    if(msgEl && cfg.m){
      var arr=cfg.m[l]||cfg.m.tr||[];
      var cur=String(msgEl.textContent||'');
      var ok=false;
      for(i=0;i<arr.length;i++){ if(cur===arr[i]){ ok=true; break; } }
      if(!ok && arr.length){ msgEl.textContent=arr[0]; }
      msgEl.setAttribute('translate','no');
    }
    if(btn && cfg.btn){ btn.textContent=(cfg.btn[l]||cfg.btn.tr||btn.textContent||''); btn.setAttribute('translate','no'); }
  }

