    s.textContent='\
#ev-efekt2-layer{position:fixed;inset:0;z-index:88;pointer-events:none;overflow:hidden;display:none;}\
.ev-e2{position:absolute;pointer-events:none;will-change:transform,opacity,filter;user-select:none;}\
.ev-e2-glow{border-radius:999px;filter:blur(1px);mix-blend-mode:screen;}\
@keyframes evE2FloatUp{0%{transform:translateY(28px) scale(.75) rotate(0deg);opacity:0}15%{opacity:.95}80%{opacity:.85}100%{transform:translateY(-92vh) scale(1.18) rotate(55deg);opacity:0}}\
@keyframes evE2Sway{0%,100%{transform:translateX(-10px) rotate(-8deg)}50%{transform:translateX(18px) rotate(9deg)}}\
@keyframes evE2Pulse{0%,100%{transform:scale(.7);opacity:.18;filter:blur(2px)}50%{transform:scale(1.32);opacity:.86;filter:blur(.5px)}}\
@keyframes evE2Spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}\
@keyframes evE2Ripple{0%{transform:scale(.15);opacity:.9;border-width:3px}100%{transform:scale(2.65);opacity:0;border-width:1px}}\
@keyframes evE2Steam{0%{transform:translateY(0) scale(.6);opacity:0}20%{opacity:.65}100%{transform:translateY(-160px) translateX(34px) scale(1.55);opacity:0}}\
@keyframes evE2Scan{0%{transform:translateX(-120%) skewX(-20deg);opacity:0}20%{opacity:.7}70%{opacity:.45}100%{transform:translateX(120%) skewX(-20deg);opacity:0}}\
@keyframes evE2Bob{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-18px) scale(1.06)}}\
.ev-e2-leaf{font-size:28px;animation:evE2FloatUp 7.5s linear infinite,evE2Sway 2.4s ease-in-out infinite;color:#6dff84;text-shadow:0 0 14px rgba(108,255,132,.75)}\
