.ev-e2-heal{font-size:28px;color:#7dffdb;text-shadow:0 0 18px rgba(120,255,220,.9),0 0 34px rgba(50,230,180,.55);animation:evE2Pulse 2.4s ease-in-out infinite;}\
.ev-e2-healorb{width:34px;height:34px;background:radial-gradient(circle,#cffff1 0%,#74ffe1 38%,rgba(80,255,200,0) 70%);animation:evE2Pulse 2.8s ease-in-out infinite;}\
.ev-e2-paint{width:18px;height:18px;border-radius:50% 45% 55% 40%;box-shadow:0 0 16px rgba(255,255,255,.35);animation:evE2FloatUp 6.4s ease-in infinite,evE2Sway 2s ease-in-out infinite;}\
.ev-e2-orbit{width:130px;height:130px;border-radius:50%;border:2px solid rgba(80,220,255,.65);box-shadow:0 0 24px rgba(80,220,255,.35),inset 0 0 18px rgba(80,220,255,.22);animation:evE2Spin 9s linear infinite;}\
.ev-e2-orbit:before,.ev-e2-orbit:after{content:"";position:absolute;left:50%;top:-5px;width:12px;height:12px;border-radius:50%;background:#7ef7ff;box-shadow:0 0 16px #7ef7ff;}\
.ev-e2-orbit:after{top:auto;bottom:-5px;background:#ffd36b;box-shadow:0 0 16px #ffd36b;}\
.ev-e2-steam{width:34px;height:72px;border-radius:50%;border-left:4px solid rgba(255,255,255,.55);filter:blur(.6px);animation:evE2Steam 4.5s ease-out infinite;}\
.ev-e2-scan{height:100%;width:22%;top:0;background:linear-gradient(90deg,transparent,rgba(160,90,255,.22),rgba(110,230,255,.32),transparent);animation:evE2Scan 5.8s ease-in-out infinite;}\
.ev-e2-holo{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle,#e7f3ff 0%,#91c7ff 22%,rgba(102,85,255,.08) 70%);box-shadow:0 0 22px rgba(120,180,255,.75);animation:evE2Bob 3.2s ease-in-out infinite;}\
.ev-e2-ring{width:120px;height:120px;border-radius:50%;border:2px solid rgba(170,150,255,.55);box-shadow:0 0 22px rgba(170,150,255,.3);animation:evE2Pulse 4s ease-in-out infinite;}\
.ev-e2-ripple{width:110px;height:110px;border-radius:50%;border:3px solid rgba(95,245,255,.8);box-shadow:0 0 24px rgba(95,245,255,.5);animation:evE2Ripple 4s ease-out infinite;}\
.ev-e2-energy{font-size:36px;color:#8df0ff;text-shadow:0 0 18px #5fe7ff,0 0 36px rgba(80,130,255,.8);animation:evE2Pulse 1.9s ease-in-out infinite;}\
