function fill(id){ var l=layer(); l.innerHTML=''; l.setAttribute('data-room',id); l.style.display='block'; var i,x,y,colors;
    if(id==='cevre'){
      for(i=0;i<12;i++){ x=4+i*8+(i%3)*2; add(l,'ev-e2-leaf','left:'+x+'%;top:'+(82+(i%4)*5)+'%;',''+(-i*.55)); add(l,'ev-e2-firefly','left:'+(8+i*7)+'%;top:'+(52+(i%5)*7)+'%;',''+(-i*.38)); }
    } else if(id==='sifa'){
      for(i=0;i<9;i++) add(l,'ev-e2-heal','left:'+(10+i*9)+'%;top:'+(22+(i%4)*13)+'%;',-i*.36).textContent=(i%2?'✚':'❤');
      for(i=0;i<7;i++) add(l,'ev-e2-healorb','left:'+(16+i*11)+'%;top:'+(58+(i%3)*8)+'%;',-i*.42);
    } else if(id==='sanat'){
      colors=['#ff4bd8','#ffcf38','#42e8ff','#7dff72','#ff6b3d','#9f72ff'];
      for(i=0;i<18;i++) add(l,'ev-e2-paint','left:'+(4+i*5.2)+'%;top:'+(74+(i%5)*5)+'%;background:'+colors[i%colors.length]+';',-i*.23);
    } else if(id==='ders'){
      add(l,'ev-e2-orbit','left:48%;top:25%;',0); add(l,'ev-e2-orbit','left:18%;top:32%;transform:scale(.75);',-2); add(l,'ev-e2-orbit','left:70%;top:38%;transform:scale(.62);',-4);
      for(i=0;i<10;i++) add(l,'ev-e2-holo','left:'+(8+i*8.8)+'%;top:'+(66+(i%3)*8)+'%;',-i*.31);
    } else if(id==='mutfak'){
      for(i=0;i<10;i++) add(l,'ev-e2-steam','left:'+(32+i*3.8)+'%;top:'+(48+(i%2)*7)+'%;',-i*.4);
      add(l,'ev-e2-scan','left:0;',0); add(l,'ev-e2-scan','left:20%;animation-delay:2.8s;',0);
    } else if(id==='aile'){
      for(i=0;i<12;i++) add(l,'ev-e2-holo','left:'+(8+i*7.4)+'%;top:'+(24+(i%5)*11)+'%;',-i*.25);
      add(l,'ev-e2-ring','left:43%;top:28%;',0); add(l,'ev-e2-ring','left:68%;top:44%;transform:scale(.75);',-1.5);
    } else if(id==='ada'){
      for(i=0;i<9;i++) add(l,'ev-e2-ripple','left:'+(16+i*7.5)+'%;top:'+(58+(i%3)*7)+'%;',-i*.48);
      for(i=0;i<8;i++) add(l,'ev-e2-holo','left:'+(10+i*10)+'%;top:'+(24+(i%4)*9)+'%;',-i*.34);
    } else if(id==='caliskan'){
      for(i=0;i<13;i++) add(l,'ev-e2-energy','left:'+(6+i*7)+'%;top:'+(28+(i%5)*10)+'%;',-i*.18).textContent=(i%2?'⚡':'✦');
      add(l,'ev-e2-scan','left:0;',0); add(l,'ev-e2-ring','left:46%;top:36%;',-1);
    }
  }

