function tick(){
    var id=''; try{ id=currentRoom&&currentRoom.id||''; }catch(e){}
    var gs=document.getElementById('gs'); var active=false; try{ active=!!(gs&&gs.style.display!=='none'&&TARGETS[id]); }catch(e){}
