function v51Sanitize(value){
      if(!v51ValuesOn() || v51ProtectedIslamicRoom()) return value;

      if(typeof value==='string'){
        return v51ReligiousText(value) ? v51Neutral() : value;
      }

      if(value && typeof value==='object' &&
         typeof value.t==='string' &&
         v51ReligiousText(value.t)){
        var copy={},k;
        for(k in value) copy[k]=value[k];
        copy.t=v51Neutral();
        return copy;
      }

      return value;
    }

