function stopBigFire(){
      try{
        if(typeof _stopStreakFire==='function'){
          _stopStreakFire();
        }
      }catch(e){}

      try{
        if(typeof _streakFireRAF!=='undefined' && _streakFireRAF){
          cancelAnimationFrame(_streakFireRAF);
          _streakFireRAF=null;
        }
      }catch(e2){}

      try{
        var c=document.getElementById('streak-fire-c');
        if(c){
          c.style.display='none';
          c.style.opacity='0';
          var ctx=c.getContext && c.getContext('2d');
          if(ctx) ctx.clearRect(0,0,c.width,c.height);
        }
      }catch(e3){}

      try{
        var bg=document.getElementById('streak-fire-premium-bg');
        if(bg){
          bg.style.display='none';
          bg.style.opacity='0';
        }
      }catch(e4){}
    }

