function storeWish(){
try{
if(!valuesOn()||!_selDua)return;
var x=_getDuaLocal(_selDua);
var a=JSON.parse(localStorage.getItem('ev_values_reflections')||'[]');
if(!Array.isArray(a))a=[];
a.unshift({text:x.text||x.name,lang:valuesLang(),ts:Date.now()});
if(a.length>100)a=a.slice(0,100);
localStorage.setItem('ev_values_reflections',JSON.stringify(a));
}catch(e){}
}

