function applyUI(){
try{
if(!valuesOn())return;

var l=valuesLang(),u=UI[l]||UI.tr;
var ov=document.getElementById('dua-ov');
if(!ov)return;

ov.setAttribute('lang',l);
ov.setAttribute('dir',l==='ar'?'rtl':'ltr');

var h=ov.querySelector('#dua-e1 div[style*="font-size:2rem"]');
var s=ov.querySelector('#dua-e1 div[style*="font-size:.85rem"]');

if(h)h.textContent=u.room;
if(s)s.textContent=u.sub;

var own=document.querySelector('[onclick="duaKendiYaz()"]');
if(own)own.textContent=u.kendiDua;

var send=document.getElementById('dua-send-btn');
if(send)send.textContent=u.muhurBtn;

var other=document.querySelector('[onclick="duaGeri()"]');
if(other)other.textContent=u.baskaSecBtn;

var title=document.getElementById('_dua-lang-title');
if(title)title.textContent=u.title;

var ta=document.getElementById('dua-custom-txt');
if(ta)ta.placeholder=u.placeholder;

var custom=document.getElementById('_dua-send-lang-btn');
if(custom)custom.textContent=u.btn;

var flag=document.getElementById('_dua-flag-btn');
if(flag)flag.style.display='none';

}catch(e){}
}

